// Logging Framework in C

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <semaphore.h>
#include <errno.h>

#define LOG_FILE_PATH "./logs/app-log.txt"
#define ERROR_LEVEL_THRESHOLD "INFO"
#define RATE_LIMIT 100
#define BUFFER_SIZE 4096

// Log Levels
typedef enum { DEBUG, INFO, WARN, ERROR } log_level_t;

// Message Template
typedef struct {
    char *message;
    log_level_t level;
} log_msg_t;

// Thread-Safe Logging Functions
void log(log_level_t level, const char* format, ...) {
    va_list args;
    char buffer[BUFFER_SIZE];

    // Locking mechanism to prevent concurrent access to the logging functions
    sem_wait(&lock);

    // Build the message using vsnprintf
    va_start(args, format);
    int n = vsnprintf(buffer, BUFFER_SIZE, format, args);
    va_end(args);

    if (n > 0) {
        // Write the message to the log file
        FILE *file = fopen(LOG_FILE_PATH, "a");
        fputs(buffer, file);
        fclose(file);
    }

    // Check if the error level is above the threshold
    if (level >= get_error_level()) {
        // Send the message to an external logging service API
        send_log(buffer);
    }

    sem_post(&lock);
}

void debug(const char* format, ...) {
    va_list args;
    char buffer[BUFFER_SIZE];

    // Locking mechanism to prevent concurrent access to the logging functions
    sem_wait(&lock);

    // Build the message using vsnprintf
    va_start(args, format);
    int n = vsnprintf(buffer, BUFFER_SIZE, format, args);
    va_end(args);

    if (n > 0) {
        log(DEBUG, buffer);
    }

    sem_post(&lock);
}

void info(const char* format, ...) {
    va_list args;
    char buffer[BUFFER_SIZE];

    // Locking mechanism to prevent concurrent access to the logging functions
    sem_wait(&lock);

    // Build the message using vsnprintf
    va_start(args, format);
    int n = vsnprintf(buffer, BUFFER_SIZE, format, args);
    va_end(args);

    if (n > 0) {
        log(INFO, buffer);
    }

    sem_post(&lock);
}

void warn(const char* format, ...) {
    va_list args;
    char buffer[BUFFER_SIZE];

    // Locking mechanism to prevent concurrent access to the logging functions
    sem_wait(&lock);

    // Build the message using vsnprintf
    va_start(args, format);
    int n = vsnprintf(buffer, BUFFER_SIZE, format, args);
    va_end(args);

    if (n > 0) {
        log(WARN, buffer);
    }

    sem_post(&lock);
}

void error(const char* format, ...) {
    va_list args;
    char buffer[BUFFER_SIZE];

    // Locking mechanism to prevent concurrent access to the logging functions
    sem_wait(&lock);

    // Build the message using vsnprintf
    va_start(args, format);
    int n = vsnprintf(buffer, BUFFER_SIZE, format, args);
    va_end(args);

    if (n > 0) {
        log(ERROR, buffer);
    }

    sem_post(&lock);
}

// External Logging Service API
void send_log(char* message) {
    // Implement the logic for sending logs to an external service API here
    printf("Sending log: %s\n", message);
}

// Get Error Level Threshold
log_level_t get_error_level() {
    return ERROR_LEVEL_THRESHOLD;
}

// Rate Limiting Mechanism
void rate_limit(int* count) {
    // Implement the logic for rate limiting here
    printf("Rate limiting: %d\n", *count);
}

// Thread-Safe Locking Mechanism
sem_t lock;

// Main Function for Testing
int main() {
    log(INFO, "Test message");
    debug("Test debug message");
    info("Test info message");
    warn("Test warn message");
    error("Test error message");

    return 0;
}']

