      try {
        Thread.sleep(backoffInterval);
      } catch (InterruptedException ex) {
        logger.log(Level.SEVERE, "Retry sleep interrupted", ex);
      }
      retryCount++;
      backoffInterval *= 2;
    } else {
      logger.log(Level.WARNING, "Exceeded maximum retries for API request");
      throw e;
    }
  }

