#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <semaphore.h>
#include <errno.h>

// Custom logging library header file
#include "logger.h"

// Define the semaphore structure
typedef struct {
  int value; // The current value of the semaphore
  int max_value; // The maximum allowed value of the semaphore
  pthread_mutex_t mutex; // Mutex for synchronizing access to the semaphore
  sem_t semaphore; // Semaphore object for blocking and non-blocking operations
} semaphore_t;

// Function to initialize a semaphore with the given value
int semaphore_init(semaphore_t* sem, int value) {
  // Check if the semaphore is null
  if (sem == NULL) {
    return -1;
  }

  // Initialize the mutex and set the maximum allowed value to the given value
  pthread_mutex_init(&sem->mutex, NULL);
  sem->max_value = value;

  // Create a new semaphore object with the initial value
  sem->semaphore = sem_open("semaphore", O_CREAT | O_EXCL, 0644, value);
  if (sem->semaphore == SEM_FAILED) {
    logger_error("Failed to create semaphore: %s", strerror(errno));
    return -1;
  }

  // Set the initial value of the semaphore
  sem->value = value;

  return 0;
}

// Function to destroy a semaphore
int semaphore_destroy(semaphore_t* sem) {
  // Check if the semaphore is null
  if (sem == NULL) {
    return -1;
  }

  // Destroy the mutex and close the semaphore object
  pthread_mutex_destroy(&sem->mutex);
  sem_close(sem->semaphore);

  return 0;
}

// Function to acquire a lock on the semaphore
int semaphore_lock(semaphore_t* sem) {
  // Check if the semaphore is null
  if (sem == NULL) {
    return -1;
  }

  // Lock the mutex and decrement the value of the semaphore
  pthread_mutex_lock(&sem->mutex);
  sem->value--;

  return 0;
}

// Function to release a lock on the semaphore
int semaphore_unlock(semaphore_t* sem) {
  // Check if the semaphore is null
  if (sem == NULL) {
    return -1;
  }

  // Unlock the mutex and increment the value of the semaphore
  pthread_mutex_unlock(&sem->mutex);
  sem->value++;

  return 0;
}

// Function to block until a lock on the semaphore is acquired
int semaphore_block(semaphore_t* sem) {
  // Check if the semaphore is null
  if (sem == NULL) {
    return -1;
  }

  // Block until a lock is acquired on the semaphore
  while (sem->value <= 0) {
    sem_wait(sem->semaphore);
  }

  // Lock the mutex and decrement the value of the semaphore
  pthread_mutex_lock(&sem->mutex);
  sem->value--;

  return 0;
}

// Function to release a lock on the semaphore without blocking
int semaphore_try(semaphore_t* sem) {
  // Check if the semaphore is null
  if (sem == NULL) {
    return -1;
  }

  // Try to acquire a lock on the semaphore without blocking
  int locked = pthread_mutex_trylock(&sem->mutex);
  if (locked == EBUSY) {
    return -1;
  } else if (locked != 0) {
    logger_error("Failed to acquire lock: %s", strerror(errno));
    return -1;
  }

  // Decrement the value of the semaphore
  sem->value--;

  return 0;
}
```
To use this semaphore management system in an existing application framework, you would need to integrate it with the framework's threading and synchronization mechanisms. This could involve creating a new API for accessing the semaphores, as well as adding error handling and logging functionality to ensure reliable operation even in the presence of crashed processes.

