    class RNGService {
        private:
            static RNGService* instance;

            RNGService() {}

            ~RNGService() {
                seedMap.clear();
            }

        public:
            static RNGService* getInstance() {
                if (!instance) {
                    instance = new RNGService();
                }
                return instance;
            }

            void init(const uint64_t& seed, const std::string& name) {
                std::lock_guard<std::mutex> lock(mutex);
                seedMap[name] = std::make_unique<MTGenerator>(seed);
            }

            uint64_t getRandomNumber(const std::string& name) {
                return seedMap[name]->getRandomNumber();
            }
    };
}
```
To use the RNG service, clients must first initialize an instance of `RNGService` with a seed and a unique name. Once initialized, the client can call `getInstance()` to retrieve the singleton instance of the service and generate random numbers using the `getRandomNumber()` method. For example:
```c++
