const processFile = async (file) => {
  try {
    const data = await promisify(fs.readFile)(file);
    const schema = validateJSON(data);
    if (!schema) throw new Error('Invalid JSON schema');
    const preprocessedData = preprocessFile(data);
    await cloudStorageClient.uploadFile(preprocessedData, {
