    console.log(`Error processing file ${file}: ${error}`);
  }
};

// Set up directory scanning and file processing loop with concurrency control
const scanDirectory = async (directory) => {
  const files = await promisify(fs.readdir)(directory);
  return Promise.all(files.map(async (file) => {
    try {
      // Limit number of concurrent uploads to avoid exceeding rate limits
      await processFile(path.join(directory, file));
    } catch (error) {
      console.log(`Error processing file ${file}: ${error}`);
    }
  })).catch((error) => {
    // Handle any errors that occur during directory scanning or file processing
    console.log(`Error scanning directory ${directory}: ${error}`);
  });
