Here is a sample implementation of a scalable PHP-based session management system that generates secure tokens of variable lengths for authenticating user sessions:
```php
<?php

// Include dependencies and define constants
include 'config.php';

// Define a class to represent a token
class Token {
  private $token;
  private $expiration;

  // Constructor to generate a new token
  public function __construct($length) {
    $this->token = bin2hex(random_bytes($length));
    $this->expiration = time() + TIMEOUT;
  }

  // Getter for the token value
  public function getToken() {
    return $this->token;
  }

  // Getter for the token expiration
  public function getExpiration() {
    return $this->expiration;
  }
}

// Define a class to represent a session
class Session {
  private $id;
  private $userId;
  private $token;

  // Constructor to generate a new session
  public function __construct($userId) {
    $this->id = uniqid();
    $this->userId = $userId;
    $this->token = new Token(TOKEN_LENGTH);
  }

  // Getter for the session ID
  public function getId() {
    return $this->id;
  }

  // Getter for the user ID associated with the session
  public function getUserId() {
    return $this->userId;
  }

  // Getter for the token associated with the session
  public function getToken() {
    return $this->token;
  }
}

// Define a class to represent a user
class User {
  private $id;
  private $username;
  private $password;

  // Constructor to create a new user
  public function __construct($username, $password) {
    $this->id = uniqid();
    $this->username = $username;
    $this->password = password_hash($password, PASSWORD_DEFAULT);
  }

  // Getter for the user ID
  public function getId() {
    return $this->id;
  }

  // Getter for the username
  public function getUsername() {
    return $this->username;
  }

  // Getter for the password
  public function getPassword() {
    return $this->password;
  }
}

// Define a class to represent a session manager
class SessionManager {
  private $sessions = [];
  private $userSessions = [];

  // Constructor to initialize the session manager
  public function __construct() {
    $this->sessions = [];
    $this->userSessions = [];
  }

  // Method to create a new session for a user
  public function createSession($userId) {
    $session = new Session($userId);
    $this->sessions[$session->getId()] = $session;
    $this->userSessions[$userId][] = $session;
    return $session;
  }

  // Method to get a session by its ID
  public function getSession($id) {
    if (isset($this->sessions[$id])) {
      return $this->sessions[$id];
    } else {
      return null;
    }
  }

  // Method to update the expiration time of a session
  public function updateExpirationTime($id) {
    if (isset($this->sessions[$id])) {
      $session = $this->sessions[$id];
      $session->getToken()->setExpiration(time() + TIMEOUT);
      return true;
    } else {
      return false;
    }
  }

  // Method to invalidate a session
  public function invalidateSession($id) {
    if (isset($this->sessions[$id])) {
      unset($this->sessions[$id]);
      return true;
    } else {
      return false;
    }
  }

  // Method to get all sessions for a user
  public function getUserSessions($userId) {
    if (isset($this->userSessions[$userId])) {
      return $this->userSessions[$userId];
    } else {
      return [];
    }
  }
}

// Define a class to represent an authentication API client
class AuthenticationClient {
  private $apiUrl;

  // Constructor to initialize the authentication API client
  public function __construct($apiUrl) {
    $this->apiUrl = $apiUrl;
  }

  // Method to validate a token against the authentication API
  public function validateToken($token) {
    $url = $this->apiUrl . '/validate';
    $data = array('token' => $token);
    $options = array(
      'http' => array(
        'method' => 'POST',
        'header' => 'Content-Type: application/json',
        'content' => json_encode($data),
      ),
    );
    $context = stream_context_create($options);
    $result = file_get_contents($url, false, $context);
    if ($result === false) {
      return null;
    } else {
      return json_decode($result);
    }
  }
}

// Define a class to represent a token store
class TokenStore {
  private $tokens = [];

  // Constructor to initialize the token store
  public function __construct() {
    $this->tokens = [];
  }

  // Method to add a new token to the store
  public function addToken($token) {
    if (isset($this->tokens[$token])) {
      return false;
    } else {
      $this->tokens[$token] = time();
      return true;
    }
  }

  // Method to get all tokens in the store
  public function getTokens() {
    return array_keys($this->tokens);
  }

  // Method to remove a token from the store
  public function removeToken($token) {
    if (isset($this->tokens[$token])) {
      unset($this->tokens[$token]);
      return true;
    } else {
      return false;
    }
  }
}

// Define a class to represent a rate limiter
class RateLimiter {
  private $limit = 10; // Number of requests per second
  private $window = 1; // Duration of the request window in seconds
  private $tokens = [];

  // Constructor to initialize the rate limiter
  public function __construct() {
    $this->tokens = array_fill(0, $this->limit, time());
  }

  // Method to check if a request is within the limit
  public function checkLimit($id) {
    if (isset($this->tokens[$id])) {
      $now = time();
      if ($now - $this->tokens[$id] <= $this->window) {
        return false;
      } else {
        $this->tokens[$id] = $now;
        return true;
      }
    } else {
      $this->tokens[$id] = time();
      return true;
    }
  }
}

// Define a class to represent an authorization server
class AuthorizationServer {
  private $sessionManager;
  private $authenticationClient;
  private $tokenStore;
  private $rateLimiter;

  // Constructor to initialize the authorization server
  public function __construct() {
    $this->sessionManager = new SessionManager();
    $this->authenticationClient = new AuthenticationClient($apiUrl);
    $this->tokenStore = new TokenStore();
    $this->rateLimiter = new RateLimiter();
  }

  // Method to handle an authorization request
  public function handleAuthorizationRequest($request) {
    if ($request instanceof AuthorizationRequest) {
      $userId = $request->getUserId();
      $clientId = $request->getClientId();
      $redirectUri = $request->getRedirectUri();

      // Check if the user is authenticated
      $userSession = $this->sessionManager->createSession($userId);

      // Generate a new token for the client
      $token = $this->generateToken($clientId, $redirectUri);

      // Add the token to the store
      $this->tokenStore->addToken($token);

      // Update the expiration time of the user session
      $this->sessionManager->updateExpirationTime($userSession->getId());

      return new AuthorizationResponse(200, 'OK', [
        'token' => $token,
        'expires_in' => TIMEOUT,
      ]);
    } else {
      throw new InvalidArgumentException('Invalid authorization request');
    }
  }

  // Method to handle a token validation request
  public function handleTokenValidationRequest($request) {
    if ($request instanceof TokenValidationRequest) {
      $token = $request->getToken();

      // Check if the token is valid
      $result = $this->authenticationClient->validateToken($token);

      return new TokenValidationResponse(200, 'OK', [
        'valid' => ($result !== null),
      ]);
    } else {
      throw new InvalidArgumentException('Invalid token validation request');
    }
  }

  // Method to handle a token revocation request
  public function handleTokenRevocationRequest($request) {
    if ($request instanceof TokenRevocationRequest) {
      $token = $request->getToken();

      // Check if the token is valid
      $result = $this->authenticationClient->validateToken($token);

      return new TokenRevocationResponse(200, 'OK', [
        'valid' => ($result !== null),
      ]);
    } else {
      throw new InvalidArgumentException('Invalid token revocation request');
    }
  }

  // Method to generate a new token for the client
  private function generateToken($clientId, $redirectUri) {
    $token = bin2hex(random_bytes(16));

    return $token;
  }
}

// Define a class to represent an authorization request
class AuthorizationRequest {
  private $userId;
  private $clientId;
  private $redirectUri;

  // Constructor to initialize the authorization request
  public function __construct($userId, $clientId, $redirectUri) {
    $this->userId = $userId;
    $this->clientId = $clientId;
    $this->redirectUri = $redirectUri;
  }

  // Method to get the user ID associated with the request
  public function getUserId() {
    return $this->userId;
  }

  // Method to get the client ID associated with the request
  public function getClientId() {
    return $this->clientId;
  }

  // Method to get the redirect URI associated with the request
  public function getRedirectUri() {
    return $this->redirectUri;
  }
}

// Define a class to represent an authorization response
class AuthorizationResponse {
  private $statusCode;
  private $reasonPhrase;
  private $headers;

  // Constructor to initialize the authorization response
  public function __construct($statusCode, $reasonPhrase, $headers) {
    $this->statusCode = $statusCode;
    $this->reasonPhrase = $reasonPhrase;
    $this->headers = $headers;
  }

  // Method to get the status code associated with the response
  public function getStatusCode() {
    return $this->statusCode;
  }

  // Method to get the reason phrase associated with the response
  public function getReasonPhrase() {
    return $this->reasonPhrase;
  }

  // Method to get the headers associated with the response
  public function getHeaders() {
    return $this->headers;
  }
}

// Define a class to represent a token validation request
class TokenValidationRequest {
  private $token;

  // Constructor to initialize the token validation request
  public function __construct($token) {
    $this->token = $token;
  }

  // Method to get the token associated with the request
  public function getToken() {
    return $this->token;
