#include <typeinfo>
#include "transaction.h"
#include "database.h"
#include "message_broker.h"

class TransactionProcessor {
public:
    TransactionProcessor(std::shared_ptr<Database> database, std::shared_ptr<MessageBroker> message_broker) :
        database_(database), message_broker_(message_broker) {}

    // Process a single transaction and return the serialized byte array representing the transaction.
    std::pair<std::string, uint64_t> process(const Transaction& transaction) {
        if (!is_valid(transaction)) {
            return {};
        }

        // Filter transactions based on their age and frequency within the last 3 seconds.
        if (filter_transaction(transaction)) {
            return {};
        }

        // Calculate a weighted sum from market indicators.
        calculate_weighted_sum(transaction);

        // Persist the transaction in a NoSQL database for later analysis.
        std::string serialized = serialize(transaction);
        uint64_t id = persist(serialized);

        // Notify the message broker of the new transaction.
        notify_broker(id);

        return {serialized, id};
    }

private:
    std::shared_ptr<Database> database_;
    std::shared_ptr<MessageBroker> message_broker_;

    // Check if the transaction is valid and meets the specified criteria.
    bool is_valid(const Transaction& transaction) {
        return transaction.age() < 3000 && transaction.frequency() > 0;
    }

    // Filter transactions based on their age and frequency within the last 3 seconds.
    bool filter_transaction(const Transaction& transaction) {
        auto now = std::chrono::system_clock::now();
        return transaction.age(now) < 3000 || transaction.frequency(now) > 0;
    }

    // Calculate a weighted sum from market indicators.
    void calculate_weighted_sum(const Transaction& transaction) {
        int64_t weight = 1;
        for (auto& indicator : transaction.indicators()) {
            weight += indicator.weight();
        }
        transaction.set_weighted_sum(transaction.value() * weight);
    }

    // Persist the transaction in a NoSQL database for later analysis.
    uint64_t persist(const std::string& serialized) {
        return database_->insert(serialized);
    }

    // Notify the message broker of the new transaction.
    void notify_broker(uint64_t id) {
        message_broker_->publish(id);
    }
};

class Database {
public:
    virtual uint64_t insert(const std::string& serialized) = 0;
};

class MessageBroker {
public:
    virtual void publish(uint64_t id) = 0;
};

class Transaction {
public:
    // Construct a transaction with the specified age and frequency.
    Transaction(int32_t age, int32_t frequency) : age_(age), frequency_(frequency) {}

    // Return the age of the transaction in milliseconds.
    int32_t age() const { return age_; }

    // Return the frequency of the transaction within the last 3 seconds.
    int32_t frequency() const { return frequency_; }

    // Return the weighted sum from market indicators.
    double weighted_sum() const { return weighted_sum_; }

    // Set the value of the transaction.
    void set_value(double value) { value_ = value; }

    // Add an indicator to the transaction's list of indicators.
    void add_indicator(const Indicator& indicator) { indicators_.push_back(indicator); }

    // Return the list of indicators for the transaction.
    const std::vector<Indicator>& indicators() const { return indicators_; }

private:
    int32_t age_;
    int32_t frequency_;
    double weighted_sum_;
    double value_;
    std::vector<Indicator> indicators_;
};

class Indicator {
public:
    // Construct an indicator with the specified weight.
    Indicator(int32_t weight) : weight_(weight) {}

    // Return the weight of the indicator.
    int32_t weight() const { return weight_; }

private:
    int32_t weight_;
};
