using namespace std;

// Attack database API URL
const string attack_api_url = "https://attack-db.com/api/v1/attacks";

// Default attack ID if the database is temporarily unavailable
const int default_attack_id = 1234;

// Cooldown period for attacks (in seconds)
const int cooldown_period = 5;

// Mutex to ensure thread safety when handling network requests and logging attack attempts
mutex attack_mutex;

// Condition variable to signal when an attack is completed
condition_variable attack_cv;

// Vector of attack IDs to keep track of successful attacks
vector<int> successful_attacks;

// Function to perform a dynamic attack using the external attack database API
void performDynamicAttack(string characterName) {
  // Acquire the mutex before making any network requests or modifying shared state
  lock_guard<mutex> lock(attack_mutex);

  // Get the current timestamp for logging purposes
  time_t timestamp = chrono::system_clock::to_time_t(chrono::system_clock::now());

  // Attempt to retrieve an attack from the external API
  try {
    // Make a GET request to the API URL
    http::client::request request(attack_api_url);
    http::client::response response = http::client::get(request);

    // Parse the JSON response into a vector of attack IDs and their respective names
    json::value response_body = json::parse(response.content());
    vector<pair<int, string>> attacks = json::to_vector<int>(response_body["attacks"]);

    // Randomly select an attack from the list
    random_device rd;
    mt19937 gen(rd());
    uniform_int_distribution<> dis(0, attacks.size() - 1);
    int attack_index = dis(gen);
    pair<int, string> selected_attack = attacks[attack_index];

    // Log the successful attack attempt with timestamp and attack ID
    successful_attacks.push_back(selected_attack.first);
    cout << "[" << timestamp << "] Attacked " << characterName << " with attack ID " << selected_attack.first << endl;
  } catch (const http::client::exception& e) {
    // If the request fails, use the default attack ID as a fallback
    cout << "[" << timestamp << "] Failed to retrieve attacks from API: " << e.what() << endl;
    selected_attack = make_pair(default_attack_id, "Default Attack");
  }

  // Sleep for the cooldown period before completing the attack
  this_thread::sleep_for(chrono::seconds(cooldown_period));

  // Notify any waiting threads that an attack has completed
  attack_cv.notify_all();
