    public class RandomValueGenerator
    {
        // Internal data structures to store configuration and generated values
        private Dictionary<string, object> _configs = new Dictionary<string, object>();
        private Dictionary<int, double> _generatedValues = new Dictionary<int, double>();

        // Method to load external configuration from a remote source
        public void LoadConfiguration(string configUrl)
