            // Update the internal configuration dictionary with the new values
            _configs = configDict;
        }

        // Method to generate a random value based on the current configuration
        public double GenerateRandomValue(int seed)
        {
            // Get the current configuration from the internal dictionary
            Dictionary<string, object> config = _configs;

            // Check if the seed is in the generated values cache
            if (_generatedValues.ContainsKey(seed))
            {
                return _generatedValues[seed];
            }

            // Generate a random value based on the current configuration
            double randomValue = GenerateRandomNumberBasedOnConfig(config, seed);

            // Add the generated value to the cache for future reuse
            _generatedValues.Add(seed, randomValue);

            return randomValue;
        }

        // Helper method to generate a random number based on the current configuration
        private double GenerateRandomNumberBasedOnConfig(Dictionary<string, object> config, int seed)
        {
            // Get the minimum and maximum values from the configuration
            double minValue = Convert.ToDouble(config["min_value"]);
            double maxValue = Convert.ToDouble(config["max_value"]);

            // Generate a random number between the minimum and maximum values
            Random random = new Random(seed);
            double randomNumber = random.NextDouble() * (maxValue - minValue) + minValue;

            return randomNumber;
        }
    }
}
