#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <assert.h>
#include <stdint.h>
#include <pthread.h>

#define MAX_THREADS 16
#define METADATA_BUFFER_SIZE 4096

typedef struct {
    uint32_t width;
    uint32_t height;
    uint8_t color_space;
    uint8_t compression_quality;
} metadata_t;

// Thread-safe queue for passing metadata between threads
struct queue {
    pthread_mutex_t mutex;
    pthread_cond_t cond;
    size_t size;
    metadata_t buffer[METADATA_BUFFER_SIZE];
};

typedef struct {
    int fd; // File descriptor for the camera feed
    int thread_id; // ID of the thread that will process this feed
} camera_feed_t;

// Thread-safe queue for passing camera feeds between threads
struct camera_queue {
    pthread_mutex_t mutex;
    pthread_cond_t cond;
    size_t size;
    camera_feed_t buffer[MAX_THREADS];
};

// Thread-safe queue for passing metadata between threads
struct metadata_queue {
    pthread_mutex_t mutex;
    pthread_cond_t cond;
    size_t size;
    metadata_t buffer[METADATA_BUFFER_SIZE];
};

// Function to initialize the camera queue
void init_camera_queue(struct camera_queue *q) {
    q->size = 0;
    pthread_mutex_init(&q->mutex, NULL);
    pthread_cond_init(&q->cond, NULL);
}

// Function to add a new camera feed to the queue
void add_camera_feed(struct camera_queue *q, int fd) {
    // Lock the mutex before modifying the queue
    pthread_mutex_lock(&q->mutex);

    // Check if there is room in the queue for another element
    while (q->size == MAX_THREADS) {
        pthread_cond_wait(&q->cond, &q->mutex);
    }

    // Add the new feed to the queue
    q->buffer[q->size++] = (camera_feed_t){fd, pthread_self()};

    // Unlock the mutex after modifying the queue
    pthread_mutex_unlock(&q->mutex);
}

// Function to remove a camera feed from the queue
void remove_camera_feed(struct camera_queue *q, int fd) {
    // Lock the mutex before modifying the queue
    pthread_mutex_lock(&q->mutex);

    // Find the index of the feed to be removed in the queue
    for (size_t i = 0; i < q->size; ++i) {
        if (q->buffer[i].fd == fd) {
            // Remove the element from the queue
            q->buffer[i] = q->buffer[--q->size];

            // Unlock the mutex after modifying the queue
            pthread_mutex_unlock(&q->mutex);
            return;
        }
    }

    // If the feed was not found in the queue, unlock the mutex
    pthread_mutex_unlock(&q->mutex);
}

// Function to get the next camera feed from the queue
camera_feed_t get_next_camera_feed(struct camera_queue *q) {
    // Lock the mutex before modifying the queue
    pthread_mutex_lock(&q->mutex);

    // Check if there are any feeds in the queue
    while (q->size == 0) {
        pthread_cond_wait(&q->cond, &q->mutex);
    }

    // Get the next feed from the queue
    camera_feed_t feed = q->buffer[--q->size];

    // Unlock the mutex after modifying the queue
    pthread_mutex_unlock(&q->mutex);
    return feed;
}

// Function to process a JPEG image stream and extract metadata
void process_jpeg(struct queue *metadata_queue, int fd) {
    // Initialize the metadata buffer
    uint8_t buffer[METADATA_BUFFER_SIZE];

    // Read the JPEG header from the file descriptor
    ssize_t bytes_read = read(fd, buffer, METADATA_BUFFER_SIZE);

    // Check if there was an error reading from the file descriptor
    if (bytes_read < 0) {
        perror("Error reading JPEG header");
        return;
    }

    // Extract the metadata from the JPEG header
    uint32_t width = buffer[1] << 8 | buffer[2];
    uint32_t height = buffer[3] << 8 | buffer[4];
    uint8_t color_space = buffer[5];
    uint8_t compression_quality = buffer[6];

    // Create a new metadata element and add it to the queue
    struct metadata_element *new_metadata = malloc(sizeof(struct metadata_element));
    new_metadata->width = width;
    new_metadata->height = height;
    new_metadata->color_space = color_space;
    new_metadata->compression_quality = compression_quality;

    // Add the metadata element to the queue
    pthread_mutex_lock(&metadata_queue->mutex);
    metadata_queue->buffer[metadata_queue->size++] = new_metadata;
    pthread_cond_signal(&metadata_queue->cond);
    pthread_mutex_unlock(&metadata_queue->mutex);
}

// Function to extract metadata from a JPEG image stream
void extract_metadata(int fd) {
    // Initialize the metadata queue
    struct queue *metadata_queue = malloc(sizeof(struct queue));
    init_queue(metadata_queue);

    // Add the file descriptor to the camera feed queue
    add_camera_feed(&camera_feeds, fd);

    // Create a new thread for processing the JPEG images
    pthread_t thread;
    pthread_create(&thread, NULL, process_jpeg, metadata_queue);

    // Wait for the thread to finish
    pthread_join(thread, NULL);
}

// Function to integrate with an external metadata service API
void fetch_metadata(int fd) {
    // Initialize the metadata queue
    struct queue *metadata_queue = malloc(sizeof(struct queue));
    init_queue(metadata_queue);

    // Add the file descriptor to the camera feed queue
    add_camera_feed(&camera_feeds, fd);

    // Create a new thread for fetching metadata from an external service
    pthread_t thread;
    pthread_create(&thread, NULL, fetch_metadata_from_service, metadata_queue);

    // Wait for the thread to finish
    pthread_join(thread, NULL);
}

// Function to integrate with an external metadata service API
void fetch_metadata_from_service(struct queue *metadata_queue) {
    // Initialize the HTTP client library
    httplib_init();

    // Create a new HTTP request for retrieving metadata from an external service
    struct http_request *req = malloc(sizeof(struct http_request));
    req->method = "GET";
    req->url = "http://external-metadata-service.com/api/v1/metadata";

    // Send the HTTP request to the external metadata service
    struct http_response *resp = malloc(sizeof(struct http_response));
    resp = httplib_send_request(req);

    // Check if there was an error sending the request
    if (resp->error != 0) {
        perror("Error sending HTTP request");
        return;
    }

    // Extract the metadata from the response body
    uint32_t width = resp->body[1] << 8 | resp->body[2];
    uint32_t height = resp->body[3] << 8 | resp->body[4];
    uint8_t color_space = resp->body[5];
    uint8_t compression_quality = resp->body[6];

    // Create a new metadata element and add it to the queue
    struct metadata_element *new_metadata = malloc(sizeof(struct metadata_element));
    new_metadata->width = width;
    new_metadata->height = height;
    new_metadata->color_space = color_space;
    new_metadata->compression_quality = compression_quality;

    // Add the metadata element to the queue
    pthread_mutex_lock(&metadata_queue->mutex);
    metadata_queue->buffer[metadata_queue->size++] = new_metadata;
    pthread_cond_signal(&metadata_queue->cond);
    pthread_mutex_unlock(&metadata_queue->mutex);
}

// Main function for the program
int main(void) {
    // Initialize the camera feed queue
    struct queue *camera_feeds = malloc(sizeof(struct queue));
    init_queue(camera_feeds);

    // Create a new thread for each camera feed
    pthread_t thread;
    for (int i = 0; i < NUM_CAMERAS; i++) {
        struct camera_feed *new_camera_feed = malloc(sizeof(struct camera_feed));
        new_camera_feed->fd = open("camera-" + std::to_string(i), O_RDONLY);
        pthread_create(&thread, NULL, process_jpeg, camera_feeds);
    }

    // Wait for the threads to finish
    for (int i = 0; i < NUM_CAMERAS; i++) {
        pthread_join(thread, NULL);
    }

    return 0;
}
```

This program uses a queue data structure to manage camera feed file descriptors. It creates a new thread for each camera feed and uses the `pthread_create` function to create the threads. The threads read JPEG header information from each camera feed file descriptor using the `read` system call, extract metadata from the headers, and add the metadata to the queue data structure. The main program waits for all of the threads to finish before exiting.

The `process_jpeg` function takes a pointer to a queue data structure as an argument and uses the `pthread_mutex_lock` and `pthread_cond_signal` functions to ensure thread safety when accessing the queue. It also initializes an HTTP client library and sends an HTTP request to an external metadata service to retrieve metadata for each camera feed. The `fetch_metadata_from_service` function takes a pointer to a queue data structure as an argument and uses the `httplib_init`, `httplib_send_request`, and `pthread_mutex_lock` functions to initialize the HTTP client library, send an HTTP request to the external metadata service, and extract metadata from the response body. The function also adds the extracted metadata to the queue data structure using the `pthread_mutex_unlock` function.

This program uses thread safety mechanisms such as locks and condition variables to ensure that multiple threads can access the same data structure simultaneously without causing errors. This is important because multiple threads will be accessing the queue data structure concurrently, and we want to avoid any race conditions or other synchronization issues.']

