  }

  // Sign the data and store the result in a buffer
  unsigned char* signature = NULL;
  int len = strlen(data);
  if (signature == NULL) {
    printf("Error: failed to allocate memory for signing\n");
    EVP_MD_CTX_free(ctx_ptr);
    return -1;
  }

  // Sign the data using RSA with SHA-256
  ret = EVP_SignUpdate(ctx_ptr, (unsigned char*)data, strlen(data));
  if (ret != 1) {
    printf("Error: failed to sign data\n");
    EVP_MD_CTX_free(ctx_ptr);
    free(signature);
    return -1;
  }

  // Free the OpenSSL message digest object and return the signature
  EVP_MD_CTX_free(ctx_ptr);
  free(signature);
  return len;
}

// Define function to verify a signature using a given algorithm
int verify(const char* data, const char* key) {
  // Initialize cryptographic operation context
  crypt_ctx_t ctx;
  ctx.algorithm = RSA with SHA-256;
  ctx.key = key;

  // Create an OpenSSL message digest object for the selected algorithm
  EVP_MD_CTX* ctx_ptr = EVP_MD_CTX_new();
  if (ctx_ptr == NULL) {
