  // Initialize cryptographic operation context
  crypt_ctx_t ctx;
  ctx.algorithm = AES with CBC mode and a 256-bit key;
  ctx.key = key;

  // Create an OpenSSL cipher object for the selected algorithm
  EVP_CIPHER_CTX* ctx_ptr = EVP_CIPHER_CTX_new();
  if (ctx_ptr == NULL) {
    printf("Error: failed to create cipher context\n");
    return -1;
  }

  // Set the decryption key and algorithm parameters
  int ret = EVP_DecryptInit_ex(ctx_ptr, EVP_aes_256_cbc(), NULL, key, NULL);
  if (ret != 1) {
    printf("Error: failed to initialize cipher\n");
    EVP_CIPHER_CTX_free(ctx_ptr);
    return -1;
  }

  // Decrypt the data and store the result in a buffer
  unsigned char* decrypted = NULL;
  int len = strlen(data);
  if (decrypted == NULL) {
    printf("Error: failed to allocate memory for decryption\n");
    EVP_CIPHER_CTX_free(ctx_ptr);
    return -1;
  }

  // Decrypt the data using AES in CBC mode with a 256-bit key
  ret = EVP_DecryptUpdate(ctx_ptr, decrypted, &len, (unsigned char*)data, strlen(data));
  if (ret != 1) {
    printf("Error: failed to decrypt data\n");
    EVP_CIPHER_CTX_free(ctx_ptr);
    free(decrypted);
    return -1;
  }

  // Free the OpenSSL cipher object and return the decryption result
  EVP_CIPHER_CTX_free(ctx_ptr);
  free(decrypted);
  return len;
}
```

Note that this is just an example, you can use different encryption/decryption algorithms and key sizes depending on your requirements. Also note that the above code uses `EVP_EncryptInit_ex` and `EVP_DecryptInit_ex` to initialize the cipher context with the selected algorithm and key, but these functions are not recommended for new code as they are considered low-level APIs. Instead, you should use the higher-level `EVP_CipherInit` function to initialize the cipher context.']

