void generate_password(char* password, size_t length) {
    if (length < 1) {
        return;
    }

    // Generate a random password of the specified length
    unsigned int i;
    for (i = 0; i < length - 1; i++) {
        *password++ = (char)(rand() % 26 + 'a');
    }
    *password = '\0';
}

void zeroize_password(const char* password, size_t length) {
