    if (key == NULL || password == NULL) {
        return -1;
    }

    // Generate a random salt for PBKDF2
    uint8_t salt[SALT_SIZE];
    generate_salt(salt, SALT_SIZE);

    // Derive the key using PBKDF2 with a configurable iteration count
    int iterations = MAX_ITERATIONS;
    if (iterations < MIN_ITERATIONS) {
        iterations = MIN_ITERATIONS;
    }
    derive_key(key, key_length, password, password_length, salt, iterations);

    // Zeroize the memory containing the password and salt
    zeroize_password(password, password_length);
    memset((void*)salt, 0, SALT_SIZE);

    return 0;
}

