    // Check if the input parameters are valid
    if (ctx == NULL || key == NULL) {
        return -1;
    }

    // Initialize the AES-256-CBC cipher using the specified key
    int ret = aes_cbc_init(ctx, key, key_length);
    if (ret != 0) {
        return ret;
    }

    return 0;
}

// Define the functions for cipher context management
int create_cipher_context(struct cipher_context* ctx, const char* password, size_t password_length) {
    // Check if the input parameters are valid
    if (ctx == NULL || password == NULL) {
        return -1;
    }

    // Derive the key using PBKDF2 and initialize the AES-256-CBC cipher context
    int ret = derive_key(ctx->key, 32, password, password_length);
    if (ret != 0) {
        return ret;
    }
    ret = initialize_cipher(&ctx->ctx, ctx->key, 32);
    if (ret != 0) {
