    }

    // Generate a random salt for PBKDF2 and store it in the context
    generate_salt(ctx->salt, SALT_SIZE);

    // Set the iteration count for PBKDF2 and store it in the context
    ctx->iteration_count = MAX_ITERATIONS;

    // Set the thread ID that created the context
    pthread_t tid = pthread_self();
    if (tid == NULL) {
