bool validate_token(const char* token, const char* token_type) {
    // lock the mutex to prevent concurrent access to the token validation function
    pthread_mutex_lock(&mutex);

    // initialize the token validation result and error message
    token_validation_result result;
    result.valid = false;
    result.err_msg = NULL;

    // check if the token type is 'Bearer' and the expires in field is present and valid
    if(strcmp(token_type, "Bearer") == 0) {
        json_object* obj = json_tokener_parse(token);
        if(obj != NULL && json_object_is_type(obj, json_type_object)) {
            json_object* expires_in = json_object_object_get(obj, "expires_in");
            if(expires_in != NULL && json_object_is_type(expires_in, json_type_int) && json_object_get_int(expires_in) < 3600) {
                // check if the access token is present and not empty
                const char* access_token = json_object_object_get_string(obj, "access_token");
                if(access_token != NULL && strlen(access_token) > 0) {
                    result.valid = true;
                } else {
                    result.err_msg = "Missing or empty access token";
                }
            } else {
                result.err_msg = "Invalid expires in field or missing access token";
            }
        } else {
            result.err_msg = "Failed to parse JSON object or missing expires in field";
        }
    } else {
