    {
        private readonly List<T> _pool;
        private readonly int _maxConnections;
        private readonly TimeSpan _connectionTimeout;
        private readonly object _syncRoot = new object();

        public ConnectionPool(int maxConnections, TimeSpan connectionTimeout)
        {
            _pool = new List<T>();
            _maxConnections = maxConnections;
            _connectionTimeout = connectionTimeout;
        }

        public async Task<T> GetAsync()
        {
            T connection = null;

            try
            {
                // Check if there is an idle connection available in the pool
                lock (_syncRoot)
                {
                    foreach (var item in _pool)
                    {
                        if (!item.IsInUse())
                        {
                            connection = item;
                            break;
                        }
                    }
                }

                // If no idle connections are available, create a new one and add it to the pool
                if (connection == null)
                {
                    connection = await CreateNewConnectionAsync();
                    _pool.Add(connection);
                }
            }
            catch (Exception ex)
            {
                // Handle any exceptions that may occur during connection pool management
                Console.WriteLine($"Error getting connection from pool: {ex}");
            }

            return connection;
        }

        public async Task ReturnAsync(T connection)
        {
            try
            {
                // Check if the connection is valid and return it to the pool for reuse
                lock (_syncRoot)
                {
                    if (connection.IsValid())
                    {
                        _pool.Add(connection);
                    }
                }
            }
            catch (Exception ex)
            {
                // Handle any exceptions that may occur during connection pool management
                Console.WriteLine($"Error returning connection to pool: {ex}");
            }
        }

        public async Task<T> CreateNewConnectionAsync()
        {
            try
            {
                // Create a new connection and return it for use
                T connection = await CreateConnectionAsync();
                return connection;
            }
            catch (Exception ex)
            {
                // Handle any exceptions that may occur during connection creation
                Console.WriteLine($"Error creating new connection: {ex}");
            }
        }

        public async Task DestroyConnectionAsync(T connection)
        {
            try
            {
                // Close the connection and remove it from the pool if necessary
                lock (_syncRoot)
                {
                    _pool.Remove(connection);
                    await connection.DisposeAsync();
                }
            }
            catch (Exception ex)
            {
                // Handle any exceptions that may occur during connection disposal
