using System;
using System.Collections.Generic;
using System.Security.Cryptography;
using System.Text;
using System.Threading;

namespace SecureHasher
{
    public class MD5Hasher
    {
        private const int DEFAULT_CACHE_SIZE = 1024; // default cache size in number of hashes
        private const int MAX_CACHE_SIZE = 8192; // maximum cache size in number of hashes
        private const int EVICTION_THRESHOLD = 100; // percentage of cache to evict when full
        private readonly Dictionary<string, string> _cache = new Dictionary<string, string>();
        private readonly object _lock = new object();

        public string GenerateMD5Hash(string input)
        {
            if (input == null || input.Length == 0)
                return "Invalid input for MD5 hashing";

            // acquire lock to prevent concurrent modifications to the cache
            Monitor.Enter(_lock);

            try
            {
                // check if the hash is already in the cache
                if (_cache.ContainsKey(input))
                    return _cache[input];

                // generate the MD5 hash and add it to the cache
                var md5 = MD5.Create();
                string hash = BitConverter.ToString(md5.ComputeHash(Encoding.UTF8.GetBytes(input)));
                _cache[input] = hash;

                // log the hash generation with external service
                LoggingService.Log("Generated MD5 hash for input " + input + ": " + hash);

                return hash;
            }
            finally
            {
                Monitor.Exit(_lock);
            }
        }

        public void ClearCache()
        {
            // acquire lock to prevent concurrent modifications to the cache
            Monitor.Enter(_lock);

            try
            {
                _cache.Clear();
            }
            finally
            {
                Monitor.Exit(_lock);
            }
        }

        public string GetCachedHash(string input)
        {
            if (input == null || input.Length == 0)
                return "Invalid input for MD5 hashing";

            // acquire lock to prevent concurrent modifications to the cache
            Monitor.Enter(_lock);

            try
            {
                if (_cache.ContainsKey(input))
                    return _cache[input];
            }
            finally
            {
                Monitor.Exit(_lock);
            }

            // generate and add the hash to the cache if it's not already there
            var hash = GenerateMD5Hash(input);
            return hash;
        }
    }
}
