using ProtocolBuffers;

public class DataProcessingException : Exception
{
    public DataProcessingException(string message) : base(message) { }
}

public static Task<T> ProcessEncryptedDataAsync<T>(string encryptedData, string key, string iv) where T : new()
{
    // Validate input parameters
    if (encryptedData == null || key == null || iv == null)
        throw new ArgumentNullException();

    try
    {
        // Fetch and decrypt data from external service
        var decryptedData = await FetchAndDecryptAsync(encryptedData, key, iv);

        // Deserialize decrypted data into custom data model
        var deserializedData = Deserialize<T>(decryptedData);

        return Task.FromResult(deserializedData);
    }
    catch (Exception e)
    {
        throw new DataProcessingException("Error processing encrypted data", e);
    }
}

private static async Task<byte[]> FetchAndDecryptAsync(string encryptedData, string key, string iv)
{
    // Integrate with external encryption service API
    var encryptionService = new EncryptionService();
    var decryptedData = await encryptionService.FetchAndDecryptAsync(encryptedData, key, iv);

    if (decryptedData == null)
        throw new DataProcessingException("Failed to fetch and decrypt data");

    return decryptedData;
}

private static T Deserialize<T>(byte[] serializedData) where T : new()
{
    // Use secure serialization mechanism like Protocol Buffers or MessagePack
    using (var memoryStream = new MemoryStream(serializedData))
    {
        var deserializer = new ProtocolBuffersDeserializer<T>();
        return deserializer.Deserialize(memoryStream);
    }
}
