public class ObjectDeserializationService {
    private static final String DESERIALIZATION_STRATEGY = "custom"; // or "default"
    private static final int MAX_RETRY_ATTEMPTS = 3;
    private static final long RETRY_BACKOFF = 500L; // milliseconds

    public static Object deserialize(byte[] data) throws IOException {
        switch (DESERIALIZATION_STRATEGY) {
            case "default":
                return defaultDeserialization(data);
            case "custom":
                return customDeserialization(data);
            default:
                throw new UnsupportedOperationException("Unsupported deserialization strategy: " + DESERIALIZATION_STRATEGY);
        }
    }

    private static Object defaultDeserialization(byte[] data) throws IOException {
        ByteArrayInputStream bais = new ByteArrayInputStream(data);
        ObjectInputStream ois = new ObjectInputStream(bais);
        return ois.readObject();
    }

    private static Object customDeserialization(byte[] data) throws IOException {
        // Custom deserialization logic goes here
        // ...
        // Return the deserialized object
        return null;
    }

    private static void handleException(IOException e, int attempt) {
        if (attempt < MAX_RETRY_ATTEMPTS) {
            try {
                Thread.sleep(RETRY_BACKOFF);
            } catch (InterruptedException ex) {
                // ignore and allow for retry
            }
            deserialize(data);
        } else {
            throw new IOException("Failed to deserialize object after " + MAX_RETRY_ATTEMPTS + " attempts", e);
        }
    }
}
