// Set up express app and middleware
const app = express();
app.use(express.json());

// Set up multer for file uploads
const multerMiddleware = multer({ dest: 'uploads/' });
app.post('/upload', multerMiddleware.single('file'), (req, res) => {
  const { file } = req;

  // Validate the uploaded file
  if (!validateFile(file)) {
    return res.status(400).send('Invalid file format');
  }

  // Create a new file name for the uploaded file
  const fileName = `${Date.now()}_${file.originalname}`;
  const filePath = path.join(__dirname, 'uploads', fileName);

  // Save the uploaded file to disk
  fs.writeFile(filePath, file.buffer, (err) => {
    if (err) {
      return res.status(500).send('Error saving file');
    }

    // Upload the file to the CDN
    axios({
      method: 'POST',
      url: `${cdnUrl}/upload`,
      data: {
        fileName,
        fileType: file.mimetype,
        fileSize: file.size,
      },
    })
      .then((response) => {
        // Return the CDN URL for the uploaded file
        res.send(response.data);
      })
      .catch((error) => {
        console.error('Error uploading file to CDN', error);
        return res.status(500).send('Error uploading file');
      });
  });
});

// Set up a route for serving files through the REST API
app.get('/file/:fileName', (req, res) => {
  const fileName = req.params.fileName;

  // Check if the requested file exists on disk
  fs.access(path.join(__dirname, 'uploads', fileName), fs.constants.F_OK, (err) => {
    if (err) {
      return res.status(404).send('File not found');
    }

    // Serve the file from disk
    const fileStream = fs.createReadStream(path.join(__dirname, 'uploads', fileName));
    res.setHeader('Content-Type', fileType(fileName).mime);
    res.setHeader('Content-Length', fileStream.bytesWritten);
    res.setHeader('Cache-Control', 'public, max-age=31536000');
    fileStream.pipe(res);
  });
});

// Set up a route for deleting files
app.delete('/file/:fileName', (req, res) => {
  const fileName = req.params.fileName;

  // Check if the requested file exists on disk
  fs.access(path.join(__dirname, 'uploads', fileName), fs.constants.F_OK, (err) => {
    if (err) {
      return res.status(404).send('File not found');
    }

    // Delete the file from disk
    fs.unlink(path.join(__dirname, 'uploads', fileName), (err) => {
      if (err) {
        console.error('Error deleting file', err);
        return res.status(500).send('Error deleting file');
      }

      // Return a success response
      res.sendStatus(204);
    });
  });
});

// Set up a route for updating the CDN URL
app.put('/cdnUrl', (req, res) => {
  const cdnUrl = req.body.cdnUrl;

  // Check if the requested URL is valid
  if (!cdnUrl || !/^https?:\/\//.test(cdnUrl)) {
    return res.status(400).send('Invalid CDN URL');
  }

  // Update the CDN URL in the config file
  fs.writeFileSync('config.json', JSON.stringify({ cdnUrl }, null, 2));

  // Return a success response
  res.sendStatus(204);
});
