const fs = require('fs');
const path = require('path');
const crypto = require('crypto');
const { spawn } = require('child_process');

class EncryptionService {
  constructor(options) {
    this.options = options;
  }

  async encrypt(files, encryptionOptions) {
    const filesToEncrypt = [];
    for (const file of files) {
      const filePath = path.resolve(file);
      if (!fs.existsSync(filePath)) {
        throw new Error(`File not found: ${file}`);
      }
      filesToEncrypt.push(filePath);
    }

    const promises = [];
    for (const file of filesToEncrypt) {
      const promise = this._encryptFile(file, encryptionOptions).then((result) => {
        return result;
      }).catch((error) => {
        throw new Error(`Failed to encrypt ${file}: ${error.message}`);
      });
      promises.push(promise);
    }

    const results = await Promise.all(promises);
    return results;
  }

  async _encryptFile(file, encryptionOptions) {
    const fileContents = fs.readFileSync(file).toString();
    const encryptedContent = await this._encrypt(fileContents, encryptionOptions);
    fs.writeFileSync(file, encryptedContent);
    return file;
  }

  async _encrypt(content, encryptionOptions) {
    const iv = crypto.randomBytes(16).toString('hex');
    const salt = crypto.randomBytes(32).toString('hex');
    const cipher = crypto.createCipheriv('aes-256-cbc', Buffer.from(encryptionOptions.password, 'utf8'), Buffer.from(salt, 'utf8'));
    let encryptedContent = await this._cipher(content, iv);
    const result = await this._appendEncryptedPassword(file, iv, salt, encryptedContent);
    return result;
  }

  async _cipher(content, iv) {
    const cipher = crypto.createCipheriv('aes-256-cbc', Buffer.from(encryptionOptions.password, 'utf8'), Buffer.from(salt, 'utf8'));
    let encryptedContent = await this._appendEncryptedPassword(file, iv, salt, cipher);
    return encryptedContent;
  }

  async _appendEncryptedPassword(file, iv, salt, encryptedContent) {
    const passwordBuffer = Buffer.from(encryptionOptions.password, 'utf8');
    const passwordLength = passwordBuffer.length;
    const encryptedPasswordBuffer = crypto.createCipheriv('aes-256-cbc', Buffer.from(encryptionOptions.password, 'utf8'), Buffer.from(salt, 'utf8'));
    const encryptedPassword = await this._cipher(encryptedPasswordBuffer, iv);
    const fileContentWithEncryptedPassword = `${encryptedContent}\n${iv}${salt}${encryptedPassword}`;
    fs.writeFileSync(file, fileContentWithEncryptedPassword);
    return encryptedPassword;
  }
}
```
