use std::collections::HashMap;
use std::env;
use std::fs;
use std::io;
use std::path;
use std::process;

struct ProjectConfig {
    name: String,
    path: String,
}

impl ProjectConfig {
    fn new(name: &str) -> Self {
        let mut config = HashMap::new();
        config.insert("project_name", name);
        config.insert("project_path", "/tmp/projects");
        config
    }
}

fn create_project(config: &ProjectConfig) -> Result<(), String> {
    let project_name = config.get("project_name").unwrap();
    let project_path = config.get("project_path").unwrap();

    // Verify that the provided project name is valid and not already in use
    if !is_valid_name(project_name) {
        return Err(format!("Invalid project name: {}", project_name));
    } else if project_exists(project_path, project_name) {
        return Err(format!("Project name already exists: {}", project_name));
    }

    // Atomically create the project directory and set the associated environment variables
    let mut env = HashMap::new();
    env.insert("PROJECT_NAME".to_string(), project_name.clone());
    env.insert("PROJECT_PATH".to_string(), project_path.clone());

    fs::create_dir(project_path).map_err(|e| {
        format!("Failed to create project directory: {}", e)
    })?;

    process::Command::new("env")
        .args(&["-i", "bash"])
        .stdin(Stdio::piped())
        .stdout(Stdio::piped())
        .stderr(Stdio::piped())
        .env_clear()
        .envs(env)
        .spawn()
        .map_err(|e| {
            format!("Failed to create environment variables: {}", e)
        })?;

    // Handle potential failures gracefully, providing detailed logs for auditing and troubleshooting
    if let Some(mut child) = process::Command::new("env").args(&["-i", "bash"]).spawn().ok() {
        let mut reader = BufReader::new(child.stdout.take().unwrap());
        let mut buffer = String::new();
