            } else if buffer.contains("project path already exists") {
                return Err(format!("Project path already exists: {}", project_path));
            }
        }
    }

    // Implement comprehensive error handling to manage diverse failure modes, including but not limited to permission denied, disk full, and network unreachable errors
    if let Some(mut child) = process::Command::new("env").args(&["-i", "bash"]).spawn().ok() {
