package com.example.api;

import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.Executors;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.TimeUnit;

import javax.sql.DataSource;

import org.apache.http.HttpStatus;
import org.json.JSONObject;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.web.bind.annotation.DeleteMapping;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.PutMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestHeader;
import org.springframework.web.bind.annotation.RequestParam;
import org.springframework.web.bind.annotation.RestController;

import com.example.api.models.UserResource;
import com.example.api.services.TokenService;
import com.example.api.utilities.JsonUtil;
import com.example.api.utilities.SecurityUtil;
import com.example.api.utilities.StringUtil;

@RestController
public class UserResourceAPI {
  private static final Logger LOGGER = LoggerFactory.getLogger(UserResourceAPI.class);

  @Autowired
  private DataSource dataSource;

  @Autowired
  private TokenService tokenService;

  // ConcurrentHashMap to store user resources, with resourceId as key and UserResource object as value
  private final ConcurrentHashMap<String, UserResource> userResources = new ConcurrentHashMap<>();

  // ScheduledExecutorService for periodic cleanup of soft-deleted resources
  private final ScheduledExecutorService scheduledExecutorService = Executors.newSingleThreadScheduledExecutor();

  @PostMapping("/userResources")
  public ResponseEntity<String> createUserResource(@RequestBody String requestBody, @RequestHeader("Authorization") String authHeader) {
    // Parse the request body and validate the user resource
    UserResource userResource = JsonUtil.fromJson(requestBody, UserResource.class);
    if (userResource == null || !StringUtil.hasLength(userResource.getName())) {
      return ResponseEntity.badRequest().body("Invalid user resource");
    }

    // Validate the OAuth2 access token and extract the userId from it
    String userId = tokenService.validateTokenAndGetUserId(authHeader);
    if (userId == null) {
      return ResponseEntity.status(HttpStatus.UNAUTHORIZED).body("Invalid access token");
    }

    // Generate a unique resourceId and create the user resource
    String resourceId = UUID.randomUUID().toString();
    UserResource newUserResource = new UserResource(resourceId, userId, userResource.getName());
    userResources.put(resourceId, newUserResource);

    // Calculate and validate the MD5 hash of the created user resource
    String md5Hash = SecurityUtil.calculateMD5Hash(JsonUtil.toJson(newUserResource));
    if (!StringUtil.hasLength(md5Hash)) {
      return ResponseEntity.badRequest().body("Failed to calculate MD5 hash");
    }

    // Return the created user resource with the unique resourceId and MD5 hash
    JSONObject response = new JSONObject();
    response.put("resourceId", resourceId);
    response.put("md5Hash", md5Hash);
    return ResponseEntity.ok(response.toString());
  }

  @PutMapping("/userResources/{resourceId}")
  public ResponseEntity<String> updateUserResource(@PathVariable String resourceId, @RequestBody String requestBody, @RequestHeader("Authorization") String authHeader) {
    // Parse the request body and validate the user resource
    UserResource userResource = JsonUtil.fromJson(requestBody, UserResource.class);
    if (userResource == null || !StringUtil.hasLength(userResource.getName())) {
      return ResponseEntity.badRequest().body("Invalid user resource");
    }

    // Validate the OAuth2 access token and extract the userId from it
    String userId = tokenService.validateTokenAndGetUserId(authHeader);
    if (userId == null) {
      return ResponseEntity.status(HttpStatus.UNAUTHORIZED).body("Invalid access token");
    }

    // Validate the resourceId and get the existing user resource
    UserResource existingUserResource = userResources.get(resourceId);
    if (existingUserResource == null || !userId.equals(existingUserResource.getUserId())) {
      return ResponseEntity.status(HttpStatus.NOT_FOUND).body("User resource not found");
    }

    // Update the user resource with new values and calculate the MD5 hash of the updated resource
    existingUserResource.setName(userResource.getName());
    String md5Hash = SecurityUtil.calculateMD5Hash(JsonUtil.toJson(existingUserResource));
    if (!StringUtil.hasLength(md5Hash)) {
      return ResponseEntity.badRequest().body("Failed to calculate MD5 hash");
    }

    // Update the user resource in the database and return the updated resource with the MD5 hash
    try (Connection connection = dataSource.getConnection()) {
      PreparedStatement statement = connection.prepareStatement(
        "UPDATE user_resources SET name=?, modified_at=CURRENT_TIMESTAMP WHERE resourceId=? AND userId=?"
      );
      statement.setString(1, existingUserResource.getName());
      statement.setString(2, resourceId);
      statement.setString(3, userId);
      int updatedRows = statement.executeUpdate();
      if (updatedRows == 0) {
        return ResponseEntity.status(HttpStatus.NOT_FOUND).body("User resource not found");
      }
    } catch (SQLException e) {
      LOGGER.error("Failed to update user resource", e);
      return ResponseEntity.internalServerError().body("Failed to update user resource");
    }

    JSONObject response = new JSONObject();
    response.put("resourceId", existingUserResource.getResourceId());
    response.put("name", existingUserResource.getName());
    response.put("md5Hash", md5Hash);
    return ResponseEntity.ok(response.toString());
  }

  @DeleteMapping("/userResources/{resourceId}")
  public ResponseEntity<String> deleteUserResource(@PathVariable String resourceId, @RequestHeader("Authorization") String authHeader) {
    // Validate the OAuth2 access token and extract the userId from it
    String userId = tokenService.validateTokenAndGetUserId(authHeader);
    if (userId == null) {
      return ResponseEntity.status(HttpStatus.UNAUTHORIZED).body("Invalid access token");
    }

    // Validate the resourceId and get the existing user resource
    UserResource existingUserResource = userResources.get(resourceId);
    if (existingUserResource == null || !userId.equals(existingUserResource.getUserId())) {
      return ResponseEntity.status(HttpStatus.NOT_FOUND).body("User resource not found");
    }

    // Soft delete the user resource in the database and return a success message
    try (Connection connection = dataSource.getConnection()) {
      PreparedStatement statement = connection.prepareStatement(
        "UPDATE user_resources SET deleted=TRUE WHERE resourceId=? AND userId=?"
      );
      statement.setString(1, resourceId);
      statement.setString(2, userId);
      int updatedRows = statement.executeUpdate();
      if (updatedRows == 0) {
        return ResponseEntity.status(HttpStatus.NOT_FOUND).body("User resource not found");
      }
    } catch (SQLException e) {
      LOGGER.error("Failed to soft delete user resource", e);
      return ResponseEntity.internalServerError().body("Failed to soft delete user resource");
    }

    JSONObject response = new JSONObject();
    response.put("message", "User resource deleted successfully");
    return ResponseEntity.ok(response.toString());
  }
}
