```typescript
import { gql } from 'apollo-server-express';

const typeDefs = gql`
  type User {
    id: ID!
    name: String!
    email: String!
  }

  type Query {
    users: [User]!
  }

  input CreateUserInput {
    name: String!
    email: String!
  }

  type Mutation {
    createUser(input: CreateUserInput): User!
  }
`;

const resolvers = {
  Query: {
    users: async () => {
      // fetch all users from the database
      const users = await fetchAllUsers();
      return users.map(user => ({
        id: user.id,
        name: user.name,
        email: user.email,
      }));
    },
  },
  Mutation: {
    createUser: async (root, { input }) => {
      // create a new user in the database with the given input
      const user = await createUser(input);
      return {
        id: user.id,
        name: user.name,
        email: user.email,
      };
    },
  },
};
```

