using System;
using System.Net.Http;
using System.Threading.Tasks;
using Microsoft.Extensions.Configuration;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Logging;
using Serilog;
using DynamicUserAccountManager.Configurations;
using DynamicUserAccountManager.Contracts;
using DynamicUserAccountManager.Services;

namespace DynamicUserAccountManager
{
    public class Program
    {
        static async Task Main(string[] args)
        {
            var configuration = new ConfigurationBuilder()
                .SetBasePath(Directory.GetCurrentDirectory())
                .AddJsonFile("appsettings.json")
                .Build();

            var serviceCollection = new ServiceCollection();
            ConfigureServices(serviceCollection, configuration);

            var services = serviceCollection.BuildServiceProvider();
            using (var scope = services.CreateScope())
            {
                var logger = scope.ServiceProvider.GetRequiredService<ILogger<Program>>();
                try
                {
                    await StartupAsync(logger, configuration);
                }
                catch (Exception ex)
                {
                    logger.LogError(ex, "Failed to start the application");
                }
            }
        }

        private static void ConfigureServices(IServiceCollection services, IConfiguration configuration)
        {
            // Add framework services
            services.AddControllers();
            services.AddOptions<DynamicUserAccountManagerConfig>()
                .Bind(configuration.GetSection("DynamicUserAccountManager"))
                .ValidateDataAnnotations();

            services.AddTransient<IDynamicUserAccountService, DynamicUserAccountService>();
            services.AddHttpClient();

            services.AddLogging(loggingBuilder =>
            {
                loggingBuilder.AddSerilog();
            });
        }

        private static async Task StartupAsync(ILogger logger, IConfiguration configuration)
        {
            // Initialize the service provider
            var serviceProvider = new ServiceCollection()
                .BuildServiceProvider();

            // Create an instance of the DynamicUserAccountManager and start it
            var dynamicUserAccountManager = serviceProvider.GetRequiredService<IDynamicUserAccountService>();
            await dynamicUserAccountManager.StartAsync(logger);
        }
    }
}
