            await Task.Run(() => _userAccounts.Add(userAccount));
        }

        public async Task UpdateUserAccountAsync(string username, UserAccount userAccount) {
            var account = _userAccounts.FirstOrDefault(u => u.Username == username);
            if (account != null) {
                await Task.Run(() => account.Update(userAccount));
            } else {
                throw new Exception("User account not found");
            }
        }

        public async Task DeleteUserAccountAsync(string username) {
            var account = _userAccounts.FirstOrDefault(u => u.Username == username);
            if (account != null) {
                await Task.Run(() => _userAccounts.Remove(account));
            } else {
                throw new Exception("User account not found");
            }
        }
    }
}
