void init_pool(int pool_size) {
    // Initialize the pool with the given size
    pool = (struct LTE_DL_CCCH_POOL *)malloc(sizeof(struct LTE_DL_CCCH_POOL));
    if (!pool) {
        perror("Error allocating memory for pool");
        exit(1);
