    sem_wait(&available_slots);
    struct LTE_DL_CCCH_MESSAGE *message = NULL;
    pthread_mutex_lock(&pool->lock);
    for (int i = 0; i < pool->size; ++i) {
        if (!pool->messages[i]) {
            message = &(pool->messages[i]);
            break;
        }
