    serv_addr.sin_family = AF_INET;
    serv_addr.sin_port = htons(DNS_PORT);
    if (inet_pton(AF_INET, "127.0.0.1", &serv_addr.sin_addr) <= 0) {
        perror("inet_pton");
        close(sockfd);
        return ip;
    }
    char *request = generate_dns_query(hostname);
    if (sendto(sockfd, request, strlen(request), 0,
            (struct sockaddr *) &serv_addr, sizeof(serv_addr)) < 0) {
        perror("sendto");
        close(sockfd);
        return ip;
    }
    free(request);

    // Receive the DNS response
    struct sockaddr_in cli_addr;
    memset(&cli_addr, 0, sizeof(cli_addr));
    socklen_t cli_len = sizeof(cli_addr);
    char buffer[1024];
    int nbytes = recvfrom(sockfd, buffer, sizeof(buffer), 0,
            (struct sockaddr *) &cli_addr, &cli_len);
    if (nbytes < 0) {
        perror("recvfrom");
        close(sockfd);
        return ip;
    }

    // Parse the DNS response and extract the IP address
    struct dns_header *header = (struct dns_header *) buffer;
    if (header->flags & DNS_FLAG_TRUNCATED) {
        fprintf(stderr, "DNS response truncated\n");
        close(sockfd);
        return ip;
    }
    struct dns_query *query = (struct dns_query *) (buffer + sizeof(struct dns_header));
    int i = 0;
    while (i < header->qdcount) {
        if (strcmp(hostname, query[i].name) == 0 && query[i].type == DNS_TYPE_A) {
            struct dns_rr *rr = (struct dns_rr *) (buffer + sizeof(struct dns_header) + i * sizeof(struct dns_query));
            ip.s_addr = rr->data.a.address;
            break;
        }
        i++;
    }

    // Add the hostname to the cache
    if (ip.s_addr != 0) {
        add_dns_cache_entry(hostname, ip);
    }

    return ip;
}

