    public class XMLParser
    {
        private readonly ILogger<XMLParser> _logger;
        private readonly int _chunkSize = 1024; // adjustable chunk size based on system load and memory availability

        public XMLParser(ILogger<XMLParser> logger)
        {
            _logger = logger;
        }

        public async Task ParseAsync(string xml, IXmlReader reader, Action<XElement> elementHandler)
        {
            var stream = new MemoryStream(Encoding.UTF8.GetBytes(xml));
            var settings = new XmlReaderSettings() { Async = true };
            using (var xmlReader = XmlReader.Create(stream, settings))
            {
                while (await xmlReader.ReadAsync())
                {
                    elementHandler(XElement.Parse(xmlReader.ReadInnerXml()));
                }
            }
        }
    }

    public class XMLProcessor
    {
        private readonly ILogger<XMLProcessor> _logger;
        private readonly Dictionary<string, XmlParser> _parsers = new Dictionary<string, XmlParser>();

        public XMLProcessor(ILogger<XMLProcessor> logger)
        {
            _logger = logger;
        }

        public void AddParser(string parserId, XmlParser parser)
        {
            if (_parsers.ContainsKey(parserId))
                throw new ArgumentException($"Parser with ID {parserId} already exists.", nameof(parser));

            _parsers[parserId] = parser;
        }

        public async Task ProcessAsync(string xml, string parserId)
        {
            if (!_parsers.ContainsKey(parserId))
                throw new ArgumentException($"Parser with ID {parserId} does not exist.", nameof(parser));

            var parser = _parsers[parserId];
            await parser.ParseAsync(xml);
        }
    }

