        Self { writer }
    }

    async fn write_json(&mut self, data: &[u8]) -> Result<usize, Box<dyn Error>> {
        let mut writer = self.writer.clone();
        writer.write_all(data).await?;
        Ok(writer.flush().await?)
    }
}

