    let transformer = DataTransformer::new(&["\"{}\"".to_string(), "\"{}\"".to_string()]);
    let mut data = parser.parse();
    let account_manager = UserAccountManager::new();
    for row in data.data {
        let id = row[0].parse::<i32>()?;
        let name = row[1];
        let email = row[2];
        account_manager.add_account(id, name, email);
    }
    let start = Instant::now();
    let resident_set_size = Arc::new(AtomicBool::new(false));
    SyncLazy::new().await;
    for row in data.data {
        let id = row[0].parse::<i32>()?;
        let name = row[1];
        let email = row[2];
        if resident_set_size.load(Ordering::Relaxed) {
            account_manager.add_account(id, name, email);
        }
    }
    let end = Instant::now();
    println!("Elapsed time: {}", start.elapsed());
    Ok(())
}
