const { DOMParser } = require('xmldom');
const { Requests } = require('node-fetch');
const { Async } = require('async');

class DOMTraversal {
  constructor(dom, selectors) {
    this.dom = dom;
    this.selectors = selectors;
  }

  async traverseDOM() {
    const results = [];
    const promises = [];

    // Traverse the DOM tree and fetch elements that match the selectors
    await Async.each(this.dom, (element) => {
      if (this.selectors.includes(element.tagName)) {
        promises.push(this._fetchElementMetadata(element));
      }
    });

    // Fetch metadata from external APIs concurrently
    await Async.parallel(promises);

    return results;
  }

  async _fetchElementMetadata(element) {
    try {
      const url = `https://api.example.com/metadata/${element.tagName}`;
      const response = await Requests.get(url);
      if (response.ok) {
        const metadata = await response.json();
        return this._processMetadata(metadata, element);
      } else {
        throw new Error(`Failed to fetch metadata for ${element.tagName}`);
      }
    } catch (error) {
      console.error(error);
      return null;
    }
  }

  _processMetadata(metadata, element) {
    // Update the DOM node with the retrieved metadata
    element.setAttribute('data-metadata', JSON.stringify(metadata));

    // Add the processed element to the results array
    this.results.push(element);
  }
}
