  private int cacheSize = 1000;
  private int cacheEvictionPolicy = 2; // LRU (Least Recently Used)
  private int rateLimit = 5; // 5 requests per minute

  public int getDisjointPairCount(int[] arr) {
    if (arr == null || arr.length < 2) {
      return -1;
    }

    // Check cache for previously computed disjoint pair counts
    Integer cachedCount = cache.get(Arrays.hashCode(arr));
    if (cachedCount != null) {
      return cachedCount;
    }

    int count = 0;
    for (int i = 0; i < arr.length - 1; i++) {
      for (int j = i + 1; j < arr.length; j++) {
        if (!isDisjoint(arr[i], arr[j])) {
          count++;
        }
      }
    }

    // Add disjoint pair count to cache
    if (cacheSize > 0) {
      cache.put(Arrays.hashCode(arr), count);
      if (cache.size() > cacheSize) {
        switch (cacheEvictionPolicy) {
          case 1: // FIFO (First In, First Out)
            cache.remove(cache.keySet().iterator().next());
            break;
          case 2: // LRU (Least Recently Used)
            cache.remove(lruKey);
            break;
        }
      }
    }

