import os
import json
import yaml
import toml
from configparser import ConfigParser
from concurrent.futures import ThreadPoolExecutor

class ConfigurationManager:
    def __init__(self):
        self.config_cache = {}
        self.config_lock = threading.Lock()
        self.config_executor = ThreadPoolExecutor(max_workers=10)

    def get_configuration(self, filename, format='json'):
        if filename not in self.config_cache:
            with self.config_lock:
                config = ConfigParser()
                if format == 'json':
                    config.read(filename, encoding='utf-8')
                elif format == 'yaml':
                    config.read_string(yaml.load(open(filename)))
                elif format == 'toml':
                    config.read_string(toml.load(open(filename)))
                self.config_cache[filename] = config
        return self.config_cache[filename]

    def fetch_configuration(self, filename, format='json'):
        if format == 'json':
            with open(filename) as f:
                config = json.load(f)
        elif format == 'yaml':
            with open(filename) as f:
                config = yaml.load(f)
        elif format == 'toml':
            with open(filename) as f:
                config = toml.load(f)
        return config

    def update_configuration(self, filename, config):
        with self.config_lock:
            self.config_cache[filename] = config
        os.replace(filename, self.get_temp_file_name())
        with open(self.get_temp_file_name(), 'w') as f:
            json.dump(config, f)

    def get_temp_file_name(self):
        return '{}.tmp'.format(filename)

    def delete_configuration(self, filename):
        with self.config_lock:
            if filename in self.config_cache:
                del self.config_cache[filename]
        os.remove(filename)

    def parse_png_file(self, filepath):
        try:
            image = Image.open(filepath)
            return image
        except Exception as e:
            print('Error parsing PNG file:', str(e))
            return None

    def store_png_file(self, filepath, image):
        with open(filepath, 'wb') as f:
            image.save(f)

    def initialize_theme_directories(self):
        # Initialize default theme directories
        default_theme_dirs = [
            os.path.join(os.getcwd(), 'themes'),
            os.path.join(os.getcwd(), 'assets', 'themes')
        ]
        for dir in default_theme_dirs:
            if not os.path.exists(dir):
                os.makedirs(dir)

    def cache_bitmap(self, filepath):
        # Load bitmap from file and cache it in memory
        image = self.parse_png_file(filepath)
        if image:
            with self.config_lock:
                self.config_cache['bitmaps'][filepath] = image

    def recycle_bitmap(self, filepath):
        # Recycle bitmap in memory and delete it from cache
        with self.config_lock:
            if filepath in self.config_cache['bitmaps']:
                del self.config_cache['bitmaps'][filepath]

    def get_cached_bitmap(self, filepath):
        # Get bitmap from cache and return it
        with self.config_lock:
            if filepath in self.config_cache['bitmaps']:
                return self.config_cache['bitmaps'][filepath]

    def initialize_theme_caches(self):
        # Initialize theme caches for each supported format
        for format in ['json', 'yaml', 'toml']:
            with self.config_lock:
                self.config_cache['themes'][format] = {}

    def cache_theme(self, filename, format):
        # Load theme from file and cache it in memory
        config = self.fetch_configuration(filename, format)
