    def fetch_configuration_asynchronously(self, filename, format):
        # Fetch configuration asynchronously and cache it in memory
        with self.config_lock:
            if filename not in self.config_cache[format]:
                self.config_executor.submit(self.fetch_configuration, filename, format)

    def fetch_theme_asynchronously(self, filename, format):
