    def handle_cache_misses(self):
        # Handle cache misses for each supported format
        with self.config_lock:
            for format in ['json', 'yaml', 'toml']:
                if len(self.config_cache[format]) == 0:
                    print("Cache miss for " + format)
                    # Fetch configuration asynchronously and cache it in memory
                    self.fetch_configuration_asynchronously('config.' + format, format)

    def handle_theme_cache_misses(self):
        # Handle cache misses for each supported format
        with self.config_lock:
