    def handle_configuration_change(self):
        # Handle configuration change for each supported format
        with self.config_lock:
            for format in ['json', 'yaml', 'toml']:
                if self.fetch_configuration(format) != self.config_cache[format]:
                    print("Configuration changed for " + format)
                    # Update cache and recycle theme caches
