                print("Theme bitmap changed")
                # Update cache and recycle theme caches
                self.config_cache['themes']['bitmaps'] = {}
                self.recycle_theme_caches()

    def update(self):
        # Handle all cache misses, configuration changes, theme changes and bitmap changes
        with self.config_lock:
            self.handle_cache_misses()
            self.handle_configuration_change()
            self.handle_theme_change()
            self.handle_bitmap_change()

    def update_themes(self):
        # Handle all cache misses, theme changes and theme bitmap changes
        with self.config_lock:
            self.handle_cache_misses()
            self.handle_theme_change()
            self.handle_theme_bitmap_change()

    def update_themes_and_configuration(self):
        # Handle all cache misses, configuration changes and theme changes
        with self.config_lock:
            self.handle_cache_misses()
            self.handle_configuration_change()
            self.handle_theme_change()

    def update_all(self):
        # Handle all cache misses, configuration changes, theme changes and bitmap changes
        with self.config_lock:
            self.handle_cache_misses()
            self.handle_configuration_change()
            self.handle_theme_change()
            self.handle_bitmap_change()

    def recycle_theme_caches(self):
        # Recycle theme caches for each supported format
        with self.config_lock:
            for format in ['json', 'yaml', 'toml']:
                self.config_cache['themes'][format] = {}

    def handle_reboot(self):
        # Handle reboot event
        with self.config_lock:
            print("Rebooting")
            # Update cache and recycle theme caches
            self.config_cache = {}
            self.recycle_theme_caches()

    def handle_shutdown(self):
        # Handle shutdown event
        with self.config_lock:
            print("Shutting down")
            # Update cache and recycle theme caches
            self.config_cache = {}
            self.recycle_theme_caches()

    def handle_power_failure(self):
        # Handle power failure event
        with self.config_lock:
            print("Power failure")
            # Update cache and recycle theme caches
            self.config_cache = {}
            self.recycle_theme_caches()

    def handle_power_off(self):
        # Handle power off event
        with self.config_lock:
            print("Powering off")
            # Update cache and recycle theme caches
            self.config_cache = {}
            self.recycle_theme_caches()

    def handle_restart(self):
        # Handle restart event
        with self.config_lock:
