import java.util.concurrent.*;
import java.util.logging.*;
import org.apache.kafka.clients.consumer.*;
import org.apache.kafka.common.serialization.*;
import org.elasticsearch.client.*;

public class EventProcessor {
    private static final Logger logger = Logger.getLogger(EventProcessor.class.getName());

    // Kafka consumer properties
    private static final String BOOTSTRAP_SERVERS = "localhost:9092";
    private static final String GROUP_ID = "event-processor";
    private static final int MAX_POLL_RECORDS = 100;
    private static final Duration POLL_TIMEOUT = Duration.ofMillis(500);

    // Elasticsearch client properties
    private static final String ELASTICSEARCH_HOST = "localhost";
    private static final int ELASTICSEARCH_PORT = 9200;
    private static final String INDEX_NAME = "events";
    private static final String DOCUMENT_TYPE = "event";

    // Serialization properties
    private static final ObjectMapper mapper = new ObjectMapper();
    private static final Module module = new SimpleModule().addDeserializer(Event.class, new EventDeserializer());
    private static final Set<Class<?>> deserializableClasses = Collections.singleton(Event.class);

    // Retry and circuit breaker properties
    private static final int MAX_RETRIES = 3;
    private static final Duration RETRY_BACKOFF = Duration.ofMillis(500);
    private static final double CIRCUIT_BREAKER_ERROR_THRESHOLD = 0.5;
    private static final int CIRCUIT_BREAKER_SAMPLE_SIZE = 10;
    private static final Duration CIRCUIT_BREAKER_TIMEOUT = Duration.ofMillis(500);

    // Event processing pipeline
    public static void main(String[] args) throws Exception {
        Properties props = new Properties();
        props.put(ConsumerConfig.BOOTSTRAP_SERVERS_CONFIG, BOOTSTRAP_SERVERS);
        props.put(ConsumerConfig.GROUP_ID_CONFIG, GROUP_ID);
        props.put(ConsumerConfig.MAX_POLL_RECORDS_CONFIG, MAX_POLL_RECORDS);
        props.put(ConsumerConfig.AUTO_OFFSET_RESET_CONFIG, "earliest");

        KafkaConsumer<String, Event> consumer = new KafkaConsumer<>(props, new StringDeserializer(), new JsonDeserializer<>(deserializableClasses));
        consumer.subscribe(Collections.singletonList("events"));

        ElasticsearchClient esClient = new ElasticsearchClient(ELASTICSEARCH_HOST, ELASTICSEARCH_PORT);
        esClient.createIndex(INDEX_NAME, DOCUMENT_TYPE);

        while (true) {
            ConsumerRecords<String, Event> records = consumer.poll(POLL_TIMEOUT);
            for (ConsumerRecord<String, Event> record : records) {
                Event event = record.value();
                try {
                    esClient.index(INDEX_NAME, DOCUMENT_TYPE, mapper.writeValueAsString(event));
                } catch (Exception e) {
                    logger.log(Level.WARNING, "Error indexing event", e);
                }
            }
        }
    }
}
```
This code uses Kafka's Java client to consume events from a Kafka topic named "events". The event data is then sent to an Elasticsearch instance for further processing and storage. The system implements retry policies and circuit breakers to handle transient failures and recover gracefully. The system also includes comprehensive unit tests and integration tests to ensure its functionality and maintainability.']

