#define MAX_CONNECTIONS 50000000
#define BUFFER_SIZE 1024 * 64
#define CERTIFICATE_PATH "certificates"

typedef struct {
    char* message;
    int length;
} LTE_DL_CCCH_MESSAGE_T;

struct connection_pool {
    struct connection_pool* next;
    LTE_DL_CCCH_MESSAGE_T message;
};

struct connection_pool* pool = NULL;

void initialize_connection_pool() {
    int i;
    for (i = 0; i < MAX_CONNECTIONS; i++) {
        struct connection_pool* new_node = malloc(sizeof(struct connection_pool));
        new_node->message = NULL;
        new_node->next = pool;
        pool = new_node;
    }
}

void free_connection_pool() {
    struct connection_pool* node = pool;
    while (node) {
        struct connection_pool* next = node->next;
        free(node);
        node = next;
    }
}

int get_available_slot() {
    struct connection_pool* current = pool;
    while (current) {
        if (!current->message) {
            return 1;
        }
        current = current->next;
    }
    return 0;
}

int allocate_slot(LTE_DL_CCCH_MESSAGE_T* message) {
    struct connection_pool* current = pool;
    while (current) {
        if (!current->message) {
            current->message = message;
            return 1;
        }
        current = current->next;
    }
    return 0;
}

int deallocate_slot(LTE_DL_CCCH_MESSAGE_T* message) {
    struct connection_pool* current = pool;
    while (current) {
        if (current->message == message) {
            current->message = NULL;
            return 1;
        }
        current = current->next;
    }
    return 0;
}

int validate_and_modify_path(char* path, int max_length, void (*error_callback)(char*), int is_absolute) {
