struct Message {
  string id;
  string data;
};

// Define a node struct to represent a node in the network
struct Node {
  int id;
  vector<Message> messages;
};

// Define a queue class that manages a distributed queue system
class Queue {
 public:
  // Constructor
  Queue(int num_nodes, int message_size) : num_nodes_(num_nodes), message_size_(message_size) {}

  // Enqueue method
  void enqueue(const string& id, const string& data) {
    // Create a new message and add it to the node's messages
    Message message = {id, data};
    nodes_[getNodeId()].messages.push_back(message);
  }

  // Dequeue method
  void dequeue() {
    // Remove the first message from the front of the queue
    Node& node = nodes_[getNodeId()];
    Message message = node.messages.front();
    node.messages.erase(node.messages.begin());
  }

 private:
  // Get the current node ID based on the number of nodes and the message size
  int getNodeId() {
    return (int)(num_nodes_ * message_size_) % num_nodes_;
  }

  // Number of nodes in the network
  int num_nodes_;

  // Size of each message
  int message_size_;

  // Map of node IDs to messages
  unordered_map<int, vector<Message>> nodes_;
};

// Test code for the queue class
