package com.example;

import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;

public class MigrateUserData {
    private static final Logger LOGGER = LoggerFactory.getLogger(MigrateUserData.class);

    public void migrateUserData(String sourceSystem, String targetSystem) throws Exception {
        // 1. Integration with legacy systems
        Database database = new Database(sourceSystem);
        API api = new API(targetSystem);

        // 2. Performance optimization
        ExecutorService executorService = Executors.newFixedThreadPool(Runtime.getRuntime().availableProcessors());

        // 3. Error handling and resilience
        try {
            // Migrate user data from source system to target system in parallel
            executorService.execute(() -> {
                while (true) {
                    User user = database.getNextUser();
                    if (user == null) {
                        break;
                    }
                    api.migrateUser(user);
                }
            });

            // Migrate user data from target system to source system in parallel
            executorService.execute(() -> {
                while (true) {
                    User user = api.getNextUser();
                    if (user == null) {
                        break;
                    }
                    database.migrateUser(user);
                }
            });

            // Wait for migration to complete
            executorService.shutdown();
            while (!executorService.isTerminated()) {
                Thread.sleep(1000);
            }
        } catch (Exception e) {
            LOGGER.error("Error occurred during user data migration", e);
        }
    }
}
```
