// Modular cryptographic service using Triple DES encryption and decryption
using System;
using System.Security.Cryptography;
using System.Threading;
using System.IO;
using System.Text;

namespace CryptographicService
{
    public class CryptoService : IDisposable
    {
        private readonly SecureTokenService _sts;
        private readonly TripleDESCryptoServiceProvider _csp;
        private readonly string _key;

        public CryptoService(SecureTokenService sts)
        {
            _sts = sts;
            _csp = new TripleDESCryptoServiceProvider();
            _key = _sts.GetKey();
        }

        public void Dispose()
        {
            _csp.Dispose();
        }

        public string Encrypt(string input)
        {
            var iv = _sts.GetIV();
            var encryptedBytes = Encrypt(Encoding.UTF8.GetBytes(input), iv);
            return Convert.ToBase64String(encryptedBytes);
        }

        public string Decrypt(string input)
        {
            var encryptedBytes = Convert.FromBase64String(input);
            var iv = _sts.GetIV();
            var decryptedBytes = Decrypt(encryptedBytes, iv);
            return Encoding.UTF8.GetString(decryptedBytes);
        }

        private byte[] Encrypt(byte[] input, byte[] iv)
        {
            var encryptedBytes = new byte[input.Length + _csp.BlockSize];
            _csp.Mode = CipherMode.CBC;
            _csp.Padding = PaddingMode.PKCS7;
            using (var encrypter = _csp.CreateEncryptor(_key, iv))
            {
                var encryptedLength = encrypter.TransformBlock(input, 0, input.Length, null, 0);
                Array.Copy(encrypter.GetIV(), 0, iv, 0, _csp.BlockSize);
                return encryptedBytes;
            }
        }

        private byte[] Decrypt(byte[] input, byte[] iv)
        {
            var decryptedBytes = new byte[input.Length - _csp.BlockSize];
            _csp.Mode = CipherMode.CBC;
            _csp.Padding = PaddingMode.PKCS7;
            using (var decrypter = _csp.CreateDecryptor(_key, iv))
            {
                var decryptedLength = decrypter.TransformBlock(input, 0, input.Length - _csp.BlockSize, null, 0);
                return decryptedBytes;
            }
        }
    }
}
```
