namespace PasswordHasher {
    public class PasswordHasher {
        private readonly IAuthenticator _authenticator; // REST API or WebSocket client for external authentication service
        private readonly int _workFactor; // dynamic configuration for adjusting hashing parameters based on system load and security policies
        private readonly int _memoryCost;

        public PasswordHasher(IAuthenticator authenticator, int workFactor = 12, int memoryCost = 4096) {
            _authenticator = authenticator;
            _workFactor = workFactor;
            _memoryCost = memoryCost;
        }

        public async Task<string> HashPassword(string password) {
            if (password == null || password.Trim().Length < 1) {
                throw new ArgumentException("Invalid password", nameof(password));
            }

            var salt = GenerateSalt(); // generate a random salt for each password
            var hashedPassword = await HashAsync(password, salt); // async version of the hashing algorithm
            return $"{salt}:{hashedPassword}"; // store the salt and hashed password together
        }

        public async Task<bool> VerifyPassword(string hashedPassword, string inputPassword) {
            if (hashedPassword == null || inputPassword == null || hashedPassword.Trim().Length < 1 || inputPassword.Trim().Length < 1) {
                throw new ArgumentException("Invalid password", nameof(inputPassword));
            }

            var salt = GetSaltFromHashedPassword(hashedPassword); // extract the salt from the stored hashed password
            var verifiedPassword = await VerifyAsync(inputPassword, salt, hashedPassword); // async version of the verification algorithm
            return verifiedPassword; // return true if the input password matches the stored password
        }

        private static string GenerateSalt() {
            using (var rngCryptoServiceProvider = new RNGCryptoServiceProvider()) {
                byte[] randomBytes = new byte[16];
                rngCryptoServiceProvider.GetBytes(randomBytes);
                return Convert.ToBase64String(randomBytes); // convert the random bytes to a base64-encoded string
            }
        }

        private async Task<string> HashAsync(string password, string salt) {
            var hasher = new Argon2(); // create an instance of the Argon2 class for hashing
            hasher.WorkFactor = _workFactor; // set the work factor based on dynamic configuration
            hasher.MemoryCost = _memoryCost;
            var hashedPassword = await Task.Run(() => {
                return hasher.Hash(password, salt); // run the hashing algorithm asynchronously
            });
            return hashedPassword;
        }

        private async Task<bool> VerifyAsync(string inputPassword, string salt, string hashedPassword) {
            var verified = false;
            if (inputPassword == null || inputPassword.Trim().Length < 1 || salt == null || salt.Trim().Length < 1 || hashedPassword == null || hashedPassword.Trim().Length < 1) {
                throw new ArgumentException("Invalid password", nameof(inputPassword));
            }

            var verifier = new Argon2(); // create an instance of the Argon2 class for verification
            verifier.WorkFactor = _workFactor; // set the work factor based on dynamic configuration
            verifier.MemoryCost = _memoryCost;
            verified = await Task.Run(() => {
                return verifier.Verify(inputPassword, salt, hashedPassword); // run the verification algorithm asynchronously
            });
            return verified;
        }

        private static string GetSaltFromHashedPassword(string hashedPassword) {
            if (hashedPassword == null || hashedPassword.Trim().Length < 1) {
                throw new ArgumentException("Invalid password", nameof(hashedPassword));
            }

            var salt = hashedPassword.Split(':')[0]; // extract the salt from the stored hashed password
            return salt;
        }
    }
}
