    ERROR_NO_SUCH_USER => 'No such user',
    ERROR_PERMISSION_DENIED => 'Permission denied',
    ERROR_DISK_FULL => 'Disk full',
    ERROR_NETWORK_UNREACHABLE => 'Network unreachable',
};

