# Define a class for managing project initialization
package ProjectInitializer;
use strict;
use warnings;
use feature qw(say);

sub new {
    my ($class, $args) = @_;

    return bless {
        name => undef,
        path => undef,
        user => undef,
        description => undef,
        dependencies => [],
        env_vars => {},
    }, $class;
}

# Initialize a new project
sub initialize {
    my ($self, $params) = @_;

    # Validate the project name and path
    if (length($params->name) > $MAX_PROJECT_NAME_LENGTH || length($params->name) < $MIN_PROJECT_NAME_LENGTH) {
        die ERROR_INVALID_PROJECT_NAME;
    }
    unless ($params->name =~ m/^$PROJECT_NAME_ALLOWED_CHARS+$/) {
        die ERROR_INVALID_PROJECT_NAME;
    }

    # Validate the user and create the project directory if necessary
    my $user = getpwnam($params->user);
    unless (defined $user) {
        die ERROR_NO_SUCH_USER;
    }

    my $path = sprintf('%s/%s', $DEFAULT_PROJECT_DIR, $params->name);
    if (!-d $path) {
        make_path($path);
    }

    # Set up the project metadata and dependencies
    my $metadata = ProjectMetadata->new({
        name => $params->name,
        path => $path,
        user => $user,
        description => $params->description,
        dependencies => [],
        env_vars => {},
    });

    # Set up the project status and return it
    my $status = ProjectStatus->new({
        name => $metadata->name,
        path => $metadata->path,
        user => $metadata->user,
        status => 'initializing',
        dependencies => [],
        env_vars => {},
    });

    return $status;
}

# Finalize a project initialization
