['```rust
use std::sync::{Arc, Mutex};
use std::collections::HashMap;
use std::thread;

struct NFAPI_CRC_INDICATION_PDU_T {
    rx_ue_information_tag: u8,
    rnti: u32,
    crc_indication_rel8_tag: u16,
    crc_data: Vec<u8>,
}

struct NFAPI_CRC_INDICATION_PDU_MAP {
    pdu_map: HashMap<u32, Arc<Mutex<NFAPI_CRC_INDICATION_PDU_T>>>,
}

impl NFAPI_CRC_INDICATION_PDU_MAP {
    fn new() -> Self {
        Self { pdu_map: HashMap::new() }
    }

    fn add(&mut self, rnti: u32, crc_data: Vec<u8>) {
        let mut pdu = NFAPI_CRC_INDICATION_PDU_T {
            rx_ue_information_tag: 0,
            rnti,
            crc_indication_rel8_tag: 0,
            crc_data,
        };
        let pdu = Arc::new(Mutex::new(pdu));
        self.pdu_map.insert(rnti, pdu);
    }

    fn get(&self, rnti: u32) -> Option<Arc<Mutex<NFAPI_CRC_INDICATION_PDU_T>>> {
        self.pdu_map.get(&rnti).cloned()
    }
}

fn generate_crc_indication_pdu(rnti: u32, crc_data: Vec<u8>) -> Arc<Mutex<NFAPI_CRC_INDICATION_PDU_T>> {
    let pdu = NFAPI_CRC_INDICATION_PDU_T {
        rx_ue_information_tag: 0,
        rnti,
        crc_indication_rel8_tag: 0,
        crc_data,
    };
    Arc::new(Mutex::new(pdu))
}

fn main() {
    let mut nfapi_crc_indication_pdu_map = NFAPI_CRC_INDICATION_PDU_MAP::new();
    for i in 0..100_000 {
        let rnti = rand::random::<u32>();
        let crc_data: Vec<u8> = vec![];
        nfapi_crc_indication_pdu_map.add(rnti, crc_data);
    }

    // Spawn a thread for each concurrent user session
    for i in 0..100 {
        let rnti = rand::random::<u32>();
        let nfapi_crc_indication_pdu_map = nfapi_crc_indication_pdu_map.clone();
        thread::spawn(move || {
            // Access the map in a thread-safe manner
            let pdu_lock = nfapi_crc_indication_pdu_map.get(rnti).unwrap();
            let mut pdu = pdu_lock.lock().unwrap();
            pdu.rx_ue_information_tag = 0;
        });
    }
}
```
