    // Put the data in the cache with a TTL of 10 minutes
    cache.put(key, value, 600);
  }

  std::optional<google::protobuf::Struct> get(const std::string& key) {
    // Get the data from the cache if it exists and is still valid
    return cache.get(key);
  }
};

