  }
};

class DataPipeline {
 public:
  void run() {
    // Create threads for each service and start them
    for (auto& service : services) {
      threads.push_back(std::thread([&]() {
        while (true) {
          auto response = service.getData();
          if (response.has_value()) {
            // Process the data and store it in the cache
            Cache().put(service.name(), response.value());
          } else {
            // Handle errors and retries here
          }
        }
      }));
    }

    while (true) {
