// Error handling function
static void error_handler(const char* file, const int line, const char* func) {
  printf("Error in %s at line %d: %s\n", file, line, ERR_error_string(ERR_get_error(), NULL));
}

// Encryption and decryption functions
int encrypt(char* input, char* key, char* iv, char** output) {
  // Set up encryption context
  EVP_CIPHER_CTX* ctx = EVP_CIPHER_CTX_new();
  if (!ctx) {
    error_handler(__FILE__, __LINE__, __func__);
    return -1;
  }

  // Set encryption parameters
  int ret = EVP_EncryptInit(ctx, EVP_aes_256_cbc(), NULL, key, iv);
  if (ret != 1) {
    error_handler(__FILE__, __LINE__, __func__);
    return -1;
  }

  // Encrypt data
  int len = strlen(input);
  int output_len = len + EVP_CIPHER_CTX_block_size(ctx) - 1;
  *output = (char*)malloc(output_len);
  ret = EVP_EncryptUpdate(ctx, *output, &output_len, input, len);
  if (ret != 1) {
    error_handler(__FILE__, __LINE__, __func__);
    return -1;
  }

  // Finalize encryption
  ret = EVP_EncryptFinal(ctx, *output + output_len, &output_len);
  if (ret != 1) {
    error_handler(__FILE__, __LINE__, __func__);
    return -1;
  }

  // Clean up encryption context
  EVP_CIPHER_CTX_free(ctx);

  return output_len;
}

int decrypt(char* input, char* key, char* iv, char** output) {
  // Set up decryption context
  EVP_CIPHER_CTX* ctx = EVP_CIPHER_CTX_new();
  if (!ctx) {
    error_handler(__FILE__, __LINE__, __func__);
    return -1;
  }

  // Set decryption parameters
  int ret = EVP_DecryptInit(ctx, EVP_aes_256_cbc(), NULL, key, iv);
  if (ret != 1) {
    error_handler(__FILE__, __LINE__, __func__);
    return -1;
  }

  // Decrypt data
  int len = strlen(input);
  int output_len = len + EVP_CIPHER_CTX_block_size(ctx) - 1;
  *output = (char*)malloc(output_len);
  ret = EVP_DecryptUpdate(ctx, *output, &output_len, input, len);
  if (ret != 1) {
    error_handler(__FILE__, __LINE__, __func__);
    return -1;
  }

  // Finalize decryption
  ret = EVP_DecryptFinal(ctx, *output + output_len, &output_len);
  if (ret != 1) {
    error_handler(__FILE__, __LINE__, __func__);
    return -1;
  }

  // Clean up decryption context
  EVP_CIPHER_CTX_free(ctx);

  return output_len;
}

// Signing and verification functions
int sign(char* input, char* key, char** signature) {
  // Set up signing context
  HMAC_CTX* ctx = HMAC_CTX_new();
  if (!ctx) {
    error_handler(__FILE__, __LINE__, __func__);
    return -1;
  }

  // Set signing parameters
  int ret = HMAC_Init(ctx, key, strlen(key), EVP_sha256());
  if (ret != 1) {
    error_handler(__FILE__, __LINE__, __func__);
    return -1;
  }

  // Sign data
  int len = strlen(input);
  *signature = (char*)malloc(EVP_MAX_MD_SIZE);
  ret = HMAC_Update(ctx, input, len);
  if (ret != 1) {
    error_handler(__FILE__, __LINE__, __func__);
    return -1;
  }

  // Finalize signing
  int signature_len = EVP_MAX_MD_SIZE;
  ret = HMAC_Final(ctx, *signature, &signature_len);
  if (ret != 1) {
    error_handler(__FILE__, __LINE__, __func__);
    return -1;
  }

  // Clean up signing context
  HMAC_CTX_free(ctx);

  return signature_len;
}

int verify(char* input, char* key, char* signature) {
  // Set up verification context
  HMAC_CTX* ctx = HMAC_CTX_new();
  if (!ctx) {
    error_handler(__FILE__, __LINE__, __func__);
    return -1;
  }

  // Set verification parameters
  int ret = HMAC_Init(ctx, key, strlen(key), EVP_sha256());
  if (ret != 1) {
    error_handler(__FILE__, __LINE__, __func__);
    return -1;
  }

  // Verify data
  int len = strlen(input);
  ret = HMAC_Update(ctx, input, len);
  if (ret != 1) {
    error_handler(__FILE__, __LINE__, __func__);
    return -1;
  }

  // Finalize verification
  int signature_len = EVP_MAX_MD_SIZE;
  ret = HMAC_Final(ctx, signature, &signature_len);
  if (ret != 1) {
    error_handler(__FILE__, __LINE__, __func__);
    return -1;
  }

  // Clean up verification context
  HMAC_CTX_free(ctx);

  return signature_len;
}
