#include <errno.h>

// Macro for checking if the string is longer than the given limit
#define LENGTH_CHECK(str, len) (strlen(str) > len)

// Function to process a conditional string and append forward slash if necessary
char *conditionalStringProcessor(const char *str, int limit) {
  // Check if the string is longer than the given limit
  if (LENGTH_CHECK(str, limit)) {
    return NULL;
  }

  // Allocate memory for the processed string
  char *processedStr = malloc(sizeof(char) * limit);
  if (!processedStr) {
    printf("Error: unable to allocate memory\n");
    return NULL;
  }

  // Append forward slash to the input string if necessary
  if (strlen(str) <= limit) {
    strcpy(processedStr, str);
  } else {
    sprintf(processedStr, "%s/", str);
  }

  return processedStr;
}

// Function to execute a shell command securely and efficiently
int shellCommandExecutor(const char *cmd) {
  // Fork the process to create a child process that executes the command
  pid_t childPid = fork();
  if (childPid < 0) {
    printf("Error: unable to fork process\n");
    return -1;
  }

  // Create a pipe for reading and writing between the parent and child processes
  int fd[2];
  if (pipe(fd) < 0) {
    printf("Error: unable to create pipe\n");
    return -1;
  }

  // Child process executes the command
  if (!childPid) {
    close(fd[0]);
    dup2(fd[1], STDOUT_FILENO);
    dup2(fd[1], STDERR_FILENO);
    execl("/bin/sh", "sh", "-c", cmd, (char *)NULL);
  }

  // Parent process waits for the child process to finish and captures the standard output and error streams
  close(fd[1]);
  char buf[BUFSIZ];
  int readBytes = 0;
  while ((readBytes = read(fd[0], buf, BUFSIZ)) > 0) {
    // Process the captured data here
  }

  close(fd[0]);
  int status = waitpid(childPid, NULL, WNOHANG);
  if (status < 0) {
    printf("Error: unable to wait for child process\n");
    return -1;
  }

  // Handle race conditions and deadlocks when executing multiple commands simultaneously
  int ret = 0;
  if (WIFEXITED(status)) {
    ret = WEXITSTATUS(status);
  } else {
    printf("Error: child process did not exit normally\n");
    return -1;
  }

  return ret;
}
