#include "DistributedCacheManager.h"

namespace {
  const std::chrono::seconds RATE_LIMIT_INTERVAL = std::chrono::seconds{10};
  const unsigned int MAX_RATE_LIMIT_REQS = 20;
}

DistributedCacheManager::DistributedCacheManager(const std::vector<std::string>& cloudStorageServices) {
  // Initialize the cache with an empty map.
  _cache = Cache{};

  // Create a vector of HTTP clients for each cloud storage service.
  for (const auto& cloudService : cloudStorageServices) {
    _cloudStorageClients.emplace_back(std::make_unique<HttpClient>(cloudService));
  }
}

DistributedCacheManager::~DistributedCacheManager() = default;

void DistributedCacheManager::addEntry(const std::string& key, const std::string& value,
                                      const std::chrono::seconds ttl) {
  // Acquire the lock before modifying the cache.
  LockGuard lock(_mutex);

  // Check if the entry already exists in the cache. If it does, update its TTL and return.
  auto it = _cache.find(key);
  if (it != _cache.end()) {
    it->second.expirationTime = std::chrono::system_clock::now() + ttl;
    return;
  }

  // Add the new entry to the cache and update its TTL.
  _cache[key] = Entry{value, std::chrono::system_clock::now() + ttl};
}

void DistributedCacheManager::getEntry(const std::string& key) {
  LockGuard lock(_mutex);
  // Check if the entry exists in the cache. If it does, return its value and update its TTL.
  auto it = _cache.find(key);
  if (it != _cache.end()) {
    it->second.expirationTime = std::chrono::system_clock::now() + DEFAULT_TTL;
    return it->second.value;
  }

  // Check if the cache has reached its maximum size. If so, evict expired entries.
  if (_cache.size() >= MAX_CACHE_SIZE) {
    evictExpiredEntries();
  }

  // Add the new entry to the cache and update its TTL.
  _cache[key] = Entry{value, std::chrono::system_clock::now() + DEFAULT_TTL};
}

void DistributedCacheManager::deleteEntry(const std::string& key) {
  LockGuard lock(_mutex);
  // Check if the entry exists in the cache. If it does, remove it and return.
  auto it = _cache.find(key);
  if (it != _cache.end()) {
    _cache.erase(it);
    return;
  }
}

void DistributedCacheManager::evictExpiredEntries() {
  // Acquire the lock before modifying the cache.
  LockGuard lock(_mutex);

  auto now = std::chrono::system_clock::now();
  for (auto it = _cache.begin(); it != _cache.end();) {
    if (it->second.expirationTime <= now) {
      // Remove the expired entry from the cache.
      it = _cache.erase(it);
    } else {
      ++it;
    }
  }
}
