// Define the FSA state list data structure
typedef struct fsa_state {
    uint32_t id;
    char* name;
} fsa_state;

// Define the FSA state list management functions
void fsa_add(fsa_state* state);
bool fsa_remove(uint32_t id);
bool fsa_update(uint32_t id, const char* new_name);
const fsa_state* fsa_get(uint32_t id);
size_t fsa_size();

// Define the FSA state list synchronization functions
