int64_t fsa_get_retry_timeout(uint32_t id);
void fsa_clear_retry_timeout(uint32_t id);

// Define the FSA state list rate limiting functions
bool fsa_rate_limit(uint32_t id, const char* new_name);
int64_t fsa_get_rate_limit_timeout(uint32_t id);
void fsa_clear_rate_limit_timeout(uint32_t id);

