void fsa_debug(const char* message);
void fsa_error(const char* message);

// Implement the FSA state list management functions
void fsa_add(fsa_state* state) {
    // Add the new state to the FSA state list
    if (state->name == NULL) {
        return;
    }
    pthread_mutex_lock(&fsa_mutex);
    bool found = false;
    for (size_t i = 0; i < fsa_states.size(); ++i) {
        if (strcmp(fsa_states[i].name, state->name) == 0) {
            found = true;
            break;
        }
    }
    if (!found) {
        fsa_states.push_back(*state);
    }
    pthread_mutex_unlock(&fsa_mutex);
}

bool fsa_remove(uint32_t id) {
    // Remove the specified state from the FSA state list
    bool found = false;
    pthread_mutex_lock(&fsa_mutex);
    for (size_t i = 0; i < fsa_states.size(); ++i) {
        if (fsa_states[i].id == id) {
            found = true;
            break;
        }
    }
    if (!found) {
        pthread_mutex_unlock(&fsa_mutex);
        return false;
    }
    fsa_states.erase(fsa_states.begin() + i);
    pthread_mutex_unlock(&fsa_mutex);
    return true;
}

