    // Update the specified state in the FSA state list
    bool found = false;
    pthread_mutex_lock(&fsa_mutex);
    for (size_t i = 0; i < fsa_states.size(); ++i) {
        if (fsa_states[i].id == id) {
            found = true;
            break;
        }
    }
    if (!found) {
        pthread_mutex_unlock(&fsa_mutex);
        return false;
    }
    fsa_states[i].name = new_name;
    pthread_mutex_unlock(&fsa_mutex);
    return true;
}

const fsa_state* fsa_get(uint32_t id) {
    // Get the specified state from the FSA state list
    bool found = false;
    pthread_mutex_lock(&fsa_mutex);
    for (size_t i = 0; i < fsa_states.size(); ++i) {
        if (fsa_states[i].id == id) {
            found = true;
            break;
        }
    }
    pthread_mutex_unlock(&fsa_mutex);
    return found ? &fsa_states[i] : NULL;
}

size_t fsa_size() {
    // Get the number of states in the FSA state list
    size_t size = 0;
    pthread_mutex_lock(&fsa_mutex);
    for (size_t i = 0; i < fsa_states.size(); ++i) {
