function traverseDOM(root, selector, testFn) {
  const matches = [];
  (function traverse(node) {
    if (!node || !node.childNodes) return;
    for (let i = 0; i < node.childNodes.length; i++) {
      const childNode = node.childNodes[i];
      if (testFn(childNode)) {
        matches.push(childNode);
      }
      traverse(childNode);
    }
  })(root);
  return matches;
}

