// Modular C++ library for managing a connection pool in a high-throughput, distributed transaction processing environment

#include <iostream>
#include <thread>
#include <mutex>
#include <condition_variable>
#include <chrono>

using namespace std;

// Thread-safe connection pool class
class ConnectionPool {
    private:
        // Mutex and condition variable for synchronizing access to the pool
        mutex _mutex;
        condition_variable _cv;

        // Vector of available connections
        vector<shared_ptr<Connection>> _availableConnections;

        // Map of busy connections
        map<string, shared_ptr<Connection>> _busyConnections;

        // Maximum number of concurrent connections
        int _maxConcurrency;

    public:
        // Constructor initializes the connection pool with a maximum concurrency of 500,000
        ConnectionPool() : _maxConcurrency(500000) {}

        // Destructor frees all connections in the pool
        ~ConnectionPool() {
            for (auto& conn : _availableConnections) {
                conn->close();
            }
        }

        // Returns a shared pointer to an available connection, blocking until one is available
        shared_ptr<Connection> getConnection() {
            unique_lock<mutex> lock(_mutex);
            while (_availableConnections.empty()) {
                _cv.wait(lock);
            }
            auto conn = _availableConnections.back();
            _availableConnections.pop_back();
            _busyConnections[conn->getId()] = conn;
            return conn;
        }

        // Returns a shared pointer to a busy connection, or nullptr if no such connection exists
        shared_ptr<Connection> getBusyConnection(string id) {
            unique_lock<mutex> lock(_mutex);
            auto it = _busyConnections.find(id);
            if (it == _busyConnections.end()) {
                return nullptr;
            }
            return it->second;
        }

        // Marks a connection as available, making it available to be used again
        void releaseConnection(shared_ptr<Connection> conn) {
            unique_lock<mutex> lock(_mutex);
            _availableConnections.push_back(conn);
            _busyConnections.erase(conn->getId());
            _cv.notify_all();
        }
};

// Connection class representing a connection to the database or cloud service
class Connection {
    private:
        // Unique identifier for this connection
        string _id;

        // Thread-safe reference counter for concurrent access to the connection
        atomic<int> _refCount;

        // Flag indicating whether the connection is closed
        bool _closed;

        // Pointer to a thread-safe pool for managing connections
        shared_ptr<ConnectionPool> _pool;

    public:
        // Constructor initializes the connection with an ID and sets it as available in the pool
        Connection(string id, shared_ptr<ConnectionPool> pool) : _id(id), _refCount(0), _closed(false), _pool(pool) {
            _pool->addAvailableConnection(shared_from_this());
        }

        // Destructor closes the connection if it is not already closed and removes it from the pool
        ~Connection() {
            close();
            _pool->removeAvailableConnection(shared_from_this());
        }

        // Returns the unique identifier for this connection
        string getId() const { return _id; }

        // Increments the reference count and returns a shared pointer to this connection
        shared_ptr<Connection> acquire() {
            _refCount.fetch_add(1);
            return shared_from_this();
        }

        // Decrements the reference count and returns true if the connection is no longer in use
        bool release() {
            auto refCount = _refCount.fetch_sub(1);
            return refCount == 0;
        }

        // Closes the connection and sets it as closed
        void close() {
            _closed = true;
        }
};
