#include <errno.h>
#include <pthread.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>

#define MAX_CONNECTIONS 100000
#define PORT 8080
#define BUFFER_SIZE 256

struct LTE_DL_CCCH_MESSAGE_T {
    int id;
    char *data;
};

struct ConnectionPool {
    struct LTE_DL_CCCH_MESSAGE_T *messages[MAX_CONNECTIONS];
    pthread_mutex_t mutex;
};

struct ConnectionPool pool = {
    .messages = malloc(sizeof(struct LTE_DL_CCCH_MESSAGE_T *) * MAX_CONNECTIONS),
    .mutex = PTHREAD_MUTEX_INITIALIZER
};

int addConnection(struct LTE_DL_CCCH_MESSAGE_T *message) {
    int i;
    pthread_mutex_lock(&pool.mutex);
    for (i = 0; i < MAX_CONNECTIONS; i++) {
        if (!pool.messages[i]) {
            pool.messages[i] = message;
            break;
        }
    }
    pthread_mutex_unlock(&pool.mutex);
    return i;
}

int removeConnection(int id) {
    int ret = 0;
    pthread_mutex_lock(&pool.mutex);
    if (pool.messages[id]) {
        free(pool.messages[id]);
        pool.messages[id] = NULL;
        ret = 1;
    }
    pthread_mutex_unlock(&pool.mutex);
    return ret;
}

int getConnection(struct LTE_DL_CCCH_MESSAGE_T **message, int id) {
    int ret = 0;
    pthread_mutex_lock(&pool.mutex);
    if (pool.messages[id]) {
        *message = pool.messages[id];
        ret = 1;
    }
    pthread_mutex_unlock(&pool.mutex);
    return ret;
}

int handleConnection(struct ConnectionPool *pool, int id) {
    struct LTE_DL_CCCH_MESSAGE_T *message;
    int ret = 0;

    // handle message
    if (getConnection(&message, id)) {
        printf("Received message from connection %d: %s\n", id, message->data);
        free(message);
        ret = removeConnection(id);
    }

    return ret;
}

void *handleConnections(void *args) {
    struct ConnectionPool *pool = args;
    int i;
    for (i = 0; i < MAX_CONNECTIONS; i++) {
        handleConnection(pool, i);
    }
    return NULL;
}

int main() {
    pthread_t thread;
    struct ConnectionPool *pool = &pool;

    // start handling connections in a separate thread
    pthread_create(&thread, NULL, handleConnections, pool);

    // listen for incoming connections
    int sockfd;
    struct sockaddr_in serv_addr;
    sockfd = socket(AF_INET, SOCK_STREAM, 0);
    bzero((char *)&serv_addr, sizeof(serv_addr));
    serv_addr.sin_family = AF_INET;
    serv_addr.sin_addr.s_addr = INADDR_ANY;
    serv_addr.sin_port = htons(PORT);
    bind(sockfd, (struct sockaddr *)&serv_addr, sizeof(serv_addr));
    listen(sockfd, 3);

    while (1) {
        struct sockaddr_in client_addr;
        int clilen = sizeof(client_addr);
        int newsockfd = accept(sockfd, (struct sockaddr *)&client_addr, &clilen);

        // handle connection and close the socket
        struct LTE_DL_CCCH_MESSAGE_T *message = malloc(sizeof(struct LTE_DL_CCCH_MESSAGE_T));
        message->id = addConnection(message);
        send(newsockfd, message, BUFFER_SIZE, 0);
        close(newsockfd);
    }

    return 0;
}
