// Define the message structure to hold LTE DL CCCH messages
typedef struct {
    unsigned char msg[2048];
} LTE_DL_CCCH_MESSAGE_T;

// Define the pool structure to manage dynamic pools of message structures
typedef struct {
    int size; // Number of messages in the pool
    int count; // Number of used messages in the pool
    LTE_DL_CCCH_MESSAGE_T *messages; // Pointer to the array of message structures
