    "queue_size": 100,
    "processor_threads": 4,
    "sink_threads": 2
}

# Create a logging queue
log_queue = queue.Queue(maxsize=logging_config["queue_size"])

# Start the logging framework
def start_logging():
    for processor in processors:
        t = threading.Thread(target=processors[processor].run, args=(logging_config["queue_size"],))
        t.daemon = True
        t.start()

    for sink in sinks:
        t = threading.Thread(target=sinks[sink].run, args=(logging_config["queue_size"],))
        t.daemon = True
        t.start()

# Logging function
