struct LogEntry {
  std::chrono::time_point<std::chrono::system_clock> timestamp;
  std::string severityLevel;
  std::string message;
};

class LoggingManager {
 public:
  // Add an event to the log
  void addEvent(const std::string_view& message, const std::chrono::time_point<std::chrono::system_clock>& timestamp, const std::string_view& severityLevel) {
    // Create a new log entry
    LogEntry entry{timestamp, severityLevel, message};

    // Add the log entry to the in-memory vector
    _logEntries.push_back(std::make_unique<LogEntry>(entry));

    // Asynchronously send the log entry to the external logging service
    std::async([this] {
      std::string jsonString = serializeLogEntryToJSON(_logEntries.back());
      _externalLogger->log(jsonString);
    });
  }

 private:
  // Define a serializer for log entries to JSON
  std::string serializeLogEntryToJSON(const LogEntry& entry) {
    // Implement your own custom serializer using a library like rapidjson or nlohmann_json
    return "{\"timestamp\": \"" + entry.timestamp.time_since_epoch().count() + "\", \"severityLevel\": \"" + entry.severityLevel + "\", \"message\": \"" + entry.message + "\"}";
  }

  // Define a vector of unique pointers to log entries in memory
  std::vector<std::unique_ptr<LogEntry>> _logEntries;

  // Define an external logging service for asynchronous event aggregation and archival
  ExternalLogger* _externalLogger;
};
