            Self {
                accounts: Default::default(),
            }
        }

        pub fn get(&self, user_id: &str) -> Option<&str> {
            self.accounts.get(user_id).map(|a| a.as_ref())
        }

        pub fn insert(&mut self, user_id: String, account: String) {
            self.accounts.insert(user_id, account);
        }

