        }
    }
}

mod streaming_csv_data {
    use std::io;
    use std::sync::Arc;
    use std::thread;
    use std::time::{Duration, Instant};

    pub struct StreamingCsvData<T> {
        reader: io::BufReader<T>,
        line_buffer: Vec<u8>,
        csv_parser: csv::StringRecord<'static>,
    }

    impl<T: io::Read + io::Seek> StreamingCsvData<T> {
        pub fn new(reader: T) -> Self {
            Self {
                reader: io::BufReader::new(reader),
                line_buffer: Vec::new(),
                csv_parser: csv::StringRecord::new(),
            }
        }

        pub async fn read(&mut self) -> Result<csv::StringRecord<'static>, csv::Error> {
            let mut bytes = [0u8; 1];
            loop {
                match self.reader.read_exact(&mut bytes).await? {
                    1 => {
                        if bytes[0] == b'\n' {
                            break;
                        }
                        self.line_buffer.push(bytes[0]);
                    }
                    0 => return Err(csv::Error::new("unexpected end of stream")),
                    _ => unreachable!(),
                }
            }
            let csv_parser = self.csv_parser.read_from_buf(&mut self.line_buffer).await?;
            Ok(csv_parser)
        }

        pub fn close(&mut self) {
            self.reader.close();
        }
    }
}

