[PYTHON]
```python
import argparse
from collections import deque

class Node:
    def __init__(self, value):
        self.value = value
        self.next = None

def solve(input):
    # parse input
    nodes = []
    for line in input.splitlines():
        nodes.append(Node(line))

    # build graph
    graph = {}
    for i in range(len(nodes)):
        node = nodes[i]
        if node.value not in graph:
            graph[node.value] = []
        for j in range(i+1, len(nodes)):
            next_node = nodes[j]
            if node.value + next_node.value == 2020:
                graph[node.value].append(next_node.value)

    # find path
    for start in graph:
        queue = deque([start])
        while queue:
            node = queue.popleft()
            if node not in graph:
                continue
            for next_node in graph[node]:
                queue.append(next_node)
            if len(queue) == 2:
                return start * next_node

if __name__ == "__main__":
    # get input
    parser = argparse.ArgumentParser(description='AOC 2020 Day 12')
    parser.add_argument('input', nargs='?', default=None, help='Input file to read ("-" for stdin, default: %(default)s)')
    args = parser.parse_args()
    if args.input == '-':
        input = sys.stdin.read().strip()
    else:
        with open(args.input) as f:
            input = ''.join([line for line in f])

    # solve
    print(solve(input))
```
