using namespace std;

// Constants for the system
const int MAX_EVENTS_PER_SEC = 1000000; // Max events per second
const int MAX_CSV_RECORDS_PER_SEC = 1000000; // Max CSV records per second
const int MIN_THREADS = 2; // Minimum number of threads for concurrency
const int MAX_THREADS = 8; // Maximum number of threads for concurrency
const string LOG_FILENAME = "event_log.txt"; // Filename for the event log file

// Structures and classes for events and CSV records
struct Event {
    string sourceIPAddress;
    int severity;
    string type;
    string message;
};

struct CSVRecord {
    vector<string> fields;
    map<string, string> metadata;
};

class CSVParser {
private:
    ifstream fileStream;
    string line;
public:
    CSVParser(const string& filename) : fileStream(filename, ios::in) {}
    CSVRecord parseNextRecord() {
        vector<string> fields;
        map<string, string> metadata;
        while (getline(fileStream, line)) {
            if (line.empty()) continue;
            size_t commaIndex = line.find(',');
            if (commaIndex == string::npos) break; // No more records
            fields.push_back(line.substr(0, commaIndex));
            metadata[fields[0]] = line.substr(commaIndex + 1);
        }
        return {fields, metadata};
    }
};

// Class for the event stream manager
class EventStreamManager {
private:
    mutex mutex; // Mutex for thread safety
    condition_variable condVar; // Condition variable for signaling events
    vector<Event> events; // Vector of events to process
    vector<CSVRecord> csvRecords; // Vector of CSV records to process
public:
    EventStreamManager() : mutex(), condVar(), events(), csvRecords() {}
    ~EventStreamManager() {
        // Clean up any remaining events or CSV records
        events.clear();
        csvRecords.clear();
    }
    void addEvent(const Event& event) {
        unique_lock<mutex> lock(mutex);
        events.push_back(event);
        condVar.notify_one(); // Signal a new event to process
    }
    void addCSVRecord(const CSVRecord& record) {
        unique_lock<mutex> lock(mutex);
        csvRecords.push_back(record);
        condVar.notify_one(); // Signal a new CSV record to process
    }
    bool hasEvents() {
        unique_lock<mutex> lock(mutex);
        return !events.empty();
    }
    bool hasCSVRecords() {
        unique_lock<mutex> lock(mutex);
        return !csvRecords.empty();
    }
    Event getNextEvent() {
        unique_lock<mutex> lock(mutex);
        while (events.empty()) condVar.wait(lock); // Wait for a new event
        Event event = events[0];
        events.erase(events.begin());
        return event;
    }
    CSVRecord getNextCSVRecord() {
        unique_lock<mutex> lock(mutex);
        while (csvRecords.empty()) condVar.wait(lock); // Wait for a new CSV record
        CSVRecord record = csvRecords[0];
        csvRecords.erase(csvRecords.begin());
        return record;
    }
};

// Class for the event processor
class EventProcessor {
private:
    int numThreads; // Number of threads to use for processing events
    mutex mutex; // Mutex for thread safety
    condition_variable condVar; // Condition variable for signaling new events
    vector<Event> processedEvents; // Vector of processed events
public:
    EventProcessor(int numThreads) : numThreads(numThreads), mutex(), condVar(), processedEvents() {}
    ~EventProcessor() {
        // Clean up any remaining events or CSV records
        processedEvents.clear();
    }
    void addEvent(const Event& event) {
        unique_lock<mutex> lock(mutex);
        processedEvents.push_back(event);
        condVar.notify_all(); // Signal new event to process
    }
    bool hasProcessedEvents() {
        unique_lock<mutex> lock(mutex);
        return !processedEvents.empty();
    }
    Event getNextProcessedEvent() {
        unique_lock<mutex> lock(mutex);
        while (processedEvents.empty()) condVar.wait(lock); // Wait for a new event
        Event event = processedEvents[0];
        processedEvents.erase(processedEvents.begin());
        return event;
    }
};

