    }
    bool hasProcessedRecords() {
        unique_lock<mutex> lock(mutex);
        return !processedRecords.empty();
    }
    CSVRecord getNextProcessedRecord() {
        unique_lock<mutex> lock(mutex);
        while (processedRecords.empty()) condVar.wait(lock); // Wait for a new CSV record
