int validate_oauth2_response(json_object *response) {
    int ret = 0;
    json_object *access_token, *expires_in, *token_type, *refresh_token;

    // Check if the response is a JSON object
    if (!json_object_is_type(response, json_type_object)) {
        ret = -1;
        goto error;
    }

    // Get the access token field
