    public class DataProcessor
    {
        private readonly WebSocket _webSocket;
        private readonly CancellationTokenSource _cancellationTokenSource = new CancellationTokenSource();
        private readonly ConcurrentQueue<string> _messageQueue = new ConcurrentQueue<string>();
        private readonly IList<string> _processedData = new List<string>();
        private readonly Stopwatch _stopwatch = new Stopwatch();

        public DataProcessor(WebSocket webSocket)
        {
            _webSocket = webSocket;
        }

        public async Task ProcessDataAsync()
        {
            _stopwatch.Start();

            try
            {
                while (!_cancellationTokenSource.IsCancellationRequested)
                {
                    string message = await ReadMessageAsync(_webSocket);
                    if (message != null)
                    {
                        // Process the message
                        await ProcessMessageAsync(message);
                    }
                }
            }
            catch (WebSocketException ex)
            {
                _cancellationTokenSource.Cancel();
                throw new DataProcessingException("Error occurred while processing data", ex);
            }
            finally
            {
                _stopwatch.Stop();
            }
        }

        private async Task<string> ReadMessageAsync(WebSocket webSocket)
        {
            // Read message from the web socket
            string message = await webSocket.ReceiveStringAsync(_cancellationTokenSource.Token);

            if (message == null)
            {
                _cancellationTokenSource.Cancel();
                return null;
            }

            // Add message to the queue
            _messageQueue.Enqueue(message);

            return message;
        }

        private async Task ProcessMessageAsync(string message)
        {
            try
            {
                // Parse the message and extract the data
                var parsedData = ParseMessage(message);

                // Add the data to the processed data list
                _processedData.AddRange(parsedData);

                // Remove the message from the queue
                _messageQueue.TryDequeue(out string _);
            }
            catch (Exception ex)
            {
                // Log the error and throw a DataProcessingException
                LogError("Error occurred while processing data", ex);
                throw new DataProcessingException("Error occurred while processing data", ex);
            }
        }

        private IList<string> ParseMessage(string message)
        {
            // Implement your own parsing logic here
            return message.Split(',').Select(x => x.Trim()).ToList();
        }

        private void LogError(string message, Exception ex)
        {
            // Implement your own logging mechanism here
            Console.WriteLine($"{message}: {ex}");
        }
    }
}
