import java.net.*;
import java.nio.channels.*;
import java.util.concurrent.*;
import java.util.logging.*;

public class LTE_DL_CCCH_MESSAGE_POOL {
    private static final int MAX_THREADS = 10000;
    private static final int TIMEOUT_MS = 5000;
    private static final int BROKER_TYPE = MessageBrokerType.RabbitMQ;

    private static final ExecutorService executor = new ThreadPoolExecutor(MAX_THREADS, MAX_THREADS, TIMEOUT_MS, TimeUnit.MILLISECONDS, new LinkedBlockingQueue<Runnable>());
    private static final Map<Integer, MessageBroker> brokers = new ConcurrentHashMap<>();
    private static final AtomicInteger nextId = new AtomicInteger(0);

    public static void establishConnection(String remoteAddress) throws IOException {
        int id = nextId.getAndIncrement();
        Channel channel = SocketChannel.open(new InetSocketAddress(remoteAddress, 5672));
        MessageBroker broker = new MessageBroker(id, channel);
        brokers.put(id, broker);
    }

    public static void sendMessage(String message) {
        int id = nextId.getAndIncrement();
        MessageBroker broker = brokers.get(id);
        if (broker == null) {
            establishConnection(message);
        } else {
            broker.sendMessage(message);
        }
    }

    private static class MessageBroker {
        private final int id;
        private final Channel channel;
        private boolean connected = true;

        public MessageBroker(int id, Channel channel) {
            this.id = id;
            this.channel = channel;
        }

        public void sendMessage(String message) {
            if (connected) {
                try {
                    channel.writeAndFlush(message);
                } catch (IOException e) {
                    connected = false;
                    brokers.remove(id);
                    Logger.getLogger("LTE_DL_CCCH_MESSAGE_POOL").log(Level.SEVERE, "Error sending message", e);
                }
            } else {
                try {
                    channel.close();
                } catch (IOException e) {
                    Logger.getLogger("LTE_DL_CCCH_MESSAGE_POOL").log(Level.WARNING, "Error closing channel", e);
                }
            }
        }

        public void handleConnectionStateChange(ChannelState state) {
            if (state == ChannelState.CONNECTED) {
                connected = true;
            } else if (state == ChannelState.DISCONNECTED || state == ChannelState.CLOSED) {
                connected = false;
                brokers.remove(id);
            }
        }
    }
}
```
