            _metricsCollector = metricsCollector;
            _tracer = tracer;
            _cachingStrategy = cachingStrategy;
        }

        public async Task<User> GetUserAsync(string userId, CancellationToken cancellationToken)
        {
            // Try to retrieve the user from the cache first.
            var cachedUser = await _cachingStrategy.GetUserAsync(userId, cancellationToken);

            if (cachedUser != null)
            {
                return cachedUser;
            }

            // If no user was found in the cache, retrieve it from the external service.
            var externalService = GetExternalServiceForUser(userId);

            try
            {
                var response = await externalService.GetUserAsync(userId, cancellationToken);

                if (response != null && !string.IsNullOrEmpty(response.Body))
                {
                    return JsonConvert.DeserializeObject<User>(response.Body);
                }
            }
            catch (Exception ex)
            {
                _logger.LogError(ex, $"Failed to retrieve user with ID {userId} from external service");
            }

            // If no user was found in the cache or retrieved from the external service, return null.
            return null;
        }

        public async Task<User> CreateUserAsync(User user, CancellationToken cancellationToken)
        {
            // Validate the user data before creating it.
            if (!ValidateUserData(user))
            {
                throw new ArgumentException("Invalid user data", nameof(user));
            }

            // Create the user in the external service and update the cache.
            var externalService = GetExternalServiceForUser(user);

            try
            {
                var response = await externalService.CreateUserAsync(user, cancellationToken);

                if (response != null && !string.IsNullOrEmpty(response.Body))
                {
                    _cachingStrategy.UpdateUser(JsonConvert.DeserializeObject<User>(response.Body));
                }
            }
            catch (Exception ex)
            {
                _logger.LogError(ex, $"Failed to create user with ID {user.Id} in external service");
            }

            // Return the created user.
            return user;
        }

        public async Task<User> UpdateUserAsync(string userId, User user, CancellationToken cancellationToken)
        {
            // Validate the user data before updating it.
            if (!ValidateUserData(user))
            {
                throw new ArgumentException("Invalid user data", nameof(user));
            }

            // Update the user in the external service and update the cache.
            var externalService = GetExternalServiceForUser(userId);

            try
            {
                var response = await externalService.UpdateUserAsync(userId, user, cancellationToken);

                if (response != null && !string.IsNullOrEmpty(response.Body))
                {
                    _cachingStrategy.UpdateUser(JsonConvert.DeserializeObject<User>(response.Body));
                }
            }
            catch (Exception ex)
            {
                _logger.LogError(ex, $"Failed to update user with ID {userId} in external service");
            }

            // Return the updated user.
            return user;
        }

        public async Task<User> DeleteUserAsync(string userId, CancellationToken cancellationToken)
        {
            // Delete the user from the cache first.
            _cachingStrategy.DeleteUser(userId);

            // If no user was found in the cache, delete it from the external service.
            var externalService = GetExternalServiceForUser(userId);

            try
            {
                var response = await externalService.DeleteUserAsync(userId, cancellationToken);

                if (response != null && !string.IsNullOrEmpty(response.Body))
                {
                    _cachingStrategy.UpdateUser(JsonConvert.DeserializeObject<User>(response.Body));
                }
            }
            catch (Exception ex)
            {
                _logger.LogError(ex, $"Failed to delete user with ID {userId} from external service");
            }

            // Return the deleted user.
            return null;
        }

        private IExternalService GetExternalServiceForUser(string userId)
        {
            // Get the external service for the specified user ID.
            var externalService = _externalServices.FirstOrDefault(s => s.IsAuthorizedForUser(userId));

            if (externalService == null)
            {
                throw new ArgumentException($"No authorized external service found for user with ID {userId}", nameof(userId));
            }

            return externalService;
        }

        private bool ValidateUserData(User user)
        {
            // Validate the user data before creating or updating it.
            if (string.IsNullOrEmpty(user.Id))
            {
                throw new ArgumentException("Invalid user ID", nameof(user));
            }

            if (string.IsNullOrEmpty(user.Name))
            {
                throw new ArgumentException("Invalid user name", nameof(user));
            }

            return true;
        }
    }
}
