#define MAX_MESSAGES 1000

typedef struct LTE_DL_CCCH_MESSAGE_T {
    int id;
    char* data;
} LTE_DL_CCCH_MESSAGE_T;

// Message storage
LTE_DL_CCCH_MESSAGE_T message_storage[MAX_MESSAGES];

// Mutex for accessing the message storage
pthread_mutex_t message_mutex = PTHREAD_MUTEX_INITIALIZER;

// Semaphore for signaling when a message is available
sem_t message_semaphore;

// Function to add a new message to the pool
void add_message(LTE_DL_CCCH_MESSAGE_T* message) {
    pthread_mutex_lock(&message_mutex);
    int index = -1;
    for (int i = 0; i < MAX_MESSAGES; i++) {
        if (message_storage[i].data == NULL) {
            index = i;
            break;
        }
    }
    if (index >= 0) {
        message_storage[index] = *message;
        sem_post(&message_semaphore);
    } else {
        printf("Error: message pool is full\n");
    }
    pthread_mutex_unlock(&message_mutex);
}

// Function to retrieve a message from the pool
LTE_DL_CCCH_MESSAGE_T* get_message() {
    LTE_DL_CCCH_MESSAGE_T* message = NULL;
    pthread_mutex_lock(&message_mutex);
    if (sem_wait(&message_semaphore) == 0) {
        for (int i = 0; i < MAX_MESSAGES; i++) {
            if (message_storage[i].data != NULL) {
                message = &message_storage[i];
                break;
            }
        }
    }
    pthread_mutex_unlock(&message_mutex);
    return message;
}

// Function to delete a message from the pool
void delete_message(int id) {
    pthread_mutex_lock(&message_mutex);
    for (int i = 0; i < MAX_MESSAGES; i++) {
        if (message_storage[i].id == id) {
            message_storage[i].data = NULL;
            break;
        }
    }
    pthread_mutex_unlock(&message_mutex);
}

// Function to update the message storage based on demand
void adjust_message_storage(int new_size) {
    if (new_size > MAX_MESSAGES) {
        printf("Error: message pool size exceeds maximum\n");
        return;
    }
    pthread_mutex_lock(&message_mutex);
    for (int i = new_size - 1; i >= 0; i--) {
        if (message_storage[i].data != NULL) {
            delete_message(message_storage[i].id);
        }
    }
    pthread_mutex_unlock(&message_mutex);
}

// Function to handle asynchronous event notifications from the message broker
void handle_event(LTE_DL_CCCH_MESSAGE_T* message) {
    add_message(message);
}

int main() {
    // Initialize the message storage and semaphore
    for (int i = 0; i < MAX_MESSAGES; i++) {
        message_storage[i].data = NULL;
    }
    sem_init(&message_semaphore, 0, 0);

    // Start the message broker thread
    pthread_t message_broker_thread;
    int status = pthread_create(&message_broker_thread, NULL, &handle_event, NULL);
    if (status != 0) {
        printf("Error: unable to create message broker thread\n");
        return 1;
    }

    // Start the message processing thread
    pthread_t message_processing_thread;
    status = pthread_create(&message_processing_thread, NULL, &process_messages, NULL);
    if (status != 0) {
