use std::sync::Arc;
use std::thread;
use tokio::sync::{Mutex, Condvar};

#[derive(Debug)]
struct LTE_DL_CCCH_MESSAGE_T {
    // ...
}

struct MessagePool<Message> {
    messages: Vec<Arc<Mutex<Message>>>,
    condvar: Arc<Condvar>,
}

impl<Message> MessagePool<Message> {
    fn new() -> Self {
        Self {
            messages: Vec::new(),
            condvar: Arc::new(Condvar::new()),
        }
    }

    fn push(&mut self, message: Arc<Mutex<Message>>) {
        self.messages.push(message);
        self.condvar.notify_all();
    }

    fn pop(&mut self) -> Option<Arc<Mutex<Message>>> {
        if let Some((index, message)) = self.messages.iter().enumerate().find(|(_, message)| {
            Arc::strong_count(message) == 1
        }) {
            self.messages.swap_remove(index);
            return Some(message);
        }
        None
    }
}

struct LTE_DL_CCCH_MESSAGE_POOL {
    messages: MessagePool<LTE_DL_CCCH_MESSAGE_T>,
    message_broker: Arc<MessageBroker>,
}

impl LTE_DL_CCCH_MESSAGE_POOL {
    fn new(message_broker: Arc<MessageBroker>) -> Self {
        Self {
            messages: MessagePool::new(),
            message_broker,
        }
    }

    async fn handle_messages(&mut self) {
        loop {
            let message = self.pop().await;
            if let Some(message) = message {
                // Handle the message using the message broker
                self.message_broker.handle_message(message).await;
            } else {
                // Wait for a new message to arrive
                self.condvar.wait().await;
            }
        }
    }
}
```
