            // Check if the data is already cached and return it if possible
            match self.cache.get(value["id"].as_str()) {
                Some(cached_data) => {
                    processed_data.push(cached_data.clone());
                    continue;
                }
                None => {}
            }

            // Process the data and cache it if necessary
            let processed_value = self.process_single_data(value)?;
            if let Some(id) = value["id"].as_str() {
                self.cache.insert(id.to_string(), processed_value.clone());
            }
            processed_data.push(processed_value);
        }

        Ok(processed_data)
    }

    fn process_single_data(&mut self, value: &Value) -> Result<Value, DataProcessingError> {
        // Check if the data is valid and handle discrepancies and duplicates as necessary
        if !self.validate_data(value) {
            return Err(DataProcessingError::InvalidData);
