    // Check if the log data is null or if it needs to be resized
    if (log_data == NULL || strlen(log_data) + sizeof(struct LogEntry) > max_log_size) {
        // Allocate new memory for the log data and copy the existing entries
        char* new_log_data = malloc(max_log_size);
        memcpy(new_log_data, log_data, strlen(log_data));
        free(log_data);
        log_data = new_log_data;
    }

    // Add the new entry to the log data
    struct LogEntry* new_entry = (struct LogEntry*) (log_data + strlen(log_data));
    *new_entry = *entry;
