// C++ Library Module for Dynamic Pool of LTE DL CCCH Messages

#include <mutex>
#include <vector>
#include <unordered_map>
#include <atomic>
#include <thread>
#include <condition_variable>
#include <iostream>
#include <fstream>
#include <sstream>
#include <memory>
#include <functional>

// Forward Declarations
class LTE_DL_CCCH_Message;
class MessageBroker;

// Mutex for thread safety
std::mutex messageLock;

// Vector of messages in the pool
std::vector<LTE_DL_CCCH_Message*> messagePool;

// Map of threads to their associated messages
std::unordered_map<std::thread::id, LTE_DL_CCCH_Message*> threadMap;

// Atomic variable for number of active threads
std::atomic<int> activeThreads;

// Condition variable for signaling when a message is available
std::condition_variable messageAvailable;

// Function to acquire a message from the pool
LTE_DL_CCCH_Message* acquireMessage(std::thread::id threadId) {
    // Lock the message pool and wait until a message is available
    std::unique_lock<std::mutex> lock(messageLock);
    while (messagePool.empty()) {
        messageAvailable.wait(lock);
    }

    // Get the next message in the pool
    LTE_DL_CCCH_Message* message = messagePool.back();
    messagePool.pop_back();

