    int32_t id;
    string payload;
};

// Define a pool of LTE DL CCCH messages
class LTE_DL_CCCH_MessagePool {
public:
    // Constructor
    LTE_DL_CCCH_MessagePool(int numMessages = 50000) : messages_(numMessages), freeList_(numMessages) {}

    // Allocate a new message
    LTE_DL_CCCH_MESSAGE* allocate() {
        unique_lock<mutex> lock(mutex_);
        while (freeList_.empty()) {
            conditionVariable_.wait(lock);
        }

        int32_t id = freeList_.front();
        LTE_DL_CCCH_MESSAGE* message = &messages_[id];
        freeList_.pop_front();
        return message;
    }

    // Free a message
    void free(LTE_DL_CCCH_MESSAGE* message) {
        unique_lock<mutex> lock(mutex_);
        int32_t id = message->id;
        freeList_.push_back(id);
        conditionVariable_.notify_one();
    }

private:
    // The pool of messages
    vector<LTE_DL_CCCH_MESSAGE> messages_;

    // A list of free message IDs
    deque<int32_t> freeList_;

    // Mutex and condition variable for synchronizing access to the pool
    mutex mutex_;
    condition_variable conditionVariable_;
};

// Define a cache class to store LTE DL CCCH messages
class LTE_DL_CCCH_MessageCache {
public:
    // Constructor
    LTE_DL_CCCH_MessageCache(int numMessages = 50000) : pool_(numMessages), cache_(numMessages) {}

    // Allocate a new message and add it to the cache
    LTE_DL_CCCH_MESSAGE* allocate() {
        unique_lock<mutex> lock(mutex_);
        while (cache_.size() == pool_.getSize()) {
            conditionVariable_.wait(lock);
        }

        int32_t id = pool_.allocate();
        cache_.insert({id, {}});
        return &cache_[id];
    }

    // Free a message and remove it from the cache
    void free(LTE_DL_CCCH_MESSAGE* message) {
        unique_lock<mutex> lock(mutex_);
        int32_t id = message->id;
        cache_.erase(id);
        pool_.free(message);
        conditionVariable_.notify_one();
    }

private:
    // The pool of messages
    LTE_DL_CCCH_MessagePool pool_;

    // A map of cached messages
    map<int32_t, LTE_DL_CCCH_MESSAGE> cache_;

    // Mutex and condition variable for synchronizing access to the cache
    mutex mutex_;
    condition_variable conditionVariable_;
};

// Define a class to manage the dynamic pool of LTE DL CCCH messages
class LTE_DL_CCCH_MessageManager {
public:
    // Constructor
    LTE_DL_CCCH_MessageManager(int numMessages = 50000) : cache_(numMessages) {}

    // Allocate a new message
    LTE_DL_CCCH_MESSAGE* allocate() {
        unique_lock<mutex> lock(mutex_);
        while (cache_.size() == pool_.getSize()) {
            conditionVariable_.wait(lock);
        }

        int32_t id = pool_.allocate();
        cache_.insert({id, {}});
        return &cache_[id];
    }

    // Free a message and remove it from the cache
    void free(LTE_DL_CCCH_MESSAGE* message) {
        unique_lock<mutex> lock(mutex_);
        int32_t id = message->id;
        cache_.erase(id);
        pool_.free(message);
        conditionVariable_.notify_one();
    }

private:
    // The pool of messages
    LTE_DL_CCCH_MessagePool pool_;

    // A map of cached messages
    map<int32_t, LTE_DL_CCCH_MESSAGE> cache_;

    // Mutex and condition variable for synchronizing access to the cache
    mutex mutex_;
    condition_variable conditionVariable_;
};
