import java.util.concurrent.Executors;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.TimeUnit;

import org.apache.logging.log4j.Logger;
import org.apache.logging.log4j.LogManager;

import com.google.common.cache.CacheBuilder;
import com.google.common.cache.LoadingCache;

public class TokenValidator {
    private static final Logger logger = LogManager.getLogger(TokenValidator.class);

    // Configuration parameters
    private static final int CONCURRENCY_LEVEL = 10;
    private static final long EXPIRATION_TIME = TimeUnit.MINUTES.toMillis(5);
    private static final int MAXIMUM_TOKENS = 10000;
    private static final float LOAD_FACTOR = 0.75f;

    // Token validation cache
    private LoadingCache<String, Boolean> tokenValidationCache;

    // OAuth2 API clients
    private List<OAuth2Client> oauth2Clients;

    public TokenValidator() {
        this.tokenValidationCache = CacheBuilder.newBuilder()
                .concurrencyLevel(CONCURRENCY_LEVEL)
                .expireAfterWrite(EXPIRATION_TIME, TimeUnit.MILLISECONDS)
                .maximumSize(MAXIMUM_TOKENS)
                .loadFactor(LOAD_FACTOR)
                .build(new TokenValidationCacheLoader());
    }

    public Boolean validateToken(String token) {
        // Check cache first
        if (tokenValidationCache.containsKey(token)) {
            return tokenValidationCache.getIfPresent(token);
        }

        // Validate token with OAuth2 API clients
        for (OAuth2Client client : oauth2Clients) {
            try {
                boolean valid = client.validateToken(token);
                if (valid) {
                    // Cache validation result
                    tokenValidationCache.put(token, valid);
                    return valid;
                }
            } catch (OAuth2ClientException e) {
                logger.error("Error validating token with client {}", client.getName(), e);
            }
        }

        // Token is not valid
        return false;
    }

    public void addOAuth2Client(OAuth2Client client) {
        oauth2Clients.add(client);
    }

    private static class TokenValidationCacheLoader extends CacheLoader<String, Boolean> {
        @Override
        public Boolean load(String token) throws Exception {
            // Validate token with OAuth2 API clients
            for (OAuth2Client client : oauth2Clients) {
                try {
                    boolean valid = client.validateToken(token);
                    if (valid) {
                        return true;
                    }
                } catch (OAuth2ClientException e) {
                    logger.error("Error validating token with client {}", client.getName(), e);
                }
            }

            // Token is not valid
            return false;
        }

        @Override
        public List<String> loadAll(Iterable<? extends String> tokens) {
            // Load all tokens from cache
            List<String> tokenList = new ArrayList<>();
            for (String token : tokens) {
                if (tokenValidationCache.containsKey(token)) {
                    tokenList.add(token);
                }
            }

            // Validate remaining tokens with OAuth2 API clients
            ScheduledExecutorService executor = Executors.newScheduledThreadPool(oauth2Clients.size());
            List<Future<Boolean>> futures = new ArrayList<>();
            for (OAuth2Client client : oauth2Clients) {
                Future<Boolean> future = executor.submit(() -> client.validateToken(token));
                futures.add(future);
            }

            // Wait for all futures to complete and cache validation results
            List<Boolean> valids = new ArrayList<>();
            for (Future<Boolean> future : futures) {
                try {
                    Boolean valid = future.get();
                    if (valid != null && valid) {
                        valids.add(valid);
                    }
                } catch (ExecutionException | InterruptedException e) {
                    logger.error("Error validating token with client {}", client.getName(), e);
                }
            }

            // Cache validation results and return tokens
            for (String token : tokens) {
                if (valids.contains(token)) {
                    tokenValidationCache.put(token, true);
                    tokenList.add(token);
                } else {
                    tokenValidationCache.put(token, false);
                }
            }

            return tokenList;
        }

        @Override
        public Iterable<String> loadAllKeys() {
            // Load all keys from cache
            List<String> keyList = new ArrayList<>();
            for (Map.Entry<String, Boolean> entry : tokenValidationCache.asMap().entrySet()) {
                if (entry.getValue() != null) {
                    keyList.add(entry.getKey());
                }
            }

            return keyList;
        }
    }
}
```
