    std::unordered_map<std::string, std::shared_ptr<TransactionManager>> transactionManagers_;
    std::mutex mutex_;

  public:
    void add(const std::string& id, const std::shared_ptr<TransactionManager>& transactionManager) {
      std::lock_guard<std::mutex> lock(mutex_);
      transactionManagers_.insert({id, transactionManager});
    }

    void remove(const std::string& id) {
      std::lock_guard<std::mutex> lock(mutex_);
      transactionManagers_.erase(id);
    }

    std::shared_ptr<TransactionManager> get(const std::string& id) {
      std::lock_guard<std::mutex> lock(mutex_);
      auto it = transactionManagers_.find(id);
      if (it != transactionManagers_.end()) {
        return it->second;
      }
      return nullptr;
    }
}
