namespace DynamicPlatformUserAccountManager
{
    public class UserAccountManager
    {
        private readonly ILogger<UserAccountManager> _logger;
        private readonly Dictionary<string, ExternalService> _externalServices;
        private readonly Dictionary<string, string> _serviceConfigs;

        public UserAccountManager(ILogger<UserAccountManager> logger)
        {
            _logger = logger;
            _externalServices = new Dictionary<string, ExternalService>();
            _serviceConfigs = new Dictionary<string, string>();
        }

        public void Initialize()
        {
            // Initialize external services and their configurations
            foreach (var service in Enum.GetValues(typeof(ExternalServices)))
            {
                var configKey = $"{service}Config";
                if (_serviceConfigs.ContainsKey(configKey))
                {
                    _externalServices[service] = new ExternalService(_logger, _serviceConfigs[configKey]);
                }
            }
        }

        public async Task<UserAccount> GetUserAccountAsync(string userId)
        {
            var externalUserAccount = await GetExternalUserAccountAsync(userId);
            if (externalUserAccount == null)
            {
                return null;
            }

            return new UserAccount
            {
                Id = userId,
                Email = externalUserAccount.Email,
                Name = externalUserAccount.Name,
                PhoneNumber = externalUserAccount.PhoneNumber,
                Address = externalUserAccount.Address,
                Orders = GetOrders(externalUserAccount)
            };
        }

        private async Task<ExternalUserAccount> GetExternalUserAccountAsync(string userId)
        {
            // Get user account from external service
            foreach (var service in Enum.GetValues(typeof(ExternalServices)))
            {
                try
                {
                    var response = await _externalServices[service].GetUserAccountAsync(userId);
                    if (response != null)
                    {
                        return response;
                    }
                }
                catch (Exception ex)
                {
                    // Log and retry on transient failures
                    _logger.LogError(ex, $"Failed to get user account from service {service}.");
                }
            }

            return null;
        }

        private async Task<List<Order>> GetOrders(ExternalUserAccount externalUserAccount)
        {
            // Get orders for user from external services
            var orders = new List<Order>();
            foreach (var service in Enum.GetValues(typeof(ExternalServices)))
            {
                try
                {
                    var response = await _externalServices[service].GetOrdersAsync(externalUserAccount.Id);
                    if (response != null)
                    {
                        orders.AddRange(response);
                    }
                }
                catch (Exception ex)
                {
                    // Log and retry on transient failures
                    _logger.LogError(ex, $"Failed to get orders for user {externalUserAccount.Id} from service {service}.");
                }
            }

            return orders;
        }

        public async Task<UserOrder> GetUserOrderAsync(string orderId)
        {
            // Get user order from external services
            foreach (var service in Enum.GetValues(typeof(ExternalServices)))
            {
                try
                {
                    var response = await _externalServices[service].GetUserOrderAsync(orderId);
                    if (response != null)
                    {
                        return response;
                    }
                }
                catch (Exception ex)
                {
                    // Log and retry on transient failures
                    _logger.LogError(ex, $"Failed to get user order {orderId} from service {service}.");
                }
            }

            return null;
        }

        public async Task<bool> CreateUserOrderAsync(string userId, Order order)
        {
            // Create user order in external services
            var successful = false;
            foreach (var service in Enum.GetValues(typeof(ExternalServices)))
            {
                try
                {
                    successful = await _externalServices[service].CreateUserOrderAsync(userId, order);
                    if (!successful)
                    {
                        // Log and retry on transient failures
                        _logger.LogError($"Failed to create user order {order.Id} in service {service}.");
                    }
                }
                catch (Exception ex)
                {
                    // Log and retry on transient failures
                    _logger.LogError(ex, $"Failed to create user order {order.Id} in service {service}.");
                }
            }

            return successful;
        }
    }
}
