        thread_count++;

        // Log the conversion attempt and manage resource usage.
        log_conversion_attempt(input_file, output_file);
        manage_resource_usage(memory_consumption);
    }

    // Wait for all threads to complete.
    while (thread_count > 0) {
        pthread_join(*threads, NULL);
        thread_count--;
    }

    // Destroy the conversion semaphore.
    semaphore_destroy(&conversion_semaphore);

