#include <iostream>
#include <string>
#include <vector>
#include <thread>
#include <mutex>
#include <condition_variable>
#include <chrono>
#include <random>
#include <algorithm>
#include <fstream>
#include <sstream>

// Log Entry Structure
struct LogEntry {
    std::string timestamp;
    std::string severity;
    std::string message;
    std::map<std::string, std::string> metadata;
};

// Logger Class
class Logger {
public:
    // Constructor
    Logger() {}

    // Destructor
    ~Logger() {}

    // Insert Log Entry
    void logAndInsert(const LogEntry& newEntry) {
        // Acquire lock on mutex
        std::unique_lock<std::mutex> lock(mutex_);

        // Check for partial match in message field
        auto it = std::search(logEntries_.begin(), logEntries_.end(),
                              [&](const LogEntry& entry) {
                                  return std::regex_search(entry.message, newEntry.message);
                              });

        // Insert new entry immediately after match
        if (it != logEntries_.end()) {
            it = logEntries_.insert(++it, newEntry);
        } else {
            // Append new entry at end of list with default severity "WARNING"
            LogEntry entry{newEntry.timestamp, "WARNING", newEntry.message, newEntry.metadata};
            logEntries_.push_back(entry);
        }
    }

    // Get Log Entries
    std::vector<LogEntry> getLogEntries() {
        return logEntries_;
    }

private:
    // Log Entry Vector
    std::vector<LogEntry> logEntries_;

