#include <random>
#include <thread>
#include <mutex>
#include <unordered_map>

namespace FinancialRNG {
  class MTGenerator {
  public:
    explicit MTGenerator(const std::string& seed) :
      mt_(std::mt19937(std::random_device())),
      distribution_(std::uniform_int_distribution<uint64_t>(0, UINT64_MAX)) {
      if (seed.empty()) {
        // Use a cryptographically secure seed for initialization
        std::string secureSeed = generateSeed();
        mt_.seed(secureSeed);
      } else {
        // Allow explicit seeding for unique streams
        mt_.seed(seed);
      }
    }

    uint64_t getRandomNumber() {
      std::lock_guard<std::mutex> lock(mtx_);
      return distribution_(mt_);
    }

  private:
    // Cryptographically secure seed generation
    static std::string generateSeed() {
      std::random_device rd;
      std::uniform_int_distribution<uint64_t> seedGen(0, UINT64_MAX);
      return std::to_string(seedGen(rd));
    }

  private:
    // Thread-safe resource management and error handling
    static std::mutex mtx_;
    static std::unordered_map<std::string, MTGenerator*> generators_;

    // Resource utilization optimization for scalability
    static const size_t maxConcurrency = 1024;
    static const size_t numStreams = 32;
    static std::vector<std::thread> streams_;
    static std::atomic<bool> shutdown_;

    // Performance optimization: switch between different RNG algorithms
    static bool useMersenneTwister;

    // API contract and dependency injection for system integration
    static void generateSeed(const std::string& seed) {
      MTGenerator generator(seed);
      generators_[seed] = &generator;
    }

    static uint64_t getRandomNumber(const std::string& seed) {
      if (!generators_.count(seed)) {
        throw std::runtime_error("Invalid seed");
      }
      return generators_[seed]->getRandomNumber();
    }

  };

  // API contract and dependency injection for system integration
  void FinancialRNG::generateSeed(const std::string& seed) {
    MTGenerator::generateSeed(seed);
  }

  uint64_t FinancialRNG::getRandomNumber(const std::string& seed) {
    return MTGenerator::getRandomNumber(seed);
  }

  // Resource utilization optimization for scalability
  std::vector<std::thread> FinancialRNG::streams_(maxConcurrency);
  std::atomic<bool> FinancialRNG::shutdown_(false);
  const size_t FinancialRNG::numStreams = 32;

  // Performance optimization: switch between different RNG algorithms
  bool FinancialRNG::useMersenneTwister = true;

  // Thread-safe resource management and error handling
  std::mutex MTGenerator::mtx_;
  std::unordered_map<std::string, MTGenerator*> MTGenerator::generators_;
}
```
