public class DynamicStateLoader {
    private static final Logger LOGGER = Logger.getLogger(DynamicStateLoader.class.getName());
    private static final ExecutorService EXECUTOR_SERVICE = Executors.newCachedThreadPool();
    private static final ConcurrentHashMap<String, Object> CACHE = new ConcurrentHashMap<>();
    private static final long DEFAULT_CACHE_TIMEOUT = 10; // in minutes
    private static final int MAX_RETRIES = 3;
    private static final int RETRY_DELAY = 1000; // in milliseconds

    public Object loadState(String source) throws Exception {
        if (source == null || source.isEmpty()) {
            throw new IllegalArgumentException("Source cannot be null or empty");
        }

        // check cache for state object
        Object state = CACHE.get(source);
        if (state != null) {
            LOGGER.info("Loaded state from cache: " + source);
            return state;
        }

        // load state from file or network endpoint
        try {
            state = loadStateFromFileOrEndpoint(source);
        } catch (Exception e) {
            LOGGER.severe("Error loading state from source: " + source + ", retrying...");
            for (int i = 0; i < MAX_RETRIES; i++) {
                try {
                    Thread.sleep(RETRY_DELAY);
                    state = loadStateFromFileOrEndpoint(source);
                    break;
                } catch (Exception ex) {
                    LOGGER.severe("Error loading state from source: " + source + ", retrying...");
                }
            }
        }

        // cache state object for future use
        CACHE.put(source, state);
        LOGGER.info("Cached state: " + source);

        return state;
    }

    private Object loadStateFromFileOrEndpoint(String source) throws Exception {
        if (source.startsWith("file://")) {
