struct BatchJobsProcessor {
    jobs: Vec<Job>,
    config: Config,
}

impl BatchJobsProcessor {
    fn new(jobs: Vec<Job>, config: Config) -> Self {
        Self { jobs, config }
    }

    async fn process_batch_jobs(&self) -> Result<(), Box<dyn Error>> {
        let mut futures = vec![];
        for job in self.jobs.iter() {
            futures.push(async move {
                // Execute the job asynchronously, with retries and error handling
                let result = job.execute().await;
                if let Err(error) = &result {
                    info!(
                        "Job {} failed with error {:?}",
                        job.id, error
                    );
                } else {
                    info!("Job {} completed successfully", job.id);
                }
            });
        }

        futures::future::join_all(futures).await;

        Ok(())
    }
}

struct Config {
    concurrency_limit: u64,
}

impl Default for Config {
    fn default() -> Self {
        Self {
            concurrency_limit: 10,
        }
    }
}
