// Octree data structure to support high-dimensional spatial partitioning
class Octree {
 public:
  // Constructor that takes in the number of dimensions and the maximum size of the octree
  Octree(int num_dims, int max_size) : num_dims_(num_dims), max_size_(max_size) {}

  // Function to insert a new node into the octree
  void insertNode(const std::vector<double>& coordinates) {
    // Calculate the hash value of the coordinates
    std::string hash = calculateHash(coordinates);

    // Lock the mutex to ensure thread safety
    std::unique_lock<std::mutex> lock(mutex_);

    // Check if the node already exists in the octree
    if (nodes_.find(hash) != nodes_.end()) {
      // If it does, return early without inserting a new node
      return;
    }

    // Create a new node and add it to the octree
    Node* new_node = new Node(coordinates);
    nodes_[hash] = new_node;

    // Unlock the mutex
    lock.unlock();
  }

  // Function to retrieve a node from the octree given its coordinates
  Node* getNode(const std::vector<double>& coordinates) {
    // Calculate the hash value of the coordinates
    std::string hash = calculateHash(coordinates);

    // Lock the mutex to ensure thread safety
    std::unique_lock<std::mutex> lock(mutex_);

    // Check if the node exists in the octree
    auto it = nodes_.find(hash);
    if (it == nodes_.end()) {
      // If it doesn't, return nullptr
      return nullptr;
    }

    // Return the node object
    Node* node = it->second;

    // Unlock the mutex
    lock.unlock();

    // Return the node object
    return node;
  }

  // Function to update a node in the octree given its coordinates and new data
  void updateNode(const std::vector<double>& coordinates, const std::string& new_data) {
    // Calculate the hash value of the coordinates
    std::string hash = calculateHash(coordinates);

    // Lock the mutex to ensure thread safety
    std::unique_lock<std::mutex> lock(mutex_);

    // Check if the node exists in the octree
    auto it = nodes_.find(hash);
    if (it == nodes_.end()) {
      // If it doesn't, return early without updating the node
      return;
    }

    // Update the node object with the new data
    Node* node = it->second;
    node->data_ = new_data;

    // Unlock the mutex
    lock.unlock();
  }

  // Function to remove a node from the octree given its coordinates
  void removeNode(const std::vector<double>& coordinates) {
    // Calculate the hash value of the coordinates
    std::string hash = calculateHash(coordinates);

    // Lock the mutex to ensure thread safety
    std::unique_lock<std::mutex> lock(mutex_);

    // Check if the node exists in the octree
    auto it = nodes_.find(hash);
    if (it == nodes_.end()) {
      // If it doesn't, return early without removing the node
      return;
    }

    // Remove the node object from the octree
