    nodes_.erase(it);

    // Unlock the mutex
    lock.unlock();
  }

 private:
  // Calculate a hash value for the given coordinates using a modular arithmetic function
  std::string calculateHash(const std::vector<double>& coordinates) {
    // Calculate the product of the coordinates modulo the maximum size of the octree
    long long int hash = 1;
    for (int i = 0; i < num_dims_; ++i) {
      hash = (hash * coordinates[i]) % max_size_;
    }
    return std::to_string(hash);
