#include "tesseract-ocr/tesseract.h" // OCR API

// Constants for output formats and DPI settings
const int OUTPUT_FORMAT_PLAIN = 0;
const int OUTPUT_FORMAT_JSON = 1;
const int OUTPUT_FORMAT_HTML = 2;
const int DPI_SETTINGS_LOW = 72;
const int DPI_SETTINGS_MEDIUM = 300;
const int DPI_SETTINGS_HIGH = 600;

// Struct for document metadata
struct DocumentMetadata {
    std::string filename;
    std::string extension;
    size_t fileSize;
    bool isEncrypted;
    bool hasPassword;
    bool isPDF;
