// Class for document processing and extraction
class DocumentProcessor {
public:
    // Constructor
    DocumentProcessor(const std::string& filename, const std::string& extension, const std::string& password) :
        m_filename(filename), m_extension(extension), m_password(password) {}

    // Function to process the document and extract text and metadata
    void processDocument() {
        // Check if the file is a PDF
        if (m_extension == "pdf") {
            // Load the PDF document
            pdfium::PDFDocument pdfDoc;
            std::stringstream ss;
            ss << m_filename;
            pdfDoc.Load(ss);

            // Check if the document is encrypted and has a password
            if (pdfDoc.IsEncrypted()) {
                if (!m_password.empty()) {
                    pdfDoc.Decrypt(m_password);
                } else {
                    throw std::invalid_argument("Password required for PDF encryption");
                }
            }

            // Extract text and metadata from the PDF document
            extractPDFTextAndMetadata(pdfDoc);
        } else if (m_extension == "docx" || m_extension == "doc") {
            // Load the Word document
            tesseract::TessBaseAPI tess;
            std::stringstream ss;
            ss << m_filename;
            tess.Init(ss, "eng", NULL);
            tess.SetVariable("tessedit_char_whitelist", "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789 ");
            tess.SetImage((uchar*)m_filename.c_str(), m_filename.length());
            tess.Recognize(0);
            std::string text = tess.GetUTF8Text();

            // Extract metadata from the Word document
            extractWordMetadata(text, m_metadata);
        } else if (m_extension == "jpg" || m_extension == "png") {
            // Load the image and run OCR on it
            tesseract::TessBaseAPI tess;
            std::stringstream ss;
            ss << m_filename;
            tess.Init(ss, "eng", NULL);
            tess.SetVariable("tessedit_char_whitelist", "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789 ");
            tess.SetImage((uchar*)m_filename.c_str(), m_filename.length());
            tess.Recognize(0);
            std::string text = tess.GetUTF8Text();

            // Extract metadata from the image
            extractImageMetadata(text, m_metadata);
        } else {
            throw std::invalid_argument("Unsupported file extension");
        }
    }

private:
    // Function to extract text and metadata from a PDF document
    void extractPDFTextAndMetadata(pdfium::PDFDocument& pdfDoc) {
        std::stringstream ss;
        size_t numPages = pdfDoc.GetPageCount();
        for (size_t pageNum = 0; pageNum < numPages; ++pageNum) {
            pdfium::FPDF_PAGE page = pdfDoc.LoadPage(pageNum);
            if (!page) continue;
            int width = pdfium::FPDF_GetPageWidth(page);
            int height = pdfium::FPDF_GetPageHeight(page);

            // Extract text from the PDF page
            char buffer[1024];
            size_t len = sizeof(buffer);
            size_t offset = 0;
            while (true) {
                len = pdfium::FPDFText_GetText(page, offset, buffer, sizeof(buffer));
                if (len == 0) break;
                ss << buffer;
                offset += len;
            }

            // Extract metadata from the PDF page
            pdfium::FPDF_DEST dest = pdfium::FPDFPage_GetDest(page, 0);
            if (dest) {
                std::string destination = "";
                int numParams = pdfium::FPDFDest_CountParams(dest);
                for (int paramNum = 0; paramNum < numParams; ++paramParam) {
                    float value = pdfium::FPDFDest_GetParamFloatValue(dest, paramNum);
                    destination += std::to_string(value);
                }
                m_metadata["destination"] = destination;
            }
        }
    }

    // Function to extract metadata from a Word document
    void extractWordMetadata(const std::string& text, std::map<std::string, std::string>& metadata) {
        size_t offset = 0;
        while (true) {
            size_t pos = text.find(':', offset);
            if (pos == std::string::npos) break;

            // Extract the key and value from the Word document
            std::string key = text.substr(offset, pos - offset);
            std::string value = text.substr(pos + 1);
            metadata[key] = value;

            // Move to the next position in the Word document
            offset = pos + 1;
        }
    }

    // Function to extract metadata from an image
    void extractImageMetadata(const std::string& text, std::map<std::string, std::string>& metadata) {
        size_t offset = 0;
        while (true) {
            size_t pos = text.find(':', offset);
            if (pos == std::string::npos) break;

            // Extract the key and value from the image
            std::string key = text.substr(offset, pos - offset);
            std::string value = text.substr(pos + 1);
            metadata[key] = value;

            // Move to the next position in the image
            offset = pos + 1;
        }
    }
};
