gateway.register_service("users", "http://localhost:8001")
gateway.register_service("products", "http://localhost:8002")

# Route a request to the appropriate service
method = "GET"
path = "/users/123"
headers = {"Authorization": "Bearer my-token"}
body = b""
response = gateway.route_request(method, path, headers, body)
print(response.content)  # Output: {"id": 123, "name": "John Doe", ...}
```']

