#define OPTION_DECRYPT "decrypt"

// Define function prototypes
void encrypt(const char *file_path, const char *key_file_path);
void decrypt(const char *file_path, const char *key_file_path);
int parse_options(char **argv);
void usage();

int main(int argc, char **argv) {
  // Parse command-line options
  int option = parse_options(argv);

  // Handle encryption and decryption based on option selected
  if (option == OPTION_ENCRYPT) {
    encrypt(FILE_PATH, KEY_FILE_PATH);
  } else if (option == OPTION_DECRYPT) {
    decrypt(FILE_PATH, KEY_FILE_PATH);
  } else {
    usage();
  }

  return 0;
}

void encrypt(const char *file_path, const char *key_file_path) {
  // Load the key from the KMS
  EVP_PKEY *key = load_key(key_file_path);

  // Encrypt the file using AES or RSA based on the type of the key
  if (EVP_PKEY_type(key) == EVP_PKEY_RSA) {
    encrypt_rsa(file_path, key);
  } else {
    encrypt_aes(file_path, key);
  }

  // Free the key and return
  EVP_PKEY_free(key);
}

void decrypt(const char *file_path, const char *key_file_path) {
  // Load the key from the KMS
  EVP_PKEY *key = load_key(key_file_path);

  // Decrypt the file using AES or RSA based on the type of the key
  if (EVP_PKEY_type(key) == EVP_PKEY_RSA) {
    decrypt_rsa(file_path, key);
  } else {
    decrypt_aes(file_path, key);
  }

  // Free the key and return
  EVP_PKEY_free(key);
}

// Load the key from the KMS using OpenSSL's API
EVP_PKEY *load_key(const char *key_file_path) {
  // Initialize the KMS client
  kms_client_t *kms = kms_client_init();

  // Load the key from the KMS
  EVP_PKEY *key = NULL;
  if (kms_get_key(kms, key_file_path, &key) != 0) {
    fprintf(stderr, "Failed to load key from KMS\n");
    return NULL;
  }

  // Free the KMS client
  kms_client_free(kms);

  return key;
}

// Encrypt a file using AES based on the given key
void encrypt_aes(const char *file_path, EVP_PKEY *key) {
  // Initialize the OpenSSL context
  EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();

  // Set up the encryption parameters based on the key type
  if (EVP_PKEY_type(key) == EVP_PKEY_RSA) {
    int bits = RSA_bits(EVP_PKEY_get1_RSA(key));
    EVP_CIPHER_CTX_init(ctx, EVP_aes_256_cbc(), NULL, NULL, 0);
  } else if (EVP_PKEY_type(key) == EVP_PKEY_AES) {
    int bits = AES_bits(EVP_PKEY_get1_AES(key));
    EVP_CIPHER_CTX_init(ctx, EVP_aes_256_cbc(), NULL, NULL, 0);
  } else {
    fprintf(stderr, "Unsupported key type\n");
    return;
  }

  // Set the encryption mode to CBC
  if (EVP_EncryptInit_ex(ctx, NULL, NULL, NULL, NULL) != 1) {
    fprintf(stderr, "Failed to initialize encryption context\n");
    EVP_CIPHER_CTX_free(ctx);
    return;
  }

  // Encrypt the file
  FILE *file = fopen(file_path, "rb");
  if (!file) {
    fprintf(stderr, "Failed to open input file\n");
    EVP_CIPHER_CTX_free(ctx);
    return;
  }
  unsigned char buffer[4096];
  size_t read = 0;
  while ((read = fread(buffer, 1, sizeof(buffer), file)) != 0) {
    if (EVP_EncryptUpdate(ctx, buffer, &read, buffer, read) != 1) {
      fprintf(stderr, "Failed to encrypt input data\n");
      EVP_CIPHER_CTX_free(ctx);
      return;
    }
  }
  if (EVP_EncryptFinal_ex(ctx, buffer, &read) != 1) {
    fprintf(stderr, "Failed to finalize encryption\n");
    EVP_CIPHER_CTX_free(ctx);
    return;
  }

  // Close the input file and write the encrypted data to an output file
  fclose(file);
  FILE *output = fopen("encrypted.dat", "wb");
  if (!output) {
    fprintf(stderr, "Failed to open output file\n");
    EVP_CIPHER_CTX_free(ctx);
    return;
  }
  fwrite(buffer, read, 1, output);
  fclose(output);

  // Free the encryption context
  EVP_CIPHER_CTX_free(ctx);
}

// Decrypt a file using AES based on the given key
void decrypt_aes(const char *file_path, EVP_PKEY *key) {
  // Initialize the OpenSSL context
  EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();

  // Set up the decryption parameters based on the key type
  if (EVP_PKEY_type(key) == EVP_PKEY_RSA) {
    int bits = RSA_bits(EVP_PKEY_get1_RSA(key));
    EVP_CIPHER_CTX_init(ctx, EVP_aes_256_cbc(), NULL, NULL, 0);
  } else if (EVP_PKEY_type(key) == EVP_PKEY_AES) {
    int bits = AES_bits(EVP_PKEY_get1_AES(key));
    EVP_CIPHER_CTX_init(ctx, EVP_aes_256_cbc(), NULL, NULL, 0);
  } else {
    fprintf(stderr, "Unsupported key type\n");
    return;
  }

  // Set the decryption mode to CBC
  if (EVP_DecryptInit_ex(ctx, NULL, NULL, NULL, NULL) != 1) {
    fprintf(stderr, "Failed to initialize decryption context\n");
    EVP_CIPHER_CTX_free(ctx);
    return;
  }

  // Decrypt the file
  FILE *file = fopen(file_path, "rb");
  if (!file) {
    fprintf(stderr, "Failed to open input file\n");
    EVP_CIPHER_CTX_free(ctx);
    return;
  }
  unsigned char buffer[4096];
  size_t read = 0;
  while ((read = fread(buffer, 1, sizeof(buffer), file)) != 0) {
    if (EVP_DecryptUpdate(ctx, buffer, &read, buffer, read) != 1) {
      fprintf(stderr, "Failed to decrypt input data\n");
      EVP_CIPHER_CTX_free(ctx);
      return;
    }
  }
  if (EVP_DecryptFinal_ex(ctx, buffer, &read) != 1) {
    fprintf(stderr, "Failed to finalize decryption\n");
    EVP_CIPHER_CTX_free(ctx);
    return;
  }

  // Close the input file and write the decrypted data to an output file
  fclose(file);
  FILE *output = fopen("decrypted.dat", "wb");
  if (!output) {
    fprintf(stderr, "Failed to open output file\n");
    EVP_CIPHER_CTX_free(ctx);
    return;
  }
  fwrite(buffer, read, 1, output);
  fclose(output);

  // Free the decryption context
  EVP_CIPHER_CTX_free(ctx);
}
```
This code demonstrates how to use OpenSSL's API to perform encryption and decryption of files using AES. It also shows how to initialize an encryption context, set up encryption parameters based on the key type, encrypt a file, decrypt a file, and free the encryption context. The `kms_get_key` function is used to load the key from the KMS server, while the `kms_client_init`, `kms_client_free`, and `kms_encrypt` functions are used for initializing and freeing the KMS client, respectively.

This code assumes that you have already set up an instance of a KMS server and have created a key pair. You can modify this code to use your own KMS server and key pair by changing the `kms_server` and `kms_port` variables in the `kms_client_init` function.

