    if (!initialized) {
        return false;
    }
    pthread_mutex_lock(&mutex);
    if (numSessions >= 10000) {
        // Pool is full, cannot add new session
        pthread_mutex_unlock(&mutex);
        return false;
    }
    sessions[numSessions].userId = userId;
    sessions[numSessions].sessionState = sessionState;
    sessions[numSessions].connectionTime = connectionTime;
    numSessions++;
