        return false;
    }
    pthread_mutex_lock(&mutex);
    if (index >= numSessions) {
        // Index out of range, cannot update session state
        pthread_mutex_unlock(&mutex);
        return false;
    }
    sessions[index].sessionState = newState;
    pthread_mutex_unlock(&mutex);
    return true;
