using namespace std;

class SessionManager {
public:
    explicit SessionManager(const string& directory, const string& authServiceURL,
                            const string& redisURL) :
        directory_(directory), authServiceURL_(authServiceURL), redisURL_(redisURL) {}

    void start() {
        // Start the gRPC server for communication with analytics and notification services.
        grpc::ServerBuilder builder;
        builder.AddListeningPort("0.0.0.0:50051", grpc::InsecureServerCredentials());
        builder.RegisterService(&service_);
        server_ = builder.BuildAndStart();

        // Initialize the Redis client for distributed caching and auto-eviction policies.
        redisClient_ = std::make_unique<RedisClient>(redisURL_);
    }

    void stop() {
        // Shut down the gRPC server and clean up resources.
        server_->Shutdown();
        server_->Wait();
        redisClient_.reset();
    }

    bool addSession(const string& user, const string& sessionID) {
        // Check if the session exists in Redis.
        if (redisClient_->exists("session:" + sessionID)) {
            return false;
        }

        // Add the session to Redis with an expiration time of 30 minutes.
        redisClient_->setex("session:" + sessionID, 30 * 60, user);
        sessions_.insert({user, sessionID});

        return true;
    }

    bool removeSession(const string& user, const string& sessionID) {
        // Check if the session exists in Redis.
        if (!redisClient_->exists("session:" + sessionID)) {
            return false;
        }

        // Remove the session from Redis and the map of sessions.
        redisClient_->del("session:" + sessionID);
        sessions_.erase(user);

        return true;
    }

    bool isValidSession(const string& user, const string& sessionID) {
        // Check if the session exists in Redis and has not expired.
        return redisClient_->exists("session:" + sessionID) &&
               !redisClient_->expireat("session:" + sessionID, time(nullptr));
    }

