    }

    // Check if the path is a placeholder for dynamic configurations
    if (is_placeholder(path)) {
        return PATH_PLACEHOLDER;
    }

    // If the path is valid, return PATH_VALID
    return PATH_VALID;
}

static bool is_symbolic_link(const char *path) {
    struct stat file_stat;
    if (lstat(path, &file_stat) < 0) {
        return false;
    }

    // Check if the path is a symbolic link by checking the file type
    if ((file_stat.st_mode & S_IFMT) == S_IFLNK) {
        return true;
    } else {
        return false;
    }
}

static bool contains_environment_variables(const char *path) {
    const char *var = getenv("PATH");
    if (var == NULL) {
