    return strstr(path, var) != NULL;
}

static bool is_placeholder(const char *path) {
    const char *prefix = "$";
    const char *suffix = "@";

    // Check if the path starts with the placeholder prefix and ends with the placeholder suffix
    return strncmp(path, prefix, strlen(prefix)) == 0 && strcmp(path + strlen(path) - strlen(suffix), suffix) == 0;
}

static validated_path_t validate_and_normalize_path(const char *path, size_t max_length, bool absolute) {
    path_info_t info = get_path_info(path);

    // Validate the path against OS-specific separators and symbolic links
    path_status_t status = validate_path(info.path, max_length, absolute);

    if (status != PATH_VALID) {
        return (validated_path_t){
            .path = NULL,
            .length = 0,
            .status = status,
        };
    }

    // Normalize the path by removing any leading or trailing separators and resolving symbolic links
    char *normalized_path = normalize_path(info.path);

    return (validated_path_t){
        .path = normalized_path,
        .length = strlen(normalized_path),
        .status = PATH_VALID,
    };
}

static char *normalize_path(const char *path) {
    // Remove any leading or trailing separators from the path
    if (strchr(path, SEPARATOR) == path || strrchr(path, SEPARATOR) == path + strlen(path) - 1) {
        return remove_separators(path);
    } else {
        return NULL;
