}

static char *remove_separators(const char *path) {
    // Remove any leading or trailing separators from the path
    size_t len = strlen(path);
    char *trimmed_path = malloc(len + 1);
    memcpy(trimmed_path, path, len + 1);

    // Remove any leading separators
    while (trimmed_path[0] == SEPARATOR) {
        trimmed_path++;
    }

    // Remove any trailing separators
    size_t i = strlen(trimmed_path) - 1;
    while (i > 0 && trimmed_path[i] == SEPARATOR) {
        trimmed_path[i--] = '\0';
    }

    return trimmed_path;
}

static bool resolve_symbolic_link(const char *path) {
    // Resolve the symbolic link by reading the target file descriptor
    int fd = open(path, O_RDONLY);
    if (fd < 0) {
        return false;
    }

    struct stat file_stat;
    if (fstat(fd, &file_stat) < 0) {
