Here is a sample implementation of the file management utility in C for a cloud-native environment:
```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/stat.h>
#include <sys/mman.h>
#include <time.h>
#include <errno.h>
#include <assert.h>

// Define the file system configuration
#define FILE_SYSTEM_ROOT "/path/to/file/system"
#define FILE_NAME_MAX_LENGTH 256
#define FILE_EXTENSION_MAX_LENGTH 10
#define FILE_CACHE_SIZE 1024 * 1024 // 1MB
#define FILE_CACHE_TTL 60 // seconds

// Define the naming conventions for files and directories
#define FILE_NAME_PREFIX "file-"
#define FILE_EXTENSION ".png"
#define DIRECTORY_PREFIX "directory-"

// Define the file system operations
void create_file(char *filename, char *extension);
void delete_file(char *filename);
void rename_file(char *old_filename, char *new_filename);
void update_file(char *filename, char *data, size_t length);
void read_file(char *filename, char *data, size_t length);
void list_files();

// Define the file cache operations
void cache_file(char *filename, char *extension);
void uncache_file(char *filename);
void evict_uncached_files();

// Define the configuration file management operations
void parse_configuration_file(char *filename);
void update_configuration_file(char *filename, char *data, size_t length);
void read_configuration_file(char *filename);

int main() {
  // Initialize the file system and cache
  initialize_file_system();
  initialize_file_cache();

  // Load the configuration files
  parse_configuration_file("config.json");

  // Run the file management utility
  while (1) {
    char *filename = get_input();
    if (!strcmp(filename, "exit")) {
      break;
    } else if (!strcmp(filename, "list")) {
      list_files();
    } else {
      // Handle file management operations
      char *extension = strrchr(filename, '.');
      if (extension) {
        // Check if the file is cached
        if (cache_file(filename)) {
          // If the file is cached, update it
          update_file(filename, get_data(), get_length());
        } else {
          // If the file is not cached, create a new one
          create_file(filename, extension);
        }
      } else {
        // If the filename does not contain an extension, rename it
        char new_filename[FILE_NAME_MAX_LENGTH];
        snprintf(new_filename, FILE_NAME_MAX_LENGTH, "%s%s", FILE_NAME_PREFIX, filename);
        rename_file(filename, new_filename);
      }
    }
  }

  // Save the configuration files
  update_configuration_file("config.json");

  // Clean up the file system and cache
  cleanup_file_system();
  cleanup_file_cache();

  return 0;
}

void create_file(char *filename, char *extension) {
  assert(filename != NULL && extension != NULL);

  // Check if the file already exists
  struct stat sb;
  if (stat(filename, &sb) == 0) {
    printf("File %s already exists\n", filename);
    return;
  }

  // Create the file
  int fd = open(filename, O_CREAT | O_RDWR, S_IRUSR | S_IWUSR);
  if (fd == -1) {
    printf("Failed to create file %s\n", filename);
    return;
  }

  // Close the file descriptor
  close(fd);
}

void delete_file(char *filename) {
  assert(filename != NULL);

  // Check if the file exists
  struct stat sb;
  if (stat(filename, &sb) == -1) {
    printf("File %s does not exist\n", filename);
    return;
  }

  // Delete the file
  int ret = unlink(filename);
  if (ret != 0) {
    printf("Failed to delete file %s\n", filename);
    return;
  }
}

void rename_file(char *old_filename, char *new_filename) {
  assert(old_filename != NULL && new_filename != NULL);

  // Check if the old file exists
  struct stat sb;
  if (stat(old_filename, &sb) == -1) {
    printf("File %s does not exist\n", old_filename);
    return;
  }

  // Rename the file
  int ret = rename(old_filename, new_filename);
  if (ret != 0) {
    printf("Failed to rename file %s to %s\n", old_filename, new_filename);
    return;
  }
}

void update_file(char *filename, char *data, size_t length) {
  assert(filename != NULL && data != NULL);

  // Check if the file exists
  struct stat sb;
  if (stat(filename, &sb) == -1) {
    printf("File %s does not exist\n", filename);
    return;
  }

  // Open the file for writing
  int fd = open(filename, O_WRONLY | O_TRUNC, S_IRUSR | S_IWUSR);
  if (fd == -1) {
    printf("Failed to open file %s for writing\n", filename);
    return;
  }

  // Write the data to the file
  ssize_t ret = write(fd, data, length);
  if (ret < 0 || ret != length) {
    printf("Failed to update file %s\n", filename);
    close(fd);
    return;
  }

  // Close the file descriptor
  close(fd);
}

void cache_file(char *filename) {
  assert(filename != NULL);

  // Check if the file exists
  struct stat sb;
  if (stat(filename, &sb) == -1) {
    printf("File %s does not exist\n", filename);
    return;
  }

  // Open the file for reading
  int fd = open(filename, O_RDONLY, S_IRUSR | S_IWUSR);
  if (fd == -1) {
    printf("Failed to open file %s for reading\n", filename);
    return;
  }

  // Read the data from the file
  char *data = malloc(sb.st_size + 1);
  ssize_t ret = read(fd, data, sb.st_size);
  if (ret < 0 || ret != sb.st_size) {
    printf("Failed to cache file %s\n", filename);
    close(fd);
    return;
  }

  // Close the file descriptor
  close(fd);

  // Add the file to the cache
  add_to_cache(filename, data);
}

void cleanup_file_system() {
  assert(filename != NULL && data != NULL);

  // Check if the file exists
  struct stat sb;
  if (stat(filename, &sb) == -1) {
    printf("File %s does not exist\n", filename);
    return;
  }

  // Open the file for reading
  int fd = open(filename, O_RDONLY, S_IRUSR | S_IWUSR);
  if (fd == -1) {
    printf("Failed to open file %s for reading\n", filename);
    return;
  }

  // Read the data from the file
  char *data = malloc(sb.st_size + 1);
  ssize_t ret = read(fd, data, sb.st_size);
  if (ret < 0 || ret != sb.st_size) {
    printf("Failed to cleanup file %s\n", filename);
    close(fd);
    return;
  }

  // Close the file descriptor
  close(fd);
}

void cleanup_file_cache() {
  assert(filename != NULL && data != NULL);

  // Check if the file exists
  struct stat sb;
  if (stat(filename, &sb) == -1) {
    printf("File %s does not exist\n", filename);
    return;
  }

  // Open the file for reading
  int fd = open(filename, O_RDONLY, S_IRUSR | S_IWUSR);
  if (fd == -1) {
    printf("Failed to open file %s for reading\n", filename);
    return;
  }

  // Read the data from the file
  char *data = malloc(sb.st_size + 1);
  ssize_t ret = read(fd, data, sb.st_size);
  if (ret < 0 || ret != sb.st_size) {
    printf("Failed to cleanup file %s\n", filename);
    close(fd);
    return;
  }

  // Close the file descriptor
  close(fd);
}
```

Please note that this is just a simple example, and in practice you would want to handle errors more robustly and add more functionality such as checking if the file exists before creating it, or renaming it if it does. Also, this code is not thread-safe, so if you need to use it in a multi-threaded environment you would want to add synchronization primitives to make sure the cache is accessed correctly.']

