from concurrent.futures import ThreadPoolExecutor
from configparser import ConfigParser

class LogAggregator:
    def __init__(self, config_file):
        self.config = ConfigParser()
        self.config.read(config_file)
        self.servers = self.config["SERVERS"]
        self.log_paths = [path for path in self.config["LOG_PATHS"]]
        self.compression_formats = {format: comp for format, comp in self.config["COMPRESSION"].items()}
        self.output_schema = self.config["OUTPUT_SCHEMA"]
        self.max_retries = int(self.config["MAX_RETRIES"])
        self.backoff_factor = float(self.config["BACKOFF_FACTOR"])
        self.logging_level = self.config["LOGGING_LEVEL"]
        self.logger = logging.getLogger("LogAggregator")
        self.logger.setLevel(self.logging_level)

    def process_log_file(self, log_file):
        try:
            with open(log_file, "rb") as f:
                compressed = f.read()
            decompressed = self.compression_formats[os.path.splitext(log_file)[1]](compressed)
            return decompressed
        except (OSError, ValueError):
            self.logger.warning(f"Invalid log file: {log_file}")
            return None

    def validate_log_files(self, files):
        valid_files = []
        for f in files:
            try:
                if not os.path.exists(f):
                    self.logger.warning(f"Log file does not exist: {f}")
                else:
                    valid_files.append(f)
            except OSError as e:
                self.logger.error(f"Error accessing log file: {e}")
        return valid_files

    def aggregate_logs(self, files):
        with ThreadPoolExecutor() as executor:
            futures = [executor.submit(self.process_log_file, f) for f in files]
            results = [f.result() for f in futures]
        return results

    def process_logs(self):
        for server in self.servers:
            try:
                server_data = []
                for path in self.log_paths:
                    log_file = os.path.join(server, path)
                    if not os.path.exists(log_file):
                        continue
                    data = self.process_log_file(log_file)
                    if data is None:
                        continue
                    server_data.append(data)
                return self.aggregate_logs(server_data)
            except OSError as e:
                self.logger.error(f"Error accessing log file: {e}")
                return 1

    def export_results(self, data):
        # Implement your own logic to export the results to a file or database
        pass

if __name__ == "__main__":
    config_file = "config.ini"
    aggregator = LogAggregator(config_file)
    files = aggregator.validate_log_files(aggregator.servers)
    if len(files) == 0:
        aggregator.logger.warning("No valid log files found")
        return 1
    results = aggregator.process_logs()
    if results is None:
        aggregator.logger.error("Processing logs failed")
        return 1
    else:
        aggregator.export_results(results)
    return 0
