#include "nosql/collection.h"

using namespace std;

class MediaProcessor {
public:
    MediaProcessor(string input_directory, string output_directory) :
            input_directory_(input_directory), output_directory_(output_directory) {}

    void process() {
        // Load metadata from Redis
        auto redis_client = make_unique<Redis::Client>();
        auto redis_connection = make_shared<Redis::Connection>(redis_client->connect("localhost", 6379));
        auto metadata = redis_connection->get("media-processor");

        // Load session and job metadata from NoSQL database
        auto nosql_client = make_unique<NoSQL::Client>();
        auto nosql_collection = nosql_client->collection("media-processor");
        auto sessions = nosql_collection->find({"session", {"$exists": true}});
        auto jobs = nosql_collection->find({"job", {"$exists": true}});

        // Iterate over input files and process them
        for (auto& file : filesystem::directory_iterator(input_directory_)) {
            string filename = file.path().filename().string();
            auto session_id = sessions.find({"file", filename});
            if (session_id == -1) {
                // No session found for this file, create one
                session_id = nosql_collection->insert({{"session", {"name": "MediaProcessor"}, {"start_time": chrono::steady_clock::now()}});
            }

            // Check if there are any jobs in progress for this file
            auto job_ids = jobs.find({"file", filename, "status", "in_progress"});
            if (job_ids.size() == 0) {
                // No jobs found, create one
                job_ids = nosql_collection->insert({{"job", {"session_id": session_id, "filename": filename, "status": "in_progress"}}});
            }

            // Process the file using a gRPC call to an analytics service
            auto analytics_client = make_shared<grpc::Client>();
            analytics_client->connect("localhost", 50051);
            analytics_client->process(filename, session_id, job_ids[0]);

            // Update the job metadata in Redis and NoSQL database
            redis_connection->set("media-processor", metadata);
            nosql_collection->update({"job", {"session_id": session_id, "filename": filename, "status": "completed"}});
        }
    }

private:
    string input_directory_;
    string output_directory_;
};
```
