['```c
#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <time.h>
#include <assert.h>
#include <unistd.h>

#define MAX_CONNECTIONS 100000
#define MAX_MESSAGE_SIZE 4096

typedef struct {
    char message[MAX_MESSAGE_SIZE];
} LTE_DL_CCCH_MESSAGE_T;

struct connection {
    int fd;
    char buffer[MAX_MESSAGE_SIZE];
};

void read_message(int fd) {
    struct connection *conn = (struct connection *) malloc(sizeof(struct connection));
    conn->fd = fd;
    conn->buffer[0] = 0;
    int nread = read(fd, conn->buffer, MAX_MESSAGE_SIZE);
    if (nread > 0) {
        // Process message
        printf("Received message from connection %d: %s\n", fd, conn->buffer);
    } else {
        free(conn);
    }
}

void write_message(int fd, char *message) {
    struct connection *conn = (struct connection *) malloc(sizeof(struct connection));
    conn->fd = fd;
    int nwrite = write(fd, message, strlen(message));
    if (nwrite > 0) {
        printf("Sent message to connection %d: %s\n", fd, message);
    } else {
        free(conn);
    }
}

void error_handler(int signal, siginfo_t *info, void *context) {
    struct connection *conn = (struct connection *) info->si_value.sival_ptr;
    printf("Error handling signal %d for connection %d\n", signal, conn->fd);
}

void main() {
    int listen_fd = socket(AF_INET, SOCK_STREAM, 0);
    assert(listen_fd >= 0);

    struct sockaddr_in server_addr;
    server_addr.sin_family = AF_INET;
    server_addr.sin_port = htons(8080);
    inet_pton(AF_INET, "127.0.0.1", &server_addr.sin_addr);

    bind(listen_fd, (struct sockaddr *) &server_addr, sizeof(server_addr));
    listen(listen_fd, MAX_CONNECTIONS);

    while (1) {
        struct connection conn = {0};
        int new_fd = accept(listen_fd, NULL, NULL);
        if (new_fd >= 0) {
            // Register signal handler for errors
            sigset_t set;
            sigemptyset(&set);
            sigaddset(&set, SIGALRM);
            sigprocmask(SIG_BLOCK, &set, NULL);
            struct sigaction sa = {0};
            sa.sa_flags = SA_SIGINFO | SA_RESTART;
            sa.sa_sigaction = error_handler;
            if (sigaction(SIGALRM, &sa, NULL) < 0) {
                perror("sigaction");
                close(new_fd);
                continue;
            }

            // Set up the connection and handle read/write events
            conn.fd = new_fd;
            event_handler(&conn);
        } else {
            perror("accept");
        }
    }
}

void event_handler(struct connection *conn) {
    struct epoll_event event;
    int nfds = epoll_wait(listen_fd, &event, 1, -1);
    if (nfds > 0) {
        // Handle read events
        if ((event.events & EPOLLIN) || (event.events & EPOLLPRI)) {
            read_message(conn->fd);
        }
        // Handle write events
        if (event.events & EPOLLOUT) {
            write_message(conn->fd, conn->buffer);
        }
    } else {
        perror("epoll_wait");
    }
}
