Here is an example of how you could implement the modular, highly available, and resilient authentication service using Java:
```
import java.util.concurrent.TimeUnit;
import java.util.concurrent.locks.Lock;
import java.util.concurrent.locks.ReentrantReadWriteLock;

public class AuthenticationService {
  private static final Lock readLock = new ReentrantReadWriteLock().readLock();
  private static final Lock writeLock = new ReentrantReadWriteLock().writeLock();
  private static final RedisClient redisClient = new RedisClient();
  private static final Map<String, String> sessions = new HashMap<>();
  private static final long EXPIRATION_TIMEOUT = TimeUnit.MINUTES.toSeconds(30);

  public static boolean authenticate(String username, String password) {
    try (Lock lock = readLock.lock()) {
      return sessions.containsKey(username) &&
             sessions.get(username).equals(password);
    } catch (IOException e) {
      e.printStackTrace();
      return false;
    }
  }

  public static void login(String username, String password) {
    try (Lock lock = writeLock.lock()) {
      sessions.put(username, password);
    } catch (IOException e) {
      e.printStackTrace();
    }
  }

  public static void logout(String username) {
    try (Lock lock = readLock.lock()) {
      sessions.remove(username);
    } catch (IOException e) {
      e.printStackTrace();
    }
  }

  public static boolean isLoggedIn(String username) {
    try (Lock lock = readLock.lock()) {
      return sessions.containsKey(username);
    } catch (IOException e) {
      e.printStackTrace();
      return false;
    }
  }
}
```
