```c
#include <stdlib.h>
#include <string.h>
#include <stdio.h>
#include <pthread.h>
#include <semaphore.h>

// Define the structure for LTE DL CCCH message
typedef struct LTE_DL_CCCH_MESSAGE {
    uint8_t *message; // Pointer to the message data
    size_t length; // Length of the message in bytes
} LTE_DL_CCCH_MESSAGE;

// Define the pool for managing the dynamic pool of LTE DL CCCH messages
typedef struct LTE_DL_CCCH_MESSAGE_POOL {
    LTE_DL_CCCH_MESSAGE *messages; // Array of LTE DL CCCH messages
    size_t capacity; // Capacity of the pool in number of messages
    size_t current_size; // Current size of the pool in number of messages
} LTE_DL_CCCH_MESSAGE_POOL;

// Define the function for allocating a new LTE DL CCCH message
LTE_DL_CCCH_MESSAGE *allocate_message(size_t length) {
    // Allocate memory for the message data
    uint8_t *data = malloc(length);
    if (!data) {
        return NULL;
    }

    // Initialize the message structure
    LTE_DL_CCCH_MESSAGE *message = calloc(1, sizeof(LTE_DL_CCCH_MESSAGE));
    message->message = data;
    message->length = length;

    return message;
}

// Define the function for freeing an LTE DL CCCH message
void free_message(LTE_DL_CCCH_MESSAGE *message) {
    // Free the memory allocated for the message data
    free(message->message);

    // Free the structure itself
    free(message);
}

// Define the function for adding an LTE DL CCCH message to the pool
void add_message_to_pool(LTE_DL_CCCH_MESSAGE *message, LTE_DL_CCCH_MESSAGE_POOL *pool) {
    // Check if the pool is full
    if (pool->current_size >= pool->capacity) {
        return;
    }

    // Add the message to the pool
    pool->messages[pool->current_size] = message;
    pool->current_size++;
}

// Define the function for removing an LTE DL CCCH message from the pool
void remove_message_from_pool(LTE_DL_CCCH_MESSAGE *message, LTE_DL_CCCH_MESSAGE_POOL *pool) {
    // Find the index of the message in the pool
    size_t i;
    for (i = 0; i < pool->current_size; i++) {
        if (pool->messages[i] == message) {
            break;
        }
    }

    // Check if the message was found in the pool
    if (i == pool->current_size) {
        return;
    }

    // Remove the message from the pool
    memmove(&pool->messages[i], &pool->messages[i + 1], sizeof(LTE_DL_CCCH_MESSAGE) * (pool->current_size - i));
    pool->current_size--;
}

// Define the function for allocating a new LTE DL CCCH message structure
LTE_DL_CCCH_MESSAGE_POOL *allocate_message_pool(size_t capacity) {
    // Allocate memory for the pool structure and the array of messages
    LTE_DL_CCCH_MESSAGE_POOL *pool = malloc(sizeof(LTE_DL_CCCH_MESSAGE_POOL));
    if (!pool) {
        return NULL;
    }

    // Initialize the pool structure and the array of messages
    pool->messages = calloc(capacity, sizeof(LTE_DL_CCCH_MESSAGE));
    pool->capacity = capacity;
    pool->current_size = 0;

    return pool;
}

// Define the function for freeing an LTE DL CCCH message structure
void free_message_pool(LTE_DL_CCCH_MESSAGE_POOL *pool) {
    // Free the memory allocated for the array of messages
    free(pool->messages);

    // Free the structure itself
    free(pool);
}
```
