    if (num_servers >= max_workers) {
        return;
    }
    num_servers++;
    server_states = realloc(server_states, num_servers * sizeof(int));
    server_weights = realloc(server_weights, num_servers * sizeof(int));
    server_states[id] = 0;
    server_weights[id] = 1;
}

// function to remove a server from the system
