// Function to check if a given file is compressed using gzip
int is_compressed(const char* filename) {
    struct stat st;
    int ret = 0;

    // Get the file information and check for errors
    if (stat(filename, &st) == -1) {
        fprintf(stderr, "Error: %s\n", strerror(errno));
        return -1;
    }

    // Check if the file is a gzip file
    if (S_ISREG(st.st_mode)) {
        ret = 1;
    }

    return ret;
}

// Function to decompress a compressed file using gzip
int decompress_file(const char* filename, const char* outfilename) {
    FILE *infile, *outfile;
    int ret = 0;

    // Open the input and output files
    infile = fopen(filename, "rb");
    outfile = fopen(outfilename, "wb");
    if (!infile || !outfile) {
        fprintf(stderr, "Error: %s\n", strerror(errno));
        ret = -1;
    }

    // Decompress the file using gzip
    else {
        int err = 0;
        gzFile gzin = gzdopen(fileno(infile), "rb");
        gzFile gzout = gzdopen(fileno(outfile), "wb");

        // Decompress the file and check for errors
        if (gzin && gzout) {
            err = gzread(gzin, outfile, st.st_size);
            fclose(outfile);
            fclose(gin);
        }

        // Handle errors
        if (err < 0) {
            fprintf(stderr, "Error: %s\n", strerror(errno));
            ret = -1;
        }
    }

    return ret;
}

// Function to handle file input using getopt()
int handle_files(const char* optarg) {
    int argc = 0, i = 0;
    char** argv = NULL;
    FILE* infile = NULL;
    FILE* outfile = NULL;
    size_t count = 0;

    // Check if the file is compressed using gzip and decompress it if necessary
    if (is_compressed(optarg)) {
        const char* outfilename = "decompressed.txt";
        argv[argc++] = optarg;
        i++;
        if (!decompress_file(optarg, outfilename)) {
            fprintf(stderr, "Error: %s\n", strerror(errno));
            return -1;
        }
    }

    // Open the input file and check for errors
    else {
        infile = fopen(optarg, "rb");
        if (!infile) {
            fprintf(stderr, "Error: %s\n", strerror(errno));
            return -1;
        }
    }

    // Open the output file and check for errors
    outfile = fopen("output.txt", "wb");
    if (!outfile) {
        fprintf(stderr, "Error: %s\n", strerror(errno));
        return -1;
    }

    // Count the number of lines in the input file and write to output file
    while (fgets(buffer, sizeof(buffer), infile)) {
        count++;
        fprintf(outfile, "%s", buffer);
    }

    // Close the files and return the count
    fclose(infile);
    fclose(outfile);
    return count;
}

// Main function to handle command-line arguments
int main(int argc, char* argv[]) {
    int opt;
    char* optarg;
    FILE* infile = NULL;
    FILE* outfile = NULL;
    size_t count = 0;

    // Loop through the command-line arguments and handle each option
    while ((opt = getopt(argc, argv, "i:o:cs")) != -1) {
        switch (opt) {
            case 'i':
                optarg = argv[optind];
                if (!handle_files(optarg)) {
                    fprintf(stderr, "Error: %s\n", strerror(errno));
                    return -1;
                }
                break;
            case 'o':
                optarg = argv[optind];
                outfile = fopen(optarg, "wb");
                if (!outfile) {
                    fprintf(stderr, "Error: %s\n", strerror(errno));
                    return -1;
                }
                break;
            case 'c':
                // Handle the count option
                count++;
                break;
            default:
                fprintf(stderr, "Error: Invalid option '%c'\n", opt);
                return -1;
        }
    }

    // Check if all required options have been set and handle errors
    if (!infile) {
        fprintf(stderr, "Error: No input file specified\n");
        return -1;
    } else if (!outfile) {
        fprintf(stderr, "Error: No output file specified\n");
        return -1;
    }

