        fprintf(stderr, "Error: %s\n", strerror(errno));
        return -1;
    } else if (ferror(outfile)) {
        fprintf(stderr, "Error: %s\n", strerror(errno));
        return -1;
    } else {
        fclose(infile);
        fclose(outfile);
        return 0;
    }
}

