    fn process_data(&mut self) -> Result<String, Box<dyn std::error::Error>> {
        for source in &self.sources {
            let data = fetch_data(source)?;
            self.cache.insert(source.name.clone(), data);
        }

        Ok("".to_string())
    }
}

fn main() -> Result<String, Box<dyn std::error::Error>> {
    let mut processor = DataProcessor::new();
    let result = processor.process_data()?;

    println!("Data processing completed successfully.");

    Ok(result)
}

fn fetch_data(source: &DataSource) -> Result<String, Box<dyn std::error::Error>> {
    // Fetch data from the specified source and return it as a string
}
