// Define the record structure
typedef struct {
    int key;
    int value;
} Record;

// Define the dynamic collection of records
typedef struct {
    int size;
    Record **records;
} Records;

// Function to initialize a new record
static void init_record(Record *record) {
    record->key = 0;
    record->value = 0;
}

// Function to create a new dynamic collection of records
static Records *create_records() {
    Records *records = malloc(sizeof(Records));
    if (records == NULL) {
        return NULL;
    }

    // Initialize the size and records array
    records->size = 0;
    records->records = NULL;

    return records;
}

// Function to add a new record to the dynamic collection
static void add_record(Records *records, int key, int value) {
    // Check if the key already exists in the records array
    for (int i = 0; i < records->size; i++) {
        if (records->records[i]->key == key) {
            return;
        }
    }

    // Create a new record and add it to the records array
    Record *record = malloc(sizeof(Record));
    init_record(record);
    record->key = key;
    record->value = value;
    records->records[records->size++] = record;
}

// Function to read a record from the dynamic collection
static int read_record(Records *records, int key) {
    // Check if the key exists in the records array
    for (int i = 0; i < records->size; i++) {
        if (records->records[i]->key == key) {
            return records->records[i]->value;
        }
    }

    // Return -1 if the key is not found
    return -1;
}

// Function to update a record in the dynamic collection
static void update_record(Records *records, int key, int value) {
    // Check if the key exists in the records array
    for (int i = 0; i < records->size; i++) {
        if (records->records[i]->key == key) {
            records->records[i]->value = value;
            return;
        }
    }
}

// Function to delete a record from the dynamic collection
static void delete_record(Records *records, int key) {
    // Check if the key exists in the records array
    for (int i = 0; i < records->size; i++) {
        if (records->records[i]->key == key) {
            // Remove the record from the records array
            records->size--;
            Records *tmp = records->records + i;
            records->records[i] = records->records[i+1];
            free(tmp);
            return;
        }
    }
}

