    // Check if the key exists in the records array
    for (int i = 0; i < records->size; i++) {
        if (records->records[i]->key == key) {
            return records->records[i]->value;
        }
    }

    // Return -1 if the key is not found
    return -1;
}

// Function to update the weighted sums and relevant metrics based on the filtered transactions
static void update_metrics(Records *records, int key, int value) {
    // Check if the key exists in the records array
    for (int i = 0; i < records->size; i++) {
        if (records->records[i]->key == key) {
            records->records[i]->value += value;
            return;
        }
    }
}

// Function to perform a graceful cleanup and error recovery, with detailed logging for debugging
