        // Filter transactions based on complex criteria: transaction age, recent transaction volume, and weighted sums
        int filtered_transaction = filter_transactions(records, key, value);

        // Update the weighted sums and relevant metrics based on the filtered transactions
        update_metrics(records, key, value);

        // Unlock the mutex after updating the records array
        pthread_mutex_unlock(&mutex);
    }

    // Create threads to read and update records, and another thread to filter transactions based on complex criteria: transaction age, recent transaction volume, and weighted sums
    pthread_t read_update_thread;
    pthread_create(&read_update_thread, NULL, read_update, NULL);

    pthread_t filter_thread;
    pthread_create(&filter_thread, NULL, filter, NULL);

    // Wait for the threads to complete before cleaning up the records and mutex
    pthread_join(read_update_thread, NULL);
    pthread_join(filter_thread, NULL);

    // Cleanup the records and mutex after all threads have completed
    cleanup(records);
}
