        exit(EXIT_FAILURE);
    }
    close(fd);
}

void read_file(const char* filepath, void** data, size_t* length) {
    int fd = open(filepath, O_RDONLY);
    if (fd == -1) {
        fprintf(stderr, "Failed to open file: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }
    *length = lseek(fd, 0, SEEK_END);
    if (*length == -1) {
        fprintf(stderr, "Failed to seek file: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }
    *data = malloc(*length);
    ssize_t read = read(fd, *data, *length);
    if (read == -1) {
        fprintf(stderr, "Failed to read file: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }
    close(fd);
}

