    if (dp == NULL) {
        fprintf(stderr, "Failed to open directory: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }
    while ((de = readdir(dp)) != NULL) {
        version++;
    }
    closedir(dp);
    return version;
}

