    ~DataPipelineProcessor() {
        delete _consumer;
        delete _flinkContext;
        delete _hdfsClient;
    }

    void processEvent(const string& topic, const string& key, const string& value) {
        // Process event using Apache Flink
        flink::DataFrame df = _flinkContext->createDataFrame();
        df.addColumn("key", key);
        df.addColumn("value", value);
        df.groupBy("key").agg({"value"}, {"count"}).show();

        // Write event to HDFS
        hdfs::HDFSWriter writer = _hdfsClient->createWriter(topic, true);
        writer.append(key, value);
        writer.close();
    }

private:
    RdKafka::Consumer* _consumer;
    flink::FlinkContext* _flinkContext;
    hdfs::HDFSClient* _hdfsClient;
};
```
