                   "-s, --summary         Print a summary of processed files\n"
                   "-m, --manpage         Display usage information\n";
const char* LOGGING_URL = "http://logging.example.com/log";
int INPUT_FILE_COUNT = 0;
int FILE_PROCESSING_ERRORS = 0;
int FILE_PROCESSING_WARNINGS = 0;
int LOG_RETRY_DELAY = 10; // seconds
int LOG_MAX_RETRIES = 3;
int LOG_CONNECTION_TIMEOUT = 5; // seconds
int OUTPUT_COMPRESSION = 0;
char* OUTPUT_FILENAME = NULL;

// Function declarations
void parseOptions(int argc, char** argv);
void processInputFiles();
void logOperation(const char* operation, const char* filepath);
void logError(const char* error, const char* filepath);
void logWarning(const char* warning, const char* filepath);
void logInfo(const char* message);
void printUsage();
void printSummary();
