// Parse command-line options
void parseOptions(int argc, char** argv) {
  int c = 0;
  opterr = 0;

  while ((c = getopt(argc, argv, "i:o:csm")) != -1) {
    switch (c) {
      case 'i':
        INPUT_FILE_COUNT++;
        break;
      case 'o':
        OUTPUT_FILENAME = optarg;
        break;
      case 'c':
        OUTPUT_COMPRESSION = 1;
        break;
      case 's':
        printSummary();
        exit(0);
        break;
      case 'm':
        printUsage();
        exit(0);
        break;
    }
  }

  if (INPUT_FILE_COUNT == 0) {
    printf("No input files specified. Use -i option to specify one or more input files.\n");
    exit(1);
  }
}

// Process input files
void processInputFiles() {
  int i = 0;
  for (i = optind; i < argc; ++i) {
    char* filename = argv[i];
    int file_size = readFile(filename);
    if (file_size <= 0) {
      FILE_PROCESSING_ERRORS++;
      logError("Failed to read input file", filename);
      continue;
    }

    // Compress or decompress file based on OUTPUT_COMPRESSION flag
    char* output_filename = NULL;
    if (OUTPUT_COMPRESSION == 1) {
      output_filename = strdup(filename);
      compressFile(filename, output_filename);
    } else if (OUTPUT_COMPRESSION == -1) {
      output_filename = strdup(filename);
      decompressFile(filename, output_filename);
    } else {
      output_filename = OUTPUT_FILENAME;
    }

    // Print file summary and log operation to external logging service
    printf("Processed %s (%d bytes)\n", filename, file_size);
    logOperation("processed", filename);

    // Write processed file to output file
    if (writeFile(output_filename, buffer, file_size) <= 0) {
      FILE_PROCESSING_ERRORS++;
      logError("Failed to write output file", output_filename);
    }

    // Clean up temporary file and free memory
    if (OUTPUT_COMPRESSION == -1) {
      unlink(output_filename);
      free(output_filename);
    }
  }
}

// Log operation to external logging service
