}

// Print usage instructions
void printUsage() {
  printf("Usage: ./file-processing -i <input file> -o <output file> [-c] [-s] [-m]\n");
  printf("\t-i: Input file to be processed\n");
  printf("\t-o: Output file name (optional)\n");
  printf("\t-c: Compress input file and output file with gzip (optional)\n");
  printf("\t-s: Print summary of processed files (optional)\n");
  printf("\t-m: Print usage instructions (optional)\n");
}

// Print summary of processed files
void printSummary() {
  if (FILE_PROCESSING_ERRORS > 0) {
    logError("Failed to process all input files", NULL);
  } else {
    logInfo("Processed all input files successfully");
  }
}

// Read file contents into buffer
int readFile(const char* filename) {
  int fd = open(filename, O_RDONLY);
  if (fd < 0) return -1;

  struct stat st;
  if (fstat(fd, &st)) return -1;

  char* buffer = malloc(st.st_size + 1);
  int bytes_read = read(fd, buffer, st.st_size);
  close(fd);

  if (bytes_read <= 0) {
    free(buffer);
    return -1;
  }

  buffer[bytes_read] = '\0';
  return bytes_read;
}

// Write contents of buffer to output file
int writeFile(const char* filename, const char* buffer) {
  int fd = open(filename, O_CREAT | O_WRONLY);
  if (fd < 0) return -1;

  int bytes_written = write(fd, buffer, strlen(buffer));
  close(fd);

  if (bytes_written <= 0) {
    return -1;
  }

  return bytes_written;
}

// Compress input file and output file with gzip
int compressFiles(const char* input_file, const char* output_file) {
  int input_fd = open(input_file, O_RDONLY);
  if (input_fd < 0) return -1;

  int output_fd = creat(output_file, S_IRUSR | S_IWUSR | S_IRGRP | S_IROTH);
  if (output_fd < 0) {
    close(input_fd);
    return -1;
  }

  gzFile input_gzip = gzdopen(input_fd, "rb");
  if (input_gzip == NULL) {
    close(input_fd);
    close(output_fd);
    unlink(output_file);
    return -1;
  }

  gzFile output_gzip = gzdopen(output_fd, "wb");
  if (output_gzip == NULL) {
    gzclose(input_gzip);
    close(input_fd);
    close(output_fd);
    unlink(output_file);
    return -1;
  }

  int ret = gzcopy(input_gzip, output_gzip);

  gzclose(input_gzip);
  close(input_fd);

  gzclose(output_gzip);
  close(output_fd);

  return ret;
}
```

This program uses a few different libraries and functions to accomplish the task of processing files. The `getopt()` function is used to parse command line arguments, which allows the user to specify input and output file names as well as other options for the program. The `http_post()` function is used to send an HTTP POST request to the external logging service with a JSON payload containing information about the processed files.

The program also uses the `stat()` function to determine the size of the input file, which is then read into a buffer using the `read()` function. The contents of the buffer are then written to the output file using the `write()` function.

Finally, the program uses the `gzdopen()` and `gzcopy()` functions from the Gzip library to compress both the input and output files with gzip.']

