class DynamicUserSessionManager {
  private:
    map<int, UserSession*> sessionMap_;

    // Tireed caching mechanism for read performance and memory usage
    map<string, shared_ptr<UserSession>> cachedSessions_;

    // Load-balancing mechanism for efficient distribution of tasks across nodes
    list<NodeInfo*> nodeInfos_;
  public:
    DynamicUserSessionManager() {}

    void addUserSession(int userId, UserSession* session) {
      sessionMap_[userId] = session;
      cachedSessions_.insert({session->getUserName(), shared_ptr<UserSession>(session)});
      nodeInfos_.push_back(new NodeInfo{userid, session});
    }

    void removeUserSession(int userId) {
      if (sessionMap_.find(userId) != sessionMap_.end()) {
        auto session = sessionMap_[userId];
        cachedSessions_.erase(session->getUserName());
        nodeInfos_.remove(new NodeInfo{userid, session});
        delete session;
      }
