#include <stdlib.h>
#include <stdio.h>
#include <pthread.h>
#include <math.h>
#include "NoSQLDatabase.h"

// Define the record structure
typedef struct {
    int key;
    int value;
} Record;

// Define the library configuration options
typedef struct {
    unsigned long seed;
    char *database_url;
    unsigned short chunk_size;
} Config;

// Initialize the library with default configuration options
void init(Config *config) {
    config->seed = 42;
    config->database_url = "http://localhost:8080";
    config->chunk_size = 1000;
}

// Create a new record and add it to the collection
void create(Record *record) {
    pthread_mutex_lock(&collection_mutex);
    // Generate a random value within the specified range
    int value = (int)(rand_r(&config->seed) % 1000);
    record->key = (unsigned long)pthread_self();
    record->value = value;
    collection.push_back(record);
    pthread_mutex_unlock(&collection_mutex);
}

// Read a record from the collection by its key
Record *read(int key) {
    pthread_mutex_lock(&collection_mutex);
    Record *record = find(key, collection);
    if (record == NULL) {
        printf("Key not found\n");
    } else {
        return record;
    }
    pthread_mutex_unlock(&collection_mutex);
}

// Update a record in the collection by its key
void update(int key, int value) {
    pthread_mutex_lock(&collection_mutex);
    Record *record = find(key, collection);
    if (record == NULL) {
        printf("Key not found\n");
    } else {
        record->value = value;
    }
    pthread_mutex_unlock(&collection_mutex);
}

// Delete a record from the collection by its key
void delete(int key) {
    pthread_mutex_lock(&collection_mutex);
    Record *record = find(key, collection);
    if (record == NULL) {
        printf("Key not found\n");
    } else {
        collection.erase(find(key, collection));
    }
    pthread_mutex_unlock(&collection_mutex);
}

// Find a record in the collection by its key
Record *find(int key, std::vector<Record> &collection) {
    for (int i = 0; i < collection.size(); i++) {
        if (collection[i].key == key) {
            return &collection[i];
        }
    }
    return NULL;
}

// Close the library and free resources
void close() {
    pthread_mutex_destroy(&collection_mutex);
}
