#include <random>
#include <chrono>
#include <iostream>

namespace FinancialRNG {
class MTGenerator {
private:
    std::mt19937 gen_;
    std::uniform_int_distribution<uint64_t> distribution_;

public:
    explicit MTGenerator(uint64_t seed) : gen_(seed), distribution_(0, 1 << 62) {}

    uint64_t getRandomNumber() { return distribution_(gen_); }

    static std::string generateSeed() {
        std::random_device rd;
        std::uniform_int_distribution<uint64_t> seedGen(0, 1 << 62);
        uint64_t seed = seedGen(rd);
        return std::to_string(seed);
    }
};
} // namespace FinancialRNG

int main() {
    auto startTime = std::chrono::high_resolution_clock::now();

    for (int i = 0; i < 1024; ++i) {
        uint64_t seed = std::stoull(FinancialRNG::MTGenerator::generateSeed());
        FinancialRNG::MTGenerator generator(seed);
        for (int j = 0; j < 1000000; ++j) {
            uint64_t randomNumber = generator.getRandomNumber();
            // Perform some computation with the random number here...
        }
    }

    auto endTime = std::chrono::high_resolution_clock::now();
    std::cout << "Elapsed time: " << std::chrono::duration<double, std::milli>(endTime - startTime).count() << " ms"
              << std::endl;

    return 0;
}']

