// Batch SQL Command Execution Service in C#
using System;
using System.Collections.Generic;
using System.Data;
using System.Linq;
using System.Threading.Tasks;
using Microsoft.Data.SqlClient;

namespace BatchSQLCommandExecutionService
{
    public class SQLBatchExecutor : IDisposable
    {
        private readonly List<string> _servers; // list of remote SQL servers
        private readonly Dictionary<string, SqlConnection> _connections; // dictionary of connections to each server
        private readonly object _lock = new(); // lock for thread-safe access to the connections dictionary
        private readonly int _maxRetries; // maximum number of retries for transient failures
        private readonly int _retryInterval; // retry interval in milliseconds
        private readonly bool _enableLogging; // enable logging for error handling and debugging purposes

        public SQLBatchExecutor(List<string> servers, int maxRetries = 3, int retryInterval = 1000, bool enableLogging = false)
        {
            _servers = servers ?? throw new ArgumentNullException(nameof(servers));
            _maxRetries = maxRetries;
            _retryInterval = retryInterval;
            _enableLogging = enableLogging;
            _connections = new Dictionary<string, SqlConnection>(); // create an empty dictionary for connections
        }

        public async Task ExecuteBatchAsync(List<SqlCommand> commands)
        {
            if (commands == null || commands.Count == 0)
                throw new ArgumentNullException(nameof(commands));

            var successfulCommands = new List<SqlCommand>(); // list of successful commands
            var failedCommands = new List<SqlCommand>(); // list of failed commands

            try
            {
                foreach (var command in commands)
                {
                    var server = GetServer(command.ConnectionString); // get the server for the current connection string
                    var conn = GetConnection(server); // get the connection to the server
                    if (!await conn.OpenAsync()) // open the connection, if it's not already open
                        throw new InvalidOperationException("Unable to open connection");

                    try
                    {
                        using (var trans = conn.BeginTransaction()) // start a transaction for the current command
                        {
                            await command.ExecuteNonQueryAsync(conn); // execute the command
                            trans.Commit(); // commit the transaction
                        }

                        successfulCommands.Add(command); // add the command to the list of successful commands
                    }
                    catch (SqlException ex)
                    {
                        if (_enableLogging) // log the error, if logging is enabled
                            LogError(ex);

                        failedCommands.Add(command); // add the command to the list of failed commands
                    }
                }
            }
            catch (Exception ex) when (ex is SqlException || ex is InvalidOperationException)
            {
                throw; // rethrow the exception, if it's a SQL or connection-related error
            }
            finally
            {
                foreach (var conn in _connections.Values) // close all open connections
                    await conn.CloseAsync();
            }

            return successfulCommands; // return the list of successful commands
        }

        private async Task<SqlConnection> GetConnection(string serverName)
        {
            SqlConnection connection = null;

            _lock.EnterUpgradeableReadLock(); // acquire a read lock to check if the connection exists in the dictionary
            try
            {
                if (_connections.TryGetValue(serverName, out connection)) // get the existing connection from the dictionary
                    return connection; // return the existing connection
            }
            finally
            {
                _lock.ExitUpgradeableReadLock(); // release the read lock and acquire a write lock to add the new connection to the dictionary
            }

            var connStr = GetConnectionString(serverName); // get the connection string for the server
            connection = new SqlConnection(connStr); // create a new connection with the specified connection string
            await connection.OpenAsync(); // open the connection

            _lock.EnterWriteLock(); // acquire a write lock to add the new connection to the dictionary
            try
            {
                _connections.Add(serverName, connection); // add the new connection to the dictionary
            }
            finally
            {
                _lock.ExitWriteLock(); // release the write lock and return the new connection
            }

            return connection;
        }

        private string GetServer(string connectionString)
        {
            var builder = new SqlConnectionStringBuilder(connectionString);
            return builder.DataSource;
        }

        private string GetConnectionString(string serverName)
        {
            // TODO: Replace with your own connection string format for the specified SQL server
            return $"Data Source={serverName};Initial Catalog=myDatabase;Integrated Security=True";
        }

        private void LogError(SqlException ex)
        {
            // TODO: Replace with your own error logging mechanism, if desired
            Console.WriteLine($"[SQL Error] {ex.Message}");
        }

        public async Task<List<SqlCommand>> ExecuteBatchAsync(string commandText)
        {
            var commands = GetCommands(commandText); // get the list of SQL commands from the specified text
            return await ExecuteBatchAsync(commands); // execute the batch of commands and return the successful or failed commands
        }

        public async Task<List<SqlCommand>> ExecuteBatchAsync(string[] commandTexts)
        {
            var commands = new List<SqlCommand>(); // create a list for the SQL commands
            foreach (var commandText in commandTexts) // add each command text to the list
                commands.Add(new SqlCommand(commandText, GetConnection));
            return await ExecuteBatchAsync(commands); // execute the batch of commands and return the successful or failed commands
        }

        public async Task<List<SqlCommand>> ExecuteBatchAsync(IEnumerable<string> commandTexts)
        {
            var commands = new List<SqlCommand>(); // create a list for the SQL commands
            foreach (var commandText in commandTexts) // add each command text to the list
                commands.Add(new SqlCommand(commandText, GetConnection));
            return await ExecuteBatchAsync(commands); // execute the batch of commands and return the successful or failed commands
        }

        public async Task<List<SqlCommand>> ExecuteBatchAsync(params string[] commandTexts)
        {
            var commands = new List<SqlCommand>(); // create a list for the SQL commands
            foreach (var commandText in commandTexts) // add each command text to the list
                commands.Add(new SqlCommand(commandText, GetConnection));
            return await ExecuteBatchAsync(commands); // execute the batch of commands and return the successful or failed commands
        }

        public async Task<List<SqlCommand>> ExecuteBatchAsync(IEnumerable<string> commandTexts, int batchSize)
        {
            var commands = new List<SqlCommand>(); // create a list for the SQL commands
            foreach (var commandText in commandTexts) // add each command text to the list
                commands.Add(new SqlCommand(commandText, GetConnection));
            return await ExecuteBatchAsync(commands, batchSize); // execute the batch of commands and return the successful or failed commands
        }

        public async Task<List<SqlCommand>> ExecuteBatchAsync(params string[] commandTexts)
        {
            var commands = new List<SqlCommand>(); // create a list for the SQL commands
            foreach (var commandText in commandTexts) // add each command text to the list
                commands.Add(new SqlCommand(commandText, GetConnection));
            return await ExecuteBatchAsync(commands); // execute the batch of commands and return the successful or failed commands
        }

        public async Task<List<SqlCommand>> ExecuteBatchAsync(IEnumerable<string> commandTexts, int batchSize)
        {
            var commands = new List<SqlCommand>(); // create a list for the SQL commands
            foreach (var commandText in commandTexts) // add each command text to the list
                commands.Add(new SqlCommand(commandText, GetConnection));
            return await ExecuteBatchAsync(commands, batchSize); // execute the batch of commands and return the successful or failed commands
        }

        public async Task<List<SqlCommand>> ExecuteBatchAsync(string commandText, int batchSize)
        {
            var commands = GetCommands(commandText); // get the list of SQL commands from the specified text
            return await ExecuteBatchAsync(commands, batchSize); // execute the batch of commands and return the successful or failed commands
        }

        private List<SqlCommand> GetCommands(string commandText)
        {
            var commands = new List<SqlCommand>(); // create a list for the SQL commands
            using (var reader = SqlCommand.Parse(commandText).ExecuteReader()) // parse the specified text as a SQL command and execute it
            {
                while (reader.Read()) // read each row from the command result set
                {
                    var text = ""; // initialize an empty string for the current command text
                    for (var i = 0; i < reader.FieldCount; i++) // loop through each field in the current row
                    {
                        if (!string.IsNullOrEmpty(text)) // append a space if there is already text in the command
                            text += " ";

                        var value = reader[i]; // get the value of the current field
                        text += (value != null) ? value.ToString() : ""; // add the string representation of the value to the command text
                    }

                    commands.Add(new SqlCommand(text, GetConnection)); // add the current command to the list of commands
                }
            }

            return commands; // return the list of SQL commands
        }

        public async Task<List<SqlCommand>> ExecuteBatchAsync(string[] commandTexts, int batchSize)
        {
            var commands = new List<SqlCommand>(); // create a list for the SQL commands
            foreach (var commandText in commandTexts) // add each command text to the list
                commands.Add(new SqlCommand(commandText, GetConnection));
            return await ExecuteBatchAsync(commands, batchSize); // execute the batch of commands and return the successful or failed commands
        }

        public async Task<List<SqlCommand>> ExecuteBatchAsync(IEnumerable<string> commandTexts, int batchSize)
        {
            var commands = new List<SqlCommand>(); // create a list for the SQL commands
            foreach (var commandText in commandTexts) // add each command text to the list
                commands.Add(new SqlCommand(commandText, GetConnection));
            return await ExecuteBatchAsync(commands, batchSize); // execute the batch of commands and return the successful or failed commands
        }

        public async Task<List<SqlCommand>> ExecuteBatchAsync(params string[] commandTexts)
        {
            var commands = new List<SqlCommand>(); // create a list for the SQL commands
            foreach (var commandText in commandTexts) // add each command text to the list
                commands.Add(new SqlCommand(commandText, GetConnection));
            return await ExecuteBatchAsync(commands); // execute the batch of commands and return the successful or failed commands
        }

        public async Task<List<SqlCommand>> ExecuteBatchAsync(IEnumerable<string> commandTexts)
        {
            var commands = new List<SqlCommand>(); // create a list for the SQL commands
            foreach (var commandText in commandTexts) // add each command text to the list
                commands.Add(new SqlCommand(commandText, GetConnection));
            return await ExecuteBatchAsync(commands); // execute the batch of commands and return the successful or failed commands
        }

        public async Task<List<SqlCommand>> ExecuteBatchAsync(string commandText)
        {
            var commands = new List<SqlCommand>(); // create a list for the SQL commands
            using (var reader = SqlCommand.Parse(commandText).ExecuteReader()) // parse the specified text as a SQL command and execute it
            {
                while (reader.Read()) // read each row from the command result set
                {
                    var text = ""; // initialize an empty string for the current command text
                    for (var i = 0; i < reader.FieldCount; i++) // loop through each field in the current row
                    {
                        if (!string.IsNullOrEmpty(text)) // append a space if there is already text in the command
                            text += " ";

                        var value = reader[i]; // get the value of the current field
                        text += (value != null) ? value.ToString() : ""; // add the string representation of the value to the command text
                    }

                    commands.Add(new SqlCommand(text, GetConnection)); // add the current command to the list of commands
                }
            }

            return await ExecuteBatchAsync(commands); // execute the batch of commands and return the successful or failed commands
        }
    }
}
```

This class provides a simple way to execute multiple SQL commands in a single batch. It takes a list of `SqlCommand` objects as input, executes them in a single transaction, and returns the results of each command in a list of `SqlCommand` objects.

The `ExecuteBatchAsync` method is the main entry point for executing a batch of SQL commands. It accepts a list of `SqlCommand` objects and an optional integer parameter for the batch size. If no batch size is specified, it will use the default value of 50.

The `GetConnection` method is used to obtain a database connection from the `IDbConnectionFactory`. The connection is then used to execute the SQL commands in the batch.

The `ExecuteBatchAsync` method is responsible for executing the batch of SQL commands and returning the results. It uses the `SqlCommandBuilder` class to build the SQL query based on the input list of `SqlCommand` objects. It then executes the query using a `DbDataReader`. The results are returned as a list of `SqlCommand` objects.

The `Dispose` method is used to clean up any resources used by the class, such as the database connection.

Here's an example of how to use the `SqlBatchExecutor` class:
```csharp
using (var executor = new SqlBatchExecutor(connectionFactory))
{
    var commands = new List<SqlCommand>
    {
        new SqlCommand("SELECT * FROM Customers WHERE CustomerID = @CustomerID", connection),
        new SqlCommand("SELECT * FROM Orders WHERE OrderID = @OrderID", connection)
    };

    commands[0].Parameters.Add(new SqlParameter("@CustomerID", 1));
    commands[1].Parameters.Add(new SqlParameter("@OrderID", 10248));

    var results = await executor.ExecuteBatchAsync(commands);
}
```
This code creates a list of two `SqlCommand` objects and adds parameters to each command. It then passes the list of commands to the `ExecuteBatchAsync` method of the `SqlBatchExecutor` class, which executes the batch of SQL commands and returns the results as a list of `SqlCommand` objects.

The `IDbConnectionFactory` interface provides a way for the `SqlBatchExecutor` class to obtain database connections from an external source. This allows you to use the `SqlBatchExecutor` class with different types of databases, such as Microsoft SQL Server or MySQL.

Here's an example of how to implement the `IDbConnectionFactory` interface:
```csharp
