```scss
use std::{
    collections::HashMap,
    sync::{Arc, Mutex},
};

struct UserAccount {
    username: String,
    password: String,
    role: String,
}

struct FSAStateList {
    states: HashMap<String, Vec<UserAccount>>,
}

impl FSAStateList {
    fn new() -> Self {
        Self {
            states: HashMap::new(),
        }
    }

    fn add_state(&mut self, state: String) {
        self.states.insert(state, Vec::new());
    }

    fn remove_state(&mut self, state: String) {
        self.states.remove(&state);
    }

    fn get_users(&self, state: String) -> &Vec<UserAccount> {
        return self.states.get(&state).unwrap();
    }
}
