    [ApiController]
    [Route("[controller]")]
    public class ProductsController : ControllerBase
    {
        private readonly IConfiguration _configuration;
        private readonly IHttpClientFactory _httpClientFactory;
        private readonly IProductService _productService;
        private readonly IDbContext _dbContext;

        public ProductsController(IConfiguration configuration, IHttpClientFactory httpClientFactory, IProductService productService, IDbContext dbContext)
        {
            _configuration = configuration;
            _httpClientFactory = httpClientFactory;
            _productService = productService;
            _dbContext = dbContext;
        }

        [HttpPost]
        public async Task<IActionResult> Post([FromBody] ProductRequest request)
        {
            // Validate input data
            if (!ModelState.IsValid)
                return BadRequest(ModelState);

            // Sanitize HTML content to prevent injection attacks
            request.Description = Sanitizer.Sanitize(request.Description);

            // Authenticate and authorize the user
            var userId = User.GetUserId();
            if (userId == null)
                return Unauthorized();

            // Retrieve the product from the database
            var product = await _dbContext.Products.FindAsync(request.ProductId);

            // Check if the product exists and is visible to the user
            if (product == null || !product.IsVisibleToUser(userId))
                return NotFound();

            // Update the product's data
            product.Name = request.Name;
            product.Description = request.Description;
            product.Price = request.Price;
            product.UpdatedAt = DateTime.Now;

            // Save changes to the database
            await _dbContext.SaveChangesAsync();

            // Update the cache with the updated product data
            var cacheKey = GetCacheKey(product.Id);
            var cacheValue = JsonConvert.SerializeObject(product);
            _httpClientFactory.CreateHttpClient().PutStringAsync($"{_configuration["CACHE_URL"]}/products/{cacheKey}", cacheValue);

            // Update the CDN with the updated product data
            var cdnUrl = $"{_configuration["CDN_URL"]}/products/{product.Id}";
            await _httpClientFactory.CreateHttpClient().PutStringAsync(cdnUrl, cacheValue);

            // Return a success response
            return Ok();
        }
    }
}
```
