import java.util.concurrent.locks.ReentrantLock;

public class StateManager {
    private final Map<String, MoSTState> stateCache = new ConcurrentHashMap<>();
    private final Lock cacheLock = new ReentrantLock();

    public void loadState(String stateName) {
        // Load state from external data source and validate against schema
        MoSTState loadedState = loadFromDataSource(stateName);
        validateAgainstSchema(loadedState);

        // Update cache with new state
        cacheLock.lock();
        try {
            stateCache.put(stateName, loadedState);
        } finally {
            cacheLock.unlock();
        }
    }

    public MoSTState getState(String stateName) {
        // Return cached state if available
        MoSTState state = stateCache.get(stateName);
        if (state != null) {
            return state;
        }

        // Load and cache new state if not found in cache
        loadState(stateName);
        return stateCache.get(stateName);
    }

    public void updateState(String stateName, MoSTState updatedState) {
        // Validate updated state against schema
        validateAgainstSchema(updatedState);

        // Update cache with new state
        cacheLock.lock();
        try {
            stateCache.put(stateName, updatedState);
        } finally {
            cacheLock.unlock();
        }
    }

