        // Perform a health check on the remote service before each iteration
        if (!remote_service_healthy(config->connection)) {
            printf("Remote service is not ready. Retrying in %d seconds...\n", BACKOFF_DELAY);
            sleep(BACKOFF_DELAY);
            continue;
