    fn add_tenant(&mut self, tenant_name: String, config: TenantConfig) {
        self.tenants.insert(tenant_name, Tenant::new(config));
    }

    // Retrieve an image from the cache if it exists, otherwise download and cache it
    fn get_image(&self, tenant: &Tenant, image_path: String) -> Result<Vec<u8>, ImageProcessingError> {
        let mut image_cache = self.image_cache.lock().unwrap();
        if let Some(cached_image) = image_cache.get(&image_path) {
            return Ok(cached_image.clone());
        }

        // Download the image from the CDN and cache it for future retrieval
        let cdn_url = format!("https://{}/{}", tenant.cdn_domain, image_path);
        let image_data = self.download_image(&cdn_url)?;
