#include <iostream>
#include <string>
#include <vector>
#include <thread>
#include <mutex>
#include <condition_variable>
#include <chrono>
#include <future>
#include <memory>
#include <unordered_map>
#include <utility>
#include <algorithm>

class GameEntity {
public:
    int id;
    std::string name;
    double position[3];
    bool isActive = true;
};

class SpatialHashMap {
private:
    std::unordered_map<int, std::vector<std::pair<double, GameEntity*>>> hashMap_;
    std::mutex mutex_;
public:
    void insert(int id, double position[3], GameEntity* entity) {
        std::lock_guard<std::mutex> lock(mutex_);
        hashMap_.insert({id, {{position[0], position[1], position[2]}, entity}});
    }

    void remove(int id) {
        std::lock_guard<std::mutex> lock(mutex_);
        hashMap_.erase(id);
    }

    std::vector<GameEntity*> query(double position[3], double radius) {
        std::lock_guard<std::mutex> lock(mutex_);
        std::vector<GameEntity*> entities;
        for (const auto& entry : hashMap_) {
            const double dx = position[0] - entry.second->position[0];
            const double dy = position[1] - entry.second->position[1];
            const double dz = position[2] - entry.second->position[2];
            const double distanceSquared = dx * dx + dy * dy + dz * dz;
            if (distanceSquared < radius * radius) {
                entities.push_back(entry.second);
            }
        }
        return entities;
    }
};

class AttackManager {
private:
    std::unordered_map<int, int> activeAttacks_; // map of entity id to attack type
    SpatialHashMap spatialHashMap_;
    std::mutex mutex_;
public:
    void addAttack(int entityId, int attackType) {
        std::lock_guard<std::mutex> lock(mutex_);
        activeAttacks_.insert({entityId, attackType});
    }

    void removeAttack(int entityId) {
        std::lock_guard<std::mutex> lock(mutex_);
        activeAttacks_.erase(entityId);
    }

    int getAttackType(int entityId) {
        std::lock_guard<std::mutex> lock(mutex_);
        if (activeAttacks_.find(entityId) != activeAttacks_.end()) {
            return activeAttacks_[entityId];
        } else {
            return -1; // attack not found
        }
    }
};

class GameStateManager {
private:
    std::unordered_map<int, GameEntity> entities_;
    AttackManager attackManager_;
    SpatialHashMap spatialHashMap_;
    std::mutex mutex_;
public:
    void addEntity(GameEntity entity) {
        std::lock_guard<std::mutex> lock(mutex_);
        entities_.insert({entity.id, entity});
    }

    void removeEntity(int entityId) {
        std::lock_guard<std::mutex> lock(mutex_);
        entities_.erase(entityId);
    }

    GameEntity* getEntityById(int entityId) {
        std::lock_guard<std::mutex> lock(mutex_);
        if (entities_.find(entityId) != entities_.end()) {
            return &entities_[entityId];
        } else {
            return nullptr; // entity not found
        }
    }

    void executeAttack(int entityId, int attackType) {
        std::lock_guard<std::mutex> lock(mutex_);
        if (entities_.find(entityId) != entities_.end()) {
            const GameEntity* entity = &entities_[entityId];
            if (attackManager_.getAttackType(entityId) == -1) { // not attacking yet
                attackManager_.addAttack(entityId, attackType);
                std::cout << "Added attack to entity with ID " << entityId << " using attack type " << attackType << std::endl;
            } else if (attackManager_.getAttackType(entityId) == attackType) { // already attacking this type
                return;
            } else { // switching attacks, remove old attack and add new one
                attackManager_.removeAttack(entityId);
                attackManager_.addAttack(entityId, attackType);
                std::cout << "Switched attack on entity with ID " << entityId << " from type " << attackManager_.getAttackType(entityId) << " to type " << attackType << std::endl;
            }
        }
    }

    void executeDynamicAttackSequence(int entityId, int attackTypes[], int numAttacks) {
        if (numAttacks <= 0 || numAttacks > MAX_ATTACKS_PER_ENTITY) { // validate input
            return;
        }

        std::lock_guard<std::mutex> lock(mutex_);
        const GameEntity* entity = getEntityById(entityId);
        if (entity == nullptr) { // check if entity exists
            return;
        }

        int currentAttackType = attackManager_.getAttackType(entityId);
        if (currentAttackType != -1 && numAttacks < MAX_ATTACKS_PER_ENTITY) { // check if entity is already attacking and there are not enough attacks in the sequence
            return;
        }

        int nextAttackIndex = 0;
        while (nextAttackIndex < numAttacks && currentAttackType != -1) {
            if (currentAttackType == attackTypes[nextAttackIndex]) { // check if attack type is already in the sequence
                break;
            } else {
                nextAttackIndex++;
            }
        }

        if (nextAttackIndex < numAttacks) { // add new attacks to the end of the sequence
            for (int i = 0; i < numAttacks - nextAttackIndex; i++) {
                attackManager_.addAttack(entityId, attackTypes[i + nextAttackIndex]);
            }
        } else if (nextAttackIndex == numAttacks) { // remove old attacks from the sequence
            while (attackManager_.getAttackType(entityId) != -1) {
                attackManager_.removeAttack(entityId);
            }
        }
    }
};

class GameLogic {
private:
    GameStateManager gameStateManager_;
    SpatialHash spatialHash_;
public:
    void initialize() {
        // Initialize game state manager and spatial hash here
    }

    void update(float deltaTime) {
        // Update game logic here, call relevant functions in game state manager and spatial hash as needed
    }
};

int main() {
    GameLogic gameLogic;
    gameLogic.initialize();

    // Testing dynamic attack sequence code
    const int entityId = 0; // test entity ID
    const int attackTypes[] = {1, 2, 3}; // attack types to add/remove from sequence
    const int numAttacks = sizeof(attackTypes) / sizeof(int); // number of attacks in the sequence
    gameLogic.gameStateManager_.executeDynamicAttackSequence(entityId, attackTypes, numAttacks);
    return 0;
}
