Here is an example of how you could implement the modular, scalable document processing service in C++:
```
#include <iostream>
#include <fstream>
#include <vector>
#include <string>
#include <map>
#include <memory>
#include <chrono>

// Document processing classes
class Document {
public:
    virtual void process() = 0;
};

class PDFDocument : public Document {
public:
    explicit PDFDocument(const std::string& filePath) {
        // Open the PDF document and extract text and metadata
        m_pdfFile.open(filePath, std::ios::binary);
        // ...
    }

    void process() override {
        // Extract text and metadata from the PDF document
        std::string text = extractText();
        std::map<std::string, std::string> metadata = extractMetadata();
        // Process the extracted text and metadata
        // ...
    }

private:
    std::ifstream m_pdfFile;
};

class WordDocument : public Document {
public:
    explicit WordDocument(const std::string& filePath) {
        // Open the Word document and extract text and metadata
        m_wordFile.open(filePath, std::ios::binary);
        // ...
    }

    void process() override {
        // Extract text and metadata from the Word document
        std::string text = extractText();
        std::map<std::string, std::string> metadata = extractMetadata();
        // Process the extracted text and metadata
        // ...
    }

private:
    std::ifstream m_wordFile;
};

class ImageDocument : public Document {
public:
    explicit ImageDocument(const std::string& filePath) {
        // Open the image file
        m_image.open(filePath, std::ios::binary);
        // ...
    }

    void process() override {
        // Extract text and metadata from the image file
        std::string text = extractText();
        std::map<std::string, std::string> metadata = extractMetadata();
        // Process the extracted text and metadata
        // ...
    }

private:
    std::ifstream m_image;
};

// Document processing service
class DocumentService {
public:
    DocumentService() {}

    void processDocument(const std::string& filePath) {
        // Create a new document instance based on the file type
        Document* doc = createDocument(filePath);
        if (doc != nullptr) {
            // Process the document
            doc->process();
            // Delete the document instance
            delete doc;
        } else {
            std::cout << "Failed to process document: " << filePath << std::endl;
        }
    }

private:
    Document* createDocument(const std::string& filePath) {
        if (filePath.ends_with(".pdf")) {
            return new PDFDocument(filePath);
        } else if (filePath.ends_with(".doc") || filePath.ends_with(".docx")) {
            return new WordDocument(filePath);
        } else if (filePath.ends_with(".jpg") || filePath.ends_with(".png")) {
            return new ImageDocument(filePath);
        } else {
            std::cout << "Unsupported document type: " << filePath << std::endl;
            return nullptr;
        }
    }
};

int main() {
    // Create a new document service instance
    DocumentService service;

    // Process documents concurrently using multiple threads
    std::vector<std::thread> threads;
    for (const auto& filePath : {"document1.pdf", "document2.docx", "image.jpg"}) {
        threads.push_back(std::thread([&service, filePath]() {
            service.processDocument(filePath);
        }));
    }

    for (auto& thread : threads) {
        thread.join();
    }

    return 0;
}
```
This implementation uses a polymorphic design pattern to allow for different document types (PDF, Word, and Image) to be processed in the same manner. The `Document` class is an abstract base class that defines a virtual `process()` method, while the `PDFDocument`, `WordDocument`, and `ImageDocument` classes are derived from `Document`.

