PemFile secureStringManager(char *input_string, int size_limit, OAuthCredentials credentials, bool caching, bool retry) {
    // Initialize variables
    PemFile pem_file = NULL;
    char *oauth_token = NULL;
    time_t cache_expiration = 0;
