    // Function to get a free thread from the pool
    fn get_free_thread(&mut self) -> Option<usize> {
        let mut idx = None;
        for i in 0..self.threads.len() {
            if self.threads[i].active == false {
                idx = Some(i);
                break;
            }
        }

        idx
    }

    // Function to mark a thread as active and return its id
    fn activate_thread(&mut self) -> Option<usize> {
        let mut idx = None;
        for i in 0..self.threads.len() {
            if self.threads[i].active == false {
                idx = Some(i);
                break;
            }
        }

        if let Some(idx) = idx {
            self.threads[idx].active = true;
        }

        idx
    }

    // Function to mark a thread as inactive and return its id
    fn deactivate_thread(&mut self, id: usize) -> bool {
        let mut ret = false;

        if let Some(idx) = self.threads.iter().position(|x| x.id == id) {
            self.threads[idx].active = false;
            ret = true;
        }

        ret
