// Update and Delete methods for user resources
public class UserResource {
    // Map to store user data
    private static final ConcurrentHashMap<String, UserData> users = new ConcurrentHashMap<>();

    // Method to update a user resource
    public void updateUser(String username, UserData updatedData) {
        UserData existingData = users.get(username);
        if (existingData != null) {
            // Calculate and validate MD5 hash of the modified resource
            String md5Hash = calculateMD5Hash(updatedData);
            if (!md5Hash.equals(existingData.getMd5Hash())) {
                throw new InvalidInputException("Invalid data provided");
            }
        }
        // Update the user data in the map
        users.put(username, updatedData);
    }

    // Method to delete a user resource
    public void deleteUser(String username) {
        UserData existingData = users.get(username);
        if (existingData != null) {
            // Implement soft-delete mechanism that retains historical records for auditing purposes
            users.remove(username);
            return;
        }
        throw new ResourceNotFoundException("User not found");
    }

    // Method to calculate and validate MD5 hash of the modified resource
    private String calculateMD5Hash(UserData updatedData) {
        // Calculate the MD5 hash of the modified data
        String md5Hash = Hashing.md5().hashString(updatedData.toString(), StandardCharsets.UTF_8).toString();
        return md5Hash;
    }
}
