// Command-line argument parsing and input handling
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <getopt.h>

int main(int argc, char *argv[]) {
    // Define command-line options and their arguments
    static struct option long_options[] = {
        {"manpage", no_argument, 0, 'm'},
        {"character-statistics", no_argument, 0, 'c'},
        {"output-file", required_argument, 0, 'o'},
        {0, 0, 0, 0}
    };

    // Define file descriptors and other variables
    int fd;
    char *filepath = NULL;
    char *output_file = NULL;
    size_t file_size = 0;
    ssize_t bytes_read;
    long line_count = 0;
    double avg_line_length = 0.0;
    int keyword_found = 0;

    // Process command-line arguments and options
    while (1) {
        int option_index = 0;
        int c = getopt_long(argc, argv, "mco:", long_options, &option_index);
        if (c == -1) break;

        switch (c) {
            case 'm':
                // Print manpage and exit
                printf("Usage: %s [OPTION]... FILE\n", argv[0]);
                printf("  -m, --manpage             Show manpage for command-line tool\n");
                printf("  -c, --character-statistics  Calculate average character length of lines\n");
                printf("  -o, --output-file FILE    Output results to file\n");
                return 0;
            case 'c':
                // Set keyword and output flag for character statistics
                keyword_found = 1;
                break;
            case 'o':
                // Set output file path
                output_file = optarg;
                break;
            default:
                // Print usage error message
                printf("Usage: %s [OPTION]... FILE\n", argv[0]);
                return 1;
        }
    }

    // Check for required arguments and set filepath
    if (optind < argc) {
        filepath = argv[optind];
    } else {
        printf("Error: No input file specified\n");
        return 1;
    }

    // Open file descriptor and check for errors
    fd = open(filepath, O_RDONLY);
    if (fd < 0) {
        perror("open");
        return 1;
    }

    // Process lines in the input file
    while ((bytes_read = read(fd, buf, BUFSIZ)) > 0) {
        line_count += count_lines(buf);
        avg_line_length += get_average_line_length(buf);
        if (keyword_found) {
            // Search for keywords in lines and update counters
            keyword_found = find_keywords(buf, &keyword_count, &word_count);
        }
    }

    // Close file descriptor and check for errors
    close(fd);
    if (bytes_read < 0) {
        perror("close");
        return 1;
    }

    // Print results to the specified output file or standard output
    if (output_file != NULL) {
        print_results(output_file, line_count, avg_line_length, keyword_found);
    } else {
        printf("Total lines: %ld\n", line_count);
        printf("Average line length: %.2f\n", avg_line_length);
        if (keyword_found) {
            printf("Keywords found: %d\n", keyword_count);
            printf("Total words: %d\n", word_count);
        } else {
            printf("No keywords found.\n");
        }
    }

    return 0;
}

// Count lines in a buffer and update line_count
long count_lines(char *buf) {
    long line_count = 0;

    // Iterate through the buffer, counting newlines
    while (*buf != '\0') {
        if (*buf == '\n') line_count++;
        buf++;
    }

    return line_count;
}

// Calculate the average length of lines in a buffer and update avg_line_length
double get_average_line_length(char *buf) {
    double avg_line_length = 0.0;
    long line_count = 0;

    // Iterate through the buffer, counting newlines
    while (*buf != '\0') {
        if (*buf == '\n') {
            line_count++;
            avg_line_length += (double)(buf - last_newline) / line_count;
            last_newline = buf + 1;
        }
        buf++;
    }

    return avg_line_length;
}

// Search for keywords in a buffer and update counters
int find_keywords(char *buf, int *keyword_count, int *word_count) {
    char delim[] = " \t\n"; // whitespace characters
    char **keywords = {"error", "failure"}; // list of keywords to search for
    int keyword_found = 0;
    int word_found = 0;

    // Iterate through the buffer, searching for keywords and words
    while (*buf != '\0') {
        if (strtok(buf, delim) != NULL) {
            // Check each word in the line for a keyword match
            char **word_ptr = strtok(buf, delim);
            while (word_ptr != NULL) {
                int i;
                for (i = 0; i < 2; i++) {
                    if (strcmp(word_ptr, keywords[i]) == 0) {
                        keyword_found++;
                        break; // found a match, continue to next line
                    }
                }
                word_ptr = strtok(NULL, delim);
            }
            if (keyword_found > 0) break; // found a keyword, stop searching
            else word_found++; // update total words in the line
        }
        buf++;
    }

    *keyword_count = keyword_found;
    *word_count = word_found;

    return keyword_found > 0 ? 1 : 0;
}

// Print results to a file or standard output
void print_results(char *filename, long line_count, double avg_line_length, int keyword_found) {
    FILE *output = fopen(filename, "w");
    if (output == NULL) {
        perror("fopen");
        return;
    }
    fprintf(output, "Total lines: %ld\n", line_count);
    fprintf(output, "Average line length: %.2f\n", avg_line_length);
    if (keyword_found) {
        fprintf(output, "Keywords found: %d\n", keyword_count);
        fprintf(output, "Total words: %d\n", word_count);
    } else {
        fprintf(output, "No keywords found.\n");
    }
    fclose(output);
}
```

This code uses a combination of `read`, `write`, and `malloc` to read from the input file and write the results to the output file. It also uses `strtok` to tokenize the input lines and find keywords. The results are printed to the specified output file or standard output using `fprintf`.

Here are some additional notes on the code:

* The `optind` variable is used to keep track of the index of the current argument in the command line arguments array. It is initialized to 1, which means that the first element of the array (the executable name) is skipped. This allows us to access the input file name as `argv[optind]`.
* The `O_RDONLY` flag is used when opening the input file in order to read it only and not write to it.
* The `perror` function is used to print an error message to standard error if there is an error reading from or writing to the file.
* The `find_keywords` function uses a combination of `strtok` and `strcmp` to search for keywords in the input lines. It returns 1 if any keyword is found, and 0 otherwise.
* The `print_results` function opens the output file using `fopen`, writes the results using `fprintf`, and closes the file using `fclose`. If there is an error opening or writing to the file, it prints an error message to standard error using `perror`.']

