        $this->setName('password-update');
        $this->setDescription('Update passwords in a database based on a list of text files');
        $this->addArgument(
            'file_list',
            InputArgument::REQUIRED,
            'The path to the file containing the list of text files'
        );
        $this->addOption(
            'character-mode',
            null,
            InputArgument::OPTIONAL,
            'Enable character mode for statistics',
            false
        );
        $this->addOption(
            'output-file',
            null,
            InputArgument::OPTIONAL,
            'The path to the file where the output should be written',
            null
        );
    }

    protected function execute(InputInterface $input, OutputInterface $output)
    {
        try {
            // Validate input arguments and options
            $fileList = $this->validateFileList($input->getArgument('file_list'));
            $characterMode = $input->getOption('character-mode');
            $outputFilePath = $input->getOption('output-file');

            // Process each file in the list
            foreach ($fileList as $file) {
                $this->processFile($file, $characterMode);
            }

            // Write output to a file if requested
            if (!is_null($outputFilePath)) {
                $this->writeOutputToFile($outputFilePath);
            }
        } catch (Exception $e) {
            $this->logger->error($e->getMessage());
        }
    }

    /**
     * Validate the file list provided as input and return a list of valid paths.
     *
     * @param string $fileList The path to the file containing the list of text files
     *
     * @return array A list of valid file paths
     */
    private function validateFileList($fileList)
    {
        // Load the file contents and split it into an array of file paths
        $fileContents = file_get_contents($fileList);
        $filePaths = explode("\n", $fileContents);

        // Validate each path and return a list of valid paths
        $validFilePaths = [];
        foreach ($filePaths as $path) {
            if (is_readable($path)) {
                $validFilePaths[] = $path;
            } else {
                throw new Exception(sprintf('File "%s" is not readable', $path));
            }
        }

        return $validFilePaths;
    }

    /**
     * Process a single file and update the passwords in the database.
     *
     * @param string $file The path to the text file
     * @param bool $characterMode Whether to enable character mode for statistics
     */
    private function processFile($file, $characterMode)
    {
        // Load the contents of the file
        $fileContents = file_get_contents($file);

        // Update the passwords in the database using the load function
        foreach (explode("\n", $fileContents) as $password) {
            if ($this->updatePassword($password)) {
                $this->logger->info(sprintf('Updated password for "%s"', $password));
            } else {
                $this->logger->warning(sprintf('Unable to update password for "%s"', $password));
            }
        }
    }

    /**
     * Update a single password in the database.
     *
     * @param string $password The new password
     *
     * @return bool Whether the password was updated successfully
     */
    private function updatePassword($password)
    {
        // Validate the password length and complexity
        if (strlen($password) < 8 || !preg_match('/[A-Z]/', $password) || !preg_match('/[a-z]/', $password)) {
            return false;
        }

        // Update the password in the database using a transaction to ensure consistency
        try {
            $this->dbh->beginTransaction();

            $stmt = $this->dbh->prepare('UPDATE users SET password = ? WHERE id = 1');
            $stmt->bindValue(1, password_hash($password, PASSWORD_DEFAULT));
            $stmt->execute();

            $this->dbh->commit();
        } catch (Exception $e) {
            $this->dbh->rollBack();
            throw new Exception('Unable to update password');
        }
    }

