import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

public class Md5HashService {
  private static final Logger logger = LoggerFactory.getLogger(Md5HashService.class);
  private static final ExecutorService executor = Executors.newCachedThreadPool();
  private static final MessageDigest md5Digest;

  static {
    try {
      md5Digest = MessageDigest.getInstance("MD5");
    } catch (NoSuchAlgorithmException e) {
      throw new RuntimeException(e);
    }
  }

  public static String hashToken(String token) {
    return md5Digest.digest(token.getBytes()).toString();
  }

  public static void updateHash(String token, long timestamp) {
    executor.submit(() -> {
      try {
        logger.info("Hashing token {} at time {}", token, timestamp);
        String hash = hashToken(token);
        // Persist the hash and timestamp to a database or cache
      } catch (Exception e) {
        logger.error("Failed to hash token {} at time {}", token, timestamp, e);
      }
    });
  }

  public static String getHash(String token) {
    return executor.submit(() -> {
      try {
        logger.info("Getting hash for token {}", token);
        // Retrieve the hash and timestamp from a database or cache
        if (hash != null && timestamp != null) {
          long currentTime = System.currentTimeMillis();
          if (currentTime - timestamp > 30 * 60 * 1000) { // 30 minutes in milliseconds
            logger.info("Hash expired for token {}", token);
            return null;
          } else {
            return hash;
          }
        }
      } catch (Exception e) {
        logger.error("Failed to get hash for token {}", token, e);
      }
    }).get();
  }
}
```
