class ServiceManager:
    def __init__(self):
        self.services = {}
        self.credentials = {}

    def add_service(self, name: str, service: object) -> None:
        """Add a new service instance to the manager."""
        if name in self.services:
            raise ValueError("Service with this name already exists.")
        else:
            self.services[name] = service

    def get_service(self, name: str) -> object:
        """Get a registered service instance by its name."""
        if name in self.services:
            return self.services[name]
        else:
            raise ValueError("Service with this name does not exist.")

    def add_credential(self, name: str, credential: Dict) -> None:
        """Add a new credential to the manager."""
        if name in self.credentials:
            raise ValueError("Credential with this name already exists.")
        else:
            self.credentials[name] = credential

    def get_credential(self, name: str) -> Dict:
        """Get a registered credential by its name."""
        if name in self.credentials:
            return self.credentials[name]
        else:
            raise ValueError("Credential with this name does not exist.")

