// Custom HTTP client library
const http = require('http');
const https = require('https');
const url = require('url');

function makeRequest(options) {
  return new Promise((resolve, reject) => {
    const request = https.request(options, (response) => {
      if (response.statusCode >= 200 && response.statusCode < 300) {
        resolve(response);
      } else {
        reject({
          status: response.statusCode,
          message: response.statusMessage
        });
      }
    });
    request.on('error', (err) => {
      reject(err);
    });
    request.end();
  });
}

// Retry logic with exponential backoff and circuit breaking
const MAX_RETRIES = 3;
const RETRY_DELAY = 1000; // 1 second
let currentRetryDelay = RETRY_DELAY;
let lastError;

function makeRequestWithRetries(options) {
  return new Promise((resolve, reject) => {
    makeRequest(options).then((response) => {
      resolve(response);
    }).catch((error) => {
      if (currentRetryDelay < RETRY_DELAY * MAX_RETRIES) {
        currentRetryDelay *= 2;
        setTimeout(() => {
          makeRequestWithRetries(options).then((response) => {
            resolve(response);
          }).catch((error) => {
            reject(error);
          });
        }, currentRetryDelay);
      } else {
        lastError = error;
        reject(lastError);
      }
    });
  });
}

// Aggregation endpoint
const aggregator = (request, response) => {
  const options = {
    method: 'GET',
    headers: {
      'Content-Type': 'application/json'
    },
    url: `http://example.com/api/data`
  };

  makeRequestWithRetries(options).then((response) => {
    const data = JSON.parse(response.body);
    response.send(JSON.stringify({
      data: data,
      pagination: {
        total: data.length,
        currentPage: 1,
        perPage: 10
      }
    }));
  }).catch((error) => {
    console.log(`Error fetching data from external service: ${error}`);
    response.sendStatus(500).send('Internal Server Error');
  });
};

// Deployment strategy
const deploy = (options) => {
  const http = require('http').createServer(aggregator);
  http.listen(80, () => {
    console.log(`RESTful API is running on port ${options.port}`);
  });
};

deploy({ port: 80 });
