import os
import sys
import re
from datetime import datetime

class LoggingFramework:
    def __init__(self, level=None, format=None, service=None):
        self.level = level
        self.format = format
        self.service = service

    @staticmethod
    def _get_env_var(name, default=None):
        return os.environ.get(name) or default

    @staticmethod
    def _get_config_value(key, default=None):
        config_file = LoggingFramework._get_env_var("CONFIG_FILE")
        if config_file:
            with open(config_file) as f:
                config = yaml.load(f, Loader=yaml.SafeLoader)
                return config.get(key) or default
        else:
            return None

    @staticmethod
    def _get_service_value(name, default=None):
        if LoggingFramework._get_env_var("SERVICE") == name:
            return True
        else:
            return False

    def _format_message(self, level, message, metadata={}):
        now = datetime.now().strftime("%Y-%m-%d %H:%M:%S")
        hostname = socket.gethostname()
        thread = threading.current_thread().getName()
        return f"{now} {hostname} {thread} {level}: {message}"

    def log(self, level, message, metadata={}, structured=False):
        if self.level and level < self.level:
            return
        if structured:
            formatted_message = json.dumps(metadata)
        else:
            formatted_message = self._format_message(level, message, metadata)
        if self.service:
            formatted_message += f" {self.service}"
        if self._get_env_var("LOGGING_URL") and self._get_env_var("LOGGING_METHOD"):
            try:
                requests.post(self._get_env_var("LOGGING_URL"), data=formatted_message, headers={"Content-Type": "application/json"})
            except requests.exceptions.RequestException:
                pass
        else:
            print(f"{formatted_message}\n")

    def debug(self, message, metadata={}, structured=False):
        self.log("DEBUG", message, metadata, structured)

    def info(self, message, metadata={}, structured=False):
        self.log("INFO", message, metadata, structured)

    def warning(self, message, metadata={}, structured=False):
        self.log("WARNING", message, metadata, structured)

    def error(self, message, metadata={}, structured=False):
        self.log("ERROR", message, metadata, structured)

    def critical(self, message, metadata={}, structured=False):
        self.log("CRITICAL", message, metadata, structured)
```']

