#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <errno.h>
#include <curl/curl.h>
#include <pthread.h>
#include <openssl/ssl.h>
#include "configuration.h"

struct api_endpoint {
    char *url;
    int timeout;
};

struct query_parameter {
    char *key;
    char *value;
};

struct configuration {
    struct api_endpoint *endpoints;
    size_t num_endpoints;
    struct query_parameter *query_parameters;
    size_t num_query_parameters;
    int timeout;
    int max_retries;
    int exponential_backoff;
    int circuit_breaking;
    int logging_level;
};

struct api_result {
    char *response;
    int status_code;
    long content_length;
    struct curl_slist *header_list;
};

struct thread_data {
    size_t index;
    struct configuration config;
    CURLM *curlm;
    pthread_mutex_t mutex;
    int error;
    struct api_result *result;
};

void *fetch_and_aggregate_data(void *ptr) {
    // cast ptr to thread data
    struct thread_data *data = (struct thread_data *)ptr;

    // initialize curl handle
    CURL *curl = curl_easy_init();

    // set URL and timeout
    char url[1024];
    snprintf(url, sizeof(url), "%s", data->config.endpoints[data->index].url);
    curl_easy_setopt(curl, CURLOPT_URL, url);
    curl_easy_setopt(curl, CURLOPT_TIMEOUT, data->config.timeout);

    // set query parameters
    struct curl_slist *query = NULL;
    for (size_t i = 0; i < data->config.num_query_parameters; i++) {
        char key[128];
        snprintf(key, sizeof(key), "%s", data->config.query_parameters[i].key);
        char value[128];
        snprintf(value, sizeof(value), "%s", data->config.query_parameters[i].value);
        query = curl_slist_append(query, key);
        query = curl_slist_append(query, value);
    }
    curl_easy_setopt(curl, CURLOPT_HTTPHEADER, query);

    // set error handling and logging options
    curl_easy_setopt(curl, CURLOPT_NOSIGNAL, 1);
    curl_easy_setopt(curl, CURLOPT_VERBOSE, data->config.logging_level);
    curl_easy_setopt(curl, CURLOPT_ERRORBUFFER, data->error);
    if (data->config.circuit_breaking) {
        curl_easy_setopt(curl, CURLOPT_FAILONERROR, 1);
        curl_easy_setopt(curl, CURLOPT_TIMEOUT_MS, data->config.timeout * 1000);
    }

    // perform request and get response
    CURLcode res = curl_easy_perform(curl);
    if (res != CURLE_OK) {
        fprintf(stderr, "CURL error: %s\n", curl_easy_strerror(res));
        data->result->status_code = -1;
        return NULL;
    }

    // get response code and content length
    long status_code = 0;
    curl_easy_getinfo(curl, CURLINFO_RESPONSE_CODE, &status_code);
    data->result->status_code = (int)status_code;
    long content_length = 0;
    curl_easy_getinfo(curl, CURLINFO_CONTENT_LENGTH_DOWNLOAD_T, &content_length);
    data->result->content_length = (long)content_length;

    // get header list and response body
    struct curl_slist *header_list = NULL;
    res = curl_easy_getinfo(curl, CURLINFO_HEADER_LIST, &header_list);
    if (res != CURLE_OK) {
        fprintf(stderr, "CURL error: %s\n", curl_easy_strerror(res));
        data->result->status_code = -1;
        return NULL;
    }
    data->result->header_list = header_list;
    res = curl_easy_getinfo(curl, CURLINFO_RESPONSE_BODY, &data->result->response);
    if (res != CURLE_OK) {
        fprintf(stderr, "CURL error: %s\n", curl_easy_strerror(res));
        data->result->status_code = -1;
        return NULL;
    }

    // clean up and return
    curl_slist_free_all(query);
    curl_easy_cleanup(curl);
    return data;
}

struct api_result *fetchAndAggregateData(struct configuration config, size_t num_endpoints) {
    // check inputs for validity and consistency
    if (!config.endpoints || !config.num_endpoints || config.timeout < 0 ||
        config.max_retries < 0 || config.exponential_backoff < 0 ||
        config.circuit_breaking < 0 || config.logging_level < 0) {
        return NULL;
    }
    if (num_endpoints != config.num_endpoints) {
        return NULL;
    }

    // initialize thread data and mutex
    struct thread_data *thread_data = calloc(num_endpoints, sizeof(*thread_data));
    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

    // perform requests in parallel using threads
    for (size_t i = 0; i < num_endpoints; i++) {
        thread_data[i].index = i;
        thread_data[i].config = config;
        thread_data[i].result = calloc(1, sizeof(*thread_data->result));
    }
    pthread_t *threads = malloc(num_endpoints * sizeof(*threads));
    for (size_t i = 0; i < num_endpoints; i++) {
        if (pthread_create(&threads[i], NULL, fetchAndAggregateData, &thread_data[i])) {
            fprintf(stderr, "Error creating thread %ld\n", i);
            return NULL;
        }
    }
    for (size_t i = 0; i < num_endpoints; i++) {
        pthread_join(threads[i], NULL);
    }

    // aggregate results and clean up
    struct api_result *results = calloc(num_endpoints, sizeof(*results));
    for (size_t i = 0; i < num_endpoints; i++) {
        if (!thread_data[i].result) {
            continue;
        }
        results[i] = *thread_data[i].result;
        free(thread_data[i].result);
    }
    free(threads);
    for (size_t i = 0; i < num_endpoints; i++) {
        free(thread_data[i].error);
    }
    free(thread_data);
    pthread_mutex_destroy(&mutex);
    return results;
}']

