  }

  // Get the current list of tables from the DBMS server
  vector<string> currentTables = getTableNamesFromDBMS();

  // Iterate over the tables in the query plan and check if they exist in the current table list
  for (auto& table : queryPlan.tables) {
    if (find(currentTables.begin(), currentTables.end(), table) == currentTables.end()) {
      // The table does not exist, so remove it from the query plan
      table = "";
