namespace DynamicTradingInsights
{
    public class TradingInsightsService : ITradingInsightsService
    {
        private readonly ILogger<TradingInsightsService> _logger;
        private readonly Dictionary<string, DataSource> _dataSources;
        private readonly CacheManager _cacheManager;

        public TradingInsightsService(ILogger<TradingInsightsService> logger)
        {
            _logger = logger;
            _dataSources = new Dictionary<string, DataSource>();
            _cacheManager = new CacheManager();
        }

        public async Task<List<dynamic>> GetTradingDataAsync(string symbol, int count = 10)
        {
            // Check if the data source is available and registered
            if (!_dataSources.ContainsKey(symbol))
            {
                throw new ArgumentException($"Invalid symbol: '{symbol}'");
            }

            // Get the data source for the given symbol
            var dataSource = _dataSources[symbol];

            // Retrieve the latest data from the cache or retrieve it from the data source
            var data = await _cacheManager.GetDataAsync(dataSource, count);

            // Return the list of dynamic objects representing the trading data
            return data;
        }

        public async Task<dynamic> GetTradingDataForSymbolAsync(string symbol)
        {
            // Check if the data source is available and registered
            if (!_dataSources.ContainsKey(symbol))
            {
                throw new ArgumentException($"Invalid symbol: '{symbol}'");
            }

            // Get the data source for the given symbol
            var dataSource = _dataSources[symbol];

            // Retrieve the latest data from the cache or retrieve it from the data source
            var data = await _cacheManager.GetDataAsync(dataSource);

            // Return the dynamic object representing the trading data
            return data;
        }

        public async Task RegisterDataSourceAsync(string name, DataSource dataSource)
        {
            // Check if the data source is already registered
            if (_dataSources.ContainsKey(name))
            {
                throw new ArgumentException($"Data source '{name}' is already registered.");
            }

            // Add the data source to the dictionary of data sources
            _dataSources.Add(name, dataSource);
        }

        public async Task UnregisterDataSourceAsync(string name)
        {
            // Check if the data source is registered
            if (!_dataSources.ContainsKey(name))
            {
                throw new ArgumentException($"Data source '{name}' is not registered.");
            }

            // Remove the data source from the dictionary of data sources
            _dataSources.Remove(name);
        }
    }
}
