    const int MAX_RETRIES = 3;
    const int RECOVERY_DELAY = 1000; // milliseconds

    Response response;
    int retries = 0;
    bool success = false;

    while (!success && retries < MAX_RETRIES) {
        try {
            // Sending a request to the external attack database API
            response = sendRequest(characterName);
            success = true;
        } catch (const std::exception& e) {
            std::cerr << "Error: " << e.what() << std::endl;
            retries++;
            std::this_thread::sleep_for(std::chrono::milliseconds(RECOVERY_DELAY));
        }
    }

    if (!success) {
        // Falling back to using cached or local attack data during outages
        response = getCachedAttacks(characterName);
