# Modular architecture with plugin support for new resource formats
import importlib.util
from typing import Dict

class ResourceFormatPlugin:
    def __init__(self, format: str):
        self.format = format
        self.module = None

    def load_module(self) -> bool:
        try:
            spec = importlib.util.spec_from_file_location(f"{self.format}_resource_loader", f"path/to/{self.format}.py")
            self.module = importlib.util.module_from_spec(spec)
            spec.loader.exec_module(self.module)
            return True
        except ModuleNotFoundError:
            return False

    def get_resource_bundle(self, bundle_id: str) -> Dict:
        if self.module is None:
            raise ValueError("No module found for this format")

        return self.module.get_resource_bundle(bundle_id)
