# Multi-threaded and asynchronous processing for concurrent bundle loading and updates
import threading
from typing import List

class BundleLoader:
    def __init__(self, cache_manager: CacheManager):
        self.cache_manager = cache_manager

    def load_bundle(self, bundle_id: str) -> Dict:
        return self.cache_manager.get_resource_bundle(bundle_id)

    def load_bundles(self, bundle_ids: List[str]) -> List[Dict]:
        thread_pool = [threading.Thread(target=self.load_bundle, args=(bundle_id,)) for bundle_id in bundle_ids]
        results = []

        for thread in thread_pool:
            thread.start()
            results.append(thread.join())

        return results
```
