#include <cstdint>
#include <random>
#include <mutex>
#include <unordered_map>

namespace FinancialRNG {
  class MTGenerator {
  private:
    static std::mutex seed_mutex;
    static std::unordered_map<uint64_t, std::mt19937> seeds;
    std::mt19937 rng;

  public:
    MTGenerator(uint64_t seed) {
      seed = seed ^ getSeed();
      std::lock_guard<std::mutex> lock(seed_mutex);
      seeds[seed] = std::mt19937(seed);
      rng = seeds[seed];
    }

    uint64_t getRandomNumber() {
      return std::uniform_int_distribution<uint64_t>(0, 2^64-1)(rng);
    }

    static uint64_t generateSeed() {
      std::lock_guard<std::mutex> lock(seed_mutex);
      return std::random_device()();
    }
  };
}
```
