<?php

class SessionTokenManager {
    private $redis;
    private $sessionTokens = array();

    public function __construct($redis) {
        $this->redis = $redis;
    }

    public function generateSessionToken($ttl, $charset) {
        // Generate a unique session token using the given TTL and charset
        $token = substr(md5(uniqid()), 0, $ttl);

        // Add the token to the list of active tokens
        $this->sessionTokens[] = $token;

        return $token;
    }

    public function isValidSessionToken($token) {
        // Check if the given token is valid and not expired
        return in_array($token, $this->sessionTokens);
    }

    public function getCachedSessionToken($token) {
        // Get the cached session token from Redis using the given token
        $cachedToken = $this->redis->get($token);

        return $cachedToken;
    }

    public function cacheSessionToken($token, $ttl) {
        // Cache the given session token in Redis with a given TTL
        $this->redis->setex($token, $ttl, time());
    }

    public function deleteCachedSessionToken($token) {
        // Delete the cached session token from Redis
        $this->redis->del($token);
    }
}
```
And here is an example of how to use the `SessionTokenManager` class:
