$token = $sessionTokenManager->generateSessionToken($ttl, $charset);

// Check if the session token is valid and not expired
if ($sessionTokenManager->isValidSessionToken($token)) {
    // Get the cached session token from Redis
    $cachedToken = $sessionTokenManager->getCachedSessionToken($token);

    // Cache the session token in Redis with a given TTL
    $ttl = 3600; // 1 hour
    $sessionTokenManager->cacheSessionToken($token, $ttl);
} else {
    // Delete the cached session token from Redis
    $sessionTokenManager->deleteCachedSessionToken($token);
}
