#include <sys/types.h>
#include <dirent.h>
#include <string>
#include <vector>
#include <map>
#include <queue>
#include <mutex>
#include <condition_variable>
#include <fstream>

// Global variables
std::map<std::string, std::string> service_urls; // Map of transcoding services and their URLs
std::vector<std::string> source_directories; // Vector of video source directories
std::vector<std::string> target_formats; // Vector of target video formats
std::vector<std::string> fallback_services; // Vector of fallback transcoding services
std::queue<std::pair<std::string, std::string>> job_queue; // Queue of jobs to be processed
std::mutex mtx; // Mutex for locking the queue and service URL map
std::condition_variable cv; // Condition variable for notifying threads when a job is available
std::atomic<bool> shutdown; // Atomic boolean indicating whether the pipeline should shut down

// Struct representing a video file in the source directory
struct VideoFile {
  std::string path;
  std::string filename;
};

// Function to load the transcoding service URLs from a JSON configuration file
void LoadServiceURLs(const char* config_file) {
  // Open the configuration file
  FILE* fp = fopen(config_file, "r");
  if (fp == NULL) {
    printf("Error: unable to open configuration file\n");
    return;
  }

  // Load the JSON data from the configuration file
  std::string json_data((std::istreambuf_iterator<char>(fp)), std::istreambuf_iterator<char>());
  fclose(fp);

  // Parse the JSON data to extract the transcoding service URLs
  nlohmann::json config = nlohmann::json::parse(json_data);
  for (auto& [service, url] : config["services"]) {
    service_urls[service] = url;
  }
}

// Function to load the video files from the source directories
void LoadVideoFiles() {
  // Traverse the source directories and load the video files
  for (auto& directory : source_directories) {
    DIR* dirp = opendir(directory.c_str());
    if (dirp == NULL) {
      printf("Error: unable to open source directory %s\n", directory.c_str());
      continue;
    }

    struct dirent *dp;
    while ((dp = readdir(dirp)) != NULL) {
      if (dp->d_name[0] == '.') {
        continue; // Skip hidden files and directories
      }

      std::string filepath = directory + "/" + dp->d_name;
      struct stat st;
      if (stat(filepath.c_str(), &st) != 0) {
        printf("Error: unable to access file %s\n", filepath.c_str());
        continue;
      }

      if ((st.st_mode & S_IFMT) == S_IFREG) { // Regular file
        VideoFile video = {directory, dp->d_name};
        job_queue.push(std::make_pair(video.path, video.filename));
      } else if ((st.st_mode & S_IFMT) == S_IFDIR) { // Directory
        LoadVideoFiles(filepath);
      }
    }
  }
}

// Function to perform the transcoding of a video file
void TranscodeVideo(std::string path, std::string filename) {
  // Get the URL of the current transcoding service
  std::string url = service_urls[current_service];

  // Construct the request for the transcoding service
  std::string req_data = "{\"path\": \"" + path + "\", \"filename\": \"" + filename + "\"}";
  curl_off_t length = req_data.length();

  // Perform the HTTP POST request to the transcoding service
  CURL* curl = curl_easy_init();
  if (curl) {
    curl_easy_setopt(curl, CURLOPT_URL, url.c_str());
    curl_easy_setopt(curl, CURLOPT_POSTFIELDS, req_data.c_str());
    curl_easy_setopt(curl, CURLOPT_HTTPHEADER, "Content-Length: " + std::to_string(length));
    curl_easy_setopt(curl, CURLOPT_TIMEOUT, 30); // Set a timeout of 30 seconds for the request

    CURLcode res = curl_easy_perform(curl);
    if (res != CURLE_OK) {
      printf("Error: unable to perform HTTP POST request\n");
      return;
    }
  } else {
    printf("Error: unable to initialize cURL\n");
    return;
  }

  // Get the response from the transcoding service
  curl_easy_setopt(curl, CURLOPT_WRITEDATA, &response);
  curl_easy_setopt(curl, CURLOPT_WRITEFUNCTION, WriteCallback);

  CURLcode res = curl_easy_perform(curl);
  if (res != CURLE_OK) {
    printf("Error: unable to perform HTTP POST request\n");
    return;
  }

  // Check the response status code and process the response data accordingly
  long response_code = 0;
  curl_easy_getinfo(curl, CURLINFO_RESPONSE_CODE, &response_code);
  if (response_code == 200) { // Transcoding successful
    printf("Transcoding successful for %s/%s\n", path.c_str(), filename.c_str());
  } else if (response_code == 404) { // Service unavailable
    printf("Error: service unavailable for transcoding of %s/%s\n", path.c_str(), filename.c_str());
    return;
  } else if (response_code == 503) { // Temporarily unavailable
    printf("Warning: temporarily unavailable for transcoding of %s/%s\n", path.c_str(), filename.c_str());
    return;
  } else { // Unknown error
    printf("Error: unknown error for transcoding of %s/%s\n", path.c_str(), filename.c_str());
    return;
  }
}

// Function to write the response data from the HTTP POST request
size_t WriteCallback(void* contents, size_t size, size_t nmemb, void* userp) {
  ((std::string*)userp)->append((char*)contents, size * nmemb);
  return size * nmemb;
}

