```c
#include <stdlib.h>
#include <stdio.h>
#include <string.h>

// Function to merge multiple resource bundles into a unified, optimized resource store
int mergeResourceBundles(char *bundlePaths[], int numBundles) {
  // Check for null pointer and empty array
  if (bundlePaths == NULL || numBundles <= 0) {
    printf("Error: Invalid input parameters\n");
    return -1;
  }

  // Initialize variables
  int i, j, k;
  char *buffer = NULL;
  size_t bufferSize = 0;
  FILE *fp = NULL;

  // Open all resource bundles and calculate total file size
  for (i = 0; i < numBundles; i++) {
    fp = fopen(bundlePaths[i], "r");
    if (fp == NULL) {
      printf("Error: Failed to open resource bundle '%s'\n", bundlePaths[i]);
      return -1;
    }
    bufferSize += (size_t)(fstat(fileno(fp), &st) ? 0 : st.st_size);
    fclose(fp);
  }

  // Allocate memory for the merged resource bundle
  buffer = malloc(bufferSize + 1);
  if (buffer == NULL) {
    printf("Error: Failed to allocate memory for merged resource bundle\n");
    return -1;
  }

  // Read all files into a single buffer
  size_t offset = 0;
  for (i = 0; i < numBundles; i++) {
    fp = fopen(bundlePaths[i], "r");
    if (fp == NULL) {
      printf("Error: Failed to open resource bundle '%s'\n", bundlePaths[i]);
      return -1;
    }
    size_t bytesRead = fread(buffer + offset, 1, bufferSize - offset, fp);
    if (bytesRead < bufferSize - offset) {
      printf("Error: Failed to read from resource bundle '%s'\n", bundlePaths[i]);
      return -1;
    }
    offset += bytesRead;
    fclose(fp);
  }

  // Write the merged resource bundle to disk
  FILE *outFile = fopen("merged_resource_bundle.dat", "wb");
  if (outFile == NULL) {
    printf("Error: Failed to open output file for writing\n");
    return -1;
  }
  size_t bytesWritten = fwrite(buffer, 1, bufferSize, outFile);
  if (bytesWritten < bufferSize) {
    printf("Error: Failed to write to output file\n");
    return -1;
  }
  fclose(outFile);

  // Clean up memory
  free(buffer);

  return 0;
}
```
