    void* connection;
} PasswordAndConnectionData;

static pthread_mutex_t dataMutex = PTHREAD_MUTEX_INITIALIZER; // Mutex to protect the data structure
static pthread_cond_t dataCond = PTHREAD_COND_INITIALIZER; // Condition variable to signal changes in the data structure

// Define a function to validate and process the session data
int validateAndProcess(SessionData* session) {
    int errorCode = 0; // Initialize the error code to success (0)

    // Check if the password is non-empty and non-null
    if (!session->password || !strlen(session->password)) {
        errorCode = ERROR_INVALID_PASSWORD;
        goto handleError;
    }

    // Validate the connection object
    if (!session->connection) {
        errorCode = ERROR_INVALID_CONNECTION;
        goto handleError;
