        errorCode = ERROR_INVALID_CONNECTION;
        goto handleError;
    }

    // Verify the callback function is not null and can safely handle asynchronous operations without causing deadlocks or race conditions within the main thread
    if (!session->callback || !session->metadata) {
        errorCode = ERROR_INVALID_CALLBACK;
        goto handleError;
    }

