using System;
using System.Security.Cryptography;
using System.Text;

namespace SecureHasher
{
    public class Hasher
    {
        private readonly Dictionary<string, string> _cache = new Dictionary<string, string>();
        private readonly ILogger _logger;
        private readonly RateLimiter _rateLimiter;

        public Hasher(ILogger logger, RateLimiter rateLimiter)
        {
            _logger = logger;
            _rateLimiter = rateLimiter;
        }

        public string GenerateHash(string algorithm, string input)
        {
            if (string.IsNullOrEmpty(input))
            {
                return "Invalid input";
            }

            var hashAlgorithm = GetHashAlgorithm(algorithm);
            var hash = hashAlgorithm.ComputeHash(Encoding.UTF8.GetBytes(input));
            _cache[input] = Convert.ToBase64String(hash);
            return _cache[input];
        }

        public string GetCachedHash(string algorithm, string input)
        {
            if (_cache.ContainsKey(input))
            {
                return _cache[input];
            }
            else
            {
                var hashAlgorithm = GetHashAlgorithm(algorithm);
                var hash = hashAlgorithm.ComputeHash(Encoding.UTF8.GetBytes(input));
                _cache[input] = Convert.ToBase64String(hash);
                return _cache[input];
            }
        }

        public void ClearCache(string algorithm)
        {
            if (_cache.ContainsKey(algorithm))
            {
                _cache.Remove(algorithm);
            }
        }

        private HashAlgorithm GetHashAlgorithm(string algorithm)
        {
            switch (algorithm)
            {
                case "SHA256":
                    return SHA256.Create();
                case "BLAKE2b":
                    return new Blake2B();
                default:
                    throw new ArgumentException("Invalid hashing algorithm", nameof(algorithm));
            }
        }

        public class Blake2B : HashAlgorithm
        {
            private readonly Blake2BBlockCipher _cipher;

            public Blake2B()
            {
                _cipher = new Blake2BBlockCipher();
            }

            public override byte[] ComputeHash(byte[] input)
            {
                return _cipher.ComputeHash(input);
            }
        }
    }
}
```
