#include "dao_layer.h"

// Define the maximum number of messages that can be stored in the pool
#define MAX_MESSAGES 1000

// Define the maximum size of each message (in bytes)
#define MESSAGE_SIZE 1024

// Define the maximum number of threads that can access the pool simultaneously
#define MAX_THREADS 10

// Define the number of messages to pre-allocate in the pool at initialization time
#define PREALLOCATED_MESSAGES 50

// Define the number of retries for message delivery before giving up
#define MESSAGE_RETRY_COUNT 3

// Define the delay between retries (in milliseconds)
#define MESSAGE_RETRY_DELAY 1000

// Define the maximum time to wait for a message delivery (in milliseconds)
#define MESSAGE_TIMEOUT 5000

// Structure to represent a pool of LTE DL CCCH messages
struct MessagePool {
    // An array of LTE DL CCCH message structures
    LTE_DL_CCCH_MESSAGE_T* messages[MAX_MESSAGES];

    // The number of messages currently in the pool
    size_t count;

    // The next available index to allocate a new message
    size_t next_index;

    // A lock for synchronizing access to the pool
    pthread_mutex_t mutex;
};

// Structure to represent a thread-safe queue of messages
struct MessageQueue {
    // An array of messages
    LTE_DL_CCCH_MESSAGE_T* messages[MAX_THREADS];

    // The number of messages currently in the queue
    size_t count;

    // The next available index to enqueue a new message
    size_t next_index;

    // A lock for synchronizing access to the queue
    pthread_mutex_t mutex;
};

// Structure to represent a pool of LTE DL CCCH messages with thread-safe access and scaling capabilities
struct LTE_DL_CCCH_MessagePool {
    // The message pool
    struct MessagePool* pool;

    // The message queue
    struct MessageQueue* queue;

    // The number of threads currently using the pool
    size_t thread_count;

    // A lock for synchronizing access to the pool and queue
    pthread_mutex_t mutex;
};

// Function to initialize a message pool with pre-allocated messages
static void init_message_pool(struct MessagePool* pool, size_t preallocated_messages) {
    // Initialize the pool structure
    pool->count = 0;
    pool->next_index = 0;
    pthread_mutex_init(&pool->mutex, NULL);

    // Pre-allocate the specified number of messages
    for (size_t i = 0; i < preallocated_messages; ++i) {
        pool->messages[i] = malloc(MESSAGE_SIZE);
        memset(pool->messages[i], 0, MESSAGE_SIZE);
        pool->count++;
    }
}

// Function to initialize a message queue with pre-allocated messages
static void init_message_queue(struct MessageQueue* queue) {
    // Initialize the queue structure
    queue->count = 0;
    queue->next_index = 0;
    pthread_mutex_init(&queue->mutex, NULL);
}

// Function to allocate a new message from the pool
static LTE_DL_CCCH_MESSAGE_T* allocate_message(struct MessagePool* pool) {
    // Acquire the lock on the pool
    pthread_mutex_lock(&pool->mutex);

    // Check if the pool is empty and there are no threads using it
    if (pool->count == 0 || pool->next_index == 0) {
        // Release the lock on the pool
        pthread_mutex_unlock(&pool->mutex);
        return NULL;
    }

    // Allocate a new message from the pool
    LTE_DL_CCCH_MESSAGE_T* message = pool->messages[pool->next_index - 1];
    memset(message, 0, MESSAGE_SIZE);

    // Update the pool structure
    pool->count--;
    pool->next_index--;

    // Release the lock on the pool
    pthread_mutex_unlock(&pool->mutex);

    return message;
}

// Function to free a message from the pool
static void free_message(struct MessagePool* pool, LTE_DL_CCCH_MESSAGE_T* message) {
    // Acquire the lock on the pool
    pthread_mutex_lock(&pool->mutex);

    // Check if there are any messages in the pool
    if (pool->count == 0 || pool->next_index >= MAX_MESSAGES) {
        // Release the lock on the pool
        pthread_mutex_unlock(&pool->mutex);
        return;
    }

    // Free the message and update the pool structure
    memset(message, 0, MESSAGE_SIZE);
    pool->messages[pool->next_index] = message;
    pool->count++;
    pool->next_index++;

    // Release the lock on the pool
    pthread_mutex_unlock(&pool->mutex);
}

// Function to push a message onto the queue
static void enqueue_message(struct MessageQueue* queue, LTE_DL_CCCH_MESSAGE_T* message) {
    // Acquire the lock on the queue
    pthread_mutex_lock(&queue->mutex);

    // Check if there is enough space in the queue to store the message
    if (queue->count >= MAX_THREADS) {
        // Release the lock on the queue
        pthread_mutex_unlock(&queue->mutex);
        return;
    }

    // Store the message in the queue and update the structure
    queue->messages[queue->next_index] = message;
    queue->count++;
    queue->next_index++;

    // Release the lock on the queue
    pthread_mutex_unlock(&queue->mutex);
}

// Function to pop a message from the queue
static LTE_DL_CCCH_MESSAGE_T* dequeue_message(struct MessageQueue* queue) {
    // Acquire the lock on the queue
    pthread_mutex_lock(&queue->mutex);

    // Check if there are any messages in the queue
    if (queue->count == 0 || queue->next_index == 0) {
        // Release the lock on the queue
        pthread_mutex_unlock(&queue->mutex);
        return NULL;
    }

    // Pop the message from the front of the queue and update the structure
    LTE_DL_CCCH_MESSAGE_T* message = queue->messages[0];
    memset(message, 0, MESSAGE_SIZE);
    queue->count--;
    queue->next_index--;

    // Release the lock on the queue
    pthread_mutex_unlock(&queue->mutex);

    return message;
}

// Function to initialize a pool of LTE DL CCCH messages with thread-safe access and scaling capabilities
static struct LTE_DL_CCCH_MessagePool* init_lte_dl_ccch_message_pool(size_t preallocated_messages) {
    // Allocate the memory for the pool structure
    struct LTE_DL_CCCH_MessagePool* pool = malloc(sizeof(struct LTE_DL_CCCH_MessagePool));

    // Initialize the pool structure
    pool->pool = malloc(sizeof(struct MessagePool) * preallocated_messages);
    init_message_pool(pool->pool, preallocated_messages);

    pool->queue = malloc(sizeof(struct MessageQueue));
    init_message_queue(pool->queue);

    // Initialize the number of threads using the pool
    pool->thread_count = 0;

    // Initialize the lock for accessing the pool and queue
    pthread_mutex_init(&pool->mutex, NULL);

    return pool;
}

// Function to allocate a message from the pool with thread-safe access and scaling capabilities
static LTE_DL_CCCH_MESSAGE_T* allocate_lte_dl_ccch_message(struct LTE_DL_CCCH_MessagePool* pool) {
    // Acquire the lock on the pool and queue
    pthread_mutex_lock(&pool->mutex);

    // Check if there are any messages in the pool or the queue
    if (pool->pool->count == 0 && pool->queue->count == 0) {
        // Release the lock on the pool and queue
        pthread_mutex_unlock(&pool->mutex);
        return NULL;
    }

    // Allocate a message from the pool or the queue
    LTE_DL_CCCH_MESSAGE_T* message = allocate_message(pool->pool);
    if (message == NULL) {
        message = dequeue_message(pool->queue);
    }

    // Update the number of threads using the pool and queue
    pool->thread_count++;

    // Release the lock on the pool and queue
    pthread_mutex_unlock(&pool->mutex);

    return message;
}

// Function to free a message from the pool with thread-safe access and scaling capabilities
static void free_lte_dl_ccch_message(struct LTE_DL_CCCH_MessagePool* pool, LTE_DL_CCCH_MESSAGE_T* message) {
    // Acquire the lock on the pool and queue
    pthread_mutex_lock(&pool->mutex);

    // Check if there are any messages in the pool or the queue
    if (pool->pool->count == 0 && pool->queue->count == 0) {
        // Release the lock on the pool and queue
        pthread_mutex_unlock(&pool->mutex);
        return;
    }

    // Free the message in the pool or the queue
    free_message(pool->pool, message);
    if (dequeue_message(pool->queue) == NULL) {
        enqueue_message(pool->queue, message);
    }

    // Update the number of threads using the pool and queue
    pool->thread_count--;

    // Release the lock on the pool and queue
    pthread_mutex_unlock(&pool->mutex);
}
