    LTE_DL_CCCH_MESSAGE_T message;
} message_t;

message_t* message_pool = NULL;
pthread_mutex_t message_lock = PTHREAD_MUTEX_INITIALIZER;
pthread_cond_t message_signal = PTHREAD_COND_INITIALIZER;
int num_messages = 0;
int next_message_id = 1;

void init_message_pool() {
    int i;
    for (i = 0; i < MESSAGE_POOL_SIZE; i++) {
        message_pool[i].id = -1;
    }
}

int allocate_message(LTE_DL_CCCH_MESSAGE_T* message) {
    int i;
    for (i = 0; i < MESSAGE_POOL_SIZE; i++) {
        if (message_pool[i].id == -1) {
            message->id = next_message_id++;
            num_messages++;
            return i;
        }
    }
    return -1;
}

void free_message(int id) {
    message_t* message = &message_pool[id];
    if (message->id != -1) {
        message->id = -1;
        num_messages--;
    }
}

void add_message(LTE_DL_CCCH_MESSAGE_T* message) {
    pthread_mutex_lock(&message_lock);
    int id = allocate_message(message);
    if (id != -1) {
        memcpy(&message->id, &message->message, sizeof(LTE_DL_CCCH_MESSAGE_T));
        pthread_cond_signal(&message_signal);
    } else {
        printf("Error: no available message slots\n");
    }
    pthread_mutex_unlock(&message_lock);
}

void remove_message(int id) {
    pthread_mutex_lock(&message_lock);
    free_message(id);
    pthread_cond_signal(&message_signal);
    pthread_mutex_unlock(&message_lock);
}

int main() {
    init_message_pool();

    // Initialize thread pool manager
    int i;
    for (i = 0; i < MAX_THREADS; i++) {
        pthread_t thread;
        if (pthread_create(&thread, NULL, worker_thread, NULL) != 0) {
            printf("Error creating thread\n");
            return -1;
        }
    }

    // Start message processing loop
    while (1) {
        pthread_mutex_lock(&message_lock);
        while (num_messages == 0) {
            pthread_cond_wait(&message_signal, &message_lock);
        }
        int id = allocate_message(message);
        if (id != -1) {
            memcpy(&message->id, &message->message, sizeof(LTE_DL_CCCH_MESSAGE_T));
            pthread_cond_signal(&message_signal);
        } else {
            printf("Error: no available message slots\n");
        }
        pthread_mutex_unlock(&message_lock);
    }
}

void* worker_thread(void* arg) {
    while (1) {
        // Lock message pool
        pthread_mutex_lock(&message_lock);

        // Wait for available message
        while (num_messages == 0) {
            pthread_cond_wait(&message_signal, &message_lock);
        }

        // Allocate message
        int id = allocate_message(message);
        if (id != -1) {
            memcpy(&message->id, &message->message, sizeof(LTE_DL_CCCH_MESSAGE_T));
        } else {
            printf("Error: no available message slots\n");
        }

        // Unlock message pool and signal condition variable
        pthread_mutex_unlock(&message_lock);
        pthread_cond_signal(&message_signal);
    }
}
