public class HttpRequestPool {
    private static final ConcurrentHashMap<String, AtomicInteger> requestCounts = new ConcurrentHashMap<>();
    private static final ExecutorService executorService = Executors.newCachedThreadPool();

    public static void addRequest(String key) {
        requestCounts.computeIfAbsent(key, k -> new AtomicInteger()).incrementAndGet();
        executorService.submit(() -> {
            try {
                // perform HTTP request here
            } catch (Exception e) {
                // handle error here
            } finally {
                requestCounts.computeIfPresent(key, (k, v) -> v.decrementAndGet());
            }
        });
    }

    public static int getRequestCount(String key) {
        return requestCounts.getOrDefault(key, new AtomicInteger()).get();
    }
}
