// define the concurrent hash table data structure to store the messages
typedef struct {
    pthread_mutex_t lock; // mutual exclusion for thread safety
    int size; // size of the hashtable
    LTE_DL_CCCH_MESSAGE_T** buckets; // array of pointers to message structures
} LTE_DL_CCCH_HASHTABLE_T;

// define the function to initialize the hash table
void init_hashtable(LTE_DL_CCCH_HASHTABLE_T* hashtable) {
    pthread_mutex_init(&hashtable->lock, NULL);
    hashtable->size = 0;
    hashtable->buckets = NULL;
}

// define the function to insert a message into the hash table
bool insert_message(LTE_DL_CCCH_HASHTABLE_T* hashtable, LTE_DL_CCCH_MESSAGE_T* message) {
    pthread_mutex_lock(&hashtable->lock);
    // check if the hash table needs to be resized before inserting a new message
    if (hashtable->size > 0.75 * LTE_DL_CCCH_HASHTABLE_SIZE) {
        resize_hashtable(hashtable);
    }
    int index = hash_message(message); // calculate the index for the message
    if (hashtable->buckets[index] == NULL) {
        hashtable->buckets[index] = malloc(sizeof(LTE_DL_CCCH_MESSAGE_T));
        memcpy(hashtable->buckets[index], message, sizeof(LTE_DL_CCCH_MESSAGE_T));
    } else {
        printf("Message with the same index already exists in the hash table\n");
    }
    hashtable->size++; // update the size of the hashtable
    pthread_mutex_unlock(&hashtable->lock);
}

// define the function to search for a message in the hash table
LTE_DL_CCCH_MESSAGE_T* find_message(LTE_DL_CCCH_HASHTABLE_T* hashtable, LTE_DL_CCCH_MESSAGE_T* message) {
    pthread_mutex_lock(&hashtable->lock);
    int index = hash_message(message); // calculate the index for the message
    if (hashtable->buckets[index] == NULL) {
        printf("Message with the same index does not exist in the hash table\n");
    } else {
        LTE_DL_CCCH_MESSAGE_T* result = malloc(sizeof(LTE_DL_CCCH_MESSAGE_T));
        memcpy(result, hashtable->buckets[index], sizeof(LTE_DL_CCCH_MESSAGE_T));
        pthread_mutex_unlock(&hashtable->lock);
        return result;
    }
}

// define the function to delete a message from the hash table
bool delete_message(LTE_DL_CCCH_HASHTABLE_T* hashtable, LTE_DL_CCCH_MESSAGE_T* message) {
    pthread_mutex_lock(&hashtable->lock);
    int index = hash_message(message); // calculate the index for the message
    if (hashtable->buckets[index] == NULL) {
        printf("Message with the same index does not exist in the hash table\n");
        pthread_mutex_unlock(&hashtable->lock);
        return false;
    } else {
        free(hashtable->buckets[index]); // free the memory allocated for the message
        hashtable->size--; // update the size of the hashtable
        pthread_mutex_unlock(&hashtable->lock);
        return true;
    }
}

// define the function to resize the hash table if necessary
void resize_hashtable(LTE_DL_CCCH_HASHTABLE_T* hashtable) {
    pthread_mutex_lock(&hashtable->lock);
    int old_size = hashtable->size;
    LTE_DL_CCCH_MESSAGE_T** old_buckets = hashtable->buckets;
    // allocate a new hash table with twice the size of the original one
    hashtable->size = 2 * old_size;
    hashtable->buckets = malloc(hashtable->size * sizeof(LTE_DL_CCCH_MESSAGE_T));
    memset(hashtable->buckets, 0, hashtable->size * sizeof(LTE_DL_CCCH_MESSAGE_T));
    // copy the messages from the old hash table to the new one
    for (int i = 0; i < old_size; i++) {
        if (old_buckets[i] != NULL) {
            int index = hash_message(old_buckets[i]);
            hashtable->buckets[index] = malloc(sizeof(LTE_DL_CCCH_MESSAGE_T));
            memcpy(hashtable->buckets[index], old_buckets[i], sizeof(LTE_DL_CCCH_MESSAGE_T));
        }
    }
    // free the memory allocated for the old hash table
    free(old_buckets);
}

// define the function to calculate the index of a message in the hash table
int hash_message(LTE_DL_CCCH_MESSAGE_T* message) {
    int index = message->index; // use the index field as the key
    return index % LTE_DL_CCCH_HASHTABLE_SIZE;
}
