                    if (response.getStatusCode() != 200) {
                        System.out.println("Failed to execute HTTP request: " + url);
                    } else {
                        System.out.println("Successfully executed HTTP request: " + url);
                    }
                } catch (IOException e) {
                    e.printStackTrace();
                } finally {
                    synchronized (httpRequests) {
                        httpRequests.remove(url);
                    }
                }
            }, 0, TimeUnit.MILLISECONDS);
        }
