import os
from datetime import datetime
import logging
import threading
from concurrent.futures import ThreadPoolExecutor

class MonitoringFramework:
    def __init__(self, config):
        self.config = config
        self.metrics_by_category = {}
        self.metrics_by_tenant = {}
        self.metric_categories = ['CPU', 'Memory', 'Network', 'Disk', 'Custom', 'APM']
        self.tenants = []
        self.metrics_per_minute_limit = 500

    def add_metric(self, metric):
        category = metric['category']
        tenant = metric['tenant']
        value = metric['value']
        timestamp = datetime.now()

        if category not in self.metrics_by_category:
            self.metrics_by_category[category] = []

        self.metrics_by_category[category].append({'tenant': tenant, 'value': value, 'timestamp': timestamp})

        if tenant not in self.metrics_by_tenant:
            self.metrics_by_tenant[tenant] = []

        self.metrics_by_tenant[tenant].append({'category': category, 'value': value, 'timestamp': timestamp})

    def submit_metrics(self):
        for metric in self.metrics_by_category:
            if len(self.metrics_by_category) > self.metrics_per_minute_limit:
                break

        for tenant, metrics in self.metrics_by_tenant.items():
            if len(metrics) > self.metrics_per_minute_limit:
                continue

    def handle_submission_failure(self, metric):
        logging.error(f'Metric submission failed for {metric}')

    def submit_async(self, metric):
        try:
            self.submit_metrics(metric)
        except Exception as e:
            self.handle_submission_failure(metric)

    def submit_sync(self, metric):
        try:
            self.submit_metrics(metric)
        except Exception as e:
            self.handle_submission_failure(metric)

    def submit_all(self):
        with ThreadPoolExecutor(max_workers=10) as executor:
            futures = [executor.submit(self.submit_async, metric) for metric in self.metrics_by_category]
            for future in futures:
                try:
                    future.result()
                except Exception as e:
                    self.handle_submission_failure(metric)

if __name__ == '__main__':
    logging.basicConfig(level=logging.INFO)

    config = {
        'metrics_per_minute_limit': 500,
        'tenants': [
            {'id': 1, 'monitoring_config': {'cpu': True, 'memory': True, 'network': False}},
            {'id': 2, 'monitoring_config': {'cpu': True, 'memory': True, 'network': True}}
        ]
    }

    framework = MonitoringFramework(config)

    for i in range(10):
        for tenant in config['tenants']:
            framework.add_metric({'category': 'CPU', 'value': 25, 'timestamp': datetime.now(), 'tenant': tenant['id']})
            framework.add_metric({'category': 'Memory', 'value': 2048, 'timestamp': datetime.now(), 'tenant': tenant['id']})

    framework.submit_all()
