private:
    static MQTTClientManagerSingleton* instance;
    MQTTClientManager* mqttClientManager; // Instance of the MQTT client manager
public:
    MQTTClientManagerSingleton() {}
    ~MQTTClientManagerSingleton() {}

    // Get the MQTT client manager singleton instance
    static MQTTClientManagerSingleton* getInstance();

    // Create a new MQTT client instance
    void createMqttClient(std::string host, int port, std::string username, std::string password);

