void MQTTClientManagerSingleton::createMqttClient(std::string host, int port, std::string username, std::string password) {
    // Acquire a lock on the MQTT client manager
    std::lock_guard<std::mutex> lock(mqttClientManager->mutex);

    // Create a new MQTT client instance with the given parameters
    MQTTClient* mqttClient = new MQTTClient();
    mqttClient->host = host;
    mqttClient->port = port;
    mqttClient->username = username;
    mqttClient->password = password;

    // Add the new MQTT client instance to the map of active clients
    mqttClientManager->clients[id] = mqttClient;
}

// Implement the deleteMqttClient method of the MQTT client manager singleton
void MQTTClientManagerSingleton::deleteMqttClient(std::string id) {
    // Acquire a lock on the MQTT client manager
    std::lock_guard<std::mutex> lock(mqttClientManager->mutex);

    // Remove the MQTT client instance with the given ID from the map of active clients
    mqttClientManager->clients.erase(id);
}

// Implement the getMqttClient method of the MQTT client manager singleton
MQTTClient* MQTTClientManagerSingleton::getMqttClient(std::string id) {
    // Acquire a lock on the MQTT client manager
    std::lock_guard<std::mutex> lock(mqttClientManager->mutex);

    // Return the MQTT client instance with the given ID, or NULL if it does not exist
    return mqttClientManager->clients[id];
}

// Implement a function for connecting to an MQTT broker using the MQTT client manager singleton
void connectToMqttBroker(std::string host, int port) {
    // Get the MQTT client manager singleton instance
    MQTTClientManagerSingleton* mqttClientManager = MQTTClientManagerSingleton::getInstance();

