    // Get the MQTT client manager singleton instance
    MQTTClientManagerSingleton* mqttClientManager = MQTTClientManagerSingleton::getInstance();

    // Find the MQTT client instance with the given parameters in the map of active clients
    std::string id = generateUniqueId();
    MQTTClient* mqttClient = mqttClientManager->getMqttClient(id);
    if (mqttClient != NULL) {
        // Use the MQTT client instance to publish to the topic on the MQTT broker
        std::string connectionString = host + ":" + port;
        mqttClient->publish(topic, message);
    }
}

// Implement a function for generating a unique ID using the MQTT client manager singleton
std::string generateUniqueId() {
    // Get the MQTT client manager singleton instance
    MQTTClientManagerSingleton* mqttClientManager = MQTTClientManagerSingleton::getInstance();

    // Generate a unique ID by combining the current time with a random number
    std::string id = std::to_string(std::chrono::high_resolution_clock::now().time_since_epoch().count()) + std::to_string(rand() % 10000);

    // Check if the generated ID is already in use by another MQTT client instance
    while (mqttClientManager->getMqttClient(id) != NULL) {
        // If the generated ID is already in use, generate a new one and check again
        id = std::to_string(std::chrono::high_resolution_clock::now().time_since_epoch().count()) + std::to_string(rand() % 10000);
    }

    // Return the generated ID
    return id;
