    char message[256];
};

// Define a linked list to store the LTE_DL_CCCH_MESSAGEs
struct LTE_DL_CCCH_MESSAGE_LIST {
    struct LTE_DL_CCCH_MESSAGE *next;
};

// Define the function to initialize the linked list
void init_list(struct LTE_DL_CCCH_MESSAGE_LIST **list) {
    *list = NULL;
}

// Define the function to add a new message to the linked list
void add_message(struct LTE_DL_CCCH_MESSAGE_LIST **list, int message_id, char *message) {
    struct LTE_DL_CCCH_MESSAGE *new_msg = (struct LTE_DL_CCCH_MESSAGE *)malloc(sizeof(struct LTE_DL_CCCH_MESSAGE));
    new_msg->message_id = message_id;
    strcpy(new_msg->message, message);
    new_msg->next = *list;
    *list = new_msg;
}

// Define the function to remove a message from the linked list
void remove_message(struct LTE_DL_CCCH_MESSAGE_LIST **list, int message_id) {
    struct LTE_DL_CCCH_MESSAGE *current = *list;
    struct LTE_DL_CCCH_MESSAGE *previous = NULL;
    while (current != NULL && current->message_id != message_id) {
        previous = current;
        current = current->next;
    }
    if (current == NULL) {
        return;
    }
    if (previous != NULL) {
        previous->next = current->next;
    } else {
        *list = current->next;
    }
    free(current);
}

// Define the function to retrieve a message from the linked list
struct LTE_DL_CCCH_MESSAGE* get_message(struct LTE_DL_CCCH_MESSAGE_LIST **list, int message_id) {
    struct LTE_DL_CCCH_MESSAGE *current = *list;
    while (current != NULL && current->message_id != message_id) {
        current = current->next;
    }
    if (current == NULL) {
        return NULL;
    }
    return current;
}

// Define the function to iterate over the linked list and process each message
void process_messages(struct LTE_DL_CCCH_MESSAGE_LIST **list, void (*process_message)(int, char *)) {
    struct LTE_DL_CCCH_MESSAGE *current = *list;
    while (current != NULL) {
        process_message(current->message_id, current->message);
        current = current->next;
    }
}
