// Define a structure to represent an LTE DL CCCH message
typedef struct {
  int msg_id;
  char *msg_content;
} LTE_DL_CCCH_MESSAGE_T;

// Define a global variable to store the list of messages
static LTE_DL_CCCH_MESSAGE_T *messages = NULL;
static size_t num_messages = 0;

// Lock used to protect access to the message list
static pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

// Function to add a new message to the list
void add_message(LTE_DL_CCCH_MESSAGE_T *msg) {
  // Acquire the lock before modifying the message list
  pthread_mutex_lock(&lock);

  // Check if the message list is empty
  if (num_messages == 0) {
    messages = malloc(sizeof(LTE_DL_CCCH_MESSAGE_T));
  } else {
    // Double the size of the message list to accommodate new messages
    messages = realloc(messages, sizeof(LTE_DL_CCCH_MESSAGE_T) * (num_messages + 1));
  }

  // Copy the new message into the list
  memcpy(&messages[num_messages], msg, sizeof(LTE_DL_CCCH_MESSAGE_T));

  // Increment the number of messages in the list
  num_messages++;

  // Release the lock after modifying the message list
  pthread_mutex_unlock(&lock);
}

// Function to remove a message from the list
void remove_message(LTE_DL_CCCH_MESSAGE_T *msg) {
  // Acquire the lock before modifying the message list
  pthread_mutex_lock(&lock);

  // Search for the message in the list
  for (size_t i = 0; i < num_messages; i++) {
    if (messages[i].msg_id == msg->msg_id) {
      // Shift all subsequent messages back one index
      memmove(&messages[i], &messages[i + 1], sizeof(LTE_DL_CCCH_MESSAGE_T) * (num_messages - i));

      // Decrement the number of messages in the list
      num_messages--;

      // Reallocate memory for the message list to remove the empty slot
      messages = realloc(messages, sizeof(LTE_DL_CCCH_MESSAGE_T) * num_messages);

      break;
    }
  }

  // Release the lock after modifying the message list
  pthread_mutex_unlock(&lock);
}

// Function to retrieve a message from the list by its ID
LTE_DL_CCCH_MESSAGE_T *get_message(int msg_id) {
  // Acquire the lock before accessing the message list
  pthread_mutex_lock(&lock);

  // Search for the message in the list
  for (size_t i = 0; i < num_messages; i++) {
    if (messages[i].msg_id == msg_id) {
      // Release the lock after accessing the message list
      pthread_mutex_unlock(&lock);

      return &messages[i];
    }
  }

  // Release the lock after accessing the message list
  pthread_mutex_unlock(&lock);

  // Return NULL if the message is not found
  return NULL;
}

// Function to retrieve all messages from the list
LTE_DL_CCCH_MESSAGE_T **get_messages(size_t *num_msgs) {
  // Acquire the lock before accessing the message list
  pthread_mutex_lock(&lock);

  *num_msgs = num_messages;
  LTE_DL_CCCH_MESSAGE_T **msgs = malloc(sizeof(LTE_DL_CCCH_MESSAGE_T *) * num_messages);

  for (size_t i = 0; i < num_messages; i++) {
    msgs[i] = &messages[i];
  }

  // Release the lock after accessing the message list
  pthread_mutex_unlock(&lock);

  return msgs;
}
