class NetworkPacketManager {
 public:
  // Constructor and destructor
  NetworkPacketManager();
  ~NetworkPacketManager();

  // Public methods
  void addPacket(const NETWORK_PACKET_T& packet);
  bool removePacket(const std::string& id);
  const NETWORK_PACKET_T* getPacketById(const std::string& id) const;
  const std::vector<NETWORK_PACKET_T>& getAllPackets() const;
  void clearPackets();

 private:
  // Private methods
  void checkAndResizePool();
  bool isValidId(const std::string& id) const;

  // Private members
  std::vector<NETWORK_PACKET_T> packets_;
  mutable std::mutex mutex_;
  std::condition_variable cv_;
  std::thread thread_;
};

#endif // NETWORK_PACKET_MANAGER_H
