using namespace std;

class AuthenticationManager {
public:
    AuthenticationManager();
    ~AuthenticationManager();

    bool authenticate(const string& user, const string& password);
    bool authorize(const string& user, const vector<string>& roles);

private:
    mutex mtx_;
    condition_variable cv_;
    atomic<bool> running_;
    thread* t_;
    map<string, shared_ptr<AuthInfo>> authInfos_;
};

struct AuthInfo {
    string user;
    string password;
    vector<string> roles;
    chrono::time_point<chrono::system_clock> lastUpdated;
};

AuthenticationManager::AuthenticationManager() : running_(true) {
    t_ = new thread(&AuthenticationManager::run, this);
}

AuthenticationManager::~AuthenticationManager() {
    running_ = false;
    cv_.notify_one();
    t_->join();
    delete t_;
}

bool AuthenticationManager::authenticate(const string& user, const string& password) {
    unique_lock<mutex> lock(mtx_);
    auto it = authInfos_.find(user);
    if (it != authInfos_.end() && it->second->password == password) {
        it->second->lastUpdated = chrono::system_clock::now();
        return true;
    }
    return false;
}

bool AuthenticationManager::authorize(const string& user, const vector<string>& roles) {
    unique_lock<mutex> lock(mtx_);
    auto it = authInfos_.find(user);
    if (it != authInfos_.end()) {
        return find(roles.begin(), roles.end(), it->second->roles) != roles.end();
    }
    return false;
}

void AuthenticationManager::run() {
    while (running_) {
        unique_lock<mutex> lock(mtx_);
        cv_.wait_for(lock, chrono::seconds(1));
        if (!running_) break;

        // update authentication information for users that have not been updated in the last minute
        auto it = authInfos_.begin();
        while (it != authInfos_.end()) {
            if (chrono::system_clock::now() - it->second->lastUpdated > chrono::minutes(1)) {
                // TODO: update authentication information for the user
                it->second->lastUpdated = chrono::system_clock::now();
            }
            ++it;
        }
    }
}
