#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <assert.h>

// Define a structure to represent an LTE DL CCCH message
struct LTE_DL_CCCH_MESSAGE {
  // Message header fields
  char msg_type;
  int msg_len;
  unsigned char* payload;
};

// Initialize a pool of LTE DL CCCH messages with size `max_msg_count`
void init_message_pool(int max_msg_count) {
  // Allocate memory for the message pool
  struct LTE_DL_CCCH_MESSAGE* msg_pool = (struct LTE_DL_CCCH_MESSAGE*)malloc(sizeof(struct LTE_DL_CCCH_MESSAGE) * max_msg_count);

  // Initialize the message pool with empty messages
  for (int i = 0; i < max_msg_count; i++) {
    msg_pool[i].msg_type = 0;
    msg_pool[i].msg_len = 0;
    msg_pool[i].payload = NULL;
  }
}

// Acquire an LTE DL CCCH message from the pool
struct LTE_DL_CCCH_MESSAGE* acquire_message() {
  // Find the first available message in the pool
  struct LTE_DL_CCCH_MESSAGE* acquired = NULL;
  for (int i = 0; i < max_msg_count; i++) {
    if (msg_pool[i].payload == NULL) {
      acquired = &msg_pool[i];
      break;
    }
  }

  // Return the acquired message or NULL if no messages are available
  return acquired;
}

// Release an LTE DL CCCH message back to the pool
void release_message(struct LTE_DL_CCCH_MESSAGE* msg) {
  assert(msg != NULL);

  // Clear the message payload and mark it as available for reuse
  msg->payload = NULL;
}
