['Here is an example implementation of a modular C++ library for managing a dynamic pool of TCP connection states in a high-performance web server environment, supporting up to millions of concurrent connections:
```c++
#include <iostream>
#include <vector>
#include <map>
#include <unordered_map>
#include <algorithm>
#include <functional>

using namespace std;

// Define a struct to represent a TCP connection state
struct ConnectionState {
    int id; // unique identifier for the connection
    string ip; // IP address of the client
    uint16_t port; // port number of the client
    bool is_secure; // whether the connection is secure (using TLS)
    uint32_t timestamp; // timestamp when the connection was established
    vector<string> headers; // HTTP request headers sent by the client
};

// Define a class to represent the TCP connection pool
class ConnectionPool {
public:
    // Constructor
    ConnectionPool() {}

    // Add a new connection to the pool
    void addConnection(int id, string ip, uint16_t port, bool is_secure) {
        // Create a new connection state object
        ConnectionState cs;
        cs.id = id;
        cs.ip = ip;
        cs.port = port;
        cs.is_secure = is_secure;
        cs.timestamp = getCurrentTime();

        // Add the connection to the pool
        connections_.push_back(cs);
    }

    // Remove a connection from the pool by its ID
    void removeConnection(int id) {
        // Find the index of the connection in the pool
        int index = findIndex(id, connections_);

        // If the connection was found, remove it from the pool
        if (index != -1) {
            connections_.erase(connections_.begin() + index);
        }
    }

    // Get the number of connections in the pool
    size_t getConnectionCount() const { return connections_.size(); }

    // Get a connection from the pool by its ID
    ConnectionState* getConnection(int id) const {
        int index = findIndex(id, connections_);
        if (index != -1) {
            return &connections_[index];
        } else {
            return nullptr;
        }
    }

private:
    // Find the index of a connection in the pool by its ID
    int findIndex(int id, const vector<ConnectionState>& connections) const {
        for (size_t i = 0; i < connections.size(); ++i) {
            if (connections[i].id == id) {
                return i;
            }
        }
        return -1;
    }

    // Get the current timestamp in milliseconds
    uint32_t getCurrentTime() const {
        auto now = std::chrono::system_clock::now();
        auto ms = std::chrono::duration_cast<std::chrono::milliseconds>(now.time_since_epoch());
        return (uint32_t)ms.count();
    }

    // The pool of connections
    vector<ConnectionState> connections_;
};

// Define a class to represent the TCP connection manager
class ConnectionManager {
public:
    // Constructor
    ConnectionManager() {}

    // Initialize the manager with the specified number of connections
    void initialize(size_t num_connections) {
        // Create a new connection pool
        pool_.resize(num_connections);
    }

    // Add a new connection to the pool
    void addConnection(int id, string ip, uint16_t port, bool is_secure) {
        // Get the index of an available slot in the pool
        size_t index = getAvailableSlotIndex();

        // If no slots are available, resize the pool and add a new connection
        if (index == -1) {
            pool_.resize(pool_.size() + 1);
            index = pool_.size() - 1;
        }

        // Add the new connection to the slot
        pool_[index].addConnection(id, ip, port, is_secure);
    }

    // Remove a connection from the pool by its ID
    void removeConnection(int id) {
        // Find the index of the connection in the pool
        size_t index = findIndex(id, pool_);

        // If the connection was found, remove it from the pool
        if (index != -1) {
            pool_.erase(pool_.begin() + index);
        }
    }

    // Get the number of connections in the pool
    size_t getConnectionCount() const { return pool_.size(); }

    // Get a connection from the pool by its ID
    ConnectionState* getConnection(int id) const {
        int index = findIndex(id, pool_);
        if (index != -1) {
            return &pool_[index];
        } else {
            return nullptr;
        }
    }

private:
    // Find the index of a connection in the pool by its ID
    int findIndex(int id, const vector<ConnectionState>& connections) const {
        for (size_t i = 0; i < connections.size(); ++i) {
            if (connections[i].id == id) {
                return i;
            }
        }
        return -1;
    }

    // Get the index of an available slot in the pool
    size_t getAvailableSlotIndex() const {
        for (size_t i = 0; i < pool_.size(); ++i) {
            if (pool_[i].getConnectionCount() == 0) {
                return i;
            }
        }
        return -1;
    }

    // The pool of connections
    vector<ConnectionState> pool_;
};
```

This code defines two classes: `ConnectionState` and `ConnectionManager`. The `ConnectionState` class represents a single connection and stores information about the connection, such as its ID, IP address, and port number. It also has a method to remove the connection from the pool of connections. The `ConnectionManager` class manages the pool of connections and provides methods for adding and removing connections from the pool.

The `initialize` method is used to initialize the manager with the specified number of connections. The `addConnection` method adds a new connection to the pool, and the `removeConnection` method removes a connection from the pool by its ID. The `getConnectionCount` method returns the number of connections in the pool, and the `getConnection` method returns a specific connection from the pool by its ID.

The `ConnectionState` class also has a `getCurrentTime` method that gets the current timestamp in milliseconds using `std::chrono`. This is used to measure the time elapsed between the creation of the connection and the last time it was used. The `ConnectionManager` class does not use this functionality, but it could be useful for other applications.

This code also defines a utility function `getAvailableSlotIndex` that returns the index of an available slot in the pool or `-1` if no slots are available. This is used by the `addConnection` method to find an available slot in the pool where it can add the new connection.']

