// External dependencies
#include "remote_service/remote_service.h"
#include "third_party/json-c/json.h"

// Thread-safe array of NFAPI_CRC_INDICATION_PDU_T structures
typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *data;
    size_t capacity;
    size_t size;
    pthread_mutex_t mutex;
} array_t;

// Initialize the array with a given capacity
static void array_init(array_t *array, size_t capacity) {
    array->data = (NFAPI_CRC_INDICATION_PDU_T *)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * capacity);
    if (!array->data) {
        perror("malloc");
        exit(EXIT_FAILURE);
    }
    array->capacity = capacity;
    array->size = 0;
    pthread_mutex_init(&array->mutex, NULL);
}

// Add an entry to the array
static void array_push(array_t *array, NFAPI_CRC_INDICATION_PDU_T entry) {
    // Lock the mutex to ensure thread-safe access
    pthread_mutex_lock(&array->mutex);

    if (array->size == array->capacity) {
        printf("Reached capacity of %zu, doubling size\n", array->capacity);
        NFAPI_CRC_INDICATION_PDU_T *new_data = realloc(array->data, 2 * array->capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_data) {
            perror("realloc");
            exit(EXIT_FAILURE);
        }
        array->data = new_data;
        array->capacity *= 2;
    }

    // Add the entry to the end of the array
    array->data[array->size] = entry;
    array->size++;

    pthread_mutex_unlock(&array->mutex);
}

// Remove and return an entry from the array
static NFAPI_CRC_INDICATION_PDU_T array_pop(array_t *array) {
    // Lock the mutex to ensure thread-safe access
    pthread_mutex_lock(&array->mutex);

    if (array->size == 0) {
        printf("Attempted to pop from empty array\n");
        pthread_mutex_unlock(&array->mutex);
        return NULL;
    }

    // Get the last entry in the array
    NFAPI_CRC_INDICATION_PDU_T entry = array->data[array->size - 1];
    array->size--;

    pthread_mutex_unlock(&array->mutex);
    return entry;
}

// Get the size of the array
static size_t array_size(array_t *array) {
    // Lock the mutex to ensure thread-safe access
    pthread_mutex_lock(&array->mutex);
    size_t size = array->size;
    pthread_mutex_unlock(&array->mutex);
    return size;
}

// Clean up the array and free its memory
static void array_free(array_t *array) {
    // Lock the mutex to ensure thread-safe access
    pthread_mutex_lock(&array->mutex);

    if (array->data) {
        free(array->data);
    }
    pthread_mutex_unlock(&array->mutex);
}

// Initialize the remote service client with a given base URL and API key
static void remote_service_init(const char *base_url, const char *api_key) {
    // Lock the mutex to ensure thread-safe access
    pthread_mutex_lock(&remote_service_client.mutex);

    if (remote_service_client.initialized) {
        printf("Attempted to initialize remote service client twice\n");
        pthread_mutex_unlock(&remote_service_client.mutex);
        return;
    }

    // Set the base URL and API key for the remote service client
    strcpy(remote_service_client.base_url, base_url);
    strcpy(remote_service_client.api_key, api_key);
    remote_service_client.initialized = true;

    pthread_mutex_unlock(&remote_service_client.mutex);
}

// Call the remote service to validate an RX UE information tag and RNTI pair
static bool remote_service_validate(const char *rx_ue_info, const uint32_t rnti) {
    // Lock the mutex to ensure thread-safe access
    pthread_mutex_lock(&remote_service_client.mutex);

    if (!remote_service_client.initialized) {
        printf("Attempted to use uninitialized remote service client\n");
        pthread_mutex_unlock(&remote_service_client.mutex);
        return false;
    }

    // Build the request body with the RX UE information tag and RNTI
    json_t *request = json_object();
    json_object_set_new(request, "rx_ue_info", json_string(rx_ue_info));
    json_object_set_new(request, "rnti", json_integer(rnti));

    // Make the request to the remote service and get the response
    json_t *response = remote_service_request(remote_service_client.base_url, request);
    if (!response) {
        printf("Failed to validate RX UE information tag and RNTI pair\n");
        pthread_mutex_unlock(&remote_service_client.mutex);
        return false;
    }

    // Check the response from the remote service
    json_t *status = json_object_get(response, "status");
    if (json_integer_value(status) != 200) {
        printf("Validation failed with status %d\n", json_integer_value(status));
        pthread_mutex_unlock(&remote_service_client.mutex);
        return false;
    }

    // Set the valid flag and unlock the mutex
    remote_service_client.valid = true;
    pthread_mutex_unlock(&remote_service_client.mutex);
    return true;
}

// Get the current RX UE information tag and RNTI pair from the array
static void get_rx_ue_info(array_t *array, char *rx_ue_info, uint32_t *rnti) {
    // Lock the mutex to ensure thread-safe access
    pthread_mutex_lock(&array->mutex);

    if (array->size == 0) {
        printf("Attempted to get RX UE information tag and RNTI pair from empty array\n");
        pthread_mutex_unlock(&array->mutex);
        return;
    }

    // Get the first entry in the array
    NFAPI_CRC_INDICATION_T entry = array->data[0];

    // Set the RX UE information tag and RNTI
    strcpy(rx_ue_info, entry.rx_ue_info);
    *rnti = entry.rnti;

    pthread_mutex_unlock(&array->mutex);
}

// Clean up the remote service client and free its memory
static void remote_service_free(void) {
    // Lock the mutex to ensure thread-safe access
    pthread_mutex_lock(&remote_service_client.mutex);

    if (!remote_service_client.initialized) {
        printf("Attempted to free uninitialized remote service client\n");
        pthread_mutex_unlock(&remote_service_client.mutex);
        return;
    }

    // Reset the initialized flag and free the memory for the base URL and API key
    remote_service_client.initialized = false;
    if (remote_service_client.base_url) {
        free(remote_service_client.base_url);
    }
    if (remote_service_client.api_key) {
        free(remote_service_client.api_key);
    }

    pthread_mutex_unlock(&remote_service_client.mutex);
}

int main() {
    array_t *array = array_create();
    remote_service_init("https://example.com", "my-api-key");

    while (true) {
        char rx_ue_info[NFAPI_MAX_RX_UE_INFO_LENGTH];
        uint32_t rnti;
        get_rx_ue_info(array, rx_ue_info, &rnti);

        if (remote_service_validate(rx_ue_info, rnti)) {
            printf("RX UE information tag %s and RNTI %u are valid\n", rx_ue_info, rnti);
        } else {
            printf("RX UE information tag %s and RNTI %u are not valid\n", rx_ue_info, rnti);
        }
    }

    return 0;
}
