    pdu->rx_ue_information_tag = (uint32_t)(rand() % 1000);

    // Set RNTI to a random value
    pdu->rnti = (uint16_t)(rand() % 1000);

    // Set CRC Indication REL8 tag to a random value
    pdu->crc_indication_rel8_tag = (uint8_t)(rand() % 256);

    // Set CRCFLAG to a random value
    pdu->crcflag = (uint8_t)(rand() % 2);
