void parse_crc_indication_pdu(NFAPI_CRC_INDICATION_PDU_T* pdu, uint8_t* buffer, size_t buffer_length) {
    // Check if the buffer is large enough to hold a complete CRC Indication PDU
    if (buffer_length < sizeof(NFAPI_CRC_INDICATION_PDU_T)) {
        printf("Error: Buffer too small\n");
        return;
    }

    // Read the RX UE Information tag from the buffer
    pdu->rx_ue_information_tag = *((uint32_t*)buffer);
