    pdu->crc_indication_rel8_tag = *((uint8_t*)buffer);
    buffer += sizeof(uint8_t);

    // Read the CRCFLAG from the buffer
    pdu->crcflag = *((uint8_t*)buffer);
    buffer += sizeof(uint8_t);
}

void store_crc_indication_pdu(NFAPI_CRC_INDICATION_PDU_T* pdu, uint8_t* buffer, size_t buffer_length) {
    // Check if the buffer is large enough to hold a complete CRC Indication PDU
    if (buffer_length < sizeof(NFAPI_CRC_INDICATION_PDU_T)) {
        printf("Error: Buffer too small\n");
        return;
    }

    // Write the RX UE Information tag to the buffer
    *((uint32_t*)buffer) = pdu->rx_ue_information_tag;
    buffer += sizeof(uint32_t);

    // Write the RNTI to the buffer
    *((uint16_t*)buffer) = pdu->rnti;
    buffer += sizeof(uint16_t);

    // Write the CRC Indication REL8 tag to the buffer
    *((uint8_t*)buffer) = pdu->crc_indication_rel8_tag;
    buffer += sizeof(uint8_t);

    // Write the CRCFLAG to the buffer
    *((uint8_t*)buffer) = pdu->crcflag;
}

void handle_crc_indication(NFAPI_CRC_INDICATION_PDU_T* pdu, char* remote_cache_root_directory, char* local_theme_cache_directory) {
    // Check if the remote cache root directory is set
    if (remote_cache_root_directory == NULL) {
        printf("Error: Remote cache root directory not set\n");
        return;
    }

    // Check if the local theme cache directory is set
    if (local_theme_cache_directory == NULL) {
        printf("Error: Local theme cache directory not set\n");
        return;
    }

    // Create a new file descriptor for the PNG file in the remote cache root directory
    int fd = open(remote_cache_root_directory, O_RDONLY);
    if (fd < 0) {
        printf("Error: Failed to open remote cache root directory\n");
        return;
    }

    // Read the PNG file from the remote cache root directory into a buffer
    uint8_t* buffer = malloc(buffer_length);
    ssize_t read_bytes = read(fd, buffer, buffer_length);
    if (read_bytes < 0) {
        printf("Error: Failed to read PNG file from remote cache root directory\n");
        close(fd);
        return;
    }

    // Close the file descriptor for the PNG file in the remote cache root directory
    close(fd);

    // Create a new file descriptor for the PNG file in the local theme cache directory
    fd = open(local_theme_cache_directory, O_RDONLY);
    if (fd < 0) {
        printf("Error: Failed to open local theme cache directory\n");
        return;
    }

    // Write the buffer containing the PNG file to the local theme cache directory
    ssize_t write_bytes = write(fd, buffer, read_bytes);
    if (write_bytes < 0) {
        printf("Error: Failed to write PNG file to local theme cache directory\n");
        close(fd);
        return;
    }

    // Close the file descriptor for the PNG file in the local theme cache directory
    close(fd);

    // Free the buffer containing the PNG file
    free(buffer);
}

