    Frame *frames[MAX_FRAMES];
    size_t frame_count;
    pthread_mutex_t mutex;
    pthread_cond_t cond;
} Cache;

// client structure to hold information about a connected client
typedef struct {
    int64_t timestamp; // last accessed timestamp
    bool active; // whether the client is still connected or not
    size_t frame_count; // number of frames currently being streamed
} Client;

// function to initialize the cache and clients
void init(Cache *cache) {
    pthread_mutex_init(&cache->mutex, NULL);
    pthread_cond_init(&cache->cond, NULL);
    for (int i = 0; i < MAX_FRAMES; i++) {
        cache->frames[i] = NULL;
    }
    cache->frame_count = 0;
}

// function to insert a frame into the cache
void insert(Cache *cache, Frame *frame) {
    pthread_mutex_lock(&cache->mutex);
    while (cache->frame_count == MAX_FRAMES) {
        pthread_cond_wait(&cache->cond, &cache->mutex);
    }
    cache->frames[cache->frame_count] = frame;
    cache->frame_count++;
    pthread_mutex_unlock(&cache->mutex);
}

// function to retrieve a frame from the cache
void retrieve(Cache *cache, Frame **frame) {
    pthread_mutex_lock(&cache->mutex);
    while (cache->frame_count == 0) {
        pthread_cond_wait(&cache->cond, &cache->mutex);
    }
    *frame = cache->frames[cache->frame_count - 1];
    cache->frame_count--;
    pthread_mutex_unlock(&cache->mutex);
}

