void get_frame(Cache *cache, Client *client) {
    Frame *frame;
    while (true) {
        // check if the client is still connected and there are frames available in the cache
        if (!is_active(client)) {
            break;
        } else if (cache->frame_count == 0) {
            // wait for new frames to be inserted into the cache
            pthread_cond_wait(&cache.cond, &cache.mutex);
        } else {
