class ConfigManager {
public:
    // Constructor
    ConfigManager(int max_threads = 16) : max_threads_(max_threads) {}

    // Add a new configuration setting with the given key and value
    void addSetting(const std::string& key, const std::string& value) {
        std::lock_guard<std::mutex> lock(mutex_);
        settings_.emplace(key, value);
    }

    // Update an existing configuration setting with the given key and new value
    void updateSetting(const std::string& key, const std::string& value) {
        std::lock_guard<std::mutex> lock(mutex_);
        settings_.at(key) = value;
    }

    // Get the value of a configuration setting with the given key
    std::optional<std::string> getSetting(const std::string& key) {
        std::lock_guard<std::mutex> lock(mutex_);
        return settings_.find(key) != settings_.end() ? std::make_optional(settings_.at(key)) : std::nullopt;
    }

    // Get the value of a configuration setting with the given key, or the default value if not found
    std::string getSettingOrDefault(const std::string& key, const std::string& default_value) {
        std::lock_guard<std::mutex> lock(mutex_);
        return settings_.find(key) != settings_.end() ? settings_.at(key) : default_value;
    }

    // Set the value of a configuration setting with the given key and version, returning true if successful and false otherwise
    bool setSettingWithVersion(const std::string& key, const std::string& value, int version) {
        std::lock_guard<std::mutex> lock(mutex_);
        auto it = settings_.find(key);
        if (it == settings_.end()) {
            return false;
        } else if (it->second.version != version) {
            return false;
        } else {
            it->second.value = value;
            it->second.version++;
            return true;
