    }

    // Get the current version of a configuration setting with the given key, or -1 if not found
    int getSettingVersion(const std::string& key) {
        std::lock_guard<std::mutex> lock(mutex_);
        auto it = settings_.find(key);
        return it == settings_.end() ? -1 : it->second.version;
    }

private:
