        int version;
        std::string value;
    };

    // Maximum number of threads to use for concurrent operations
    int max_threads_;

    // Map from configuration setting keys to values and versions
    std::unordered_map<std::string, Setting> settings_;

    // Mutex for protecting the map
    std::mutex mutex_;
};

