public:
    // Constructor
    SessionManager(int capacity) : capacity_(capacity), sessions_(), mutex_(), condition_variable_() {}

    // Destructor
    ~SessionManager() {
        for (auto& session : sessions_) {
            delete session;
        }
    }

    // Add a new WebSocket session object to the pool
    void add(WS_SESSION_OBJECT* session) {
        std::lock_guard<std::mutex> lock(mutex_);
        if (sessions_.size() < capacity_) {
            sessions_.push_back(session);
        } else {
            throw "Session pool is full";
        }
    }

    // Remove a WebSocket session object from the pool
    void remove(int id) {
        std::lock_guard<std::mutex> lock(mutex_);
        for (auto it = sessions_.begin(); it != sessions_.end(); ++it) {
            if ((*it)->id == id) {
                delete *it;
                sessions_.erase(it);
                return;
            }
        }
    }

    // Get a WebSocket session object from the pool by ID
    WS_SESSION_OBJECT* get(int id) {
        std::lock_guard<std::mutex> lock(mutex_);
        for (auto& session : sessions_) {
            if (session->id == id) {
                return session;
            }
        }
        throw "Session not found";
    }

    // Check if a WebSocket session object is active in the pool
