int findResourceInStore(OptimizedResourceStore* store, char* name) {
    if (store == NULL || name == NULL) {
        return -1;
    }
    for (int i = 0; i < store->numResources; i++) {
        ResourceBundle* bundle = store->resources[i];
        if (strcmp(bundle->name, name) == 0) {
            return i;
        }
