        for (size_t i = 0; i < num_pools - 1; ++i) {
            memcpy(&new_pools[i], &tp->pools[i], sizeof(struct pool));
        }
        new_pools[num_pools - 1].connections = malloc(THREADPOOL_SIZE * sizeof(struct connection));
        for (size_t j = 0; j < THREADPOOL_SIZE; ++j) {
