    }
    struct connection *connection = &pool->connections[pool->num_connections++];
    connection->message.data = malloc(sizeof(LTE_DL_CCCH_MESSAGE_T));
    connection->message.length = 0;
    pthread_mutex_init(&connection->mutex, NULL);
    pthread_cond_init(&connection->cond, NULL);
    return 1;
}

// Process a message and handle any connections that are ready to be processed.
void process_message(struct socket *sock) {
    struct threadpool *tp = get_threadpool();
    pthread_mutex_lock(&tp->mutex);
    for (size_t i = 0; i < tp->num_pools; ++i) {
        struct pool *pool = &tp->pools[i];
        if (pool->num_connections == 0) continue;
        pthread_mutex_lock(&pool->mutex);
        while (1) {
            // Check for any connections that are ready to be processed.
            struct connection *connection = &pool->connections[0];
            if (connection->message.length > 0) break;
            if (i == tp->num_pools - 1) {
                pthread_mutex_unlock(&tp->mutex);
