        pthread_cond_init(&connection->cond, NULL);
        connection->message.data = malloc(sizeof(LTE_DL_CCCH_Message));
        connection->message.length = 0;
        pthread_mutex_unlock(&pool->mutex);
    }
}

// Handle a disconnection and remove it from the pool if necessary.
void handle_disconnection(struct socket *sock) {
    struct threadpool *tp = get_threadpool();
    pthread_mutex_lock(&tp->mutex);
    for (size_t i = 0; i < tp->num_pools; ++i) {
        struct pool *pool = &tp->pools[i];
        if (pool->num_connections == 0) continue;
        pthread_mutex_lock(&pool->mutex);
        while (1) {
            // Check for any connections that are ready to be processed.
