const int STATUS_UPDATE_INTERVAL = 10000; // Interval for updating the status in milliseconds
const string STATUS_UPDATE_URL = "http://localhost:8080/status"; // URL for updating the status
const string OBJECT_DETECTION_TASK = "object-detection"; // Object detection task name
const string FACE_RECOGNITION_TASK = "face-recognition"; // Face recognition task name
const string SCENE_ANALYSIS_TASK = "scene-analysis"; // Scene analysis task name
const int OBJECT_DETECTION_THRESHOLD = 50; // Threshold for object detection
const float FACE_RECOGNITION_CONFIDENCE = 0.8f; // Confidence threshold for face recognition
