#define DEFAULT_BUFFER_SIZE 8192
#define DEFAULT_PRIORITY_THRESHOLD 1000

struct connection {
    int fd;
    SSL* ssl;
    struct addrinfo* ai;
    char host[NI_MAXHOST];
    unsigned short port;
};

struct thread {
    pthread_t id;
    struct connection* conn;
};

struct connection_pool {
    int num_connections;
    struct connection connections[MAX_CONNECTIONS];
    struct thread threads[MAX_THREADS];
};

void* worker(void* arg) {
    struct connection* conn = (struct connection*)arg;

    SSL_set_fd(conn->ssl, conn->fd);

    while (1) {
        char buffer[DEFAULT_BUFFER_SIZE];
        int ret = SSL_read(conn->ssl, buffer, sizeof(buffer));

        if (ret <= 0) {
            break;
        }

        // process request...

        SSL_write(conn->ssl, "HTTP/1.1 200 OK\r\nContent-Type: text/plain\r\n\r\nHello World!", 46);
    }

    SSL_free(conn->ssl);
    close(conn->fd);
    return NULL;
}

void init_connection_pool() {
    struct connection_pool* pool = malloc(sizeof(struct connection_pool));
    pool->num_connections = 0;

    for (int i = 0; i < MAX_CONNECTIONS; i++) {
        struct connection* conn = &pool->connections[i];
        conn->ssl = SSL_new(SSL_CTX);
        SSL_set_fd(conn->ssl, conn->fd);
    }

    for (int i = 0; i < MAX_THREADS; i++) {
        struct thread* thread = &pool->threads[i];
        pthread_create(&thread->id, NULL, worker, &pool->connections[i]);
    }
}

void free_connection_pool(struct connection_pool* pool) {
    for (int i = 0; i < MAX_CONNECTIONS; i++) {
        struct connection* conn = &pool->connections[i];
        SSL_free(conn->ssl);
        close(conn->fd);
    }

    free(pool);
}
