#define METRICS_TABLE "metrics"
#define LOG_ENTRIES_TABLE "log_entries"

typedef struct {
    int severity;
    char* message;
} LogEntry;

// Thread-safe queue for logging entries
struct Queue {
    pthread_mutex_t mutex;
    pthread_cond_t cond;
    LogEntry* head;
    LogEntry* tail;
};

void initQueue(struct Queue* queue) {
    queue->head = NULL;
    queue->tail = NULL;
}

void enqueue(struct Queue* queue, LogEntry* entry) {
    pthread_mutex_lock(&queue->mutex);
    if (queue->head == NULL) {
        queue->head = entry;
        queue->tail = entry;
    } else {
        queue->tail->next = entry;
        queue->tail = entry;
    }
    pthread_cond_signal(&queue->cond);
    pthread_mutex_unlock(&queue->mutex);
}

LogEntry* dequeue(struct Queue* queue) {
    LogEntry* result = NULL;
    pthread_mutex_lock(&queue->mutex);
    if (queue->head != NULL) {
        result = queue->head;
        queue->head = queue->head->next;
        if (queue->head == NULL) {
            queue->tail = NULL;
        }
    }
    pthread_cond_signal(&queue->cond);
    pthread_mutex_unlock(&queue->mutex);
    return result;
}

// Logging worker thread
void* logWorker(void* arg) {
    struct Queue* queue = (struct Queue*)arg;
    while (1) {
        LogEntry* entry = dequeue(queue);
        if (entry != NULL) {
            // Process log entry here
        } else {
            break;
        }
    }
}

