int validate_access_token(const char *token) {
    json_object *root = NULL;
    const char *token_type, *expires_in;
    long expiration_time;

    root = json_tokener_parse(token);
    if (!root || !json_is_object(root)) {
        fprintf(stderr, "Invalid JSON object\n");
        return -1;
    }

    token_type = json_object_get_string(json_object_get(root, "token_type"));
    if (!token_type || strcmp(token_type, "Bearer") != 0) {
        fprintf(stderr, "Invalid token type: %s\n", token_type);
        return -1;
    }

    expires_in = json_object_get_string(json_object_get(root, "expires_in"));
    if (!expires_in) {
        fprintf(stderr, "Missing expiration time\n");
        return -1;
    }

    expiration_time = strtol(expires_in, NULL, 10);
    if (errno == ERANGE || errno == EINVAL) {
        fprintf(stderr, "Invalid expiration time: %s\n", expires_in);
        return -1;
    }

    json_object_put(root);
    return 0;
}
