#define CONFIG_FILE "config.json"
#define CONFIG_CACHE_SIZE 1024 * 1024 // 1MB
#define CACHE_TTL 3600 // seconds

typedef struct {
  int connection;
  char* hostname;
  char* endpoint;
} service_t;

typedef enum {
  SERVICE_NOTIFICATION,
  SERVICE_MONITORING,
  SERVICE_BACKUP,
  NUM_SERVICES
} service_type_t;

typedef struct {
  char* key;
  char* value;
} config_setting_t;

typedef struct {
  int status;
  char* message;
} response_t;

static const service_t services[] = {
  { SERVICE_NOTIFICATION, "https://notification.example.com", "/api/v1/notify" },
  { SERVICE_MONITORING, "https://monitoring.example.com", "/api/v1/monitor" },
  { SERVICE_BACKUP, "https://backup.example.com", "/api/v1/backup" }
};

static pthread_mutex_t cache_lock;
static config_setting_t* config_cache = NULL;

void init_config() {
  // Initialize the configuration cache and lock.
  config_cache = calloc(CONFIG_CACHE_SIZE, sizeof(config_setting_t));
  pthread_mutexattr_t attr;
  pthread_mutexattr_init(&attr);
  pthread_mutexattr_setpshared(&attr, PTHREAD_PROCESS_SHARED);
  pthread_mutex_init(&cache_lock, &attr);
}

void free_config() {
  // Free the configuration cache and lock.
  if (config_cache) {
    free(config_cache);
    config_cache = NULL;
  }
  pthread_mutex_destroy(&cache_lock);
}

int get_config_setting(const char* key, char** value) {
  // Get the configuration setting for a given key from the cache.
  int status = -1;
  *value = NULL;
  pthread_mutex_lock(&cache_lock);
  if (config_cache && config_cache->key && !strcmp(config_cache->key, key)) {
    *value = config_cache->value;
    status = 0;
  }
  pthread_mutex_unlock(&cache_lock);
  return status;
}

int set_config_setting(const char* key, const char* value) {
  // Set the configuration setting for a given key in the cache.
  int status = -1;
  pthread_mutex_lock(&cache_lock);
  if (config_cache && config_cache->key && !strcmp(config_cache->key, key)) {
    free(config_cache->value);
    config_cache->value = strdup(value);
    status = 0;
  } else {
    // Add the new setting to the cache.
    config_setting_t* new_setting = calloc(1, sizeof(config_setting_t));
    if (new_setting) {
      new_setting->key = strdup(key);
      new_setting->value = strdup(value);
      status = 0;
    }
  }
  pthread_mutex_unlock(&cache_lock);
  return status;
}

int update_config() {
  // Update the configuration cache from the JSON file.
  int status = -1;
  FILE* fp = fopen(CONFIG_FILE, "r");
  if (fp) {
    config_cache = calloc(CONFIG_CACHE_SIZE, sizeof(config_setting_t));
    char buffer[BUFSIZ];
    while (fgets(buffer, BUFSIZ, fp)) {
      // Parse the JSON object.
      json_error_t error;
      json_t* json = json_loads(buffer, 0, &error);
      if (!json) {
        printf("Invalid JSON: %s\n", error.text);
        goto end;
      }
      // Get the configuration settings from the JSON object.
      const char* key = NULL;
      json_t* value = json_object_get(json, "key");
      if (!value || !json_is_string(value)) {
        printf("Invalid JSON: missing or invalid 'key' property\n");
        goto end;
      }
      key = json_string_value(value);
      value = json_object_get(json, "value");
      if (!value || !json_is_string(value)) {
        printf("Invalid JSON: missing or invalid 'value' property\n");
        goto end;
      }
      // Set the configuration setting in the cache.
      set_config_setting(key, json_string_value(value));
    }
    status = 0;
    end:
    fclose(fp);
    if (status) {
      free_config();
    }
  }
  return status;
}

int push_settings_to_services() {
  // Push the configuration settings to each service.
  int status = -1;
  char* json = NULL;
  size_t json_size = 0;
  for (int i = 0; i < sizeof(services) / sizeof(services[0]); i++) {
    // Get the configuration setting for the service.
    const char* key = services[i].key;
    char* value = NULL;
    if (get_config_setting(key, &value)) {
      continue;
    }
    // Build the JSON object with the configuration setting.
    json_t* json = json_object();
    json_object_set_new(json, "key", json_string(key));
    json_object_set_new(json, "value", json_string(value));
    // Send the JSON object to the service.
    int ret = send_request(services[i].url, json);
    if (ret != 0) {
      printf("Error sending request to %s\n", services[i].url);
      goto end;
    }
  }
  status = 0;
  end:
  if (json) {
    json_decref(json);
  }
  return status;
}

int send_request(const char* url, json_t* json) {
  // Send a JSON object to a service over HTTPS.
  int status = -1;
  cURL* curl = NULL;
  CURLcode res = CURLE_FAILED_INIT;
  if (curl) {
    curl_easy_setopt(curl, CURLOPT_SSL_VERIFYPEER, false);
    curl_easy_setopt(curl, CURLOPT_HTTPHEADER, headers);
    curl_easy_setopt(curl, CURLOPT_URL, url);
    curl_easy_setopt(curl, CURLOPT_POSTFIELDS, json);
    res = curl_easy_perform(curl);
  } else {
    printf("Error initializing cURL\n");
  }
  if (res == CURLE_OK) {
    status = 0;
  }
  end:
  if (curl) {
    curl_easy_cleanup(curl);
  }
  return status;
}

int main() {
  // Initialize the configuration cache and update it from the JSON file.
  init_config();
  update_config();
  // Push the updated configuration to each service.
  push_settings_to_services();
  // Free the configuration cache and lock.
  free_config();
  return 0;
}']

