        self.secret_key = secret_key or os.getenv("SECRET_KEY")
        self.session = requests.Session()

    def object_exists(self, key: str) -> bool:
        # check if the object exists in the cloud storage
        url = f"{self.name}.com/{key}"
        response = self.session.head(url)
        return response.status_code == 200

    def put_object(self, file: str, key: str):
        # upload the file to the cloud storage
        url = f"{self.name}.com/{key}"
        with open(file, "rb") as f:
            self.session.put(url, data=f)

    def get_object(self, key: str, file: str):
        # download the file from the cloud storage
        url = f"{self.name}.com/{key}"
        with open(file, "wb") as f:
            self.session.get(url, data=f)
