void initializeService(secureCrcAndEncryptionService_t *service) {
    if (!service) {
        fprintf(stderr, "Error: service is null\n");
        return;
    }
    memset(service, 0, sizeof(*service));
    service->numEntries = 0;
    service->numPools = MAX_POOLS;
    pthread_mutex_init(&service->mutex, NULL);
    service->initialized = true;
}

bool addEntry(secureCrcAndEncryptionService_t *service, NFAPI_CRC_INDICATION_PDU_T entry) {
    if (!service || !entry) {
        fprintf(stderr, "Error: service or entry is null\n");
        return false;
    }
    pthread_mutex_lock(&service->mutex);
    int index = -1;
    for (int i = 0; i < MAX_ENTRIES; ++i) {
        if (!service->entries[i].initialized) {
            index = i;
            break;
        }
    }
    if (index == -1) {
        fprintf(stderr, "Error: no available slots\n");
        pthread_mutex_unlock(&service->mutex);
        return false;
    }
    service->entries[index] = entry;
    ++service->numEntries;
    pthread_mutex_unlock(&service->mutex);
    return true;
}

NFAPI_CRC_INDICATION_PDU_T* getEntry(secureCrcAndEncryptionService_t *service, int index) {
    if (!service || index < 0 || index >= MAX_ENTRIES) {
        fprintf(stderr, "Error: service or index is invalid\n");
        return NULL;
    }
    pthread_mutex_lock(&service->mutex);
    NFAPI_CRC_INDICATION_PDU_T* entry = &service->entries[index];
    if (!entry->initialized) {
        fprintf(stderr, "Error: entry does not exist\n");
        pthread_mutex_unlock(&service->mutex);
        return NULL;
    }
    pthread_mutex_unlock(&service->mutex);
    return entry;
}

void removeEntry(secureCrcAndEncryptionService_t *service, int index) {
    if (!service || index < 0 || index >= MAX_ENTRIES) {
        fprintf(stderr, "Error: service or index is invalid\n");
        return;
    }
    pthread_mutex_lock(&service->mutex);
    if (service->entries[index].initialized) {
        memset(&service->entries[index], 0, sizeof(NFAPI_CRC_INDICATION_PDU_T));
        --service->numEntries;
    }
    pthread_mutex_unlock(&service->mutex);
}

bool updateEntry(secureCrcAndEncryptionService_t *service, int index, NFAPI_CRC_INDICATION_PDU_T entry) {
    if (!service || index < 0 || index >= MAX_ENTRIES || !entry.initialized) {
        fprintf(stderr, "Error: service or entry is invalid\n");
        return false;
    }
    pthread_mutex_lock(&service->mutex);
    if (service->entries[index].initialized) {
        memcpy(&service->entries[index], &entry, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    } else {
        fprintf(stderr, "Error: entry does not exist\n");
        pthread_mutex_unlock(&service->mutex);
        return false;
    }
    pthread_mutex_unlock(&service->mutex);
    return true;
}

int getNumEntries(secureCrcAndEncryptionService_t *service) {
