// Modular, highly available Rust service for managing projects
use std::collections::HashMap;
use serde::{Deserialize, Serialize};
use anyhow::Result;
use log::info;

#[derive(Serialize, Deserialize)]
struct Project {
    name: String,
    team_id: i32,
}

#[derive(Serialize, Deserialize)]
struct Team {
    id: i32,
    name: String,
}

#[derive(Serialize, Deserialize)]
struct ProjectRegistry {
    projects: HashMap<String, Project>,
}

impl ProjectRegistry {
    fn new() -> Self {
        Self {
            projects: HashMap::new(),
        }
    }

    fn add_project(&mut self, name: &str) -> Result<()> {
        if let Some(team_id) = get_team_id(name)? {
            let project = Project {
                name: String::from(name),
                team_id: team_id,
            };
            self.projects.insert(String::from(name), project);
            Ok(())
        } else {
            Err(anyhow!("Invalid project name"))
        }
    }
}

fn get_team_id(name: &str) -> Result<Option<i32>> {
    let team = Team::get_by_name(name)?;
    if let Some(team) = team {
        Ok(Some(team.id))
    } else {
        Ok(None)
    }
}
