#include <mutex>
#include <vector>
#include <unordered_map>
#include <thread>

namespace payment {
    class PaymentProcessor {
        public:
            PaymentProcessor();
            ~PaymentProcessor();

            // Add a new payment gateway to the processor
            void addGateway(const std::string& name, const std::string& url);

            // Remove a payment gateway from the processor
            void removeGateway(const std::string& name);

            // Process a payment transaction using the specified gateway
            bool processPayment(const std::string& gatewayName, const std::string& transactionId);

            // Set the maximum number of concurrent transactions
            void setMaxConcurrentTransactions(size_t numTransactions);

            // Get the maximum number of concurrent transactions
            size_t getMaxConcurrentTransactions() const;

            // Get the current number of active transactions
            size_t getNumActiveTransactions() const;

        private:
            struct GatewayInfo {
                std::string name;
                std::string url;
                bool available = false;
                int version = 0;
            };

            // Map of gateway names to gateway information
            std::unordered_map<std::string, GatewayInfo> gateways_;

            // Mutex for protecting concurrent access to the payment processor
            mutable std::mutex mutex_;

            // Condition variable for waiting on active transactions
            std::condition_variable cv_;

            // Maximum number of concurrent transactions
            size_t maxConcurrentTransactions_ = 0;

            // Current number of active transactions
            size_t numActiveTransactions_ = 0;

            // Vector of payment transaction threads
            std::vector<std::thread> threads_;
    };
}

#endif // PAYMENT_PROCESSOR_H
