```
// Source file: PaymentProcessor.cpp
#include "PaymentProcessor.h"
#include <iostream>
#include <sstream>

namespace payment {
    PaymentProcessor::PaymentProcessor() {}

    PaymentProcessor::~PaymentProcessor() {
        for (auto& thread : threads_) {
            if (thread.joinable()) {
                thread.join();
            }
        }
    }

    void PaymentProcessor::addGateway(const std::string& name, const std::string& url) {
        std::unique_lock<std::mutex> lock(mutex_);
        gateways_.emplace(name, GatewayInfo{name, url, true, 0});
    }

    void PaymentProcessor::removeGateway(const std::string& name) {
        std::unique_lock<std::mutex> lock(mutex_);
        gateways_.erase(name);
    }

    bool PaymentProcessor::processPayment(const std::string& gatewayName, const std::string& transactionId) {
        std::unique_lock<std::mutex> lock(mutex_);

        // Check if the payment gateway is available
        auto it = gateways_.find(gatewayName);
        if (it == gateways_.end() || !it->second.available) {
            return false;
        }

        // Update the gateway version
        it->second.version++;

        // Create a new payment transaction thread
        threads_.emplace_back(std::thread([this, &gatewayName, &transactionId]() {
            std::stringstream ss;
            ss << "Transaction ID: " << transactionId << ", Gateway: " << gatewayName;

            // Simulate a payment request to the payment gateway
            bool success = simulatePayment(ss.str());

            // Notify other threads of the completed transaction
            cv_.notify_all();

            return success;
        }));

        // Wait for all active transactions to complete before proceeding
        while (numActiveTransactions_ >= maxConcurrentTransactions_) {
            cv_.wait(lock);
        }

        // Increment the number of active transactions
        numActiveTransactions_++;

        return true;
    }

    void PaymentProcessor::setMaxConcurrentTransactions(size_t numTransactions) {
        std::unique_lock<std::mutex> lock(mutex_);
        maxConcurrentTransactions_ = numTransactions;
    }

    size_t PaymentProcessor::getMaxConcurrentTransactions() const {
        std::unique_lock<std::mutex> lock(mutex_);
        return maxConcurrentTransactions_;
    }

    size_t PaymentProcessor::getNumActiveTransactions() const {
        std::unique_lock<std::mutex> lock(mutex_);
        return numActiveTransactions_;
    }

    bool simulatePayment(const std::string& transactionId) {
        // Simulate a payment request to the payment gateway
        std::cout << "Simulating payment for transaction: " << transactionId << std::endl;
        return true;
    }
}
```

