    pthread_mutex_lock(&config_lock);

    // Look up the key in the configuration data and set its value
    for (int i = 0; i < config_data.config_id; i++) {
        if (strcmp(key, config_data.config[i].key) == 0) {
            strcpy(config_data.config[i].value, value);
            break;
        }
    }

    // Release the lock on the configuration data and return the new value
    pthread_mutex_unlock(&config_lock);
    semaphore_post(config_sem);
}

// Update the configuration with the given data
void configuration_manager_update(const char* data) {
    if (!initialized) return;

    // Acquire a lock on the configuration data
