import redis
from multiprocessing import Process, Queue
from threading import Thread
import time
import logging

class DistributedCachingService:
    def __init__(self):
        self.redis = redis.Redis(host='localhost', port=6379)
        self.processes = []
        self.threads = []
        self.queue = Queue()
        self.logging = logging.getLogger(__name__)

    def start(self):
        for i in range(5):
            p = Process(target=self.process_worker, args=(i,))
            t = Thread(target=self.thread_worker, args=(i,))
            self.processes.append(p)
            self.threads.append(t)

        for p in self.processes:
            p.start()

        for t in self.threads:
            t.start()

    def process_worker(self, i):
        while True:
            item = self.queue.get()
            if item is None:
                break
            else:
                self.redis.set('key', 'value')
                self.queue.task_done()

    def thread_worker(self, i):
        while True:
            item = self.queue.get()
            if item is None:
                break
            else:
                self.redis.set('key', 'value')
                self.queue.task_done()

    def stop(self):
        for p in self.processes:
            p.terminate()

        for t in self.threads:
            t.join()

    def get(self, key):
        return self.redis.get(key)

    def set(self, key, value):
        return self.redis.set(key, value)
