use std::path::Path;
use std::fs::File;
use std::io::{Read, Write};
use std::thread;
use std::sync::mpsc::channel;
use std::collections::HashMap;
use std::process::Command;

struct FileProcessor {
    file_path: String,
    transformation_rules: Vec<String>,
}

impl FileProcessor {
    fn new(file_path: &str) -> Self {
        Self {
            file_path: file_path.to_string(),
            transformation_rules: Vec::new(),
        }
    }

    fn add_transformation_rule(&mut self, rule: String) {
        self.transformation_rules.push(rule);
    }

    fn process_file(&self) -> Result<(), std::io::Error> {
        let file = File::open(self.file_path)?;
        let mut reader = BufReader::new(file);
        let mut writer = BufWriter::new(File::create("output.txt")?);
        let mut buffer = Vec::new();

        loop {
            match reader.read(&mut buffer) {
                Ok(0) => break,
                Ok(_) => {
                    // Apply transformation rules to the buffer
                    for rule in self.transformation_rules.iter() {
                        buffer = rule.apply(&buffer)?;
                    }

                    writer.write_all(&buffer)?;
                }
                Err(error) => {
                    return Err(error);
                }
            }
        }

        Ok(())
    }
}

fn main() {
    let file_path = "input.txt";
    let transformation_rules = vec!["rule1", "rule2", "rule3"];

    // Create a FileProcessor instance for the given file path and transformation rules
    let mut processor = FileProcessor::new(file_path);
    for rule in transformation_rules {
        processor.add_transformation_rule(rule.to_string());
    }

    // Process the file using the FileProcessor instance
    if let Err(error) = processor.process_file() {
        println!("Error processing file: {}", error);
        return;
    }
}
