// Define the LTE_DL_CCCH_MESSAGE_T structure to store the message data
typedef struct LTE_DL_CCCH_MESSAGE_T {
    char* payload; // Payload of the message
    int size; // Size of the payload in bytes
} LTE_DL_CCCH_MESSAGE_T;

// Define a thread-safe queue data structure to store messages
typedef struct THREAD_SAFE_QUEUE {
    pthread_mutex_t mutex; // Mutex for synchronizing access to the queue
    pthread_cond_t cond; // Condition variable for waiting for new messages
    LTE_DL_CCCH_MESSAGE_T* head; // Pointer to the first message in the queue
    LTE_DL_CCCH_MESSAGE_T* tail; // Pointer to the last message in the queue
} THREAD_SAFE_QUEUE;

// Define a structure for storing message metadata
typedef struct MESSAGE_METADATA {
    char* user; // User who sent the message
    int size; // Size of the message in bytes
    time_t timestamp; // Timestamp of when the message was sent
} MESSAGE_METADATA;

// Define a structure for storing message data and metadata
typedef struct MESSAGE {
    LTE_DL_CCCH_MESSAGE_T* payload; // Payload of the message
    MESSAGE_METADATA metadata; // Metadata for the message
} MESSAGE;

// Define a function to initialize the library module
void init_library(THREAD_SAFE_QUEUE* queue) {
    // Initialize the mutex and condition variable for synchronizing access to the queue
    pthread_mutex_init(&queue->mutex, NULL);
    pthread_cond_init(&queue->cond, NULL);
}

// Define a function to create a new message in the library module
void create_message(THREAD_SAFE_QUEUE* queue, char* user, int size) {
    // Lock the mutex to synchronize access to the queue
    pthread_mutex_lock(&queue->mutex);

    // Allocate memory for the message payload and metadata
    LTE_DL_CCCH_MESSAGE_T* payload = malloc(size * sizeof(char));
    MESSAGE_METADATA* metadata = malloc(sizeof(MESSAGE_METADATA));

    // Initialize the message metadata
    strcpy(metadata->user, user);
    metadata->size = size;
    metadata->timestamp = time(NULL);

    // Create a new message structure and store it in the queue
    MESSAGE* message = malloc(sizeof(MESSAGE));
    message->payload = payload;
    message->metadata = metadata;

    // Add the message to the end of the queue
    if (queue->tail) {
        queue->tail->next = message;
        queue->tail = message;
    } else {
        queue->head = queue->tail = message;
    }

    // Unlock the mutex and signal the condition variable to wake up any waiting threads
    pthread_mutex_unlock(&queue->mutex);
    pthread_cond_signal(&queue->cond);
}

// Define a function to delete a message from the library module
void delete_message(THREAD_SAFE_QUEUE* queue, char* user) {
    // Lock the mutex to synchronize access to the queue
    pthread_mutex_lock(&queue->mutex);

    // Find the message with the specified user in the queue
    MESSAGE* message = queue->head;
    while (message && strcmp(message->metadata.user, user) != 0) {
        message = message->next;
    }

    // If the message was found, remove it from the queue and free its memory
    if (message) {
        if (queue->head == message) {
            queue->head = message->next;
        } else {
            MESSAGE* prev = queue->head;
            while (prev && prev->next != message) {
                prev = prev->next;
            }
            if (prev) {
                prev->next = message->next;
            }
        }
        free(message->payload);
        free(message->metadata);
        free(message);
    }

    // Unlock the mutex and signal the condition variable to wake up any waiting threads
    pthread_mutex_unlock(&queue->mutex);
    pthread_cond_signal(&queue->cond);
}

// Define a function to update a message in the library module
void update_message(THREAD_SAFE_QUEUE* queue, char* user) {
    // Lock the mutex to synchronize access to the queue
    pthread_mutex_lock(&queue->mutex);

    // Find the message with the specified user in the queue
    MESSAGE* message = queue->head;
    while (message && strcmp(message->metadata.user, user) != 0) {
        message = message->next;
    }

    // If the message was found, update its payload and metadata
    if (message) {
        free(message->payload);
        free(message->metadata);

        LTE_DL_CCCH_MESSAGE_T* payload = malloc(size * sizeof(char));
        MESSAGE_METADATA* metadata = malloc(sizeof(MESSAGE_METADATA));

        // Initialize the message metadata
        strcpy(metadata->user, user);
        metadata->size = size;
        metadata->timestamp = time(NULL);

        // Create a new message structure and store it in the queue
        MESSAGE* updated_message = malloc(sizeof(MESSAGE));
        updated_message->payload = payload;
        updated_message->metadata = metadata;

        // Add the updated message to the end of the queue
        if (queue->tail) {
            queue->tail->next = updated_message;
            queue->tail = updated_message;
        } else {
            queue->head = queue->tail = updated_message;
        }
    }

    // Unlock the mutex and signal the condition variable to wake up any waiting threads
    pthread_mutex_unlock(&queue->mutex);
    pthread_cond_signal(&queue->cond);
}
```

In this example, we define a `THREAD_SAFE_QUEUE` structure that contains a mutex and condition variable for synchronizing access to the queue. We also define three functions: `init_library`, `create_message`, and `delete_message`. The `init_library` function initializes the library module by creating an empty queue and initializing the mutex and condition variable. The `create_message` function creates a new message in the queue, allocating memory for its payload and metadata. The `delete_message` function deletes a message from the queue, freeing its memory.

The `THREAD_SAFE_QUEUE` structure also contains a `next` pointer that allows us to store messages in a linked list. This makes it easy to traverse the queue and access individual messages.

Note that we use `pthread_mutex_lock` and `pthread_mutex_unlock` to synchronize access to the queue, and `pthread_cond_signal` to wake up any waiting threads when a message is added or deleted from the queue. This ensures that only one thread can modify the queue at a time, and that all threads will see the most up-to-date version of the queue.

In addition to these functions, we also define three helper functions: `malloc`, `free`, and `strcpy`. These functions allow us to allocate memory for the message payload and metadata, and copy strings into the structure.

This is just one example of how you can use a mutex and condition variable to synchronize access to a shared resource in a multi-threaded program. There are many other ways to do this, and the best approach will depend on your specific requirements and design choices."]

