// Define a structure to represent a client request
struct request {
    int file_id; // Unique identifier for the file being requested
    int offset; // Offset in the file where the read/write operation should start
    char* data; // Buffer containing the data to be written or read
};

// Define a structure to represent a client connection
struct connection {
    struct request req; // Request sent by the client
    int fd; // File descriptor for the file being requested
    int status; // Status of the request (0 = success, -1 = failure)
};

// Function to handle client requests and process them accordingly
void handle_request(struct connection* conn) {
    struct request req = conn->req;

    // Open the file with the specified file descriptor
    int fd = open(req.file, O_RDWR);
    if (fd == -1) {
        perror("Error opening file");
        conn->status = -1;
        return;
    }

    // Check the offset and ensure it is valid for the given file
    off_t offset = req.offset;
    struct stat st;
    if (fstat(fd, &st) == -1) {
        perror("Error getting file stats");
        conn->status = -1;
        close(fd);
        return;
    }

    off_t file_size = st.st_size;
    if (offset < 0 || offset > file_size) {
        fprintf(stderr, "Offset is invalid for the given file\n");
        conn->status = -1;
        close(fd);
        return;
    }

    // Perform the requested read/write operation
    if (req.data != NULL) {
        ssize_t bytes_written = pwrite(fd, req.data, strlen(req.data), offset);
        if (bytes_written == -1) {
            perror("Error writing to file");
            conn->status = -1;
            close(fd);
            return;
        }
    } else {
        ssize_t bytes_read = pread(fd, req.data, file_size - offset, offset);
        if (bytes_read == -1) {
            perror("Error reading from file");
            conn->status = -1;
            close(fd);
            return;
        }
    }

    // Close the file descriptor and update the status of the connection
    close(fd);
    conn->status = 0;
}

// Main function for the application
int main() {
    struct connection* connections = malloc(sizeof(struct connection) * MAX_CONNECTIONS); // Array to store all active client connections

    while (1) {
        // Accept a new connection from a client
        int client_fd = accept(server_fd, NULL, NULL);
        if (client_fd == -1) {
            perror("Error accepting connection");
            continue;
        }

        // Create a new connection object for the client and store it in the array of active connections
        struct connection* conn = malloc(sizeof(struct connection));
        conn->req.file_id = -1;
        conn->req.offset = -1;
        conn->req.data = NULL;
        conn->fd = client_fd;
        conn->status = -1;
        connections[num_connections++] = conn;

        // Handle the client request asynchronously in a separate thread
        pthread_t thread;
        if (pthread_create(&thread, NULL, handle_request, conn) != 0) {
            perror("Error creating thread");
            close(client_fd);
            continue;
        }
    }

    return 0;
}']

