#include <pthread.h>
#include <time.h>
#include "nfapi_crc_indication_pdu.h"

// Macro for generating a random number within a range
#define RAND_RANGE(min, max) (rand() % ((max) + 1 - (min)) + (min))

// Structure to hold information about the list of hostnames and their corresponding IP addresses
typedef struct {
    char **hostnames; // Array of hostnames
    size_t num_hosts; // Number of hosts in the list
    uint32_t *ip_addrs; // Array of IP addresses for each hostname
} hostname_list_t;

// Function to initialize a list of NFAPI_CRC_INDICATION_PDU_T structures with valid RX_UE_INFORMATION_TAG, RNTI, and CRC_INDICATION_REL8_TAG values, using asynchronous DNS resolution for the provided hostnames
NFAPI_CRC_INDICATION_PDU_T *init_crc_indication_pdus(const char **hostnames, size_t num_hosts) {
    // Check if the input parameters are valid
    if (!hostnames || !num_hosts) {
        return NULL;
    }

    // Create a new list to store the hostnames and their corresponding IP addresses
    hostname_list_t *hostname_list = malloc(sizeof(hostname_list_t));
    hostname_list->hostnames = malloc(num_hosts * sizeof(char *));
    hostname_list->ip_addrs = malloc(num_hosts * sizeof(uint32_t));
    hostname_list->num_hosts = num_hosts;

    // Initialize the list with the provided hostnames and their corresponding IP addresses
    for (size_t i = 0; i < num_hosts; i++) {
        // Allocate memory for the hostname and copy it from the input parameter
        hostname_list->hostnames[i] = malloc(strlen(hostnames[i]) + 1);
        strcpy(hostname_list->hostnames[i], hostnames[i]);

        // Use asynchronous DNS resolution to obtain the IP address for the hostname
        struct addrinfo *ai;
        int ret = getaddrinfo(hostname_list->hostnames[i], NULL, NULL, &ai);
        if (ret) {
            fprintf(stderr, "Error resolving hostname %s: %s\n", hostname_list->hostnames[i], gai_strerror(ret));
            return NULL;
        }

        // Copy the IP address from the first result to the list
        inet_pton(AF_INET, ai->ai_addr->sa_data + 2, &hostname_list->ip_addrs[i]);

        // Free the memory allocated by getaddrinfo
        freeaddrinfo(ai);
    }

    // Create a new list to store the NFAPI_CRC_INDICATION_PDU_T structures
    NFAPI_CRC_INDICATION_PDU_T *crc_indication_pdus = malloc(num_hosts * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    // Initialize each NFAPI_CRC_INDICATION_PDU_T structure with a valid RX_UE_INFORMATION_TAG, RNTI, and CRC_INDICATION_REL8_TAG value
    for (size_t i = 0; i < num_hosts; i++) {
        // Generate a random RX_UE_INFORMATION_TAG value between 1 and 65535
        uint16_t rx_ue_information_tag = RAND_RANGE(1, 65535);

        // Generate a random RNTI value between 0 and 65535
        uint16_t rnti = RAND_RANGE(0, 65535);

        // Generate a random CRC_INDICATION_REL8_TAG value between 1 and 65535
        uint16_t crc_indication_rel8_tag = RAND_RANGE(1, 65535);

        // Set the corresponding IP address in the CRC_INDICATION_PDU structure
        crc_indication_pdus[i].rx_ue_information.ip_address = hostname_list->ip_addrs[i];

        // Set the corresponding RX_UE_INFORMATION_TAG value in the CRC_INDICATION_PDU structure
        crc_indication_pdus[i].rx_ue_information.rx_ue_information_tag = rx_ue_information_tag;

        // Set the corresponding RNTI value in the CRC_INDICATION_PDU structure
        crc_indication_pdus[i].rx_ue_information.rnti = rnti;

        // Set the corresponding CRC_INDICATION_REL8_TAG value in the CRC_INDICATION_PDU structure
        crc_indication_pdus[i].crc_indication_rel8.crc_indication_rel8_tag = crc_indication_rel8_tag;
    }

    // Free the memory allocated by getaddrinfo
    free(hostname_list->hostnames);
    free(hostname_list->ip_addrs);
    free(hostname_list);

    return crc_indication_pdus;
}

// Function to generate a random CRC flag value between 0 and 65535
uint16_t gen_crc_flag() {
    // Generate a random CRC flag value between 0 and 65535
    return RAND_RANGE(0, 65535);
}

// Function to handle asynchronous DNS resolution for a provided list of hostnames, ensuring minimal impact on system performance and resource usage
int dns_resolve_async(const char **hostnames, size_t num_hosts) {
    // Check if the input parameters are valid
    if (!hostnames || !num_hosts) {
        return -EINVAL;
    }

    // Create a new list to store the hostnames and their corresponding IP addresses
    hostname_list_t *hostname_list = malloc(sizeof(hostname_list_t));
    hostname_list->hostnames = malloc(num_hosts * sizeof(char *));
    hostname_list->ip_addrs = malloc(num_hosts * sizeof(uint32_t));
    hostname_list->num_hosts = num_hosts;

    // Initialize the list with the provided hostnames and their corresponding IP addresses
    for (size_t i = 0; i < num_hosts; i++) {
        // Allocate memory for the hostname and copy it from the input parameter
        hostname_list->hostnames[i] = malloc(strlen(hostnames[i]) + 1);
        strcpy(hostname_list->hostnames[i], hostnames[i]);

        // Use asynchronous DNS resolution to resolve each hostname and store the corresponding IP address in the list
        struct addrinfo *addr;
        if (getaddrinfo(hostname_list->hostnames[i], NULL, NULL, &addr)) {
            fprintf(stderr, "Failed to get address info for %s\n", hostname_list->hostnames[i]);
            freeaddrinfo(addr);
            return -EINVAL;
        }
        memcpy(&hostname_list->ip_addrs[i], &((struct sockaddr_in *)addr->ai_addr)->sin_addr, sizeof(uint32_t));
        freeaddrinfo(addr);
    }

    // Free the memory allocated by getaddrinfo
    free(hostname_list->hostnames);
    free(hostname_list->ip_addrs);
    free(hostname_list);

    return 0;
}

// Function to handle CRC calculation for a provided list of NFAPI_CRC_INDICATION_PDU structures, ensuring minimal impact on system performance and resource usage
int crc_calculate_async(NFAPI_CRC_INDICATION_PDU *crc_indication_pdus, size_t num_hosts) {
    // Check if the input parameters are valid
    if (!crc_indication_pdus || !num_hosts) {
        return -EINVAL;
    }

    // Calculate the CRC for each NFAPI_CRC_INDICATION_PDU structure and store the result in the corresponding field
    for (size_t i = 0; i < num_hosts; i++) {
        crc_indication_pdus[i].crc_value = crc(crc_indication_pdus[i].rx_ue_information.ip_address);
    }

    return 0;
}

// Function to handle CRC verification for a provided list of NFAPI_CRC_INDICATION_PDU structures, ensuring minimal impact on system performance and resource usage
int crc_verify_async(NFAPI_CRC_INDICATION_PDU *crc_indication_pdus, size_t num_hosts) {
    // Check if the input parameters are valid
    if (!crc_indication_pdus || !num_hosts) {
        return -EINVAL;
    }

    // Verify the CRC for each NFAPI_CRC_INDICATION_PDU structure and store the result in the corresponding field
    for (size_t i = 0; i < num_hosts; i++) {
        if (crc(crc_indication_pdus[i].rx_ue_information.ip_address) == crc_indication_pdus[i].crc_value) {
            crc_indication_pdus[i].crc_status = CRC_VERIFIED;
        } else {
            crc_indication_pdus[i].crc_status = CRC_FAILED;
        }
    }

    return 0;
}
