```c++
#include <iostream>
#include <string>
#include <vector>
#include <map>
#include <set>
#include <future>
#include <chrono>
#include <thread>
#include <mutex>
#include <condition_variable>
#include <functional>
#include <memory>
#include <atomic>

using namespace std;

// Define the WebSocket message structure
struct WebSocketMessage {
  string data;
  bool is_heartbeat;
};

// Define the WebSocket session structure
struct WebSocketSession {
  int id;
  string name;
  vector<WebSocketMessage> messages;
  atomic<bool> heartbeat;
};

// Define the WebSocket connection pool class
class WebSocketConnectionPool {
public:
  // Constructor
  WebSocketConnectionPool(int capacity = 10) : capacity_(capacity) {}

  // Add a new connection to the pool
  void addConnection(const string& name, const int id) {
    if (connections_.size() >= capacity_) {
      return;
    }

    connections_.push_back({name, id});
  }

  // Remove a connection from the pool
  void removeConnection(const string& name, const int id) {
    for (auto it = connections_.begin(); it != connections_.end(); ++it) {
      if (it->name == name && it->id == id) {
        connections_.erase(it);
        break;
      }
    }
  }

  // Get the next available connection from the pool
  shared_ptr<WebSocketSession> getNextConnection() {
    if (connections_.empty()) {
      return nullptr;
    }

    auto connection = connections_.front();
    connections_.pop_front();
    return make_shared<WebSocketSession>(connection);
  }

private:
  int capacity_;
  deque<tuple<string, int>> connections_;
};

// Define the WebSocket message processor class
class WebSocketMessageProcessor {
public:
  // Constructor
  WebSocketMessageProcessor(const shared_ptr<WebSocketConnectionPool>& pool) : pool_(pool) {}

  // Process a new WebSocket message
  void processMessage(const WebSocketMessage& message) {
    if (message.is_heartbeat) {
      return;
    }

    auto session = pool_->getNextConnection();
    if (!session) {
      return;
    }

    session->messages.push_back(message);
  }

private:
  shared_ptr<WebSocketConnectionPool> pool_;
};

// Define the WebSocket server class
class WebSocketServer {
public:
  // Constructor
  WebSocketServer() {}

  // Start the server
  void start(int port) {
    // Initialize the server socket and bind to the given port
    sock_ = socket(AF_INET, SOCK_STREAM, 0);
    if (sock_ < 0) {
      perror("socket failed");
      return;
    }

    int enable = 1;
    if (setsockopt(sock_, SOL_SOCKET, SO_REUSEADDR, &enable, sizeof(int)) < 0) {
      perror("setsockopt failed");
      close(sock_);
      return;
    }

    struct sockaddr_in serv_addr = {0};
    serv_addr.sin_family = AF_INET;
    serv_addr.sin_addr.s_addr = INADDR_ANY;
    serv_addr.sin_port = htons(port);

    if (bind(sock_, (struct sockaddr*)&serv_addr, sizeof(serv_addr)) < 0) {
      perror("bind failed");
      close(sock_);
      return;
    }

    // Listen for incoming connections
    listen(sock_, SOMAXCONN);

    // Initialize the connection pool
    connection_pool_ = make_shared<WebSocketConnectionPool>();

    // Start the message processor
    message_processor_ = make_unique<WebSocketMessageProcessor>(connection_pool_);
  }

  // Stop the server
  void stop() {
    // Close the socket
    close(sock_);

    // Clear the connection pool
    connection_pool_.reset();
  }

  // Handle incoming connections
  void handleConnection() {
    struct sockaddr_in cli_addr;
    socklen_t clilen = sizeof(cli_addr);
    int newsock = accept(sock_, (struct sockaddr*)&cli_addr, &clilen);
    if (newsock < 0) {
      perror("accept failed");
      return;
    }

    // Create a new connection session
    auto session = make_shared<WebSocketSession>();
    session->id = newsock;

    // Add the connection to the pool
    connection_pool_->addConnection(session->name, session->id);

    // Initialize the message buffer
    vector<char> buffer;

    // Read incoming messages from the client
    while (true) {
      auto n = read(newsock, &buffer[0], buffer.size());
      if (n < 0) {
        perror("read failed");
        break;
      } else if (n == 0) {
        // Connection closed by client
        break;
      }

      // Process the received message
      auto message = WebSocketMessage();
      message.data = string(buffer.begin(), buffer.end());
      message_processor_->processMessage(message);
    }

    // Remove the connection from the pool
    connection_pool_->removeConnection(session->name, session->id);

    // Close the socket
    close(newsock);
  }

private:
  int sock_;
  shared_ptr<WebSocketConnectionPool> connection_pool_;
  unique_ptr<WebSocketMessageProcessor> message_processor_;
};

// Define the main function
int main() {
  // Start the server on port 9000
  WebSocketServer server;
  server.start(9000);

  // Handle incoming connections
  while (true) {
    server.handleConnection();
  }

  return 0;
}']

