package com.example.microservice;

import java.security.MessageDigest;
import java.util.HashMap;
import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;

import org.apache.commons.io.FileUtils;
import org.apache.commons.lang3.RandomStringUtils;
import org.apache.commons.logging.Log;
import org.apache.commons.logging.LogFactory;
import org.springframework.http.HttpStatus;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RestController;

@RestController
public class AuthenticationTokenService {
    private static final Log logger = LogFactory.getLog(AuthenticationTokenService.class);

    // Token storage map
    private ConcurrentHashMap<String, String> tokenMap = new ConcurrentHashMap<>();

    @GetMapping("/tokens/{token}")
    public ResponseEntity<?> getToken(@PathVariable("token") String token) {
        if (token == null || !tokenMap.containsKey(token)) {
            return ResponseEntity.status(HttpStatus.NOT_FOUND).build();
        } else {
            return ResponseEntity.ok().body(tokenMap.get(token));
        }
    }

    @PostMapping("/tokens")
    public ResponseEntity<?> createToken(@RequestBody Map<String, String> requestBody) {
        // Generate a random token and save it to the map
        String token = RandomStringUtils.randomAlphanumeric(32);
        tokenMap.put(token, requestBody.get("token"));
        return ResponseEntity.ok().body(token);
    }

    @PostMapping("/tokens/{token}")
    public ResponseEntity<?> verifyToken(@PathVariable("token") String token) {
        if (token == null || !tokenMap.containsKey(token)) {
            return ResponseEntity.status(HttpStatus.NOT_FOUND).build();
        } else {
            return ResponseEntity.ok().body("Verified");
        }
    }

    @PostMapping("/tokens/{token}/revoke")
    public ResponseEntity<?> revokeToken(@PathVariable("token") String token) {
        if (token == null || !tokenMap.containsKey(token)) {
            return ResponseEntity.status(HttpStatus.NOT_FOUND).build();
        } else {
            // Remove the token from the map
            tokenMap.remove(token);
            return ResponseEntity.ok().body("Revoked");
        }
    }
}
