// Define the maximum number of concurrent transcoding jobs
#define MAX_JOBS 100

// Define the default target format for transcoding
#define DEFAULT_TARGET_FORMAT "mp4"

// Define the minimum and maximum buffer sizes for input and output data
#define MIN_BUFFER_SIZE 1024
#define MAX_BUFFER_SIZE (1024 * 1024)

// Define the directory where transcoded videos will be stored
#define VIDEO_STORAGE_DIR "/tmp/video-storage"

// Define the path to the external transcoding service executable
#define TRANSCODING_EXECUTABLE "transcode.out"

// Define the path to the cloud storage solution for persistent data
#define CLOUD_STORAGE_PATH "s3://my-bucket/video-data"

// Define the timeout for waiting on transcoding jobs (in seconds)
#define TRANSCODING_TIMEOUT 60

// Define the maximum number of retries for transcoding jobs
#define MAX_RETRIES 3

// Define the retry interval for transcoding jobs (in milliseconds)
#define RETRY_INTERVAL 1000

// Define the error message for unsupported file formats
#define UNSUPPORTED_FILE_FORMAT "Unsupported file format. Please use MP4, MOV, or AVI."

// Define the error message for incomplete metadata
#define INCOMPLETE_METADATA "Incomplete metadata. Please provide a valid title and artist."

// Define the error message for transcoding failures
#define TRANSCODING_FAILURE "Transcoding failed with code %d: %s"

// Define the state list structure
typedef struct {
  char* name;
  int value;
} StateList;

// Define the finite state machine for managing transcoding jobs
static StateList state_list[] = {
  {"INIT", 0},
  {"TRANSCODING", 1},
  {"FINISHED", 2},
  {"FAILED", 3}
};

// Define the number of states in the state list
#define NUM_STATES (sizeof(state_list) / sizeof(StateList))

// Define the transcoding job structure
typedef struct {
  char* input_path;
  char* output_path;
  int target_format;
  int num_retries;
} TranscodingJob;

// Define the concurrent queue for managing transcoding jobs
static ConcurrentQueue* job_queue = NULL;

// Define the mutex and semaphore for synchronizing access to the job queue
static pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
static sem_t semaphore = SEM_FAILED;

// Function for creating a new transcoding job
TranscodingJob* create_job(const char* input_path, const char* output_path) {
  // Allocate memory for the transcoding job
  TranscodingJob* job = (TranscodingJob*) malloc(sizeof(TranscodingJob));
  if (!job) {
    fprintf(stderr, "Error: Failed to allocate memory for transcoding job\n");
    return NULL;
  }

  // Initialize the transcoding job fields
  job->input_path = strdup(input_path);
  job->output_path = strdup(output_path);
  job->target_format = DEFAULT_TARGET_FORMAT;
  job->num_retries = 0;

  return job;
}

// Function for destroying a transcoding job
void destroy_job(TranscodingJob* job) {
  if (job) {
    free(job->input_path);
    free(job->output_path);
    free(job);
  }
}

// Function for creating a new state list entry
StateList* create_state_list_entry(const char* name, int value) {
  // Allocate memory for the state list entry
  StateList* entry = (StateList*) malloc(sizeof(StateList));
  if (!entry) {
    fprintf(stderr, "Error: Failed to allocate memory for state list entry\n");
    return NULL;
  }

  // Initialize the state list entry fields
  entry->name = strdup(name);
  entry->value = value;

  return entry;
}

// Function for destroying a state list entry
void destroy_state_list_entry(StateList* entry) {
  if (entry) {
    free(entry->name);
    free(entry);
  }
}

// Function for adding a new job to the job queue
int add_job(const char* input_path, const char* output_path) {
  // Create a new transcoding job
  TranscodingJob* job = create_job(input_path, output_path);
  if (!job) {
    fprintf(stderr, "Error: Failed to create new transcoding job\n");
    return -1;
  }

  // Lock the mutex and semaphore
  pthread_mutex_lock(&mutex);
  if (sem_wait(&semaphore) == -1) {
    fprintf(stderr, "Error: Failed to wait on semaphore\n");
    return -1;
  }

  // Add the job to the job queue
  ConcurrentQueue* queue = concurrent_queue_create();
  if (!queue) {
    fprintf(stderr, "Error: Failed to create new concurrent queue\n");
    pthread_mutex_unlock(&mutex);
    return -1;
  }
  if (concurrent_queue_push(queue, job)) {
    fprintf(stderr, "Error: Failed to push job to concurrent queue\n");
    concurrent_queue_destroy(queue);
    pthread_mutex_unlock(&mutex);
    return -1;
  }

  // Update the job queue pointer
  if (job_queue) {
    concurrent_queue_destroy(job_queue);
  }
  job_queue = queue;

  // Unlock the mutex and semaphore
  pthread_mutex_unlock(&mutex);
  sem_post(&semaphore);

  return 0;
}

// Function for removing a job from the job queue
int remove_job(const char* input_path) {
  // Lock the mutex and semaphore
  pthread_mutex_lock(&mutex);
  if (sem_wait(&semaphore) == -1) {
    fprintf(stderr, "Error: Failed to wait on semaphore\n");
    return -1;
  }

  // Find the job in the job queue
  ConcurrentQueue* queue = job_queue;
  TranscodingJob* job = NULL;
  while ((job = (TranscodingJob*)concurrent_queue_pop(queue))) {
    if (!strcmp(job->input_path, input_path)) {
      break;
    }
    destroy_job(job);
  }
  if (!job) {
    fprintf(stderr, "Error: Failed to find job in concurrent queue\n");
    pthread_mutex_unlock(&mutex);
    sem_post(&semaphore);
    return -1;
  }

  // Remove the job from the job queue
  if (concurrent_queue_remove(queue, job)) {
    fprintf(stderr, "Error: Failed to remove job from concurrent queue\n");
    pthread_mutex_unlock(&mutex);
    sem_post(&semaphore);
    return -1;
  }

  // Update the job queue pointer
  if (!concurrent_queue_size(queue)) {
    concurrent_queue_destroy(job_queue);
    job_queue = NULL;
  }

  // Unlock the mutex and semaphore
  pthread_mutex_unlock(&mutex);
  sem_post(&semaphore);

  return 0;
}

// Function for getting the state of a job from the job queue
int get_state(const char* input_path) {
  // Lock the mutex and semaphore
  pthread_mutex_lock(&mutex);
  if (sem_wait(&semaphore) == -1) {
    fprintf(stderr, "Error: Failed to wait on semaphore\n");
    return -1;
  }

  // Find the job in the job queue
  ConcurrentQueue* queue = job_queue;
  TranscodingJob* job = NULL;
  while ((job = (TranscodingJob*)concurrent_queue_pop(queue))) {
    if (!strcmp(job->input_path, input_path)) {
      break;
    }
    destroy_job(job);
  }
  if (!job) {
    fprintf(stderr, "Error: Failed to find job in concurrent queue\n");
    pthread_mutex_unlock(&mutex);
    sem_post(&semaphore);
    return -1;
  }

  // Get the state of the job
  int state = -1;
  for (int i = 0; i < NUM_STATES; i++) {
    if (!strcmp(state_list[i].name, job->state)) {
      state = state_list[i].value;
      break;
    }
  }

  // Unlock the mutex and semaphore
  pthread_mutex_unlock(&mutex);
  sem_post(&semaphore);

  return state;
}

// Function for setting the state of a job in the job queue
int set_state(const char* input_path, const char* state) {
  // Lock the mutex and semaphore
  pthread_mutex_lock(&mutex);
  if (sem_wait(&semaphore) == -1) {
    fprintf(stderr, "Error: Failed to wait on semaphore\n");
    return -1;
  }

  // Find the job in the job queue
  ConcurrentQueue* queue = job_queue;
  TranscodingJob* job = NULL;
  while ((job = (TranscodingJob*)concurrent_queue_pop(queue))) {
    if (!strcmp(job->input_path, input_path)) {
      break;
    }
