  }
  if (!job) {
    fprintf(stderr, "Error: Failed to find job in concurrent queue\n");
    pthread_mutex_unlock(&mutex);
    sem_post(&semaphore);
    return -1;
  }

  // Set the state of the job
  for (int i = 0; i < NUM_STATES; i++) {
    if (!strcmp(state_list[i].name, state)) {
      strcpy(job->state, state);
      break;
    }
  }

  // Unlock the mutex and semaphore
  pthread_mutex_unlock(&mutex);
  sem_post(&semaphore);

  return 0;
}

// Function for destroying a job in the job queue
int destroy_job(const char* input_path) {
  // Lock the mutex and semaphore
  pthread_mutex_lock(&mutex);
  if (sem_wait(&semaphore) == -1) {
    fprintf(stderr, "Error: Failed to wait on semaphore\n");
    return -1;
  }

  // Find the job in the job queue
  ConcurrentQueue* queue = job_queue;
  TranscodingJob* job = NULL;
  while ((job = (TranscodingJob*)concurrent_queue_pop(queue))) {
    if (!strcmp(job->input_path, input_path)) {
      break;
    }
    destroy_job(job);
  }
  if (!job) {
    fprintf(stderr, "Error: Failed to find job in concurrent queue\n");
    pthread_mutex_unlock(&mutex);
    sem_post(&semaphore);
    return -1;
  }

  // Destroy the job and remove it from the job queue
  destroy_job(job);
  if (concurrent_queue_remove(queue, job)) {
    fprintf(stderr, "Error: Failed to remove job from concurrent queue\n");
    pthread_mutex_unlock(&mutex);
    sem_post(&semaphore);
    return -1;
  }

  // Update the job queue pointer
  if (!concurrent_queue_size(queue)) {
    concurrent_queue_destroy(job_queue);
    job_queue = NULL;
  }

  // Unlock the mutex and semaphore
  pthread_mutex_unlock(&mutex);
  sem_post(&semaphore);

  return 0;
}

// Function for printing the job queue
int print_job_queue() {
  // Lock the mutex and semaphore
  pthread_mutex_lock(&mutex);
  if (sem_wait(&semaphore) == -1) {
    fprintf(stderr, "Error: Failed to wait on semaphore\n");
    return -1;
  }

  // Print the job queue
  printf("Job Queue:\n");
  if (job_queue) {
    ConcurrentQueue* queue = job_queue;
    TranscodingJob* job = NULL;
    while ((job = (TranscodingJob*)concurrent_queue_pop(queue))) {
      printf("  - %s (%d)\n", job->input_path, get_state(job->input_path));
      destroy_job(job);
    }
  } else {
    printf("  Empty\n");
  }

  // Unlock the mutex and semaphore
  pthread_mutex_unlock(&mutex);
  sem_post(&semaphore);

  return 0;
}
