  NFAPI_CRC_INDICATION_PDU *head; // Pointer to the head node of the list
  NFAPI_CRC_INDICATION_PDU *tail; // Pointer to the tail node of the list
} NFAPI_CRC_INDICATION_LIST;

// Define a function to initialize the linked list
void init_list(NFAPI_CRC_INDICATION_LIST *list) {
  list->head = NULL;
  list->tail = NULL;
}

// Define a function to add an entry to the linked list
int add_entry(NFAPI_CRC_INDICATION_LIST *list, unsigned char *data, size_t len) {
  // Create a new node to store the CRC indication PDU data
  NFAPI_CRC_INDICATION_PDU *node = malloc(sizeof(NFAPI_CRC_INDICATION_PDU));
  if (node == NULL) {
    return -1;
  }

  // Copy the raw packet data and length to the new node
  node->data = data;
  node->len = len;

  // If the list is empty, set the head and tail pointers to the new node
  if (list->head == NULL) {
    list->head = node;
    list->tail = node;
  } else {
    // Otherwise, add the new node to the end of the list
    list->tail->next = node;
    list->tail = node;
  }

  return 0;
}

// Define a function to remove an entry from the linked list
int remove_entry(NFAPI_CRC_INDICATION_LIST *list, NFAPI_CRC_INDICATION_PDU *node) {
  // If the node is not found in the list, return -1
  if (node == NULL) {
    return -1;
  }

  // If the node is the head of the list, set the new head to the next node
  if (list->head == node) {
    list->head = node->next;
  }

  // If the node is the tail of the list, set the new tail to the previous node
  if (list->tail == node) {
    list->tail = node->prev;
  }

  // Remove the node from the list by setting its next and previous pointers to NULL
  node->next = NULL;
  node->prev = NULL;

  return 0;
}

