#include <stdlib.h>
#include <stdbool.h>
#include <pthread.h>
#include <assert.h>

#define MAX_ELEMENTS 10000 // maximum number of elements in the collection
#define MIN_POOL_SIZE 16 // minimum pool size for slab allocator
#define DEFAULT_POOL_SIZE 32 // default pool size for slab allocator
#define POOL_GROWTH_FACTOR 2 // factor to grow the pool by when no free elements are available

// structure representing a single NFAPI_CRC_INDICATION_PDU_T element in the collection
struct nfapi_crc_indication_pdu {
    uint16_t length;
    uint8_t* data;
};

// structure representing the dynamic collection of NFAPI_CRC_INDICATION_PDU_T elements
struct nfapi_crc_indication_collection {
    struct slab_allocator allocator; // slab allocator for managing memory allocation and deallocation
    size_t num_elements; // number of elements in the collection
    pthread_mutex_t lock; // mutex for synchronizing access to the collection
};

// initialize the dynamic collection with an initial pool size
void nfapi_crc_indication_collection_init(struct nfapi_crc_indication_collection* col) {
    assert(col != NULL);
    slab_allocator_init(&col->allocator, DEFAULT_POOL_SIZE, MIN_POOL_SIZE, POOL_GROWTH_FACTOR);
    pthread_mutex_init(&col->lock, NULL);
}

// clean up the dynamic collection and release all resources
void nfapi_crc_indication_collection_destroy(struct nfapi_crc_indication_collection* col) {
    assert(col != NULL);
    slab_allocator_destroy(&col->allocator);
    pthread_mutex_destroy(&col->lock);
}

// add a new element to the dynamic collection
struct nfapi_crc_indication_pdu* nfapi_crc_indication_collection_insert(struct nfapi_crc_indication_collection* col, uint16_t length) {
    assert(col != NULL);
    pthread_mutex_lock(&col->lock);
    struct slab_allocator* alloc = &col->allocator;
    struct nfapi_crc_indication_pdu* new_element = (struct nfapi_crc_indication_pdu*)slab_allocator_alloc(alloc, sizeof(*new_element));
    if (!new_element) {
        pthread_mutex_unlock(&col->lock);
        return NULL;
    }
    new_element->length = length;
    new_element->data = (uint8_t*)malloc(length * sizeof(uint8_t));
    if (!new_element->data) {
        slab_allocator_free(alloc, new_element);
        pthread_mutex_unlock(&col->lock);
        return NULL;
    }
    col->num_elements++;
    pthread_mutex_unlock(&col->lock);
    return new_element;
}

// remove an element from the dynamic collection by its index
void nfapi_crc_indication_collection_remove(struct nfapi_crc_indication_collection* col, size_t index) {
    assert(col != NULL);
    pthread_mutex_lock(&col->lock);
    struct slab_allocator* alloc = &col->allocator;
    if (index >= col->num_elements) {
        pthread_mutex_unlock(&col->lock);
        return;
    }
    size_t removed_length = 0;
    struct nfapi_crc_indication_pdu* removed_element = &col->elements[index];
    if (removed_element->data) {
        free(removed_element->data);
        removed_length += removed_element->length * sizeof(uint8_t);
    }
    slab_allocator_free(alloc, removed_element);
    col->num_elements--;
    pthread_mutex_unlock(&col->lock);
}

// retrieve an element from the dynamic collection by its index
struct nfapi_crc_indication_pdu* nfapi_crc_indication_collection_get(struct nfapi_crc_indication_collection* col, size_t index) {
    assert(col != NULL);
    pthread_mutex_lock(&col->lock);
    if (index >= col->num_elements) {
        pthread_mutex_unlock(&col->lock);
        return NULL;
    }
    struct nfapi_crc_indication_pdu* element = &col->elements[index];
    pthread_mutex_unlock(&col->lock);
    return element;
}
