// Synchronization mechanism for thread safety
class LogEventBuffer {
public:
    // Constructor
    LogEventBuffer(AllocationStrategy strategy) : strategy_(strategy), buffer_(nullptr), capacity_(0), size_(0) {}

    // Destructor
    ~LogEventBuffer() {
        if (buffer_) {
            delete[] buffer_;
        }
    }

    // Insert a new log event record into the buffer
    void insert(const LOG_EVENT_RECORD& record) {
        std::unique_lock<std::mutex> lock(mutex_);
        if (strategy_ == AllocationStrategy::ADAPTIVE && size_ == capacity_) {
            // Resize the buffer when it's full
            capacity_ += 1024;
            buffer_ = new LOG_EVENT_RECORD[capacity_];
        }
        buffer_[size_++] = record;
    }

    // Read all log event records in the buffer and clear it
    std::vector<LOG_EVENT_RECORD> readAll() {
        std::unique_lock<std::mutex> lock(mutex_);
        std::vector<LOG_EVENT_RECORD> result;
        for (int i = 0; i < size_; ++i) {
            result.push_back(buffer_[i]);
        }
        size_ = 0;
        return result;
    }

