    AllocationStrategy strategy_;
    LOG_EVENT_RECORD* buffer_;
    int capacity_;
    int size_;
    std::mutex mutex_;
};

// Deadlock prevention mechanism for thread safety
class DeadlockPrevention {
public:
    // Constructor
    DeadlockPrevention() : monitor_(new std::condition_variable) {}

    // Wait until the resource is available
    void wait(const std::unique_lock<std::mutex>& lock) {
        monitor_->wait(lock);
    }

    // Signal that the resource is available
    void signal() {
        monitor_->notify_all();
    }

