void create_nas_protocols(NFAPI_CRC_INDICATION_PDU_T **list, uint32_t count) {
  // Initialize the head of the linked list to NULL
  *list = NULL;

  // Create a new node for each NAS protocol structure and add it to the linked list
  for (uint32_t i = 0; i < count; i++) {
    NFAPI_CRC_INDICATION_PDU_T *node = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    node->rx_ue_information_tag = rand() % (1 << 20);
    node->rnti = rand() % (1 << 16);
    node->crc_indication_rel8_tag = rand() % (1 << 8);
    node->crcflag = (rand() & 1) == 0;

    // Add the new node to the end of the linked list
    if (*list == NULL) {
      *list = node;
    } else {
      NFAPI_CRC_INDICATION_PDU_T *tmp = *list;
      while (tmp->next != NULL) {
        tmp = tmp->next;
