#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <sys/types.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <pthread.h>
#include <assert.h>
#include <errno.h>

#define MAX_PDU 1024
#define MAX_THREADS 64

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    int manpage;
    char *config_source;
    char *output_file;
    int num_threads;
    int batch_mode;
    int realtime_mode;
} CommandLineOptions;

CommandLineOptions options;

void parse_command_line(int argc, char **argv) {
    // Initialize command line options with default values
    options = (CommandLineOptions){
        .manpage = 0,
        .config_source = NULL,
        .output_file = NULL,
        .num_threads = 1,
        .batch_mode = 1,
        .realtime_mode = 0
    };

    // Parse command line options
    int c;
    while ((c = getopt(argc, argv, "m:c:o:t:br")) != -1) {
        switch (c) {
            case 'm':
                options.manpage = 1;
                break;
            case 'c':
                options.config_source = optarg;
                break;
            case 'o':
                options.output_file = optarg;
                break;
            case 't':
                options.num_threads = atoi(optarg);
                break;
            case 'b':
                options.batch_mode = 1;
                break;
            case 'r':
                options.realtime_mode = 1;
                break;
            default:
                fprintf(stderr, "Invalid option %c\n", c);
                exit(EXIT_FAILURE);
        }
    }
}

void print_usage() {
    printf("Usage: nas-manager [options]\n");
    printf("\nOptions:\n");
    printf("  -m, --manpage      Print NAS manager manual page\n");
    printf("  -c, --config <str> Config source for NAS manager (e.g., file path)\n");
    printf("  -o, --output <str> Output file for NAS manager logs\n");
    printf("  -t, --threads <int> Number of threads to use for NAS manager\n");
    printf("  -b, --batch        Batch mode (process data in batches)\n");
    printf("  -r, --realtime     Realtime mode (stream data as it arrives)\n");
}

void *thread_handler(void *arg) {
    // Define thread-local variables
    pthread_t tid = (pthread_t)arg;
    int i, j, k;
    int ret;
    char buffer[MAX_PDU];

    // Allocate memory for PDUs
    NFAPI_CRC_INDICATION_PDU_T *pdu = calloc(MAX_PDU, sizeof(NFAPI_CRC_INDICATION_PDU_T));

    // Populate PDUs with random data
    srand(time(NULL) + tid);
    for (i = 0; i < MAX_PDU; i++) {
        pdu[i].RX_UE_INFORMATION_TAG = rand() % 1000;
        pdu[i].RNTI = rand() % 1000;
        pdu[i].CRC_INDICATION_REL8_TAG = rand() % 1000;
    }

    // Send PDUs to NAS manager
    for (j = 0; j < MAX_PDU; j++) {
        ret = sendto(tid, pdu[j], sizeof(NFAPI_CRC_INDICATION_PDU_T), MSG_CONFIRM, NULL, NULL);
        if (ret < 0) {
            fprintf(stderr, "Error sending PDU to NAS manager: %s\n", strerror(errno));
        }
    }

    // Wait for ack from NAS manager
    int ack;
    recvfrom(tid, &ack, sizeof(int), MSG_WAITALL, NULL, NULL);
    if (ack != 0) {
        fprintf(stderr, "Error receiving ack from NAS manager: %s\n", strerror(errno));
    }

    // Clean up memory allocated to PDUs
    free(pdu);
}

int main(int argc, char **argv) {
    parse_command_line(argc, argv);
    if (options.manpage == 1) {
        print_usage();
        return 0;
    }

    // Handle command line options and initialize NAS manager
    int ret;
    pthread_t tid[MAX_THREADS];
    for (int i = 0; i < MAX_THREADS; i++) {
        ret = pthread_create(&tid[i], NULL, thread_handler, &tid[i]);
        if (ret != 0) {
            fprintf(stderr, "Error creating thread: %s\n", strerror(errno));
            return EXIT_FAILURE;
        }
    }

    // Handle data input and processing
    while (1) {
        if (options.batch_mode == 1) {
            // Batch mode: process data in batches
            int ret = recvfrom(tid[0], NULL, 0, MSG_WAITALL, NULL, NULL);
            if (ret < 0) {
                fprintf(stderr, "Error receiving PDUs from external API: %s\n", strerror(errno));
                return EXIT_FAILURE;
            }
        } else {
            // Realtime mode: stream data as it arrives
            int ret = recvfrom(tid[0], NULL, 0, MSG_WAITALL, NULL, NULL);
            if (ret < 0) {
                fprintf(stderr, "Error receiving PDUs from external API: %s\n", strerror(errno));
                return EXIT_FAILURE;
            }
        }
    }

    // Clean up and exit
    for (int i = 0; i < MAX_THREADS; i++) {
        pthread_join(tid[i], NULL);
    }
    return 0;
}
