class Cache {
 public:
  // Constructor to initialize the cache size and eviction policy
  explicit Cache(size_t size, EvictionPolicy policy) : size_(size), policy_(policy) {}

  // Function to add an event to the cache
  void AddEvent(const TRADE_EVENT_T& event);

  // Function to remove an event from the cache
  void RemoveEvent(const TRADE_EVENT_T& event);

  // Function to get an event from the cache by its timestamp
  optional<TRADE_EVENT_T> GetEvent(int64_t timestamp);

