  // Constructor to initialize the pool size and timeout for acquiring a connection
  explicit ConnectionPool(size_t size, chrono::milliseconds timeout);

  // Function to acquire a connection from the pool
  shared_ptr<Connection> Acquire();

  // Function to release a connection back to the pool
  void Release(shared_ptr<Connection> conn);

 private:
  size_t size_;                    // Maximum number of connections in the pool
  chrono::milliseconds timeout_;   // Timeout for acquiring a connection from the pool
  queue<shared_ptr<Connection>> conns_;  // Queue of available connections
  mutex mtx_;                               // Mutex to protect concurrent access
};

// Define a trading platform class to manage the events and external APIs
class TradingPlatform {
 public:
  // Constructor to initialize the trading platform with the cache size, connection pool size, and API SLAs
  explicit TradingPlatform(size_t cache_size, size_t conn_pool_size, unordered_map<string, chrono::milliseconds> slas);

  // Function to add an event to the trading platform
  void AddEvent(const TRADE_EVENT_T& event);

  // Function to remove an event from the trading platform
  void RemoveEvent(const TRADE_EVENT_T& event);

  // Function to get an event from the trading platform by its timestamp
  optional<TRADE_EVENT_T> GetEvent(int64_t timestamp);

  // Function to update the API SLAs for the external APIs
  void UpdateSLAs(unordered_map<string, chrono::milliseconds> slas);

 private:
  size_t cache_size_;                         // Size of the cache for storing events
  ConnectionPool conn_pool_;                // Pool of connections to external APIs
  unordered_map<string, chrono::milliseconds> slas_;   // SLAs for each API (key = API name, value = SLA in milliseconds)
  mutex mtx_;                                // Mutex to protect concurrent access
};

