// Connection handler function
void *connection_handler(void *args) {
    struct client *client = (struct client *)args;

    // Create a connection structure for this client
    struct connection *conn = create_connection(client);

    // Connect to the server
    if (!connect_to_server(conn)) {
        handle_error("Error connecting to server");
    }

    // Read and write messages in a loop
    while (1) {
        LTE_DL_CCCH_MESSAGE_T message;
        read_message(conn, &message);
        if (!write_message(conn, &message)) {
            handle_error("Error writing message to server");
        }
    }

