    disconnect_from_server(conn);

    return NULL;
}

// Allocate memory for connections
int allocate_memory(size_t size) {
    pthread_mutex_lock(&memory_lock);
    if (size > memory_size) {
        deallocate_memory();
        memory_pool = mmap(NULL, size, PROT_READ | PROT_WRITE, MAP_ANONYMOUS | MAP_PRIVATE, -1, 0);
        if (memory_pool == NULL) {
            handle_error("Error allocating memory");
        }
        memory_size = size;
    }
    num_connections++;
    pthread_mutex_unlock(&memory_lock);
    return 1;
}

// Deallocate memory for connections
void deallocate_memory() {
    if (memory_pool != NULL) {
        munmap(memory_pool, memory_size);
        memory_pool = NULL;
        num_connections--;
    }
}

// Create a connection structure for this client
struct connection *create_connection(struct client *client) {
    struct connection *conn = malloc(sizeof(struct connection));
    if (conn == NULL) {
        handle_error("Error allocating memory");
    }
    conn->message.present = 0;
    memcpy(&conn->client, client, sizeof(struct client));
    pthread_mutex_init(&conn->lock, NULL);
    return conn;
}

