    conn->socket = socket(AF_INET, SOCK_STREAM, 0);
    if (conn->socket < 0) {
        handle_error("Error creating connection");
    }

    if (!connect(conn->socket, (struct sockaddr *)&server_address, sizeof(server_address))) {
        ret = 1;
    } else {
        handle_error("Error connecting to server");
    }

    return ret;
}

// Disconnect from the server
void disconnect_from_server(struct connection *conn) {
    close(conn->socket);
}

// Read a message from the server
int read_message(struct connection *conn, LTE_DL_CCCH_Message_t *message) {
    int ret = 0;
    pthread_mutex_lock(&conn->lock);
    if (conn->message.present == 1) {
        memcpy(message, &conn->message, sizeof(LTE_DL_CCCH_Message_t));
        conn->message.present = 0;
        ret = 1;
    }
    pthread_mutex_unlock(&conn->lock);
    return ret;
}

// Write a message to the server
int write_message(struct connection *conn, LTE_DL_CCCH_Message_t *message) {
    int ret = 0;
    pthread_mutex_lock(&conn->lock);
    memcpy(&conn->message, message, sizeof(LTE_DL_CCCH_Message_t));
    conn->message.present = 1;
    pthread_mutex_unlock(&conn->lock);
    return ret;
}

// Handle errors by logging a message and exiting the program
void handle_error(char *msg) {
    log_message(msg);
    exit(1);
}

// Log messages to the console
void log_message(char *msg) {
