    RedisConnectionError(RedisError),
    KafkaProducerCreationError(String),
    KafkaConsumerCreationError(String),
    IoError(io::Error),
}

impl From<io::Error> for ApplicationError {
    fn from(err: io::Error) -> Self {
        ApplicationError::IoError(err)
    }
}

// Function to create a Kafka producer instance
fn create_kafka_producer(kafka_brokers: &[&str]) -> Result<Producer, ApplicationError> {
    let mut kafka_config = kafka::client::Config::new();
    kafka_config.set("bootstrap.servers", kafka_brokers.join(","));

