use std::path::Path;
use std::io::{BufReader, BufWriter};
use std::fs::File;
use std::thread::spawn;
use std::time::Duration;
use std::error::Error;

// Configuration parameters
const MAX_PARALLELISM: usize = 100;
const MIN_BLOCK_SIZE: usize = 512;
const MAX_BLOCK_SIZE: usize = 4 * 1024 * 1024;
const DEFAULT_RETRY_COUNT: u32 = 3;
const RETRY_DELAY: Duration = Duration::from_secs(5);

fn main() -> Result<(), Box<dyn Error>> {
    // Initialize the logging hooks and compilation time measurement
    let mut logger = Logger::new();
    let mut timer = Timer::new();

    // Load the input file
    let filename = Path::new("input.txt");
    let reader = BufReader::new(File::open(filename)?);

    // Spawn a thread for each line in the file
    let parallelism = std::cmp::min(MAX_PARALLELISM, reader.lines().count());
    let threads: Vec<JoinHandle<Result<(), Box<dyn Error>>>> = (0..parallelism)
        .map(|line| {
            spawn(move || {
                // Create a buffer for the line
                let mut buf = [0; MAX_BLOCK_SIZE];

                // Read the next line from the file
                let size = reader.read(&mut buf)?;

                // Process the line
                process_line(&buf[..size], &logger, &timer);

                Ok(())
            })
        })
        .collect();

    // Wait for all threads to finish and measure the compilation time
    let start = Instant::now();
    threads.into_iter().for_each(|thread| thread.join().unwrap());
    let end = Instant::now();
    println!("Compilation time: {} ms", timer.elapsed().as_millis());

    // Return the result of the program
    Ok(())
}

// Process a single line from the input file
fn process_line(line: &[u8], logger: &Logger, timer: &Timer) {
    // Deserialize the line into an integer
    let num = match serde_json::from_slice::<i32>(line) {
        Ok(num) => num,
        Err(_) => return,
    };

    // Log the number and measure the time it takes to process it
    logger.log(format!("{}", num));
    let start = timer.now();
    for i in 0..num {
        // Do some computation on the number
        i * i;
    }
    let end = timer.now();
    println!("Processed {} in {} ms", num, timer.elapsed().as_millis());
}
