using namespace std;

// Define the LTE_DL_CCCH_MESSAGE_T structure
struct LTE_DL_CCCH_MESSAGE_T {
    uint8_t message_type;
    uint32_t message_length;
    vector<uint8_t> message_data;
};

// Define the octree data structure
class Octree {
public:
    // Constructor for creating a new octree
    Octree(int depth) : depth_(depth) {}

    // Destructor for deleting an existing octree
    ~Octree() {}

    // Insert a new message into the octree
    void insert_message(const LTE_DL_CCCH_MESSAGE_T& message) {
        // Lock the mutex to prevent concurrent access
        std::lock_guard<std::mutex> lock(mutex_);

        // Check if the message is already in the octree
        auto it = messages_.find(message.message_type);
        if (it != messages_.end()) {
            // If the message is already in the octree, update its position
            it->second.push_back(message);
        } else {
            // If the message is not in the octree, insert a new node
            messages_.insert({message.message_type, list<LTE_DL_CCCH_MESSAGE_T>({message})});
        }
    }

    // Retrieve a message from the octree
    LTE_DL_CCCH_MESSAGE_T retrieve_message(uint8_t message_type) {
        // Lock the mutex to prevent concurrent access
        std::lock_guard<std::mutex> lock(mutex_);

        // Check if the message is in the octree
        auto it = messages_.find(message_type);
        if (it == messages_.end()) {
            return {};
        } else {
            // If the message is in the octree, retrieve it from the list
            LTE_DL_CCCH_MESSAGE_T message = it->second.front();
            it->second.pop_front();
            return message;
        }
    }

private:
    // The depth of the octree (i.e., the number of levels)
    int depth_;

    // A map to store messages in the octree
    map<uint8_t, list<LTE_DL_CCCH_MESSAGE_T>> messages_;

    // A mutex for protecting concurrent access to the octree
    std::mutex mutex_;
};
