        {
            // Create a task to process the files concurrently
            var processFileTask = new Task(() => ProcessFiles());

            // Start the task and wait for it to complete
            processFileTask.Start();
            _resetEvent.WaitOne();

            // Print the results
            Console.WriteLine("Keywords:");
            foreach (var keyword in _keywords)
            {
                Console.WriteLine($"{keyword.Key}: {string.Join(", ", keyword.Value)}");
            }
        }

        private void ProcessFiles()
        {
            // Iterate over the files and process them concurrently
            foreach (var file in _files)
            {
                Task.Run(() => ProcessFile(file));
            }
        }

        private void ProcessFile(string filePath)
        {
            // Open the file stream for reading
            using var fileStream = new FileStream(filePath, FileMode.Open);

            // Create a buffer to read lines from the file
            var buffer = new byte[1024];
            var lineBuffer = new List<byte>();

            // Read the lines from the file and process them concurrently
            while (true)
            {
                int bytesRead = fileStream.Read(buffer, 0, buffer.Length);
                if (bytesRead == 0) break;

                for (int i = 0; i < bytesRead; i++)
                {
                    // Check if the current byte is a newline character
