                        }

                        // Clear the line buffer and continue to the next byte
                        lineBuffer.Clear();
                        continue;
                    }

                    // Add the current byte to the line buffer
                    lineBuffer.Add(buffer[i]);
                }
            }

            // Signal that all files have been processed
            _resetEvent.Set();
        }
    }
}
