typedef struct {
    void *data;
    size_t size;
} LTE_DL_CCCH_MESSAGE_ALLOCATOR_DATA;

// Lock-free data structures for concurrent access
struct LTE_DL_CCCH_MESSAGE_QUEUE {
    pthread_spinlock_t lock;
    struct LTE_DL_CCCH_MESSAGE_T *head, *tail;
};

struct LTE_DL_CCCH_MESSAGE_HASHMAP {
    pthread_rwlock_t lock;
    size_t capacity;
    struct LTE_DL_CCCH_MESSAGE_T **buckets;
};

// Thread-local storage for optimized read/write locks
struct LTE_DL_CCCH_MESSAGE_THREAD_LOCAL {
    pthread_key_t tls_key;
    struct LTE_DL_CCCH_MESSAGE_QUEUE *queue;
};

// Memory reclamation strategy for reduced leaks and optimized garbage collection
struct LTE_DL_CCCH_MESSAGE_RECLAIMER {
    pthread_mutex_t lock;
    struct LTE_DL_CCCH_MESSAGE_T *head, *tail;
};

// Concurrent data structure for managing a dynamic pool of LTE_DL_CCCH_MESSAGE_T
struct LTE_DL_CCCH_MESSAGE_POOL {
    struct LTE_DL_CCCH_MESSAGE_QUEUE *queue;
    struct LTE_DL_CCCH_MESSAGE_HASHMAP *hashmap;
    struct LTE_DL_CCCH_MESSAGE_THREAD_LOCAL *tls;
    struct LTE_DL_CCCH_MESSAGE_RECLAIMER *reclamation;
};

void lte_dl_ccch_message_pool_init(struct LTE_DL_CCCH_MESSAGE_POOL *pool) {
    pool->queue = malloc(sizeof(*pool->queue));
    pthread_spinlock_init(&pool->queue->lock, PTHREAD_PROCESS_PRIVATE);
    pool->queue->head = NULL;
    pool->queue->tail = NULL;

    pool->hashmap = malloc(sizeof(*pool->hashmap));
    pthread_rwlock_init(&pool->hashmap->lock, PTHREAD_PROCESS_PRIVATE);
    pool->hashmap->capacity = 0;
    pool->hashmap->buckets = NULL;

    pool->tls = malloc(sizeof(*pool->tls));
    pthread_key_create(&pool->tls->tls_key, NULL);
    pool->tls->queue = NULL;

    pool->reclamation = malloc(sizeof(*pool->reclamation));
    pthread_mutex_init(&pool->reclamation->lock, PTHREAD_PROCESS_PRIVATE);
    pool->reclamation->head = NULL;
    pool->reclamation->tail = NULL;
}

void lte_dl_ccch_message_pool_destroy(struct LTE_DL_CCCH_MESSAGE_POOL *pool) {
    pthread_spinlock_destroy(&pool->queue->lock);
    free(pool->queue);

    pthread_rwlock_destroy(&pool->hashmap->lock);
    free(pool->hashmap);

    pthread_key_delete(pool->tls->tls_key);
    free(pool->tls);

    pthread_mutex_destroy(&pool->reclamation->lock);
    free(pool->reclamation);
}

void *lte_dl_ccch_message_allocator(struct LTE_DL_CCCH_MESSAGE_POOL *pool) {
    void *data = NULL;
    size_t size = 0;

    // Allocate memory for the message data structure using the allocator provided by the NMS API
    if ((data = nms_alloc(sizeof(*data))) == NULL) {
        return NULL;
    }

    // Initialize the message data structure and set its size
    memset(data, 0, sizeof(*data));
    size = sizeof(*data);

    // Add the allocated memory to the reclamation list for later recycling
    pthread_mutex_lock(&pool->reclamation->lock);
    struct LTE_DL_CCCH_MESSAGE_T *message = malloc(sizeof(*message));
    message->data = data;
    message->size = size;
    if (pool->reclamation->head == NULL) {
        pool->reclamation->head = message;
        pool->reclamation->tail = message;
    } else {
        pool->reclamation->tail->next = message;
        pool->reclamation->tail = message;
    }
    pthread_mutex_unlock(&pool->reclamation->lock);

    // Return a pointer to the allocated memory
    return data;
}

void lte_dl_ccch_message_deallocator(struct LTE_DL_CCCH_MESSAGE_POOL *pool, void *data) {
    pthread_mutex_lock(&pool->reclamation->lock);
    struct LTE_DL_CCCH_MESSAGE_T *message = malloc(sizeof(*message));
    message->data = data;
    message->size = 0;
    if (pool->reclamation->head == NULL) {
        pool->reclamation->head = message;
        pool->reclamation->tail = message;
    } else {
        pool->reclamation->tail->next = message;
        pool->reclamation->tail = message;
    }
    pthread_mutex_unlock(&pool->reclamation->lock);
}
