// define functions for processing events and CSV records
void processEvent(const Event& event) {
    // do something with the event
}

void processCSVRecord(const CSVRecord& record) {
    // do something with the CSV record
}

// define a class for managing the ingestion of events and CSV records
class DataIngester {
public:
    void ingestEvent(const Event& event) {
        std::lock_guard<std::mutex> lock(mutex_);
        events_.push_back(event);
    }

    void ingestCSVRecord(const CSVRecord& record) {
        std::lock_guard<std::mutex> lock(mutex_);
        csvRecords_.push_back(record);
    }

    void processEvents() {
        // process events in the queue
        while (!events_.empty()) {
            Event event = events_.front();
            events_.pop_front();
            processEvent(event);
        }
    }

    void processCSVRecords() {
        // process CSV records in the queue
        while (!csvRecords_.empty()) {
            CSVRecord record = csvRecords_.front();
            csvRecords_.pop_front();
            processCSVRecord(record);
        }
    }

private:
    std::mutex mutex_;
    std::condition_variable cv_;
    std::vector<Event> events_;
    std::vector<CSVRecord> csvRecords_;
};

