using System;
using System.Collections.Generic;
using System.Linq;
using System.Threading;
using System.Threading.Tasks;

namespace MarketDataHub
{
    public class DataConsistencyException : Exception
    {
        public DataConsistencyException(string message)
            : base(message)
        {
        }
    }

    public class MarketDataHub
    {
        private readonly List<IAsyncRestClient> _asyncRestClients = new List<IAsyncRestClient>();
        private readonly Dictionary<Type, IValidator> _validators = new Dictionary<Type, IValidator>();
        private readonly Dictionary<Type, object> _cache = new Dictionary<Type, object>();

        public MarketDataHub(IEnumerable<IAsyncRestClient> asyncRestClients)
        {
            _asyncRestClients.AddRange(asyncRestClients);
        }

        public Task<T> GetConsolidatedDataAsync<T>(CancellationToken cancellationToken = default) where T : class, IDataModel
        {
            var resultTask = new TaskCompletionSource<T>();

            try
            {
                ValidateInputType<T>();

                var dataTasks = _asyncRestClients.Select(c => c.GetAsync<T>(cancellationToken));
                var results = await Task.WhenAll(dataTasks);

                var consolidatedData = ConsolidateData<T>(results);

                resultTask.SetResult(consolidatedData);
            }
            catch (Exception e) when (e is DataConsistencyException || e is AggregateException)
            {
                resultTask.SetCanceled();
            }

            return resultTask.Task;
        }

        private void ValidateInputType<T>() where T : class, IDataModel
        {
            if (!_validators.ContainsKey(typeof(T)))
            {
                throw new ArgumentException($"The type '{typeof(T)}' is not valid for this method.");
            }
        }

        private T ConsolidateData<T>(IEnumerable<T> results) where T : class, IDataModel
        {
            var consolidatedData = (T)_cache.GetOrAdd(typeof(T), key => new T());

            foreach (var result in results)
            {
                consolidatedData.UpdateWith(result);
            }

            return consolidatedData;
        }
    }
}
