using System.Runtime.Serialization.Formatters.Binary;

namespace AsyncDataService
{
    public class DataService
    {
        private readonly string _filePath;
        private readonly BinaryFormatter _formatter = new BinaryFormatter();
        private readonly MemoryStream _stream = new MemoryStream();
        private readonly object _lockObj = new object();

        public DataService(string filePath)
        {
            _filePath = filePath;
        }

        public async Task<T> LoadDataAsync<T>() where T : class
        {
            try
            {
                lock (_lockObj)
                {
                    // Open the binary file stream and read its contents into a memory stream.
                    using (var fileStream = new FileStream(_filePath, FileMode.Open))
                    {
                        await _stream.CopyToAsync(fileStream);
                        _stream.Seek(0, SeekOrigin.Begin);
                    }
                }

                // Deserialize the data from the memory stream using the BinaryFormatter class.
                var data = (T)_formatter.Deserialize(_stream);

                // Close the memory stream to release resources.
                _stream.Close();

                return data;
            }
            catch (Exception ex)
            {
                Console.WriteLine($"Error loading data: {ex}");
                return null;
            }
        }

        public async Task<bool> SaveDataAsync(object data)
        {
            try
            {
                lock (_lockObj)
                {
                    // Serialize the data object using the BinaryFormatter class.
                    _formatter.Serialize(_stream, data);

                    // Flush the memory stream to ensure all data is written to disk.
                    await _stream.FlushAsync();

                    // Close the memory stream to release resources.
                    _stream.Close();
                }

                return true;
            }
            catch (Exception ex)
            {
                Console.WriteLine($"Error saving data: {ex}");
                return false;
            }
        }

        public async Task<bool> ResumeAsync()
        {
            try
            {
                lock (_lockObj)
                {
                    // Open the binary file stream and read its contents into a memory stream.
                    using (var fileStream = new FileStream(_filePath, FileMode.Open))
                    {
                        await _stream.CopyToAsync(fileStream);
                        _stream.Seek(0, SeekOrigin.Begin);
                    }
                }

                return true;
            }
            catch (Exception ex)
            {
                Console.WriteLine($"Error resuming: {ex}");
                return false;
            }
        }

        public async Task<bool> RetryAsync()
